import { requireUser, parseJsonBody, parseUuidParam } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { databaseErrorResponse } from "@/lib/api/errors";
import type { Agent } from "@/types/agents";
import { NextResponse } from "next/server";

type RouteContext = { params: Promise<{ id: string }> };

export async function GET(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { data, error } = await auth.supabase
    .from("agents")
    .select("*")
    .eq("id", idParsed.id)
    .or(`user_id.eq.${auth.user!.id},is_template.eq.true`)
    .single();

  if (error) {
    if (error.code === "42P01") return apiErrorResponse(API_ERROR_CODES.MIGRATION_REQUIRED, 503, "Table not ready");
    if (error.code === "PGRST116") return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Agent not found");
    return databaseErrorResponse("agents.get", error);
  }
  return NextResponse.json({ agent: data as Agent });
}

export async function PATCH(request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const body = await parseJsonBody<Record<string, unknown>>(request);
  if (body instanceof NextResponse) return body;

  const allowedFields = ["name", "description", "system_prompt", "tools", "capabilities", "temperature", "max_tokens", "is_active", "tags", "config"];
  const updates: Record<string, unknown> = { updated_at: new Date().toISOString() };
  for (const key of allowedFields) {
    if (body[key] !== undefined) updates[key] = body[key];
  }

  const { data, error } = await auth.supabase
    .from("agents")
    .update(updates)
    .eq("id", idParsed.id)
    .eq("user_id", auth.user!.id)
    .select("*")
    .single();

  if (error || !data) return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Update failed");
  return NextResponse.json({ agent: data as Agent, message: "Agent updated." });
}

export async function DELETE(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { error } = await auth.supabase.from("agents").delete().eq("id", idParsed.id).eq("user_id", auth.user!.id);
  if (error) return databaseErrorResponse("agents.delete", error);
  return NextResponse.json({ message: "Agent deleted." });
}

import { requireUser, parseUuidParam } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { databaseErrorResponse } from "@/lib/api/errors";
import type { AgentExecution } from "@/types/agents";
import { NextResponse } from "next/server";

type RouteContext = { params: Promise<{ id: string }> };

export async function GET(_request: Request, context: RouteContext) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;

  const { data, error } = await auth.supabase
    .from("agent_executions")
    .select("*")
    .eq("id", idParsed.id)
    .eq("user_id", auth.user!.id)
    .single();

  if (error) {
    if (error.code === "PGRST116") {
      return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Execution not found.");
    }
    return databaseErrorResponse("executions.get", error);
  }

  return NextResponse.json({ execution: data as AgentExecution });
}

import { requireUser, parseJsonBody } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { databaseErrorResponse } from "@/lib/api/errors";
import { enforceMutationRateLimit } from "@/lib/api/rate-limit";
import { listKnowledgeBases, createKnowledgeBase, listDocuments, addDocument } from "@/lib/agents/knowledge";
import { logAgentAudit } from "@/lib/agents/audit";
import { NextResponse } from "next/server";
import { z } from "zod";

export async function GET(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;
  const kbId = new URL(request.url).searchParams.get("knowledgeBaseId");
  if (kbId) {
    const { data, error } = await listDocuments(auth.supabase, auth.user!.id, kbId);
    if (error && !/relation/i.test(error.message ?? "")) return databaseErrorResponse("agents.knowledge.docs", error);
    return NextResponse.json({ documents: data ?? [] });
  }
  const { data, error } = await listKnowledgeBases(auth.supabase, auth.user!.id);
  if (error && !/relation/i.test(error.message ?? "")) return databaseErrorResponse("agents.knowledge.list", error);
  return NextResponse.json({ knowledgeBases: data ?? [] });
}

const kbSchema = z.object({ name: z.string().min(1), description: z.string().optional(), agentId: z.string().uuid().optional() });
const docSchema = z.object({
  knowledgeBaseId: z.string().uuid(),
  title: z.string().min(1),
  content: z.string().min(1),
  sourceType: z.string().default("text"),
});

export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;
  const rateLimited = enforceMutationRateLimit(auth.user!.id);
  if (rateLimited) return rateLimited;
  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const doc = docSchema.safeParse(body);
  if (doc.success) {
    const { data, error } = await addDocument(auth.supabase, {
      user_id: auth.user!.id,
      knowledge_base_id: doc.data.knowledgeBaseId,
      title: doc.data.title,
      content: doc.data.content,
      source_type: doc.data.sourceType,
    });
    if (error) return databaseErrorResponse("agents.knowledge.document", error);
    await logAgentAudit(auth.supabase, { user_id: auth.user!.id, action: "create", entity_type: "knowledge_document", entity_id: data?.id });
    return NextResponse.json({ document: data });
  }

  const parsed = kbSchema.safeParse(body);
  if (!parsed.success) return apiValidationError("Invalid");
  const { data, error } = await createKnowledgeBase(auth.supabase, {
    user_id: auth.user!.id,
    name: parsed.data.name,
    description: parsed.data.description,
    agent_id: parsed.data.agentId ?? null,
  });
  if (error) return databaseErrorResponse("agents.knowledge.create", error);
  await logAgentAudit(auth.supabase, { user_id: auth.user!.id, action: "create", entity_type: "knowledge_base", entity_id: data?.id });
  return NextResponse.json({ knowledgeBase: data });
}

import { requireUser, parseJsonBody } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { databaseErrorResponse } from "@/lib/api/errors";
import { enforceMutationRateLimit } from "@/lib/api/rate-limit";
import { listMemory, saveMemory, updateMemory, deleteMemory } from "@/lib/agents/memory";
import { logAgentAudit } from "@/lib/agents/audit";
import { NextResponse } from "next/server";
import { z } from "zod";

export async function GET(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;
  const agentId = new URL(request.url).searchParams.get("agentId") ?? undefined;
  const { data, error } = await listMemory(auth.supabase, auth.user!.id, agentId);
  if (error && !/relation/i.test(error.message ?? "")) return databaseErrorResponse("agents.memory.list", error);
  return NextResponse.json({ memories: data ?? [] });
}

const saveSchema = z.object({
  agentId: z.string().uuid(),
  memoryType: z.enum(["conversation", "fact", "context", "preference", "summary"]).default("context"),
  key: z.string().default(""),
  content: z.string().min(1),
  relevanceScore: z.number().min(0).max(1).optional(),
});

const updateSchema = z.object({
  id: z.string().uuid(),
  content: z.string().optional(),
  key: z.string().optional(),
  relevanceScore: z.number().min(0).max(1).optional(),
});

export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;
  const rateLimited = enforceMutationRateLimit(auth.user!.id);
  if (rateLimited) return rateLimited;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const action = (body as Record<string, unknown>).action;
  if (action === "delete") {
    const id = String((body as Record<string, unknown>).id ?? "");
    const { error } = await deleteMemory(auth.supabase, auth.user!.id, id);
    if (error) return databaseErrorResponse("agents.memory.delete", error);
    await logAgentAudit(auth.supabase, { user_id: auth.user!.id, action: "delete", entity_type: "memory", entity_id: id });
    return NextResponse.json({ message: "Memory deleted." });
  }

  const upd = updateSchema.safeParse(body);
  if (upd.success) {
    const { data, error } = await updateMemory(auth.supabase, auth.user!.id, upd.data.id, {
      content: upd.data.content,
      key: upd.data.key,
      relevance_score: upd.data.relevanceScore,
    });
    if (error) return databaseErrorResponse("agents.memory.update", error);
    return NextResponse.json({ memory: data });
  }

  const parsed = saveSchema.safeParse(body);
  if (!parsed.success) return apiValidationError("Invalid");
  const { data, error } = await saveMemory(auth.supabase, {
    user_id: auth.user!.id,
    agent_id: parsed.data.agentId,
    memory_type: parsed.data.memoryType,
    key: parsed.data.key,
    content: parsed.data.content,
    relevance_score: parsed.data.relevanceScore,
  });
  if (error) return databaseErrorResponse("agents.memory.save", error);
  await logAgentAudit(auth.supabase, { user_id: auth.user!.id, action: "create", entity_type: "memory", entity_id: data?.id });
  return NextResponse.json({ memory: data });
}

import { requireUser, parseJsonBody, paginationParams } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { databaseErrorResponse } from "@/lib/api/errors";
import type { PromptLibraryEntry } from "@/types/agents";
import { NextResponse } from "next/server";
import { z } from "zod";

export async function GET(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { searchParams } = new URL(request.url);
  const { page, limit, from, to } = paginationParams(searchParams);
  const category = searchParams.get("category");

  let query = auth.supabase
    .from("prompt_library")
    .select("*", { count: "exact" })
    .or(`user_id.eq.${auth.user!.id},is_public.eq.true`)
    .order("usage_count", { ascending: false });

  if (category) query = query.eq("category", category);

  const { data, error, count } = await query.range(from, to);
  if (error) {
    if (error.code === "42P01") return NextResponse.json({ prompts: [], total: 0, page, limit, totalPages: 1 });
    return databaseErrorResponse("prompts.list", error);
  }

  const total = count ?? 0;
  return NextResponse.json({ prompts: data as PromptLibraryEntry[], total, page, limit, totalPages: Math.ceil(total / limit) || 1 });
}

const createSchema = z.object({
  title: z.string().trim().min(1).max(200),
  category: z.string().default("general"),
  promptText: z.string().trim().min(1).max(10000),
  variables: z.array(z.string()).default([]),
  tags: z.array(z.string()).default([]),
  isPublic: z.boolean().default(false),
});

export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = createSchema.safeParse(body);
  if (!parsed.success) return apiValidationError(parsed.error.issues[0]?.message);

  const { data, error } = await auth.supabase.from("prompt_library").insert({
    user_id: auth.user!.id,
    title: parsed.data.title,
    category: parsed.data.category,
    prompt_text: parsed.data.promptText,
    variables: parsed.data.variables,
    tags: parsed.data.tags,
    is_public: parsed.data.isPublic,
  }).select("*").single();

  if (error) {
    if (error.code === "42P01") return apiErrorResponse(API_ERROR_CODES.MIGRATION_REQUIRED, 503, "Prompt library table not ready. Apply migration 022.");
    return databaseErrorResponse("prompts.create", error);
  }
  return NextResponse.json({ prompt: data as PromptLibraryEntry, message: "Prompt saved." });
}

import { requireUser, parseJsonBody, paginationParams } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { databaseErrorResponse, serverErrorResponse } from "@/lib/api/errors";
import { beginAiUsage } from "@/lib/api/rate-limit";
import { enforceMutationRateLimit } from "@/lib/api/rate-limit";
import { runAgent } from "@/lib/agent-runner";
import { logAgentAudit } from "@/lib/agents/audit";
import { getRequestAiLanguage } from "@/lib/i18n/api";
import { aiOutputLanguageDirective } from "@/lib/ai/prompts/language-directive.server";
import type { Agent, AgentExecution } from "@/types/agents";
import { NextResponse } from "next/server";
import { z } from "zod";

export async function GET(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { searchParams } = new URL(request.url);
  const { page, limit, from, to } = paginationParams(searchParams);
  const type = searchParams.get("type");
  const category = searchParams.get("category");

  let query = auth.supabase
    .from("agents")
    .select("*", { count: "exact" })
    .or(`user_id.eq.${auth.user!.id},is_template.eq.true`)
    .order("created_at", { ascending: false });

  if (type) query = query.eq("agent_type", type);
  if (category) query = query.eq("category", category);

  const { data, error, count } = await query.range(from, to);
  if (error) {
    if (error.code === "42P01") return NextResponse.json({ agents: [], total: 0, page, limit, totalPages: 1 });
    return databaseErrorResponse("agents.list", error);
  }

  const total = count ?? 0;
  return NextResponse.json({ agents: data as Agent[], total, page, limit, totalPages: Math.ceil(total / limit) || 1 });
}

const createAgentSchema = z.object({
  name: z.string().trim().min(1).max(200),
  description: z.string().max(2000).default(""),
  agentType: z.string().default("custom"),
  category: z.string().default("general"),
  systemPrompt: z.string().max(10000).default(""),
  tools: z.array(z.string()).default([]),
  capabilities: z.array(z.string()).default([]),
  temperature: z.number().min(0).max(2).default(0.7),
  maxTokens: z.number().int().min(100).max(32000).default(4096),
  tags: z.array(z.string()).default([]),
});

const runAgentSchema = z.object({
  agentId: z.string().uuid().optional(),
  task: z.string().trim().min(1).max(5000),
  context: z.string().max(10000).optional(),
  maxSteps: z.number().int().min(1).max(12).default(6),
  language: z.string().trim().optional(),
  country: z.string().trim().optional(),
});

export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const action = (body as Record<string, unknown>).action;

  if (action === "create-agent") {
    const rateLimited = enforceMutationRateLimit(auth.user!.id);
    if (rateLimited) return rateLimited;
    const parsed = createAgentSchema.safeParse(body);
    if (!parsed.success) return apiValidationError(parsed.error.issues[0]?.message);

    const slug = parsed.data.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").slice(0, 60);
    const { data, error } = await auth.supabase.from("agents").insert({
      user_id: auth.user!.id,
      name: parsed.data.name,
      slug,
      description: parsed.data.description,
      agent_type: parsed.data.agentType,
      category: parsed.data.category,
      system_prompt: parsed.data.systemPrompt,
      tools: parsed.data.tools,
      capabilities: parsed.data.capabilities,
      temperature: parsed.data.temperature,
      max_tokens: parsed.data.maxTokens,
      tags: parsed.data.tags,
    }).select("*").single();

    if (error) {
      if (error.code === "42P01") return apiErrorResponse(API_ERROR_CODES.MIGRATION_REQUIRED, 503, "Agents table not ready. Apply migration 022.");
      return databaseErrorResponse("agents.create", error);
    }
    await logAgentAudit(auth.supabase, { user_id: auth.user!.id, action: "create", entity_type: "agent", entity_id: data?.id });
    return NextResponse.json({ agent: data as Agent, message: "Agent created." });
  }

  const parsed = runAgentSchema.safeParse(body);
  if (!parsed.success) return apiValidationError(parsed.error.issues[0]?.message);

  const usage = await beginAiUsage(auth.supabase, auth.user!.id, "ai-agents");
  if (!usage.ok) return usage.response;
  const creditLease = usage.lease;

  let agent: Agent | null = null;
  if (parsed.data.agentId) {
    const { data: a } = await auth.supabase.from("agents").select("*").eq("id", parsed.data.agentId).single();
    agent = a as Agent | null;
  }

  const systemPrompt = agent?.system_prompt ?? "You are a helpful AI agent. Complete the user's task thoroughly.";
  const aiLanguage = getRequestAiLanguage(request, parsed.data.language, parsed.data.country);
  const localizedSystemPrompt = `${systemPrompt}${aiOutputLanguageDirective(aiLanguage, "agent")}`;
  const tools = (agent?.tools ?? []) as string[];
  const agentType = agent?.agent_type ?? "custom";

  const startTime = Date.now();
  try {
    const result = await runAgent({
      task: parsed.data.task,
      agentType,
      systemPrompt: localizedSystemPrompt,
      tools,
      context: parsed.data.context,
      maxSteps: parsed.data.maxSteps,
      language: aiLanguage,
      supabase: auth.supabase,
      userId: auth.user!.id,
      agentId: parsed.data.agentId,
    });

    const execData = {
      user_id: auth.user!.id,
      agent_id: parsed.data.agentId ?? null,
      task_name: result.output.title || parsed.data.task.slice(0, 100),
      input: { task: parsed.data.task, context: parsed.data.context },
      output: result.output,
      steps_log: result.output.stepResults,
      status: "completed",
      provider: result.provider,
      token_usage: result.usage,
      execution_time_ms: result.generationTimeMs,
      completed_at: new Date().toISOString(),
    };

    const { data: exec, error: execErr } = await auth.supabase.from("agent_executions").insert(execData).select("*").single();
    if (execErr && execErr.code !== "42P01") {
      await creditLease.settle(auth.supabase);
      return NextResponse.json({ execution: execData, output: result.output, message: "Execution completed (not persisted)." });
    }

    if (agent) {
      await auth.supabase.from("agents").update({
        total_runs: (agent.total_runs ?? 0) + 1,
        total_tokens_used: (agent.total_tokens_used ?? 0) + (result.usage.totalTokens ?? 0),
        updated_at: new Date().toISOString(),
      }).eq("id", agent.id);
    }

    await creditLease.settle(auth.supabase);
    return NextResponse.json({ execution: exec as AgentExecution, output: result.output, message: "Agent task completed." });
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : "Unknown error";
    try {
      await auth.supabase.from("agent_executions").insert({
        user_id: auth.user!.id,
        agent_id: parsed.data.agentId ?? null,
        task_name: parsed.data.task.slice(0, 100),
        input: { task: parsed.data.task },
        status: "failed",
        error_message: errMsg,
        execution_time_ms: Date.now() - startTime,
      });
    } catch { /* best effort */ }
    return serverErrorResponse("agents.run", err);
  }
}

import { requireUser, parseJsonBody } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { databaseErrorResponse } from "@/lib/api/errors";
import { enforceMutationRateLimit } from "@/lib/api/rate-limit";
import { listSchedules, createSchedule, executeDueSchedules } from "@/lib/agents/scheduler";
import { logAgentAudit } from "@/lib/agents/audit";
import { NextResponse } from "next/server";
import { z } from "zod";

export async function GET() {
  const auth = await requireUser();
  if (auth.response) return auth.response;
  const { data, error } = await listSchedules(auth.supabase, auth.user!.id);
  if (error && !/relation/i.test(error.message ?? "")) return databaseErrorResponse("agents.schedules.list", error);
  return NextResponse.json({ schedules: data ?? [] });
}

const createSchema = z.object({
  name: z.string().min(1),
  cronExpression: z.string().min(1),
  agentId: z.string().uuid().optional(),
  workflowId: z.string().uuid().optional(),
  input: z.record(z.string(), z.unknown()).optional(),
});

export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;
  const rateLimited = enforceMutationRateLimit(auth.user!.id);
  if (rateLimited) return rateLimited;
  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  if ((body as Record<string, unknown>).action === "execute-due") {
    const results = await executeDueSchedules(auth.supabase, auth.user!.id);
    return NextResponse.json({ results });
  }

  const parsed = createSchema.safeParse(body);
  if (!parsed.success) return apiValidationError("Invalid");
  const { data, error } = await createSchedule(auth.supabase, {
    user_id: auth.user!.id,
    name: parsed.data.name,
    cron_expression: parsed.data.cronExpression,
    agent_id: parsed.data.agentId ?? null,
    workflow_id: parsed.data.workflowId ?? null,
    input: parsed.data.input ?? {},
  });
  if (error) return databaseErrorResponse("agents.schedules.create", error);
  await logAgentAudit(auth.supabase, { user_id: auth.user!.id, action: "create", entity_type: "schedule", entity_id: data?.id });
  return NextResponse.json({ schedule: data });
}

import { requireUser, parseJsonBody } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { PLATFORM_TOOL_KEYS, invokeTool } from "@/lib/agents/tool-registry";
import { NextResponse } from "next/server";

export async function GET() {
  const auth = await requireUser();
  if (auth.response) return auth.response;
  return NextResponse.json({ tools: PLATFORM_TOOL_KEYS });
}

export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;
  const body = await parseJsonBody<{ toolKey?: string; args?: Record<string, unknown> }>(request);
  if (body instanceof NextResponse) return body;
  if (!body.toolKey) return apiValidationError("toolKey required");
  const result = await invokeTool(body.toolKey, { supabase: auth.supabase, userId: auth.user!.id, args: body.args });
  return NextResponse.json({ result });
}

import { requireUser, parseJsonBody } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { databaseErrorResponse } from "@/lib/api/errors";
import { enforceMutationRateLimit } from "@/lib/api/rate-limit";
import { listTriggers, createTrigger, fireTrigger } from "@/lib/agents/triggers";
import { logAgentAudit } from "@/lib/agents/audit";
import { NextResponse } from "next/server";
import { z } from "zod";

export async function GET() {
  const auth = await requireUser();
  if (auth.response) return auth.response;
  const { data, error } = await listTriggers(auth.supabase, auth.user!.id);
  if (error && !/relation/i.test(error.message ?? "")) return databaseErrorResponse("agents.triggers.list", error);
  return NextResponse.json({ triggers: data ?? [] });
}

const createSchema = z.object({
  name: z.string().min(1),
  triggerType: z.enum(["manual", "schedule", "webhook", "event", "api"]),
  agentId: z.string().uuid().optional(),
  workflowId: z.string().uuid().optional(),
  config: z.record(z.string(), z.unknown()).optional(),
});

