import { requireUser, parseJsonBody, parseUuidParam } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { beginAiUsage } from "@/lib/api/rate-limit";
import { databaseErrorResponse } from "@/lib/api/errors";
import {
  blueprintToModel,
  modelToBlueprint,
  runBrandAssistant,
} from "@/lib/ai-core/brand-studio";
import type { BrandIdentityGeneration } from "@/types/brand-identity";
import { NextResponse } from "next/server";
import { z } from "zod";
import { resolveRequestLanguage } from "@/lib/i18n/api";

type RouteContext = { params: Promise<{ id: string }> };

const bodySchema = z.object({
  message: z.string().trim().min(1).max(2000),
  language: z.string().trim().optional(),
  country: z.string().trim().optional(),
});

export async function POST(request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const usage = await beginAiUsage(auth.supabase, auth.user!.id, "brand-identity");
  if (!usage.ok) return usage.response;
  const creditLease = usage.lease;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;
  const parsed = bodySchema.safeParse(body);
  if (!parsed.success) {
    return apiValidationError("Message required");
  }
  resolveRequestLanguage(request, parsed.data.language, parsed.data.country);

  const { data: gen, error } = await auth.supabase
    .from("brand_identity_generations")
    .select("*")
    .eq("id", id)
    .eq("user_id", auth.user!.id)
    .single();

  if (error || !gen?.blueprint) {
    return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Brand identity not found");
  }

  const generation = gen as BrandIdentityGeneration;
  const model = blueprintToModel(generation.blueprint!, generation);
  const result = runBrandAssistant({ message: parsed.data.message, model });

  const blueprint = modelToBlueprint(result.model, generation.prompt);
  const { data: updated, error: updateError } = await auth.supabase
    .from("brand_identity_generations")
    .update({
      blueprint: blueprint as unknown as Record<string, unknown>,
      updated_at: new Date().toISOString(),
    })
    .eq("id", id)
    .eq("user_id", auth.user!.id)
    .select("*")
    .single();

  if (updateError) return databaseErrorResponse("brand-identity.assistant", updateError);

  const { data: session } = await auth.supabase
    .from("brand_assistant_sessions")
    .select("*")
    .eq("generation_id", id)
    .eq("user_id", auth.user!.id)
    .order("updated_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  const messages = [
    ...((session?.messages as Array<{ role: string; content: string }>) ?? []),
    { role: "user", content: parsed.data.message, at: new Date().toISOString() },
    { role: "assistant", content: result.message, actions: result.actions, at: new Date().toISOString() },
  ];

  if (session?.id) {
    await auth.supabase
      .from("brand_assistant_sessions")
      .update({
        messages,
        credits_used: (session.credits_used ?? 0) + (result.creditsUsed ?? 0),
        updated_at: new Date().toISOString(),
      })
      .eq("id", session.id);
  } else {
    await auth.supabase.from("brand_assistant_sessions").insert({
      user_id: auth.user!.id,
      generation_id: id,
      messages,
      credits_used: result.creditsUsed ?? 0,
    });
  }

  await creditLease.settle(auth.supabase);
  return NextResponse.json({
    result,
    generation: updated as BrandIdentityGeneration,
    message: result.message,
  });
}

import { requireUser, parseUuidParam } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import {
  blueprintToModel,
  buildExportManifest,
  buildBrandGuidelinesHtml,
  applyBrandKit,
} from "@/lib/ai-core/brand-studio";
import type { BrandApplyTarget } from "@/lib/ai-core/brand-studio/types";
import type { BrandIdentityGeneration } from "@/types/brand-identity";
import { NextResponse } from "next/server";

type RouteContext = { params: Promise<{ id: string }> };

export async function GET(request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { searchParams } = new URL(request.url);
  const format = searchParams.get("format") ?? "json";
  const applyTo = searchParams.get("applyTo") as BrandApplyTarget | null;

  const { data: gen, error } = await auth.supabase
    .from("brand_identity_generations")
    .select("*")
    .eq("id", id)
    .eq("user_id", auth.user!.id)
    .single();

  if (error || !gen?.blueprint) {
    return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Brand identity not found");
  }

  const generation = gen as BrandIdentityGeneration;
  const model = blueprintToModel(generation.blueprint!, generation);
  const manifest = buildExportManifest(model);

  if (format === "html" || format === "pdf") {
    const html = buildBrandGuidelinesHtml(model);
    return new NextResponse(html, {
      headers: {
        "Content-Type": "text/html; charset=utf-8",
        "Content-Disposition": `attachment; filename="${model.brandName.replace(/\s+/g, "-").toLowerCase()}-guidelines.html"`,
      },
    });
  }

  if (format === "markdown") {
    return new NextResponse(manifest.guidelines, {
      headers: {
        "Content-Type": "text/markdown; charset=utf-8",
        "Content-Disposition": `attachment; filename="${model.brandName.replace(/\s+/g, "-").toLowerCase()}-guidelines.md"`,
      },
    });
  }

  if (applyTo) {
    return NextResponse.json({
      apply: applyBrandKit(model, applyTo),
      tokens: model.tokens,
    });
  }

  return NextResponse.json({
    model,
    manifest,
    files: manifest.files,
    qualityScore: model.qualityScore,
  });
}

import { requireUser, parseJsonBody, parseUuidParam } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { beginAiUsage } from "@/lib/api/rate-limit";
import { databaseErrorResponse, serverErrorResponse } from "@/lib/api/errors";
import {
  blueprintToModel,
  mergeModel,
  modelToBlueprint,
} from "@/lib/ai-core/brand-studio/model";
import { generateBrandLogos } from "@/lib/ai-core/brand-studio/logos";
import type { BrandIdentityGeneration } from "@/types/brand-identity";
import { NextResponse } from "next/server";
import { z } from "zod";
import { resolveRequestLanguage } from "@/lib/i18n/api";

type RouteContext = { params: Promise<{ id: string }> };

const bodySchema = z.object({
  conceptCount: z.number().int().min(1).max(5).optional(),
  language: z.string().trim().optional(),
  country: z.string().trim().optional(),
});

export async function POST(request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const usage = await beginAiUsage(auth.supabase, auth.user!.id, "brand-identity");
  if (!usage.ok) return usage.response;
  const creditLease = usage.lease;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;
  const parsed = bodySchema.safeParse(body ?? {});
  if (!parsed.success) {
    return apiValidationError("Invalid input");
  }
  const aiLanguage = resolveRequestLanguage(request, parsed.data.language, parsed.data.country);

  const { data: gen, error: fetchError } = await auth.supabase
    .from("brand_identity_generations")
    .select("*")
    .eq("id", id)
    .eq("user_id", auth.user!.id)
    .single();

  if (fetchError || !gen || !gen.blueprint) {
    return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Brand identity not found");
  }

  try {
    const generation = gen as BrandIdentityGeneration;
    let model = blueprintToModel(generation.blueprint!, generation);

    const logoResult = await generateBrandLogos({
      model,
      conceptCount: parsed.data.conceptCount ?? 3,
      language: aiLanguage,
    });

    model = mergeModel(model, {
      logos: logoResult.concepts,
      logoVariants: logoResult.variants,
      logoDirection: {
        ...model.logoDirection,
        guidelinesDocument: logoResult.guidelines || model.logoDirection.guidelinesDocument,
      },
    });

    const blueprint = modelToBlueprint(model, generation.prompt);
    const { data, error } = await auth.supabase
      .from("brand_identity_generations")
      .update({
        blueprint: blueprint as unknown as Record<string, unknown>,
        updated_at: new Date().toISOString(),
      })
      .eq("id", id)
      .eq("user_id", auth.user!.id)
      .select("*")
      .single();

    if (error) return databaseErrorResponse("brand-identity.logos", error);

    await creditLease.settle(auth.supabase);
    return NextResponse.json({
      generation: data as BrandIdentityGeneration,
      logos: logoResult.concepts,
      variants: logoResult.variants,
      message: "Logo concepts generated.",
    });
  } catch (error) {
    return serverErrorResponse("brand-identity.logos", error, "Unable to generate logos.");
  }
}

import { syncFavorite } from "@/lib/db/favorites";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { requireUser, parseJsonBody, parseUuidParam } from "@/lib/api/helpers";
import { databaseErrorResponse } from "@/lib/api/errors";
import { blueprintToModel, mergeModel, modelToBlueprint } from "@/lib/ai-core/brand-studio/model";
import type { BrandIdentityGeneration } from "@/types/brand-identity";
import { NextResponse } from "next/server";
import { z } from "zod";

type RouteContext = { params: Promise<{ id: string }> };

const updateSchema = z.object({
  is_favorite: z.boolean().optional(),
  brand_name: z.string().trim().min(1).max(120).optional(),
  colors: z.array(z.object({
    name: z.string(),
    hex: z.string(),
    role: z.string(),
    usage: z.string().optional(),
  })).optional(),
  typography: z.object({
    primary: z.string(),
    secondary: z.string(),
    weight: z.string().optional(),
    headingStyle: z.string().optional(),
    bodyStyle: z.string().optional(),
    notes: z.string().optional(),
  }).optional(),
  voiceTone: z.object({
    tone: z.string(),
    doExamples: z.array(z.string()).optional(),
    dontExamples: z.array(z.string()).optional(),
    tagline: z.string().optional(),
    elevatorPitch: z.string().optional(),
  }).optional(),
});
export async function GET(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { data, error } = await auth.supabase.from("brand_identity_generations").select("*").eq("id", id).eq("user_id", auth.user!.id).single();
  if (error || !data) return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Brand identity not found");
  return NextResponse.json({ generation: data as BrandIdentityGeneration });
}

export async function PATCH(request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = updateSchema.safeParse(body);
  if (!parsed.success) return apiValidationError(parsed.error.issues[0]?.message);

  const { is_favorite, brand_name, colors, typography, voiceTone } = parsed.data;

  const { data: existing, error: existingError } = await auth.supabase
    .from("brand_identity_generations")
    .select("*")
    .eq("id", id)
    .eq("user_id", auth.user!.id)
    .single();

  if (existingError || !existing) {
    return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Brand identity not found");
  }

  let blueprintUpdate: Record<string, unknown> | undefined;
  if ((colors || typography || voiceTone) && existing.blueprint) {
    const gen = existing as BrandIdentityGeneration;
    let model = blueprintToModel(gen.blueprint!, gen);
    if (colors) {
      const normalized = colors.map((c) => ({ ...c, usage: c.usage ?? "" }));
      model = mergeModel(model, {
        colors: normalized,
        tokens: { ...model.tokens, primary: normalized[0]?.hex ?? model.tokens.primary },
      });
    }
    if (typography) {
      model = mergeModel(model, {
        typography: {
          ...model.typography,
          ...typography,
          weight: typography.weight ?? model.typography.weight,
          headingStyle: typography.headingStyle ?? model.typography.headingStyle,
          bodyStyle: typography.bodyStyle ?? model.typography.bodyStyle,
          notes: typography.notes ?? model.typography.notes,
        },
        tokens: {
          ...model.tokens,
          headingFont: typography.primary,
          bodyFont: typography.secondary,
        },
      });
    }
    if (voiceTone) {
      model = mergeModel(model, {
        voice: { ...model.voice, ...voiceTone },
        tokens: { ...model.tokens, voiceTone: voiceTone.tone, tagline: voiceTone.tagline ?? model.tokens.tagline },
      });
    }
    blueprintUpdate = modelToBlueprint(model, gen.prompt) as unknown as Record<string, unknown>;
  }

  const { data, error } = await auth.supabase
    .from("brand_identity_generations")
    .update({
      ...(typeof is_favorite === "boolean" ? { is_favorite } : {}),
      ...(brand_name ? { brand_name } : {}),
      ...(blueprintUpdate ? { blueprint: blueprintUpdate } : {}),
      updated_at: new Date().toISOString(),
    })
    .eq("id", id).eq("user_id", auth.user!.id).select("*").single();
  if (error || !data) return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Brand identity not found");

  if (typeof is_favorite === "boolean") {
    const sync = await syncFavorite(auth.supabase, auth.user!.id, "brand_identity_generation", id, is_favorite);
    if (sync.error) return databaseErrorResponse("brand-identity.syncFavorite", sync.error);
  }

  return NextResponse.json({ generation: data as BrandIdentityGeneration, message: "Updated." });
}

export async function POST(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { data: source, error: sourceError } = await auth.supabase.from("brand_identity_generations").select("*").eq("id", id).eq("user_id", auth.user!.id).single();
  if (sourceError || !source) return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Brand identity not found");

  const { data, error } = await auth.supabase
    .from("brand_identity_generations")
    .insert({ user_id: auth.user!.id, brand_name: `${source.brand_name} (Copy)`, brand_type: source.brand_type, description: source.description, industry: source.industry, target_audience: source.target_audience, brand_personality: source.brand_personality, deliverables: source.deliverables, prompt: source.prompt, blueprint: source.blueprint, status: source.status, mode: "generate", is_favorite: false })
    .select("*").single();

  if (error || !data) return databaseErrorResponse("brand-identity.duplicate", error);
  return NextResponse.json({ generation: data as BrandIdentityGeneration, message: "Duplicated." });
