import { requireUser, parseJsonBody, paginationParams } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { databaseErrorResponse } from "@/lib/api/errors";
import { buildMultiColumnIlikeOrFilter } from "@/lib/api/search-filters";
import { documentCounts } from "@/lib/content-studio/documents";
import { createDocumentVersion } from "@/lib/content-studio/versions";
import type { ContentDocument } from "@/types/content";
import { NextResponse } from "next/server";
import { z } from "zod";

const createSchema = z.object({
  title: z.string().trim().min(1).max(200).default("Untitled Document"),
  body: z.string().default(""),
  projectId: z.string().uuid().optional(),
  contentType: z.string().trim().default("document"),
  contentTool: z.string().trim().default("content-writer"),
  status: z.enum(["draft", "published", "archived"]).default("draft"),
  generationId: z.string().uuid().optional(),
  brandIdentityId: z.string().uuid().optional(),
  metadata: z.record(z.string(), z.unknown()).optional(),
});

export async function GET(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { searchParams } = new URL(request.url);
  const { page, limit, from, to } = paginationParams(searchParams);
  const search = searchParams.get("search")?.trim();
  const favorite = searchParams.get("favorite");
  const status = searchParams.get("status");
  const projectId = searchParams.get("projectId");
  const recent = searchParams.get("recent");

  let query = auth.supabase
    .from("content_documents")
    .select("*", { count: "exact" })
    .eq("user_id", auth.user!.id);

  if (recent === "true") {
    query = query.order("last_edited_at", { ascending: false });
  } else {
    query = query.order("updated_at", { ascending: false });
  }

  const orFilter = buildMultiColumnIlikeOrFilter(["title", "body"], search);
  if (orFilter) query = query.or(orFilter);
  if (favorite === "true") query = query.eq("is_favorite", true);
  if (status) query = query.eq("status", status);
  if (projectId) query = query.eq("project_id", projectId);

  const { data, error, count } = await query.range(from, to);

  if (error) {
    if (error.code === "42P01" || /relation/i.test(error.message ?? "")) {
      return NextResponse.json({ documents: [], page, limit, total: 0, totalPages: 1 });
    }
    return databaseErrorResponse("content-studio.documents.list", error);
  }

  const total = count ?? 0;
  return NextResponse.json({
    documents: data as ContentDocument[],
    page,
    limit,
    total,
    totalPages: Math.ceil(total / limit) || 1,
  });
}

export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = createSchema.safeParse(body);
  if (!parsed.success) {
    return apiValidationError(parsed.error.issues[0]?.message);
  }

  const input = parsed.data;
  const counts = documentCounts(input.body);
  const now = new Date().toISOString();

  const row = {
    user_id: auth.user!.id,
    project_id: input.projectId ?? null,
    title: input.title,
    body: input.body,
    content_type: input.contentType,
    content_tool: input.contentTool,
    status: input.status,
    generation_id: input.generationId ?? null,
    brand_identity_id: input.brandIdentityId ?? null,
    metadata: input.metadata ?? {},
    last_edited_at: now,
    ...counts,
  };

  const { data, error } = await auth.supabase.from("content_documents").insert(row).select("*").single();

  if (error) {
    if (error.code === "42P01" || /relation/i.test(error.message ?? "")) {
      return apiErrorResponse(API_ERROR_CODES.MIGRATION_REQUIRED, 503, "Apply migration 061 for Content Studio platform tables.");
    }
    return databaseErrorResponse("content-studio.documents.insert", error);
  }

  await createDocumentVersion(auth.supabase, {
    userId: auth.user!.id,
    documentId: data.id,
    title: data.title,
    body: data.body,
    changeSummary: "Initial version",
    source: "manual",
  });

  return NextResponse.json({ document: data as ContentDocument });
}

import { requireUser, parseJsonBody, paginationParams } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { databaseErrorResponse, serverErrorResponse } from "@/lib/api/errors";
import { beginAiUsage } from "@/lib/api/rate-limit";
import { buildMultiColumnIlikeOrFilter } from "@/lib/api/search-filters";
import { generateContent } from "@/lib/content-generator";
import { getActiveProvider } from "@/lib/ai/provider-config";
import { resolveIteratedPrompt } from "@/lib/ai/iteration";
import { getContentToolLabel, getContentTypeLabel } from "@/lib/constants/content-studio";
import { fetchBrandVoiceContext, brandVoiceToPromptContext } from "@/lib/content-studio/brand-voice";
import { getRequestAiLanguage } from "@/lib/i18n/api";
import type { ContentGeneration, ContentBlueprint } from "@/types/content";
import { NextResponse } from "next/server";
import { z } from "zod";

const requestSchema = z.object({
  prompt: z.string().trim().min(5, "Describe your content in at least 5 characters."),
  contentTool: z.string().trim().min(1, "Select a content tool."),
  contentType: z.string().trim().min(1, "Select a content type."),
  tone: z.string().trim().default("Professional"),
  audience: z.string().trim().default("General"),
  language: z.string().trim().default("English"),
  country: z.string().trim().optional(),
  brandVoice: z.string().trim().default(""),
  writingStyle: z.string().trim().default("Standard"),
  creativityLevel: z.string().trim().default("Balanced"),
  options: z.array(z.string().trim()).default([]),
  seoKeywords: z.string().trim().default(""),
  mode: z.enum(["generate", "regenerate", "continue", "rewrite", "expand", "shorten", "translate", "summarize"]).optional(),
  parentGenerationId: z.string().uuid().optional(),
  continueInstruction: z.string().trim().max(4000).optional(),
  projectId: z.string().uuid().optional(),
  brandIdentityId: z.string().uuid().optional(),
});

function logError(stage: string, error: unknown) {
  const msg = error instanceof Error ? (error.stack ?? error.message) : JSON.stringify(error, null, 2);
  console.error(`[content-studio:${stage}]`, msg);
}

export async function GET(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { searchParams } = new URL(request.url);
  const { page, limit, from, to } = paginationParams(searchParams);
  const search = searchParams.get("search")?.trim();
  const favorite = searchParams.get("favorite");
  const tool = searchParams.get("tool");
  const contentType = searchParams.get("contentType");

  let query = auth.supabase
    .from("content_generations")
    .select("*", { count: "exact" })
    .eq("user_id", auth.user!.id)
    .order("created_at", { ascending: false });

  const orFilter = buildMultiColumnIlikeOrFilter(["title", "description", "content_type", "content_tool"], search);
  if (orFilter) query = query.or(orFilter);
  if (favorite === "true") query = query.eq("is_favorite", true);
  if (tool) query = query.eq("content_tool", tool);
  if (contentType) query = query.eq("content_type", contentType);

  const { data, error, count } = await query.range(from, to);

  if (error) {
    if (error.code === "42P01" || (typeof error.message === "string" && error.message.includes("relation"))) {
      return NextResponse.json({ generations: [], page, limit, total: 0, totalPages: 1 });
    }
    return databaseErrorResponse("content-studio.list", error);
  }

  const total = count ?? 0;
  return NextResponse.json({ generations: data as ContentGeneration[], page, limit, total, totalPages: Math.ceil(total / limit) || 1 });
}

export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const usage = await beginAiUsage(auth.supabase, auth.user!.id, "content-studio");
  if (!usage.ok) return usage.response;
  const creditLease = usage.lease;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = requestSchema.safeParse(body);
  if (!parsed.success) {
    return apiValidationError(parsed.error.issues[0]?.message);
  }

  const input = parsed.data;
  const aiLanguage = getRequestAiLanguage(request, input.language, input.country);
  let stage = "generateContent";

  try {
    const iterated = await resolveIteratedPrompt({
      supabase: auth.supabase,
      table: "content_generations",
      userId: auth.user!.id,
      mode: input.mode,
      prompt: input.prompt,
      continueInstruction: input.continueInstruction,
      parentGenerationId: input.parentGenerationId,
      titleField: "title",
    });
    if (!iterated.ok) {
      return apiErrorResponse(API_ERROR_CODES.SERVER_ERROR, iterated.status, iterated.error);
    }

    let brandVoiceText = input.brandVoice;
    if (input.brandIdentityId) {
      const voice = await fetchBrandVoiceContext(
        auth.supabase,
        auth.user!.id,
        input.brandIdentityId,
      );
      if (voice) brandVoiceText = brandVoiceToPromptContext(voice);
    }

    const result = await generateContent({
      prompt: iterated.prompt,
      contentTool: input.contentTool,
      contentType: input.contentType,
      tone: input.tone,
      audience: input.audience,
      language: aiLanguage,
      brandVoice: brandVoiceText,
      writingStyle: input.writingStyle,
      creativityLevel: input.creativityLevel,
      options: input.options,
      seoKeywords: input.seoKeywords,
    });

    const blueprint: ContentBlueprint = {
      title: result.title,
      contentTool: input.contentTool,
      contentType: input.contentType,
      body: result.body,
      headlines: result.headlines,
      seo: result.seo,
      suggestions: result.suggestions,
      improvements: result.improvements,
      summary: result.summary,
      files: result.files,
      prompt: input.prompt,
      tone: input.tone,
      audience: input.audience,
      language: aiLanguage,
      writingStyle: input.writingStyle,
      creativityLevel: input.creativityLevel,
      generatedAt: new Date().toISOString(),
      progressEvents: [...result.progressEvents, "Saving...", "Done."],
    };

    stage = "supabase.insert.content_generations";

    const row = {
      user_id: auth.user!.id,
      title: result.title || `${getContentToolLabel(input.contentTool)} — ${getContentTypeLabel(input.contentType)}`,
      content_tool: input.contentTool,
      content_type: input.contentType,
      description: result.summary || input.prompt,
      prompt: input.prompt,
      tone: input.tone,
      audience: input.audience,
      language: aiLanguage,
      brand_voice: brandVoiceText,
      writing_style: input.writingStyle,
      creativity_level: input.creativityLevel,
      options: input.options,
      seo_keywords: input.seoKeywords,
      blueprint: blueprint as unknown as Record<string, unknown>,
      status: "completed",
      mode: input.mode ?? "generate",
      provider: result.provider ?? getActiveProvider(),
      token_usage: result.usage,
      generation_time_ms: result.generationTimeMs,
      parent_generation_id: input.parentGenerationId ?? null,
      project_id: input.projectId ?? null,
    };

    const { data, error } = await auth.supabase.from("content_generations").insert(row).select("*").single();

    if (error) {
      if (error.code === "42P01" || (typeof error.message === "string" && error.message.includes("relation"))) {
        return apiErrorResponse(API_ERROR_CODES.MIGRATION_REQUIRED, 503, "Content Studio table not found. Please apply migration 019.");
      }
      logError(stage, error);
      return databaseErrorResponse("content-studio.insert", error);
    }

    await creditLease.settle(auth.supabase);
    return NextResponse.json({ generation: data as ContentGeneration, message: "Content generated and saved." });
  } catch (error) {
    logError(stage, error);
    return serverErrorResponse(stage, error, "Unable to generate content.");
  }
}

import { requireUser, parseJsonBody } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { beginAiUsage } from "@/lib/api/rate-limit";
import { serverErrorResponse } from "@/lib/api/errors";
import { generateContent } from "@/lib/content-generator";
import { getActiveProvider } from "@/lib/ai/provider-config";
import { resolveIteratedPrompt } from "@/lib/ai/iteration";
import { fetchBrandVoiceContext, brandVoiceToPromptContext } from "@/lib/content-studio/brand-voice";
import { runContentAction } from "@/lib/content-studio/actions";
import { createSseStreamHelpers } from "@/lib/api/sse-stream";
import { getContentToolLabel, getContentTypeLabel } from "@/lib/constants/content-studio";
import { resolveRequestLanguage } from "@/lib/i18n/api";
import type { ContentBlueprint } from "@/types/content";
import { NextResponse } from "next/server";
import { z } from "zod";

const streamSchema = z.discriminatedUnion("type", [
  z.object({
    type: z.literal("generate"),
    prompt: z.string().trim().min(5),
    contentTool: z.string().trim().min(1),
    contentType: z.string().trim().min(1),
    tone: z.string().trim().default("Professional"),
    audience: z.string().trim().default("General"),
    language: z.string().trim().default("English"),
    country: z.string().trim().optional(),
    brandVoice: z.string().trim().default(""),
    brandIdentityId: z.string().uuid().optional(),
    writingStyle: z.string().trim().default("Standard"),
    creativityLevel: z.string().trim().default("Balanced"),
    options: z.array(z.string().trim()).default([]),
    seoKeywords: z.string().trim().default(""),
    mode: z.enum(["generate", "regenerate", "continue", "rewrite", "expand", "shorten", "translate", "summarize"]).optional(),
    parentGenerationId: z.string().uuid().optional(),
    continueInstruction: z.string().trim().max(4000).optional(),
    projectId: z.string().uuid().optional(),
    documentId: z.string().uuid().optional(),
  }),
  z.object({
    type: z.literal("action"),
    action: z.enum(["rewrite", "improve", "expand", "shorten", "summarize", "translate", "change_tone", "change_style"]),
    text: z.string().trim().min(1).max(50000),
    tone: z.string().trim().optional(),
    style: z.string().trim().optional(),
    targetLanguage: z.string().trim().optional(),
    instruction: z.string().trim().max(2000).optional(),
    brandIdentityId: z.string().uuid().optional(),
  }),
]);

export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const usage = await beginAiUsage(auth.supabase, auth.user!.id, "content-studio");
  if (!usage.ok) return usage.response;
  const creditLease = usage.lease;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = streamSchema.safeParse(body);
  if (!parsed.success) {
    return apiValidationError(parsed.error.issues[0]?.message);
  }

  const input = parsed.data;
  const aiLanguage = resolveRequestLanguage(
    request,
    input.type === "generate" ? input.language : input.targetLanguage,
    input.type === "generate" ? input.country : undefined,
  );

  const stream = new ReadableStream({
    async start(controller) {
      const { send, close } = createSseStreamHelpers(controller, "content-studio-stream");

      try {
        if (input.type === "action") {
          send("progress", { stage: "action", message: `Running ${input.action}…` });

          let brandVoice = null;
          if (input.brandIdentityId) {
            brandVoice = await fetchBrandVoiceContext(
              auth.supabase!,
              auth.user!.id,
              input.brandIdentityId,
            );
          }

          let partial = "";
          const result = await runContentAction(
            {
              action: input.action,
              text: input.text,
              tone: input.tone,
              style: input.style,
              targetLanguage:
                input.action === "translate"
                  ? input.targetLanguage ?? aiLanguage
                  : input.targetLanguage,
              outputLanguage: input.action === "translate" ? undefined : aiLanguage,
              instruction: input.instruction,
              brandVoice,
            },
            (chunk) => {
              partial += chunk;
              send("token", { chunk, partial });
            },
          );

          send("complete", { result: result.text, action: result.action, provider: result.provider });
          await creditLease.settle(auth.supabase);
          close();
          return;
        }

        send("progress", { stage: "prepare", message: "Preparing generation…" });

        let brandVoiceText = input.brandVoice;
        if (input.brandIdentityId) {
          const voice = await fetchBrandVoiceContext(
            auth.supabase!,
            auth.user!.id,
            input.brandIdentityId,
          );
          if (voice) brandVoiceText = brandVoiceToPromptContext(voice);
        }

        const iterated = await resolveIteratedPrompt({
          supabase: auth.supabase!,
          table: "content_generations",
          userId: auth.user!.id,
          mode: input.mode,
          prompt: input.prompt,
          continueInstruction: input.continueInstruction,
          parentGenerationId: input.parentGenerationId,
          titleField: "title",
        });

        if (!iterated.ok) {
          send("error", { error: iterated.error });
          close();
          return;
        }

        const progressEvents: string[] = [];
        const result = await generateContent({
          prompt: iterated.prompt,
          contentTool: input.contentTool,
          contentType: input.contentType,
          tone: input.tone,
          audience: input.audience,
          language: aiLanguage,
          brandVoice: brandVoiceText,
          writingStyle: input.writingStyle,
          creativityLevel: input.creativityLevel,
          options: input.options,
          seoKeywords: input.seoKeywords,
          onProgress: (event) => {
            progressEvents.push(event);
            send("progress", { stage: "pipeline", message: event });
          },
        });

        const bodyChunks = result.body.match(/.{1,120}/g) ?? [result.body];
        let partial = "";
        for (const chunk of bodyChunks) {
          partial += chunk;
          send("token", { chunk, partial });
          await new Promise((r) => setTimeout(r, 8));
        }

        const blueprint: ContentBlueprint = {
          title: result.title,
          contentTool: input.contentTool,
          contentType: input.contentType,
          body: result.body,
          headlines: result.headlines,
          seo: result.seo,
          suggestions: result.suggestions,
          improvements: result.improvements,
          summary: result.summary,
          files: result.files,
          prompt: input.prompt,
          tone: input.tone,
          audience: input.audience,
          language: aiLanguage,
          writingStyle: input.writingStyle,
          creativityLevel: input.creativityLevel,
          generatedAt: new Date().toISOString(),
          progressEvents: [...result.progressEvents, "Saving…"],
        };

        send("progress", { stage: "save", message: "Saving generation…" });

        const row = {
          user_id: auth.user!.id,
          title: result.title || `${getContentToolLabel(input.contentTool)} — ${getContentTypeLabel(input.contentType)}`,
          content_tool: input.contentTool,
          content_type: input.contentType,
          description: result.summary || input.prompt,
          prompt: input.prompt,
          tone: input.tone,
          audience: input.audience,
          language: aiLanguage,
          brand_voice: brandVoiceText,
          writing_style: input.writingStyle,
          creativity_level: input.creativityLevel,
          options: input.options,
          seo_keywords: input.seoKeywords,
          blueprint: blueprint as unknown as Record<string, unknown>,
          status: "completed",
          mode: input.mode ?? "generate",
          provider: result.provider ?? getActiveProvider(),
          token_usage: result.usage,
          generation_time_ms: result.generationTimeMs,
          parent_generation_id: input.parentGenerationId ?? null,
          project_id: input.projectId ?? null,
        };

        const { data, error } = await auth.supabase!
          .from("content_generations")
          .insert(row)
          .select("*")
          .single();

        if (error) {
          await creditLease.release(auth.supabase);
          send("error", { error: "Failed to save generation." });
          close();
          return;
        }

        await creditLease.settle(auth.supabase);
        send("complete", {
          generation: data,
          blueprint,
          progressEvents,
        });
      } catch (error) {
        await creditLease.release(auth.supabase);
        send("error", {
          error: error instanceof Error ? error.message : "Stream failed",
        });
      } finally {
        close();
      }
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache, no-transform",
      Connection: "keep-alive",
    },
  });
}

import { requireUser, parseJsonBody } from "@/lib/api/helpers";
