import { generateBusinessIdeas } from "@/lib/ai/business-ideas";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { requireUser, parseJsonBody, paginationParams } from "@/lib/api/helpers";
import { databaseErrorResponse, serverErrorResponse } from "@/lib/api/errors";
import { beginAiUsage } from "@/lib/api/rate-limit";
import { buildMultiColumnIlikeOrFilter } from "@/lib/api/search-filters";
import {
  ideaInputSchema,
} from "@/lib/validations/ideas";
import { resolveRequestLanguage } from "@/lib/i18n/api";
import type { BusinessIdea } from "@/types/database";
import { NextResponse } from "next/server";

export async function GET(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { searchParams } = new URL(request.url);
  const { page, limit, from, to } = paginationParams(searchParams);
  const search = searchParams.get("search")?.trim();
  const favorite = searchParams.get("favorite");

  let query = auth.supabase
    .from("business_ideas")
    .select("*", { count: "exact" })
    .eq("user_id", auth.user!.id)
    .order("created_at", { ascending: false });

  const orFilter = buildMultiColumnIlikeOrFilter(
    ["title", "description", "industry"],
    search,
  );
  if (orFilter) {
    query = query.or(orFilter);
  }

  if (favorite === "true") query = query.eq("is_favorite", true);
  if (favorite === "false") query = query.eq("is_favorite", false);

  const { data, error, count } = await query.range(from, to);

  if (error) {
    return databaseErrorResponse("ideas.list", error);
  }

  const total = count ?? 0;

  return NextResponse.json({
    ideas: data as BusinessIdea[],
    page,
    limit,
    total,
    totalPages: Math.ceil(total / limit) || 1,
  });
}

export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const usage = await beginAiUsage(auth.supabase, auth.user!.id, "ideas");
  if (!usage.ok) return usage.response;
  const creditLease = usage.lease;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = ideaInputSchema.safeParse(body);
  if (!parsed.success) {
    return apiValidationError(parsed.error.issues[0]?.message);
  }

  const aiLanguage = resolveRequestLanguage(request, parsed.data.language, parsed.data.country);

  let generated;
  let source: string;
  try {
    const result = await generateBusinessIdeas({ ...parsed.data, language: aiLanguage });
    generated = result.ideas;
    source = result.source;
  } catch (error) {
    await creditLease.release(auth.supabase);
    return serverErrorResponse(
      "ideas.generate",
      error,
      error instanceof Error ? error.message : "AI idea generation failed.",
    );
  }

  const rows = generated.map((idea) => ({
    user_id: auth.user!.id,
    title: idea.title,
    description: idea.description,
    industry: idea.industry,
    target_market: idea.target_market,
    revenue_model: idea.revenue_model,
    is_favorite: false,
  }));

  const { data, error } = await auth.supabase
    .from("business_ideas")
    .insert(rows)
    .select("*");

  if (error) {
    await creditLease.release(auth.supabase);
    return databaseErrorResponse("ideas.insert", error);
  }

  await creditLease.settle(auth.supabase);
  return NextResponse.json({
    ideas: data as BusinessIdea[],
    message:
      source === "deepseek" || source === "openai" || source === "claude"
        ? "3 new ideas generated and saved with AI."
        : "3 new ideas generated and saved.",
  });
}

import { requireUser, parseJsonBody, parseUuidParam } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { beginAiUsage } from "@/lib/api/rate-limit";
import { serverErrorResponse } from "@/lib/api/errors";
import { blueprintToModel } from "@/lib/ai-core/image-design-platform/model";
import { runDesignImageEdit } from "@/lib/ai-core/image-design-platform/editing/pipeline";
import type { ImageEditOperation } from "@/lib/ai-core/image-design-platform/editing/types";
import { saveDesignAssets } from "@/lib/ai-core/image-design-platform/assets";
import type { ImageGeneration } from "@/types/image-generation";
import { NextResponse } from "next/server";
import { z } from "zod";
import { resolveRequestLanguage } from "@/lib/i18n/api";

type RouteContext = { params: Promise<{ id: string }> };

const editSchema = z.object({
  operation: z.enum([
    "background_removal",
    "enhance",
    "upscale",
    "variation",
    "object_replace",
  ]),
  assetId: z.string().optional(),
  prompt: z.string().optional(),
  scale: z.number().min(1).max(4).optional(),
  language: z.string().trim().optional(),
  country: z.string().trim().optional(),
});

export async function POST(request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const usage = await beginAiUsage(auth.supabase, auth.user!.id, "image-generator");
  if (!usage.ok) return usage.response;
  const creditLease = usage.lease;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = editSchema.safeParse(body);
  if (!parsed.success) {
    return apiValidationError(parsed.error.issues[0]?.message);
  }
  resolveRequestLanguage(request, parsed.data.language, parsed.data.country);

  const { data: gen, error } = await auth.supabase
    .from("image_generations")
    .select("*")
    .eq("id", id)
    .eq("user_id", auth.user!.id)
    .single();

  if (error || !gen?.blueprint) {
    return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Design not found");
  }

  const generation = gen as ImageGeneration;
  const model = blueprintToModel(generation.blueprint!);
  const source =
    (parsed.data.assetId
      ? model.rasterAssets.find((a) => a.id === parsed.data.assetId)
      : model.rasterAssets.find((a) => a.status === "completed")) ?? model.rasterAssets[0];

  if (!source) {
    return apiValidationError("No source image available for editing.");
  }

  try {
    const edited = await runDesignImageEdit({
      operation: parsed.data.operation as ImageEditOperation,
      sourceAsset: source,
      prompt: parsed.data.prompt,
      scale: parsed.data.scale,
    });

    const saved = await saveDesignAssets({
      supabase: auth.supabase,
      userId: auth.user!.id,
      generationId: id,
      assets: [edited.asset],
    });

    await creditLease.settle(auth.supabase);
    return NextResponse.json({
      asset: edited.asset,
      savedAssets: saved.assets,
      message: edited.message,
    });
  } catch (err) {
    return serverErrorResponse("image-generator.edit-image", err, "Unable to edit image.");
  }
}

