type RouteContext = { params: Promise<{ id: string }> };

export async function GET(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  try {
    const { data: gen, error } = await auth.supabase
      .from("image_generations")
      .select("*")
      .eq("id", id)
      .eq("user_id", auth.user!.id)
      .single();

    if (error || !gen) {
      return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Design not found");
    }

    const generation = gen as ImageGeneration;
    const templateId =
      typeof generation.blueprint?.templateId === "string"
        ? generation.blueprint.templateId
        : undefined;

    const loaded = await loadCanvasDocument({
      supabase: auth.supabase,
      userId: auth.user!.id,
      generationId: id,
      generationName: generation.image_name,
      blueprint: generation.blueprint,
      templateId,
    });

    return NextResponse.json({
      generation,
      canvas: loaded.canvas,
      document: loaded.document,
      templates: listCanvasTemplatesV2(),
      editOperations: listSupportedEditOperations(),
    });
  } catch (error) {
    return serverErrorResponse("image-generator.editor.get", error, "Unable to load editor.");
  }
}

import { requireUser, parseUuidParam } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { blueprintToModel, buildExportManifest, assetToBuffer, buildProjectExport, buildPdfFromCanvas } from "@/lib/ai-core/image-design-platform";
import { loadCanvasDocument } from "@/lib/ai-core/image-design-platform/canvas-repository";
import type { ImageGeneration } from "@/types/image-generation";
import { NextResponse } from "next/server";

type RouteContext = { params: Promise<{ id: string }> };

export async function GET(request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { searchParams } = new URL(request.url);
  const format = searchParams.get("format") ?? "json";

  const { data: gen, error } = await auth.supabase
    .from("image_generations")
    .select("*")
    .eq("id", id)
    .eq("user_id", auth.user!.id)
    .single();

  if (error || !gen?.blueprint) {
    return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Image not found");
  }

  const generation = gen as ImageGeneration;
  const model = blueprintToModel(generation.blueprint!);
  const loaded = await auth.supabase
    .from("design_canvas")
    .select("document")
    .eq("image_generation_id", id)
    .eq("user_id", auth.user!.id)
    .maybeSingle();
  const canvasDoc = loaded.data?.document ?? (
    await loadCanvasDocument({
      supabase: auth.supabase,
      userId: auth.user!.id,
      generationId: id,
      generationName: generation.image_name,
      blueprint: generation.blueprint,
    })
  ).document;

  const manifest = buildExportManifest(model);

  if (format === "project") {
    return NextResponse.json(buildProjectExport(canvasDoc));
  }

  if (format === "pdf") {
    const pdfBytes = await buildPdfFromCanvas(canvasDoc);
    return new NextResponse(Buffer.from(pdfBytes), {
      headers: {
        "Content-Type": "application/pdf",
        "Content-Disposition": `attachment; filename="${model.title.replace(/\s+/g, "-").toLowerCase()}.pdf"`,
      },
    });
  }

  if (format === "zip") {
    const JSZip = (await import("jszip")).default;
    const zip = new JSZip();
    for (const f of model.files) zip.file(f.path, f.content);
    for (const { path, asset } of manifest.rasterFiles) {
      const buf = assetToBuffer(asset);
      if (buf) zip.file(path, buf);
    }
    zip.file("prompt-library.json", JSON.stringify(model.promptLibrary, null, 2));
    zip.file("design-project.json", JSON.stringify(buildProjectExport(canvasDoc), null, 2));
    const blob = await zip.generateAsync({ type: "arraybuffer" });
    return new NextResponse(blob, {
      headers: {
        "Content-Type": "application/zip",
        "Content-Disposition": `attachment; filename="${model.title.replace(/\s+/g, "-").toLowerCase()}-design-kit.zip"`,
      },
    });
  }

  const raster = model.rasterAssets.find((a) => a.status === "completed");
  if (raster && (format === "png" || format === "jpg" || format === "webp")) {
    const buf = assetToBuffer(raster);
    if (buf) {
      const mime =
        format === "jpg" ? "image/jpeg" : format === "webp" ? "image/webp" : "image/png";
      return new NextResponse(new Uint8Array(buf), {
        headers: {
          "Content-Type": mime,
          "Content-Disposition": `attachment; filename="${model.title.replace(/\s+/g, "-").toLowerCase()}.${format}"`,
        },
      });
    }
  }

  return NextResponse.json({ model, manifest });
}

import { syncFavorite } from "@/lib/db/favorites";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { requireUser, parseJsonBody, parseUuidParam } from "@/lib/api/helpers";
import { databaseErrorResponse } from "@/lib/api/errors";
import type { ImageGeneration } from "@/types/image-generation";
import { NextResponse } from "next/server";
import { z } from "zod";

type RouteContext = { params: Promise<{ id: string }> };

const updateSchema = z.object({
  is_favorite: z.boolean().optional(),
  image_name: z.string().trim().min(1).max(120).optional(),
});

export async function GET(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { data, error } = await auth.supabase.from("image_generations").select("*").eq("id", id).eq("user_id", auth.user!.id).single();
  if (error || !data) return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Image not found");
  return NextResponse.json({ generation: data as ImageGeneration });
}

export async function PATCH(request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = updateSchema.safeParse(body);
  if (!parsed.success) return apiValidationError(parsed.error.issues[0]?.message);

  const { is_favorite, image_name } = parsed.data;

  const { data, error } = await auth.supabase
    .from("image_generations")
    .update({ ...(typeof is_favorite === "boolean" ? { is_favorite } : {}), ...(image_name ? { image_name } : {}), updated_at: new Date().toISOString() })
    .eq("id", id).eq("user_id", auth.user!.id).select("*").single();

  if (error || !data) return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Image not found");

  if (typeof is_favorite === "boolean") {
    const sync = await syncFavorite(auth.supabase, auth.user!.id, "image_generation", id, is_favorite);
    if (sync.error) return databaseErrorResponse("image-generator.syncFavorite", sync.error);
  }

  return NextResponse.json({ generation: data as ImageGeneration, message: "Updated." });
}

export async function POST(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { data: source, error: sourceError } = await auth.supabase.from("image_generations").select("*").eq("id", id).eq("user_id", auth.user!.id).single();
  if (sourceError || !source) return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Image not found");

  const { data, error } = await auth.supabase
    .from("image_generations")
    .insert({ user_id: auth.user!.id, image_name: `${source.image_name} (Copy)`, image_type: source.image_type, description: source.description, style: source.style, aspect_ratio: source.aspect_ratio, mood: source.mood, options: source.options, prompt: source.prompt, blueprint: source.blueprint, status: source.status, mode: "generate", is_favorite: false })
    .select("*").single();

  if (error || !data) return databaseErrorResponse("image-generator.duplicate", error);
  return NextResponse.json({ generation: data as ImageGeneration, message: "Duplicated." });
}

export async function DELETE(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  await syncFavorite(auth.supabase, auth.user!.id, "image_generation", id, false);
  const { data, error } = await auth.supabase.from("image_generations").delete().eq("id", id).eq("user_id", auth.user!.id).select("id").single();
  if (error || !data) return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Image not found");
  return NextResponse.json({ message: "Image deleted." });
}

import { requireUser, paginationParams } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse } from "@/lib/i18n/api-errors";
import { searchDesignAssets, listAssetFolders } from "@/lib/ai-core/image-design-platform/asset-library";
import { NextResponse } from "next/server";

export async function GET(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { searchParams } = new URL(request.url);
  const { page, limit, from, to } = paginationParams(searchParams);
  const query = searchParams.get("q") ?? searchParams.get("query") ?? undefined;
  const folder = searchParams.get("folder") ?? undefined;
  const favorite = searchParams.get("favorite");
  const generationId = searchParams.get("generationId") ?? undefined;
  const projectId = searchParams.get("projectId") ?? undefined;
  const tags = searchParams.get("tags")?.split(",").map((t) => t.trim()).filter(Boolean);
  const listFolders = searchParams.get("folders") === "true";

  if (listFolders) {
    const folders = await listAssetFolders({ supabase: auth.supabase, userId: auth.user!.id });
    if (folders.error) {
      return apiErrorResponse(API_ERROR_CODES.LOAD_FAILED, 500, folders.error);
    }
    return NextResponse.json({ folders: folders.folders });
  }

  const result = await searchDesignAssets({
    supabase: auth.supabase,
    userId: auth.user!.id,
    filters: {
      query,
      folder,
      tags,
      favorite: favorite === "true" ? true : favorite === "false" ? false : undefined,
      generationId,
      projectId,
      limit,
      offset: from,
    },
  });

  const total = result.total;
  if (result.error) {
    return apiErrorResponse(API_ERROR_CODES.LOAD_FAILED, 500, result.error);
  }
  return NextResponse.json({
    assets: result.assets,
    page,
    limit,
    total,
    totalPages: Math.ceil(total / limit) || 1,
  });
}

import { requireUser, parseJsonBody, paginationParams } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { databaseErrorResponse, serverErrorResponse } from "@/lib/api/errors";
import { beginAiUsage } from "@/lib/api/rate-limit";
import { buildMultiColumnIlikeOrFilter } from "@/lib/api/search-filters";
import { generateImage, modelToBlueprint } from "@/lib/image-generator";
import { getActiveProvider } from "@/lib/ai/provider-config";
import { resolveIteratedPrompt } from "@/lib/ai/iteration";
import { getImageTypeLabel } from "@/lib/constants/image-generator";
import { resolveRequestLanguage } from "@/lib/i18n/api";
import { getDesignTemplate } from "@/lib/ai-core/image-design-platform/templates";
import { brandTokensToContext } from "@/lib/ai-core/image-design-platform/model";
import {
  ensureDesignProject,
  saveDesignAssets,
  saveDesignGeneration,
} from "@/lib/ai-core/image-design-platform/assets";
import type { ImageProviderId, ImageQuality } from "@/lib/ai-core/assets/settings";
import type { ImageGeneration, ImageBlueprint } from "@/types/image-generation";
import { NextResponse } from "next/server";
import { z } from "zod";

const requestSchema = z.object({
  prompt: z.string().trim().min(5, "Describe your image in at least 5 characters."),
  negativePrompt: z.string().trim().default(""),
  imageType: z.string().trim().min(1, "Select an image type."),
  style: z.string().trim().default("Photorealistic"),
  aspectRatio: z.string().trim().default("1:1"),
  mood: z.string().trim().default("Professional"),
  options: z.array(z.string().trim()).default([]),
  batchCount: z.number().int().min(1).max(4).default(2),
  brandColors: z.array(z.string().trim()).default([]),
  mode: z.enum(["generate", "regenerate", "continue", "retry"]).optional(),
  parentGenerationId: z.string().uuid().optional(),
  continueInstruction: z.string().trim().max(4000).optional(),
  projectId: z.string().uuid().optional(),
  templateId: z.string().optional(),
  quality: z.enum(["standard", "hd"]).optional(),
  preferredProvider: z.enum(["openai", "replicate", "stability"]).optional(),
  seed: z.number().int().optional(),
  language: z.string().trim().optional(),
  country: z.string().trim().optional(),
  brandIdentity: z.object({
    brandName: z.string().optional(),
    primary: z.string().optional(),
    secondary: z.string().optional(),
    accent: z.string().optional(),
    headingFont: z.string().optional(),
    bodyFont: z.string().optional(),
    voiceTone: z.string().optional(),
    tagline: z.string().optional(),
  }).optional(),
});

function logError(stage: string, error: unknown) {
  const stack = error instanceof Error ? (error.stack ?? error.message) : JSON.stringify(error, null, 2);
  console.error(`[image-generator:${stage}]`, stack);
}

export async function GET(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { searchParams } = new URL(request.url);
  const { page, limit, from, to } = paginationParams(searchParams);
  const search = searchParams.get("search")?.trim();
  const favorite = searchParams.get("favorite");

  let query = auth.supabase
    .from("image_generations")
    .select("*", { count: "exact" })
    .eq("user_id", auth.user!.id)
    .order("created_at", { ascending: false });

  const orFilter = buildMultiColumnIlikeOrFilter(["image_name", "description", "image_type"], search);
  if (orFilter) query = query.or(orFilter);
  if (favorite === "true") query = query.eq("is_favorite", true);
  if (favorite === "false") query = query.eq("is_favorite", false);

  const { data, error, count } = await query.range(from, to);

  if (error) {
    if (error.code === "42P01" || (typeof error.message === "string" && error.message.includes("relation"))) {
      return NextResponse.json({ generations: [], page, limit, total: 0, totalPages: 1 });
    }
    return databaseErrorResponse("image-generator.list", error);
  }

  const total = count ?? 0;
  return NextResponse.json({
    generations: data as ImageGeneration[],
    page, limit, total,
    totalPages: Math.ceil(total / limit) || 1,
  });
}

export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const usage = await beginAiUsage(auth.supabase, auth.user!.id, "image-generator");
  if (!usage.ok) return usage.response;
  const creditLease = usage.lease;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = requestSchema.safeParse(body);
  if (!parsed.success) {
    return apiValidationError(parsed.error.issues[0]?.message);
  }

  const input = parsed.data;
  const aiLanguage = resolveRequestLanguage(request, input.language, input.country);
  const template = input.templateId ? getDesignTemplate(input.templateId) : undefined;
  const typeLabel = getImageTypeLabel(input.imageType);
  const brand = input.brandIdentity ? brandTokensToContext(input.brandIdentity) : undefined;
  let stage = "generateImage";

  try {
    const iterated = await resolveIteratedPrompt({
      supabase: auth.supabase,
      table: "image_generations",
      userId: auth.user!.id,
      mode: input.mode,
      prompt: input.prompt,
      continueInstruction: input.continueInstruction,
      parentGenerationId: input.parentGenerationId,
      titleField: "image_name",
    });
    if (!iterated.ok) {
      return apiErrorResponse(API_ERROR_CODES.SERVER_ERROR, iterated.status, iterated.error);
    }

    const result = await generateImage({
      prompt: iterated.prompt,
      negativePrompt: input.negativePrompt,
      imageType: template?.imageType || input.imageType,
      style: template?.style || input.style,
      aspectRatio: template?.aspectRatio || input.aspectRatio,
      mood: template?.mood || input.mood,
      options: template?.deliverables?.length ? template.deliverables : input.options,
      batchCount: input.batchCount,
      brandColors: input.brandColors,
      templateId: input.templateId,
      brand,
      quality: (input.quality ?? "standard") as ImageQuality,
      preferredProvider: input.preferredProvider as ImageProviderId | undefined,
      seed: input.seed,
      language: aiLanguage,
    });

    const blueprint: ImageBlueprint = result.model
      ? modelToBlueprint(result.model, input.prompt, input.negativePrompt)
      : {
      title: result.title,
      description: result.description,
      imageType: result.imageType,
      style: result.style,
      concepts: result.concepts,
      colorDirection: result.colorDirection,
      moodBoard: result.moodBoard,
      promptLibrary: result.promptLibrary,
      files: result.files,
      prompt: input.prompt,
      negativePrompt: input.negativePrompt,
      generatedAt: new Date().toISOString(),
    };
    blueprint.progressEvents = [...result.progressEvents, "Saving...", "Done."];

    stage = "supabase.insert.image_generations";

    const row = {
      user_id: auth.user!.id,
      image_name: result.title || `${typeLabel} Image`,
      image_type: input.imageType,
      description: result.description || input.prompt,
      style: input.style,
      aspect_ratio: input.aspectRatio,
      mood: input.mood,
      options: input.options,
      prompt: input.prompt,
      blueprint: blueprint as unknown as Record<string, unknown>,
      status: "completed",
      mode: input.mode ?? "generate",
      provider: result.provider ?? getActiveProvider(),
      token_usage: result.usage,
      generation_time_ms: result.generationTimeMs,
      parent_generation_id: input.parentGenerationId ?? null,
      project_id: input.projectId ?? null,
    };

    const { data, error } = await auth.supabase
      .from("image_generations")
      .insert(row)
      .select("*")
      .single();

    if (error) {
      if (error.code === "42P01" || (typeof error.message === "string" && error.message.includes("relation"))) {
        return apiErrorResponse(API_ERROR_CODES.MIGRATION_REQUIRED, 503, "Image Generator table not found. Please apply migration 017.");
      }
      logError(stage, error);
      return databaseErrorResponse("image-generator.insert", error);
    }

    const generation = data as ImageGeneration;
    let projectId = input.projectId ?? null;

    if (!projectId && result.model) {
      const project = await ensureDesignProject({
        supabase: auth.supabase,
        userId: auth.user!.id,
        name: generation.image_name,
        description: generation.description,
      });
      projectId = project.projectId;
    }

    if (result.model) {
      await saveDesignGeneration({
        supabase: auth.supabase,
        userId: auth.user!.id,
        imageGenerationId: generation.id,
        projectId,
        model: result.model,
        status: result.model.rasterAssets.some((a) => a.status === "completed") ? "completed" : "fallback",
        provider: result.model.providerUsed,
      });

      if (result.model.rasterAssets.length) {
        const saved = await saveDesignAssets({
          supabase: auth.supabase,
          userId: auth.user!.id,
          generationId: generation.id,
          projectId,
          assets: result.model.rasterAssets,
        });
        if (saved.assets.length && blueprint.model) {
          blueprint.rasterAssets = saved.assets.map((a, i) => ({
            ...(result.model!.rasterAssets[i] ?? result.model!.rasterAssets[0]!),
            storagePath: a.storage_path,
            publicUrl: a.public_url,
          }));
          blueprint.model = { ...result.model, rasterAssets: blueprint.rasterAssets };
          await auth.supabase
            .from("image_generations")
            .update({ blueprint: blueprint as unknown as Record<string, unknown> })
            .eq("id", generation.id);
        }
      }
    }

    await creditLease.settle(auth.supabase);
    return NextResponse.json({
      generation,
      message: result.model?.rasterAssets.some((a) => a.status === "completed")
        ? "Images generated and saved."
        : "Image concepts generated and saved.",
    });
  } catch (error) {
    logError(stage, error);
    return serverErrorResponse(stage, error, "Unable to generate image.");
  }
}

