    auth.supabase,
    auth.user!.id,
    "market_analysis",
    id,
    is_favorite,
  );
  if (favoriteSync.error) {
    return databaseErrorResponse("market-analysis.syncFavorite", favoriteSync.error);
  }

  return NextResponse.json({
    analysis: data as MarketAnalysis,
    message: is_favorite
      ? "Analysis added to favorites."
