export const dynamic = "force-dynamic";

type Params = { params: Promise<{ id: string }> };

const versionSchema = z.object({
  version: z.string().trim().min(1).max(32),
  changelog: z.string().trim().min(1).max(1000),
  premiumTemplateId: z.string().trim().max(80).optional(),
  marketplaceTemplateId: z.string().trim().max(120).optional(),
});

/**
 * POST — Add a new version to a creator-owned listing.
 */
export async function POST(request: Request, { params }: Params) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { id } = await params;
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return apiErrorResponse(API_ERROR_CODES.INVALID_JSON, 400);
  }

  const parsed = versionSchema.safeParse(body);
  if (!parsed.success) {
    return apiValidationError(parsed.error.issues[0]?.message);
  }

  try {
    const listing = versionCreatorTemplate({
      listingId: id,
      userId: auth.user!.id,
      ...parsed.data,
    });
    return NextResponse.json({ listing }, { status: 201 });
  } catch (err) {
    const message = err instanceof Error ? err.message : "Version failed";
    const status = message.includes("Not allowed") ? 403 : 404;
    const code = status === 403 ? API_ERROR_CODES.FORBIDDEN : API_ERROR_CODES.NOT_FOUND;
    return apiErrorResponse(code, status, message);
  }
}

import { requireUser } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { NextResponse } from "next/server";

export async function GET() {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const isAdmin = auth.user!.app_metadata?.role === "admin";
  if (!isAdmin) return apiErrorResponse(API_ERROR_CODES.FORBIDDEN, 403, "Unauthorized");

  const tables = [
    "profiles",
    "business_ideas",
    "content_generations",
    "business_generations",
    "website_generations",
    "logo_generations",
    "video_generations",
  ] as const;

  const countResults = await Promise.all(
    tables.map(async (table) => {
      try {
        const { count } = await auth.supabase
          .from(table)
          .select("*", { count: "exact", head: true });
        return [table, count ?? 0] as const;
      } catch {
        return [table, 0] as const;
      }
    }),
  );

  const stats: Record<string, number> = Object.fromEntries(countResults);

  let featureFlags: unknown[] = [];
  try {
    const { data } = await auth.supabase
      .from("feature_flags")
      .select("*")
      .order("created_at", { ascending: false });
    featureFlags = data ?? [];
  } catch {
    /* table may not exist */
  }

  return NextResponse.json({ stats, featureFlags, isAdmin: true });
}

import { requireUser, parseUuidParam } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { NextResponse } from "next/server";

type RouteContext = { params: Promise<{ id: string }> };

export async function DELETE(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { data, error } = await auth.supabase.from("api_keys").delete().eq("id", idParsed.id).eq("user_id", auth.user!.id).select("id").single();
  if (error || !data) return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "API key not found");
  return NextResponse.json({ message: "API key revoked." });
}

export async function PATCH(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { data: existing } = await auth.supabase.from("api_keys").select("is_active").eq("id", idParsed.id).eq("user_id", auth.user!.id).single();
  if (!existing) return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "API key not found");

  const { data, error } = await auth.supabase.from("api_keys").update({ is_active: !existing.is_active }).eq("id", idParsed.id).eq("user_id", auth.user!.id).select("*").single();
  if (error || !data) return apiErrorResponse(API_ERROR_CODES.SERVER_ERROR, 500, "Update failed");
  return NextResponse.json({ key: data, message: data.is_active ? "API key activated." : "API key deactivated." });
}

import { requireUser, parseJsonBody } from "@/lib/api/helpers";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { databaseErrorResponse } from "@/lib/api/errors";
import { enforceMutationRateLimit } from "@/lib/api/rate-limit";
import type { ApiKey } from "@/types/platform";
import { NextResponse } from "next/server";
import { z } from "zod";
import { createHash, randomBytes } from "crypto";

function generateApiKey(): { fullKey: string; prefix: string; hash: string } {
  const raw = randomBytes(30).toString("base64url");
  const fullKey = `tbai_${raw}`;
  const prefix = fullKey.slice(0, 12);
  const hash = createHash("sha256").update(fullKey).digest("hex");
  return { fullKey, prefix, hash };
}

const createSchema = z.object({
  name: z.string().trim().min(1, "Name is required").max(100),
  scopes: z.array(z.string()).default(["read"]),
  expiresInDays: z.number().int().min(0).max(365).optional(),
});

export async function GET() {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { data, error } = await auth.supabase
    .from("api_keys")
    .select("id, name, key_prefix, scopes, last_used_at, expires_at, is_active, created_at")
    .eq("user_id", auth.user!.id)
    .order("created_at", { ascending: false });

  if (error) {
    if (error.code === "42P01") return NextResponse.json({ keys: [] });
    return databaseErrorResponse("api-keys.list", error);
  }

  return NextResponse.json({ keys: data as Partial<ApiKey>[] });
}

export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const rl = enforceMutationRateLimit(auth.user!.id);
  if (rl) return rl;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = createSchema.safeParse(body);
  if (!parsed.success) return apiValidationError(parsed.error.issues[0]?.message);

  const { fullKey, prefix, hash } = generateApiKey();
  const expiresAt = parsed.data.expiresInDays
    ? new Date(Date.now() + parsed.data.expiresInDays * 86400000).toISOString()
    : null;

  const { data, error } = await auth.supabase.from("api_keys").insert({
    user_id: auth.user!.id,
    name: parsed.data.name,
    key_prefix: prefix,
    key_hash: hash,
    scopes: parsed.data.scopes,
    expires_at: expiresAt,
  }).select("id, name, key_prefix, scopes, expires_at, is_active, created_at").single();

  if (error) {
    if (error.code === "42P01") return apiErrorResponse(API_ERROR_CODES.MIGRATION_REQUIRED, 503, "API Keys table not ready. Apply migration 021.");
    return databaseErrorResponse("api-keys.create", error);
  }

  return NextResponse.json({ key: data, fullKey, message: "API key created. Copy it now — it won't be shown again." });
}

