import { listProviderJobsForProject } from "@/lib/ai-core/video-production-platform/persistence";
import { videoStudioCreditOperationId } from "@/lib/ai-core/video-production-platform/runtime/video-credits";
import { assertSafeRemoteFetchUrl, UnsafeRemoteUrlError } from "@/lib/website/url-safety";
import type { VideoGenerationStatus } from "@/types/video";
import { z } from "zod";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";
export const maxDuration = 300;

type Params = { params: Promise<{ id: string }> };

async function loadGeneration(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  supabase: any,
  userId: string,
  id: string,
) {
  const { data, error } = await supabase
    .from("video_generations")
    .select("*")
    .eq("id", id)
    .eq("user_id", userId)
    .maybeSingle();
  if (error) throw error;
  return data as VideoGeneration | null;
}

async function persist(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  supabase: any,
  userId: string,
  id: string,
  blueprint: VideoBlueprint,
  extra?: { video_name?: string; status?: VideoGenerationStatus },
) {
  const { data, error } = await supabase
    .from("video_generations")
    .update({
      blueprint,
      ...(extra?.video_name ? { video_name: extra.video_name } : {}),
      ...(extra?.status ? { status: extra.status } : {}),
      updated_at: new Date().toISOString(),
    })
    .eq("id", id)
    .eq("user_id", userId)
    .select("*")
    .single();
  if (error) throw error;
  return data as VideoGeneration;
}

export async function GET(_request: Request, { params }: Params) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { id: rawId } = await params;
  const parsedId = parseUuidParam(rawId, "generation id");
  if (parsedId instanceof NextResponse) return parsedId;

  try {
    const generation = await loadGeneration(
      auth.supabase,
      auth.user!.id,
      parsedId.id,
    );
    if (!generation) {
      return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Video not found.");
    }

    const model = extractProductionModel(generation.blueprint, {
      prompt: generation.prompt,
      style: generation.style,
      aspectRatio: generation.aspect_ratio,
      duration: generation.duration,
      videoType: generation.video_type,
    });
    const history = extractVideoVersionHistory(generation.blueprint);
    const job = getLatestJob(model);

    return NextResponse.json({
      generation,
      model,
      history,
      quality: runVideoQualityChecks(model),
      timeline: timelineSummary(model),
      visualTimeline: buildVisualTimeline(model),
      assembly: assemblyPlan(model),
      latestJob: job ? jobStatusSummary(job) : null,
      job,
    });
  } catch (error) {
    return serverErrorResponse(
      "video-studio.manage.get",
      error,
      "Unable to load video management data.",
    );
  }
}

const manageSchema = z.discriminatedUnion("action", [
