    action: z.literal("render"),
    mode: z.enum(["preview", "full", "avatar", "image-to-video"]).default("preview"),
    providerId: z.enum(["preview", "kling", "runway", "heygen", "external"]).optional(),
    sourceImageUrl: z.string().url().optional(),
    useAvatar: z.boolean().optional(),
  }),
  z.object({ action: z.literal("synthesize_voice"), real: z.boolean().optional() }),
  z.object({ action: z.literal("rebuild_subtitles") }),
  z.object({
    action: z.literal("apply_brand"),
    businessName: z.string().trim().min(1),
    primary: z.string().optional(),
    secondary: z.string().optional(),
    accent: z.string().optional(),
    logoUrl: z.string().nullable().optional(),
    headingFont: z.string().optional(),
    bodyFont: z.string().optional(),
    brandIdentityId: z.string().nullable().optional(),
  }),
  z.object({
    action: z.literal("reorder_scenes"),
    sceneIds: z.array(z.string()).min(1),
  }),
  z.object({
    action: z.literal("update_script"),
    sceneId: z.string().min(1),
    script: z.string(),
  }),
  z.object({
    action: z.literal("trim_scene"),
    sceneId: z.string().min(1),
    durationSec: z.number().min(1).max(600),
  }),
  z.object({
    action: z.literal("replace_visual"),
    sceneId: z.string().min(1),
    visualPrompt: z.string().min(3),
  }),
  z.object({
    action: z.literal("update_subtitles"),
    subtitles: z.array(
      z.object({
        timestamp: z.string(),
        text: z.string(),
        startSec: z.number().optional(),
        endSec: z.number().optional(),
      }),
    ),
  }),
  z.object({
    action: z.literal("replace_music"),
    name: z.string().min(1),
    genre: z.string().optional(),
    mood: z.string().optional(),
    bpm: z.string().optional(),
  }),
  z.object({
    action: z.literal("change_presenter"),
    personaId: z.enum([
      "fitness-trainer",
      "doctor",
      "teacher",
      "business-expert",
      "news-presenter",
      "sales-representative",
      "fashion-model",
      "chef",
      "automotive-expert",
      "real-estate-agent",
      "custom",
    ]),
  }),
  z.object({
    action: z.literal("generate_avatar"),
    personaId: z.enum([
      "fitness-trainer",
      "doctor",
      "teacher",
      "business-expert",
      "news-presenter",
      "sales-representative",
      "fashion-model",
      "chef",
      "automotive-expert",
      "real-estate-agent",
      "custom",
    ]),
    script: z.string().min(5).optional(),
    emotion: z.string().optional(),
  }),
  z.object({
    action: z.literal("change_voice"),
    style: z.string().min(1),
  }),
  z.object({
    action: z.literal("export_social"),
    presetId: z.enum([
      "tiktok",
      "instagram-reels",
      "youtube-shorts",
      "youtube",
      "linkedin",
    ]),
    persistAssets: z.boolean().optional().default(true),
    reencode: z.boolean().optional().default(true),
  }),
  z.object({ action: z.literal("platform_health") }),
  z.object({ action: z.literal("resume_render") }),
  z.object({
    action: z.literal("retry_clips"),
    useAvatar: z.boolean().optional(),
  }),
  z.object({
    action: z.literal("nudge_scene"),
    sceneId: z.string().min(1),
    direction: z.enum(["left", "right"]),
  }),
  z.object({
    action: z.literal("save_version"),
    note: z.string().trim().max(200).optional(),
  }),
  z.object({
    action: z.literal("restore_version"),
    versionId: z.string().min(1),
  }),
]);

export async function POST(request: Request, { params }: Params) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { id: rawId } = await params;
  const parsedId = parseUuidParam(rawId, "generation id");
  if (parsedId instanceof NextResponse) return parsedId;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = manageSchema.safeParse(body);
  if (!parsed.success) {
    return apiValidationError(parsed.error.issues[0]?.message);
  }

  getRequestAiLanguage(request);

  try {
    const generation = await loadGeneration(
      auth.supabase,
      auth.user!.id,
      parsedId.id,
    );
    if (!generation) {
      return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Video not found.");
    }

    let model = extractProductionModel(generation.blueprint, {
      prompt: generation.prompt,
      style: generation.style,
      aspectRatio: generation.aspect_ratio,
      duration: generation.duration,
      videoType: generation.video_type,
    });
    let history = extractVideoVersionHistory(generation.blueprint);
    const action = parsed.data;
    let creditAttempt: number | undefined;
    if (action.action === "render" && action.mode !== "preview") {
      const jobs = await listProviderJobsForProject(auth.supabase, parsedId.id);
      creditAttempt = jobs.length ? Math.max(...jobs.map((job) => job.attempt || 1)) : 1;
      const usage = await beginAiUsage(
        auth.supabase,
        auth.user!.id,
        "video-studio",
        videoStudioCreditOperationId({ kind: "render", projectId: parsedId.id, attempt: creditAttempt }),
      );
      if (!usage.ok) return usage.response;
    } else if (action.action === "resume_render" || action.action === "retry_clips") {
      const jobs = await listProviderJobsForProject(auth.supabase, parsedId.id);
      const maxAttempt = jobs.length ? Math.max(...jobs.map((job) => job.attempt || 1)) : 1;
      creditAttempt = action.action === "retry_clips" ? maxAttempt + 1 : maxAttempt;
      const usage = await beginAiUsage(
        auth.supabase,
        auth.user!.id,
        "video-studio",
        videoStudioCreditOperationId({ kind: "render", projectId: parsedId.id, attempt: creditAttempt }),
      );
      if (!usage.ok) return usage.response;
    }
    let message = "Updated.";
    let job = getLatestJob(model);
    let socialExport = undefined as ReturnType<typeof buildSocialExportPackage> | undefined;
    let avatarResult = undefined as Awaited<ReturnType<typeof requestAvatarPresenterClip>> | undefined;
    let platformHealth = undefined as Awaited<ReturnType<typeof probeFfmpegHealth>> | undefined;

    switch (action.action) {
      case "render": {
        if (action.sourceImageUrl) {
          try {
            await assertSafeRemoteFetchUrl(action.sourceImageUrl);
          } catch (error) {
            const msg =
              error instanceof UnsafeRemoteUrlError
                ? error.message
                : "Invalid source image URL.";
            return apiValidationError(msg);
          }
        }
        if (action.mode === "preview") {
          const result = startAndProcessRender(model, "preview");
          model = result.model;
          job = result.job;
          message = result.job.message;
        } else {
          const result = await runDomainRenderPipeline({
            model,
            supabase: auth.supabase,
            userId: auth.user!.id,
            generationId: parsedId.id,
            mode: action.mode === "avatar" || action.mode === "image-to-video" ? action.mode : "full",
            providerId: action.providerId,
            sourceImageUrl: action.sourceImageUrl,
            useAvatar: action.useAvatar || action.mode === "avatar",
            creditAttempt,
          });
          model = result.model;
          job = result.job;
          message = result.job.message;
        }
        break;
      }
      case "synthesize_voice": {
        if (action.real) {
          const script =
            model.voiceTracks[0]?.script ||
            model.scenes.map((s) => s.script).join("\n");
          const tts = await synthesizeSpeech({
            text: script,
            voiceId: model.presenter?.voiceId,
            language: model.language,
            style: model.presenter?.voiceStyle,
          });
          if (tts.bytes) {
            const uploaded = await uploadVideoStudioMedia({
              supabase: auth.supabase,
              userId: auth.user!.id,
              generationId: parsedId.id,
              kind: "audio",
              bytes: tts.bytes,
              mimeType: tts.mimeType,
              filename: `voice.${tts.mimeType.includes("mpeg") ? "mp3" : "wav"}`,
              durationSec: tts.durationSecEstimate,
              provider: tts.provider,
            });
            model = {
              ...model,
              voiceTracks: model.voiceTracks.map((v, i) =>
                i === 0
                  ? { ...v, status: "completed", asset: uploaded.asset }
                  : v,
              ),
              assets: [...model.assets, uploaded.asset],
              version: model.version + 1,
              updatedAt: new Date().toISOString(),
            };
            message = tts.message;
          } else {
            model = synthesizeVoicePreview(model);
            message = "TTS produced no bytes; used preview.";
          }
        } else {
          model = synthesizeVoicePreview(model);
          message = "Voice/audio tracks synthesized (preview).";
        }
        break;
      }
      case "rebuild_subtitles":
        model = rebuildSubtitlesFromScenes(model);
        message = "Subtitles rebuilt from scenes.";
        break;
      case "apply_brand":
        model = applyBrandToVideoModel(model, action);
        message = "Brand applied to video model.";
        break;
      case "reorder_scenes":
        model = editorReorder(model, action.sceneIds);
        message = "Timeline reordered.";
        break;
      case "update_script":
        model = editorUpdateScript(model, action.sceneId, action.script);
        message = "Scene script updated.";
        break;
      case "trim_scene": {
        model = editorTrimScene(model, action.sceneId, action.durationSec);
        const latest = getLatestJob(model);
        const clip = latest?.clips.find((c) => c.sceneId === action.sceneId);
        if (clip?.asset?.url) {
          const trimmed = await trimClipWithFfmpeg(
            clip.asset.url,
            action.durationSec,
          );
          if (trimmed) {
            const uploaded = await uploadVideoStudioMedia({
              supabase: auth.supabase,
              userId: auth.user!.id,
              generationId: parsedId.id,
              kind: "clip",
              bytes: trimmed,
              mimeType: "video/mp4",
              filename: `trim-${action.sceneId}.mp4`,
              durationSec: action.durationSec,
              provider: "ffmpeg-trim",
              meta: { sceneId: action.sceneId, trimmed: true },
            });
            model = {
              ...model,
              assets: [...model.assets, uploaded.asset],
              jobs: model.jobs.map((j) =>
                j.id === latest?.id
                  ? {
                      ...j,
                      clips: j.clips.map((c) =>
                        c.sceneId === action.sceneId
                          ? { ...c, asset: uploaded.asset }
                          : c,
                      ),
                    }
                  : j,
              ),
            };
            message = "Scene trimmed (duration + media).";
          } else {
            message = "Scene duration trimmed (ffmpeg trim unavailable).";
          }
        } else {
          message = "Scene trimmed.";
        }
        break;
      }
      case "replace_visual":
        model = editorReplaceSceneVisual(
          model,
          action.sceneId,
          action.visualPrompt,
        );
        message = "Scene visual replaced.";
        break;
      case "update_subtitles":
        model = editorUpdateSubtitles(model, action.subtitles);
        message = "Subtitles updated.";
        break;
      case "replace_music":
        model = editorReplaceMusic(model, action);
        message = "Music bed updated.";
        break;
      case "change_presenter":
        model = editorChangePresenter(model, action.personaId);
        message = "Presenter updated.";
        break;
      case "generate_avatar": {
        avatarResult = await requestAvatarPresenterClip({
          personaId: action.personaId,
          script:
            action.script ||
            model.scenes.map((s) => s.script).join(" ") ||
            model.title,
          language: model.language,
          emotion: action.emotion,
          aspectRatio: model.aspectRatio,
        });
        model = applyAvatarProfileToModel(model, avatarResult.profile);
        if (avatarResult.remoteUrl) {
          const bytes = await fetchRemoteVideoToBytes(avatarResult.remoteUrl);
          if (bytes) {
            const uploaded = await uploadVideoStudioMedia({
              supabase: auth.supabase,
              userId: auth.user!.id,
              generationId: parsedId.id,
              kind: "clip",
              bytes,
              mimeType: avatarResult.mimeType || "video/mp4",
              filename: `avatar-${action.personaId}.mp4`,
              provider: avatarResult.provider,
              meta: {
                avatar: true,
                externalJobId: avatarResult.externalJobId,
              },
            });
            model = {
              ...model,
              assets: [...model.assets, uploaded.asset],
            };
          }
        }
        message = avatarResult.message;
        break;
      }
      case "change_voice":
        model = editorChangeVoiceStyle(model, action.style);
        message = "Voice style updated.";
        break;
      case "export_social": {
        const exported = await reencodeForSocialPreset({
          supabase: auth.supabase,
          userId: auth.user!.id,
          generationId: parsedId.id,
          model,
          presetId: action.presetId,
          reencode: action.reencode !== false,
        });
        socialExport = exported.package;
        model = {
          ...model,
          assets: [
            ...model.assets,
            {
              id: exported.artifact.id || `export-${action.presetId}`,
              kind: "composite" as const,
              mimeType: exported.artifact.mimeType,
              url: exported.videoUrl,
              durationSec: exported.artifact.durationSec,
              width: exported.artifact.width,
              height: exported.artifact.height,
              provider: "ffmpeg",
              createdAt: new Date().toISOString(),
            },
          ],
        };
        message = exported.message;
        if (action.persistAssets !== false && socialExport) {
          const persisted = await persistSocialExportAssets({
            supabase: auth.supabase,
            userId: auth.user!.id,
            generationId: parsedId.id,
            package: socialExport,
          });
          message += ` Captions ${persisted.captionsAssetId ? "saved" : "inline"}.`;
        }
        break;
      }
      case "platform_health": {
        platformHealth = await probeFfmpegHealth();
        message = platformHealth.message;
        break;
      }
      case "resume_render": {
        const current = getLatestJob(model);
        if (!current) {
          return apiValidationError("No render job to resume.");
        }
        const resumed = await resumeDomainRender({
          model,
          supabase: auth.supabase,
          userId: auth.user!.id,
          generationId: parsedId.id,
          mode: current.mode === "preview" ? "full" : current.mode,
          providerId: current.provider,
          creditAttempt,
        });
        model = resumed.model;
        job = resumed.job;
        message = resumed.job.message;
        break;
      }
      case "retry_clips": {
        const retried = await retryDomainRender({
          model,
          supabase: auth.supabase,
          userId: auth.user!.id,
          generationId: parsedId.id,
          useAvatar: action.useAvatar,
          creditAttempt,
        });
        model = retried.model;
        job = retried.job;
        message = retried.job.message;
        break;
      }
      case "nudge_scene":
        model = editorNudgeScene(model, action.sceneId, action.direction);
        message = "Scene order updated.";
        break;
      case "save_version":
        history = saveVideoVersion(history, model, action.note);
        message = "Version saved.";
        break;
      case "restore_version": {
        const restored = restoreVideoVersion(history, action.versionId);
        if (!restored) {
          return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Version not found.");
        }
        model = restored.model;
        history = restored.history;
        message = "Version restored.";
        break;
      }
    }

    if (action.action !== "save_version" && action.action !== "platform_health") {
      history = saveVideoVersion(history, model, `After ${action.action}`);
    }

    if (action.action === "platform_health") {
      return NextResponse.json({
        message,
        model,
        history,
        quality: runVideoQualityChecks(model),
        timeline: timelineSummary(model),
        visualTimeline: buildVisualTimeline(model),
        assembly: assemblyPlan(model),
        latestJob: job ? jobStatusSummary(job) : null,
        job,
        ffmpeg: platformHealth,
        providers: listVideoProviders().map((p) => ({
          id: p.id,
          label: p.label,
          configured: p.configured,
          supportsImageToVideo: p.supportsImageToVideo,
          supportsAvatar: p.supportsAvatar,
        })),
      });
    }

    const blueprint = withProductionModel(
      (generation.blueprint || {}) as VideoBlueprint,
      model,
      history,
    ) as VideoBlueprint;

    const persistStatus =
      action.action === "render" && action.mode === "preview"
        ? job
          ? generationStatusAfterRenderJob({
              mode: job.mode,
              status: job.status,
              provider: job.provider,
              composite: job.compositeAsset,
              clips: (job.clips || []).map((c) => ({
                mimeType: c.asset?.mimeType,
                url: c.asset?.url,
                isStub: c.asset?.provider === "preview",
                durationSec: c.asset?.durationSec,
              })),
            })
          : STORYBOARD_READY_STATUS
        : undefined;

    const saved = await persist(
      auth.supabase,
      auth.user!.id,
      parsedId.id,
      blueprint,
      { video_name: model.title, status: persistStatus },
    );

    return NextResponse.json({
      message,
      generation: saved,
      model,
      history,
      quality: runVideoQualityChecks(model),
      timeline: timelineSummary(model),
      visualTimeline: buildVisualTimeline(model),
      assembly: assemblyPlan(model),
      latestJob: job ? jobStatusSummary(job) : null,
      job,
      socialExport,
      avatar: avatarResult,
      providers: listVideoProviders().map((p) => ({
        id: p.id,
        label: p.label,
        configured: p.configured,
        supportsImageToVideo: p.supportsImageToVideo,
        supportsAvatar: p.supportsAvatar,
      })),
    });
  } catch (error) {
    if (error instanceof ProviderNotConfiguredError) {
      return apiValidationError(error.message);
    }
    if (error instanceof ProductionExportError) {
      return apiValidationError(error.message);
    }
    return serverErrorResponse(
      "video-studio.manage.post",
      error,
      "Unable to update video project.",
    );
  }
}

import { syncFavorite } from "@/lib/db/favorites";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { requireUser, parseJsonBody, parseUuidParam } from "@/lib/api/helpers";
import { databaseErrorResponse } from "@/lib/api/errors";
import type { VideoGeneration } from "@/types/video";
import { NextResponse } from "next/server";
import { z } from "zod";
import { purgeGenerationMedia } from "@/lib/ai-core/video-production-platform";

type RouteContext = { params: Promise<{ id: string }> };

const updateSchema = z.object({
  is_favorite: z.boolean().optional(),
  video_name: z.string().trim().min(1).max(120).optional(),
});

export async function GET(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { data, error } = await auth.supabase.from("video_generations").select("*").eq("id", id).eq("user_id", auth.user!.id).single();
  if (error || !data) return apiErrorResponse(API_ERROR_CODES.VIDEO_NOT_FOUND, 404);
  return NextResponse.json({ generation: data as VideoGeneration });
}

export async function PATCH(request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = updateSchema.safeParse(body);
  if (!parsed.success) return apiValidationError(parsed.error.issues[0]?.message);

  const { is_favorite, video_name } = parsed.data;

  const { data, error } = await auth.supabase
    .from("video_generations")
    .update({ ...(typeof is_favorite === "boolean" ? { is_favorite } : {}), ...(video_name ? { video_name } : {}), updated_at: new Date().toISOString() })
    .eq("id", id).eq("user_id", auth.user!.id).select("*").single();

  if (error || !data) return apiErrorResponse(API_ERROR_CODES.VIDEO_NOT_FOUND, 404);

  if (typeof is_favorite === "boolean") {
    const sync = await syncFavorite(auth.supabase, auth.user!.id, "video_generation", id, is_favorite);
    if (sync.error) return databaseErrorResponse("video-studio.syncFavorite", sync.error);
  }

  return NextResponse.json({ generation: data as VideoGeneration, message: "Updated." });
}

export async function POST(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { data: source, error: srcErr } = await auth.supabase.from("video_generations").select("*").eq("id", id).eq("user_id", auth.user!.id).single();
  if (srcErr || !source) return apiErrorResponse(API_ERROR_CODES.VIDEO_NOT_FOUND, 404);

  const { data, error } = await auth.supabase
    .from("video_generations")
    .insert({ user_id: auth.user!.id, video_name: `${source.video_name} (Copy)`, video_type: source.video_type, description: source.description, style: source.style, aspect_ratio: source.aspect_ratio, duration: source.duration, options: source.options, prompt: source.prompt, blueprint: source.blueprint, status: source.status, mode: "generate", is_favorite: false })
    .select("*").single();

  if (error || !data) return databaseErrorResponse("video-studio.duplicate", error);
  return NextResponse.json({ generation: data as VideoGeneration, message: "Duplicated." });
}

export async function DELETE(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  await syncFavorite(auth.supabase, auth.user!.id, "video_generation", id, false);
  await purgeGenerationMedia({
    supabase: auth.supabase,
    userId: auth.user!.id,
    generationId: id,
  });
  const { data, error } = await auth.supabase.from("video_generations").delete().eq("id", id).eq("user_id", auth.user!.id).select("id").single();
  if (error || !data) return apiErrorResponse(API_ERROR_CODES.VIDEO_NOT_FOUND, 404);
  return NextResponse.json({ message: "Video deleted." });
}

import { NextResponse } from "next/server";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { z } from "zod";
import { requireUser, parseJsonBody } from "@/lib/api/helpers";
import { beginAiUsage } from "@/lib/api/rate-limit";
import { serverErrorResponse } from "@/lib/api/errors";
import { generateVideo } from "@/lib/video-generator";
import { getActiveProvider } from "@/lib/ai/provider-config";
import {
  planBatchVideos,
  batchItemToPluginInput,
  createBatchProgress,
  updateBatchProgressPercent,
  runFullRenderPipeline,
  withProductionModel,
  resolveBatchCreditLeaseAction,
  BATCH_PLAN_MAX,
  BATCH_GENERATE_MAX,
  ProviderNotConfiguredError,
} from "@/lib/ai-core/video-production-platform";
import type { VideoProductionModel } from "@/lib/ai-core/video-production-platform/types";
import type { VideoBlueprint, VideoGeneration } from "@/types/video";
import { generationStatusAfterRenderJob } from "@/lib/ai-core/video-production-platform/generation-status";
import { resolveRequestLanguage } from "@/lib/i18n/api";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";
export const maxDuration = 300;

const batchSchema = z.object({
  prompt: z.string().trim().min(5),
  count: z.number().int().min(1).max(BATCH_PLAN_MAX).default(5),
  durationSec: z.number().int().min(5).max(600).default(30),
  language: z.string().optional(),
  country: z.string().optional(),
  style: z.string().default("Cinematic"),
  platform: z.string().default("TikTok"),
  videoType: z.string().optional(),
  planOnly: z.boolean().optional().default(false),
  generateLimit: z
    .number()
    .int()
    .min(1)
    .max(BATCH_GENERATE_MAX)
    .optional()
    .default(5),
  fullRender: z.boolean().optional().default(false),
  varyTalent: z.boolean().optional().default(true),
  /** Skip first N planned items (for chunked 50/100 generation) */
  offset: z.number().int().min(0).max(BATCH_PLAN_MAX).optional().default(0),
});

/**
 * POST — plan (and optionally generate) a batch of videos.
 * Credits: settle-after-success for this request lease (1 credit) when at least one
 * item is successfully generated. planOnly does not charge. Failures release (no-op
 * if never settled). Chunked retries are separate requests with their own leases.
 */
export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const usage = await beginAiUsage(
    auth.supabase,
    auth.user!.id,
    "video-studio",
  );
  if (!usage.ok) return usage.response;
  const creditLease = usage.lease;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) {
    await creditLease.release(auth.supabase);
    return body;
  }

  const parsed = batchSchema.safeParse(body);
  if (!parsed.success) {
    await creditLease.release(auth.supabase);
    return apiValidationError(parsed.error.issues[0]?.message);
  }

  const req = {
    ...parsed.data,
    language: resolveRequestLanguage(request, parsed.data.language, parsed.data.country),
  };
  const planned = planBatchVideos(req);
  let progress = createBatchProgress(
    planned.batchId,
    planned.items,
    planned.estimatedCredits,
  );

  if (req.planOnly) {
    // planOnly never settles (see resolveBatchCreditLeaseAction)
    await creditLease.release(auth.supabase);
    return NextResponse.json({
      batchId: planned.batchId,
      items: planned.items,
      estimatedCredits: planned.estimatedCredits,
      variation: planned.variation,
      progress,
      message: `Planned ${planned.items.length} videos (~${planned.estimatedCredits} credits).`,
    });
  }

  const toGenerate = planned.items.slice(
    req.offset,
    req.offset + req.generateLimit,
  );
  const generations: VideoGeneration[] = [];

  try {
    for (const item of toGenerate) {
      progress = {
        ...progress,
        items: progress.items.map((p) =>
          p.index === item.index ? { ...p, status: "generating" } : p,
        ),
        pending: Math.max(0, progress.pending - 1),
      };

      try {
        const pluginInput = batchItemToPluginInput(req, item);
        const result = await generateVideo(pluginInput);
        let productionModel: VideoProductionModel | undefined = result.productionModel
          ? {
              ...result.productionModel,
              batchMeta: {
                batchId: planned.batchId,
                index: item.index,
                total: planned.items.length,
              },
            }
          : undefined;

        const blueprint: VideoBlueprint = {
          title: result.title || item.title,
          description: result.description,
          videoType: result.videoType,
          style: result.style,
          aspectRatio: pluginInput.aspectRatio,
          totalDuration: pluginInput.duration,
          scenes: result.scenes,
          script: result.script,
          voiceoverScript: result.voiceoverScript,
          musicSuggestions: result.musicSuggestions,
          subtitles: result.subtitles,
          thumbnailSvg: result.thumbnailSvg,
          colorGrade: result.colorGrade,
          exportPreset: "1080p",
          files: result.files,
          prompt: pluginInput.prompt,
          generatedAt: new Date().toISOString(),
          progressEvents: result.progressEvents,
          productionModel,
          versionHistory: result.versionHistory,
        };

        const { data, error } = await auth.supabase
          .from("video_generations")
          .insert({
            user_id: auth.user!.id,
            video_name: blueprint.title,
            video_type: pluginInput.videoType,
            description: blueprint.description || item.idea,
            style: pluginInput.style,
            aspect_ratio: pluginInput.aspectRatio,
            duration: pluginInput.duration,
            options: pluginInput.options,
            prompt: pluginInput.prompt,
            blueprint,
            status: "storyboard_ready",
            mode: "generate",
            provider: result.provider ?? getActiveProvider(),
            token_usage: result.usage,
            generation_time_ms: result.generationTimeMs,
          })
          .select("*")
          .single();

        if (error || !data) {
          progress = {
            ...progress,
            failed: progress.failed + 1,
            items: progress.items.map((p) =>
              p.index === item.index
                ? { ...p, status: "failed", error: error?.message || "insert failed" }
                : p,
            ),
          };
          continue;
        }

        let generation = data as VideoGeneration;

        if (req.fullRender && productionModel) {
          try {
            const rendered = await runFullRenderPipeline({
              model: productionModel,
              supabase: auth.supabase,
              userId: auth.user!.id,
              generationId: generation.id,
              mode: "batch-item",
            });
            productionModel = rendered.model;
            const nextBp = withProductionModel(
              blueprint,
              productionModel,
              result.versionHistory,
            ) as VideoBlueprint;
            const nextStatus = generationStatusAfterRenderJob({
              mode: rendered.job.mode,
              status: rendered.job.status,
              provider: rendered.job.provider,
              composite: rendered.job.compositeAsset,
              clips: (rendered.job.clips || []).map((c) => ({
                mimeType: c.asset?.mimeType,
                url: c.asset?.url,
                isStub: c.asset?.provider === "preview",
                durationSec: c.asset?.durationSec,
              })),
            });
            const { data: updated } = await auth.supabase
              .from("video_generations")
              .update({
                blueprint: nextBp,
                status: nextStatus,
                updated_at: new Date().toISOString(),
              })
              .eq("id", generation.id)
              .select("*")
              .single();
            if (updated) generation = updated as VideoGeneration;
          } catch (renderError) {
            if (!(renderError instanceof ProviderNotConfiguredError)) {
              throw renderError;
            }
          }
        }

        generations.push(generation);
        progress = updateBatchProgressPercent({
          ...progress,
          completed: progress.completed + 1,
          spentCredits: progress.spentCredits + 1,
          items: progress.items.map((p) =>
            p.index === item.index
              ? { ...p, status: "completed", generationId: generation.id }
              : p,
          ),
        });
      } catch (itemError) {
        progress = updateBatchProgressPercent({
          ...progress,
          failed: progress.failed + 1,
          items: progress.items.map((p) =>
            p.index === item.index
              ? {
                  ...p,
                  status: "failed",
                  error:
                    itemError instanceof Error
                      ? itemError.message
                      : "generation failed",
                }
              : p,
          ),
        });
      }
    }

    if (resolveBatchCreditLeaseAction({
      planOnly: false,
      successfulGenerations: generations.length,
    }) === "settle") {
      await creditLease.settle(auth.supabase);
    } else {
      await creditLease.release(auth.supabase);
    }

    return NextResponse.json({
      batchId: planned.batchId,
      planned: planned.items,
      generated: generations,
      progress: updateBatchProgressPercent(progress),
      variation: planned.variation,
      estimatedCredits: planned.estimatedCredits,
      message: `Generated ${generations.length} of ${planned.items.length} planned videos (offset ${req.offset}, limit ${req.generateLimit}).`,
      nextOffset:
        req.offset + generations.length < planned.items.length
          ? req.offset + req.generateLimit
          : null,
    });
  } catch (error) {
    await creditLease.release(auth.supabase);
    return serverErrorResponse(
      "video-studio.batch",
      error,
      "Batch video generation failed.",
    );
  }
}

import { NextResponse } from "next/server";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { createAdminClient } from "@/lib/supabase/admin";
import { serverErrorResponse } from "@/lib/api/errors";
import { processVideoStudioBackgroundQueue } from "@/lib/ai-core/video-production-platform";
import { authorizeVideoStudioCron } from "@/lib/ai-core/video-production-platform/runtime/cron-auth";
import { validateVideoStudioProductionEnv } from "@/lib/ai-core/video-production-platform/env-config";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";
export const maxDuration = 300;

/**
 * Platform worker: processes due jobs across tenants using the service role.
 * Authenticated dashboard users must use `/api/video-studio/jobs`, which is
 * always scoped to the caller. This route is not a tenant session.
 */
async function runWorker(request: Request) {
  if (!authorizeVideoStudioCron(request)) {
    return apiErrorResponse(API_ERROR_CODES.UNAUTHORIZED, 401, "Unauthorized. Set VIDEO_STUDIO_CRON_SECRET and pass Bearer token.");
  }

  const productionEnv = validateVideoStudioProductionEnv();
  if (productionEnv.production && !productionEnv.ok) {
    return apiErrorResponse(
      API_ERROR_CODES.PROVIDER_UNAVAILABLE,
      503,
      productionEnv.blockers[0] || "Video Studio production configuration is incomplete.",
      productionEnv.blockers.join(" "),
    );
  }

  const admin = createAdminClient();
  if (!admin) {
    return apiErrorResponse(
      API_ERROR_CODES.MIGRATION_REQUIRED,
      503,
      "SUPABASE_SERVICE_ROLE_KEY required for background render worker.",
    );
  }

  try {
    const url = new URL(request.url);
    const limit = Math.min(
      20,
      Math.max(1, Number.parseInt(url.searchParams.get("limit") || "10", 10) || 10),
    );
    const retryFailed = url.searchParams.get("retryFailed") !== "false";

    const result = await processVideoStudioBackgroundQueue({
      supabase: admin,
      limit,
      pollRounds: 24,
      retryFailed,
      maxRetryAttempts: 3,
    });

    return NextResponse.json({
      message: `Video Studio worker processed ${result.processed} job(s).`,
      ...result,
    });
  } catch (error) {
    return serverErrorResponse(
      "video-studio.cron",
      error,
      "Video Studio background worker failed.",
    );
  }
}

export async function GET(request: Request) {
  return runWorker(request);
}

export async function POST(request: Request) {
  return runWorker(request);
}

import { NextResponse } from "next/server";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { z } from "zod";
import { requireUser, parseJsonBody } from "@/lib/api/helpers";
import { beginAiUsage } from "@/lib/api/rate-limit";
import { serverErrorResponse } from "@/lib/api/errors";
import { generateVideo } from "@/lib/video-generator";
import { getActiveProvider } from "@/lib/ai/provider-config";
import {
  buildImageToVideoBrief,
  attachSourceImageToModel,
  runFullRenderPipeline,
  withProductionModel,
  ProviderNotConfiguredError,
} from "@/lib/ai-core/video-production-platform";
import type { VideoBlueprint, VideoGeneration } from "@/types/video";
import {
  generationStatusAfterStoryboard,
  generationStatusAfterRenderJob,
  storyboardGeneratedMessage,
  videoRenderedMessage,
} from "@/lib/ai-core/video-production-platform/generation-status";
import { assertSafeRemoteFetchUrl, UnsafeRemoteUrlError } from "@/lib/website/url-safety";
import { resolveRequestLanguage } from "@/lib/i18n/api";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";
export const maxDuration = 300;

const schema = z.object({
  imageUrl: z.string().url(),
  prompt: z.string().trim().min(5),
  motion: z.string().optional(),
  cameraMove: z.string().optional(),
  duration: z.string().optional(),
  aspectRatio: z.string().optional(),
  kind: z.enum(["product", "person", "scene"]).optional(),
  intensity: z.enum(["subtle", "medium", "dynamic"]).optional(),
  render: z.boolean().optional().default(true),
  providerId: z.enum(["kling", "runway", "heygen", "external"]).optional(),
  language: z.string().trim().optional(),
  country: z.string().trim().optional(),
});

/**
 * POST — Image to Video: upload URL → concept package → optional real render.
 */
export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const usage = await beginAiUsage(
    auth.supabase,
    auth.user!.id,
    "video-studio",
  );
  if (!usage.ok) return usage.response;
  const creditLease = usage.lease;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = schema.safeParse(body);
  if (!parsed.success) {
    return apiValidationError(parsed.error.issues[0]?.message);
  }

  try {
    try {
      await assertSafeRemoteFetchUrl(parsed.data.imageUrl);
    } catch (error) {
      const message =
        error instanceof UnsafeRemoteUrlError ? error.message : "Invalid image URL.";
      return apiValidationError(message);
    }

    const aiLanguage = resolveRequestLanguage(request, parsed.data.language, parsed.data.country);
    const brief = buildImageToVideoBrief({
      ...parsed.data,
      language: aiLanguage,
    });
    const result = await generateVideo(brief.pluginInput);

    let productionModel = result.productionModel
      ? attachSourceImageToModel(
          result.productionModel,
          parsed.data.imageUrl,
          parsed.data.kind,
        )
      : undefined;

    const blueprint: VideoBlueprint = {
      title: result.title,
      description: result.description,
      videoType: "image-to-video",
      style: result.style,
      aspectRatio: brief.pluginInput.aspectRatio,
      totalDuration: brief.pluginInput.duration,
      scenes: result.scenes,
      script: result.script,
      voiceoverScript: result.voiceoverScript,
      musicSuggestions: result.musicSuggestions,
      subtitles: result.subtitles,
      thumbnailSvg: result.thumbnailSvg,
      colorGrade: result.colorGrade,
      exportPreset: "1080p",
      files: result.files,
      prompt: brief.pluginInput.prompt,
      generatedAt: new Date().toISOString(),
      progressEvents: result.progressEvents,
      productionModel,
      versionHistory: result.versionHistory,
    };

    const { data, error } = await auth.supabase
      .from("video_generations")
      .insert({
        user_id: auth.user!.id,
        video_name: blueprint.title,
        video_type: "image-to-video",
        description: blueprint.description,
        style: brief.pluginInput.style,
        aspect_ratio: brief.pluginInput.aspectRatio,
        duration: brief.pluginInput.duration,
        options: brief.pluginInput.options,
        prompt: brief.pluginInput.prompt,
        blueprint,
        status: generationStatusAfterStoryboard(),
        mode: "generate",
        provider: result.provider ?? getActiveProvider(),
        token_usage: result.usage,
        generation_time_ms: result.generationTimeMs,
      })
      .select("*")
      .single();

    if (error || !data) {
      return apiErrorResponse(API_ERROR_CODES.SERVER_ERROR, 500, error?.message || "Insert failed");
    }

    let generation = data as VideoGeneration;
    let job = null;

    if (parsed.data.render && productionModel) {
      try {
        const rendered = await runFullRenderPipeline({
          model: productionModel,
          supabase: auth.supabase,
          userId: auth.user!.id,
          generationId: generation.id,
          mode: "image-to-video",
          providerId: parsed.data.providerId,
          sourceImageUrl: parsed.data.imageUrl,
        });
        productionModel = rendered.model;
        job = rendered.job;
        const nextBlueprint = withProductionModel(
          blueprint,
          productionModel,
          result.versionHistory,
        ) as VideoBlueprint;
        const nextStatus = generationStatusAfterRenderJob({
          mode: job.mode,
          status: job.status,
          provider: job.provider,
          composite: job.compositeAsset,
          clips: (job.clips || []).map((c) => ({
            mimeType: c.asset?.mimeType,
            url: c.asset?.url,
            isStub: c.asset?.provider === "preview",
            durationSec: c.asset?.durationSec,
          })),
        });
        const { data: updated } = await auth.supabase
          .from("video_generations")
          .update({
            blueprint: nextBlueprint,
            status: nextStatus,
            updated_at: new Date().toISOString(),
          })
          .eq("id", generation.id)
          .eq("user_id", auth.user!.id)
          .select("*")
          .single();
        if (updated) generation = updated as VideoGeneration;
      } catch (renderError) {
        if (!(renderError instanceof ProviderNotConfiguredError)) {
          throw renderError;
        }
        job = null;
      }
    }

    const playableVideo = generation.status === "video_rendered";
    await creditLease.settle(auth.supabase);
    return NextResponse.json({
      generation,
      job,
      outputKind: playableVideo ? "video" : "storyboard",
      playableVideo,
      message: playableVideo
        ? videoRenderedMessage()
        : parsed.data.render && !job
          ? `${storyboardGeneratedMessage()} Image-to-video render blocked: video provider is not configured.`
          : job && job.status === "failed"
            ? `Storyboard saved. Render failed: ${job.message}`
            : storyboardGeneratedMessage(),
      templateId: brief.templateId,
    });
  } catch (error) {
    return serverErrorResponse(
      "video-studio.image-to-video",
      error,
      "Unable to create image-to-video.",
    );
  }
}

import { NextResponse } from "next/server";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { requireUser, parseJsonBody } from "@/lib/api/helpers";
import { serverErrorResponse } from "@/lib/api/errors";
import {
  processPendingRenderJobs,
  processVideoStudioBackgroundQueue,
} from "@/lib/ai-core/video-production-platform";
import { z } from "zod";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";
export const maxDuration = 300;

const schema = z.object({
  limit: z.number().int().min(1).max(20).optional().default(5),
  /** Resume queued/processing jobs and retry recent failures */
  fullQueue: z.boolean().optional().default(false),
  retryFailed: z.boolean().optional().default(true),
});

/**
 * POST — resume processing/queued render jobs for the authenticated tenant only.
 * Cross-tenant drains are not allowed here. The secret-gated cron worker owns
 * platform-wide polling (`POST /api/video-studio/cron`).
 */
export async function POST(request: Request) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = schema.safeParse(body ?? {});
  if (!parsed.success) {
    return apiValidationError(parsed.error.issues[0]?.message);
  }

  const userId = auth.user!.id;

  try {
    if (parsed.data.fullQueue) {
      const result = await processVideoStudioBackgroundQueue({
        supabase: auth.supabase,
        userId,
        limit: parsed.data.limit,
        pollRounds: 16,
        retryFailed: parsed.data.retryFailed,
      });
      return NextResponse.json({
        message: `Processed ${result.processed} render job(s) (${result.resumed} resumed, ${result.retried} retried).`,
        ...result,
      });
    }

    const result = await processPendingRenderJobs({
      supabase: auth.supabase,
      userId,
      limit: parsed.data.limit,
      pollRounds: 12,
    });

    return NextResponse.json({
      message: `Processed ${result.processed} render job(s).`,
      ...result,
    });
  } catch (error) {
    return serverErrorResponse(
      "video-studio.jobs.process",
      error,
      "Unable to process render jobs.",
    );
  }
}

/**
 * GET — list recent render jobs for the user.
 */
export async function GET() {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  try {
    const { data, error } = await auth.supabase
      .from("video_render_jobs")
      .select("id,generation_id,status,provider,mode,progress,updated_at,created_at")
      .eq("user_id", auth.user!.id)
      .order("updated_at", { ascending: false })
      .limit(40);

    if (error) {
      if (
        error.code === "42P01" ||
        (typeof error.message === "string" && error.message.includes("relation"))
      ) {
        return NextResponse.json({
          jobs: [],
          message: "Apply migration 044_video_studio_media.sql for render jobs.",
        });
      }
      return apiErrorResponse(API_ERROR_CODES.SERVER_ERROR, 500, error.message);
    }

    return NextResponse.json({ jobs: data ?? [] });
  } catch (error) {
    return serverErrorResponse(
      "video-studio.jobs.list",
      error,
      "Unable to list render jobs.",
    );
  }
}

import { NextResponse } from "next/server";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import {
  searchVideoTemplates,
  templateCatalogStats,
  listMarketplaceIndustries,
  getVideoTemplate,
  VIDEO_PRESENTER_PERSONAS,
  VIDEO_LOCATIONS,
  VIDEO_CONTENT_TYPES,
} from "@/lib/ai-core/video-production-platform";

export const dynamic = "force-dynamic";

/**
 * GET — Template marketplace catalog (Video Studio only).
 * Query: q, industry, contentType, presenter, location, limit, offset, templateId
 */
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const templateId = searchParams.get("templateId");

  if (templateId) {
    const template = getVideoTemplate(templateId);
    if (!template) {
      return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Template not found.");
    }
    return NextResponse.json({ template });
  }

  const result = searchVideoTemplates({
    q: searchParams.get("q") || undefined,
    industry: searchParams.get("industry") || undefined,
    contentType: (searchParams.get("contentType") as never) || undefined,
    presenter: (searchParams.get("presenter") as never) || undefined,
    location: (searchParams.get("location") as never) || undefined,
    limit: Number(searchParams.get("limit") || 40),
    offset: Number(searchParams.get("offset") || 0),
  });

  return NextResponse.json({
    stats: templateCatalogStats(),
    filters: {
