/**
 * POST — mutate structured app model without regenerating source.
 */
export async function POST(request: Request, { params }: Params) {
  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { id: rawId } = await params;
  const parsedId = parseUuidParam(rawId, "generation id");
  if (parsedId instanceof NextResponse) return parsedId;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = manageSchema.safeParse(body);
  if (!parsed.success) {
    return apiValidationError(parsed.error.issues[0]?.message);
  }

  try {
    const generation = await loadGeneration(
      auth.supabase,
      auth.user!.id,
      parsedId.id,
    );
    if (!generation) {
      return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "App not found.");
    }

    let model = extractAppModelFromBlueprint(generation.blueprint, {
      prompt: generation.prompt,
      appType: generation.app_type,
      language: generation.language,
      designStyle: generation.design_style,
      colorStyle: generation.color_style,
      features: generation.features,
      appName: generation.app_name,
    });
    let history = extractVersionHistory(generation.blueprint);
    const action = parsed.data;
    let assistantResult = undefined as AppAssistantAgentResult | undefined;
    let compare = undefined as ReturnType<typeof compareAppVersions> | undefined;
    let editor = createVisualEditorState(model);
    let preview = buildAppPreviewPayload(model);
    let persist = true;
    let syncFiles = false;
    let message = "App updated.";
    let blueprintFiles = generation.blueprint?.files ?? [];

    switch (action.action) {
      case "update_settings":
        model = updateAppSettings(model, {
          appName: action.appName,
          tagline: action.tagline,
          language: action.language,
          currency: action.currency,
          logoUrl: action.logoUrl,
        });
        syncFiles = true;
        message = "Settings updated.";
        break;
      case "upsert_catalog":
        model = upsertCatalogItem(model, action.item);
        syncFiles = true;
        message = "Catalog item saved.";
        break;
      case "delete_catalog":
        model = deleteCatalogItem(model, action.itemId);
        syncFiles = true;
        message = "Catalog item removed.";
        break;
      case "add_screen":
        model = addScreen(model, {
          name: action.name,
          path: action.path.startsWith("/") ? action.path : `/${action.path}`,
          purpose: action.purpose,
        });
        syncFiles = true;
        message = "Screen added.";
        break;
      case "remove_screen":
        model = removeScreen(model, action.screenId);
        syncFiles = true;
        message = "Screen removed.";
        break;
      case "apply_brand":
        model = applyBrandKitToModel(model, {
          name: action.name || model.brand.businessName,
          primary: action.primary,
          secondary: action.secondary,
          accent: action.accent,
          logoUrl: action.logoUrl,
          displayFont: action.displayFont,
          bodyFont: action.bodyFont,
          brandIdentityId: action.brandIdentityId,
        });
        syncFiles = true;
        message = "Brand applied.";
        break;
      case "assistant":
        assistantResult = await runAppAssistantAgent({
          message: action.message,
          model,
          files: blueprintFiles,
          syncFiles: true,
        });
        if (assistantResult.applied && assistantResult.model) {
          model = assistantResult.model;
          if (assistantResult.files) blueprintFiles = assistantResult.files;
          syncFiles = true;
          message = assistantResult.actions.join("; ") || "Assistant applied changes.";
        } else {
          persist = false;
          message = assistantResult.notes[0] || "No changes applied.";
        }
        break;
      case "save_version":
        history = saveAppVersion(history, model, action.note);
        message = "Version saved.";
        break;
      case "restore_version": {
        const restored = restoreAppVersion(history, action.versionId);
        if (!restored) {
          return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Version not found.");
        }
        model = restored.model;
        history = restored.history;
        message = "Version restored.";
        break;
      }
      case "compare_versions":
        compare = compareAppVersions(history, action.aId, action.bId);
        persist = false;
        message = "Comparison ready.";
        break;
      case "editor_select_screen":
        editor = selectScreen(model, editor, action.screenId);
        persist = false;
        message = "Screen selected.";
        break;
      case "editor_update_props":
        editor = selectScreen(model, editor, action.screenId);
        editor = updateNodeProps(editor, action.nodeId, action.props);
        model = applyEditorTreeToModel(model, editor);
        syncFiles = true;
        message = "Component props updated.";
        break;
      case "preview":
        preview = buildAppPreviewPayload(
          model,
          action.device,
          action.screenId ?? null,
        );
        persist = false;
        message = "Preview ready.";
        break;
      case "editor_add_component": {
        const added = addComponentToScreen(model, action.screenId, action.componentType);
        model = added.model;
        editor = selectScreen(model, editor, action.screenId);
        syncFiles = true;
        message = `Added ${action.componentType}.`;
        break;
      }
      case "editor_remove_component":
        model = removeComponentFromModel(model, action.componentId);
        editor = createVisualEditorState(model, editor.device);
        syncFiles = true;
        message = "Component removed.";
        break;
      case "editor_reorder_components":
        model = reorderComponentsOnScreen(
          model,
          action.screenId,
          action.fromIndex,
          action.toIndex,
        );
        editor = selectScreen(model, editor, action.screenId);
        syncFiles = true;
        message = "Components reordered.";
        break;
      case "reorder_screens":
        model = reorderScreens(model, action.fromIndex, action.toIndex);
        editor = createVisualEditorState(model, editor.device);
        syncFiles = true;
        message = "Screens reordered.";
        break;
      case "editor_select_node":
        editor = selectScreen(model, editor, action.screenId);
        editor = selectNode(editor, action.nodeId);
        persist = false;
        message = "Node selected.";
        break;
      case "editor_update_styles":
        editor = selectScreen(model, editor, action.screenId);
        editor = updateNodeStyles(editor, action.nodeId, action.style);
        model = applyEditorTreeToModel(model, editor);
        syncFiles = true;
        message = "Styles updated.";
        break;
      case "sync_files": {
        const sync = syncAppModelToFiles(model, blueprintFiles);
        blueprintFiles = sync.files;
        persist = true;
        syncFiles = false;
        message = sync.notes.join(" ");
        break;
      }
      case "provision_backend": {
        const backend = provisionAppBackend(model, blueprintFiles);
        blueprintFiles = backend.files;
        persist = true;
        syncFiles = false;
        message = backend.notes.join(" ");
        break;
      }
      case "run_workflow": {
        const workflow = model.workflows.find((w) => w.id === action.workflowId);
        if (!workflow) {
          return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Workflow not found.");
        }
        const execution = await executeWorkflow({ workflow, model, trigger: "manual" });
        persist = false;
        message = `Workflow executed: ${execution.actionsRun.join(", ")}`;
        return NextResponse.json({
          message,
          execution,
          model,
          intelligence: runAppIntelligence(model),
        });
      }
    }

    let saved = generation;
    if (persist) {
      if (syncFiles) {
        const sync = syncAppModelToFiles(model, blueprintFiles);
        blueprintFiles = sync.files;
      }
      history = saveAppVersion(history, model, `After ${action.action}`);
      const blueprint = withAppModel(
        {
          ...(generation.blueprint || {}),
          files: blueprintFiles,
          pages: syncPagesFromModel(model),
        } as WebAppBlueprint,
        model,
        history,
      ) as WebAppBlueprint;
      saved = await persistBlueprint(
        auth.supabase,
        auth.user!.id,
        parsedId.id,
        blueprint,
        { app_name: model.settings.appName },
      );
    }

    return NextResponse.json({
      message,
      generation: saved,
      model,
      history,
      intelligence: runAppIntelligence(model),
      quality: runAppQualityChecks({
        model,
        files: saved.blueprint?.files ?? [],
      }),
      preview,
      editor,
      assistant: assistantResult,
      compare,
      componentPalette: listEditorComponentPalette(model.templateId),
      livePreviewUrl: `/api/webapp-builder/${parsedId.id}/live-preview`,
    });
  } catch (error) {
    return serverErrorResponse(
      "webapp-builder.manage.post",
      error,
      "Unable to update application.",
    );
  }
}

import { syncFavorite } from "@/lib/db/favorites";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { requireUser, parseJsonBody, parseUuidParam } from "@/lib/api/helpers";
import { databaseErrorResponse } from "@/lib/api/errors";
import type { WebAppGeneration } from "@/types/webapp";
import { NextResponse } from "next/server";
import { z } from "zod";

type RouteContext = { params: Promise<{ id: string }> };

const updateSchema = z.object({
  is_favorite: z.boolean().optional(),
  app_name: z.string().trim().min(1).max(120).optional(),
});

export async function GET(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { data, error } = await auth.supabase
    .from("webapp_generations")
    .select("*")
    .eq("id", id)
    .eq("user_id", auth.user!.id)
    .single();

  if (error || !data) {
    return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Web app not found");
  }

  return NextResponse.json({ generation: data as WebAppGeneration });
}

export async function PATCH(request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = updateSchema.safeParse(body);
  if (!parsed.success) {
    return apiValidationError(parsed.error.issues[0]?.message);
  }

  const { is_favorite, app_name } = parsed.data;

  const { data, error } = await auth.supabase
    .from("webapp_generations")
    .update({
      ...(typeof is_favorite === "boolean" ? { is_favorite } : {}),
      ...(app_name ? { app_name } : {}),
      updated_at: new Date().toISOString(),
    })
    .eq("id", id)
    .eq("user_id", auth.user!.id)
    .select("*")
    .single();

  if (error || !data) {
    return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Web app not found");
  }

  if (typeof is_favorite === "boolean") {
    const sync = await syncFavorite(
      auth.supabase,
      auth.user!.id,
      "webapp_generation",
      id,
      is_favorite,
    );
    if (sync.error) {
      return databaseErrorResponse("webapp-builder.syncFavorite", sync.error);
    }
  }

  return NextResponse.json({
    generation: data as WebAppGeneration,
    message: "Web app updated.",
  });
}

export async function POST(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  const { data: source, error: sourceError } = await auth.supabase
    .from("webapp_generations")
    .select("*")
    .eq("id", id)
    .eq("user_id", auth.user!.id)
    .single();

  if (sourceError || !source) {
    return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Web app not found");
  }

  const { data, error } = await auth.supabase
    .from("webapp_generations")
    .insert({
      user_id: auth.user!.id,
      app_name: `${source.app_name} (Copy)`,
      app_type: source.app_type,
      description: source.description,
      language: source.language,
      design_style: source.design_style,
      color_style: source.color_style,
      features: source.features,
      prompt: source.prompt,
      blueprint: source.blueprint,
      status: source.status,
      mode: "generate",
      is_favorite: false,
    })
    .select("*")
    .single();

  if (error || !data) {
    return databaseErrorResponse("webapp-builder.duplicate", error);
  }

  return NextResponse.json({
    generation: data as WebAppGeneration,
    message: "Web app duplicated.",
  });
}

export async function DELETE(_request: Request, context: RouteContext) {
  const { id: rawId } = await context.params;
  const idParsed = parseUuidParam(rawId);
  if (idParsed instanceof NextResponse) return idParsed;
  const { id } = idParsed;

  const auth = await requireUser();
  if (auth.response) return auth.response;

  await syncFavorite(auth.supabase, auth.user!.id, "webapp_generation", id, false);

  const { data, error } = await auth.supabase
    .from("webapp_generations")
    .delete()
    .eq("id", id)
    .eq("user_id", auth.user!.id)
    .select("id")
    .single();

  if (error || !data) {
    return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Web app not found");
  }

  return NextResponse.json({ message: "Web app deleted." });
}

import { NextResponse } from "next/server";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { z } from "zod";
import {
  listAppTemplates,
  listComponentsForTemplate,
  runAppDesignEngine,
  matchTemplateFromSignals,
} from "@/lib/ai-core/app-design-platform";

export const dynamic = "force-dynamic";

const designSchema = z.object({
  prompt: z.string().trim().min(5),
  appType: z.string().optional(),
  language: z.string().optional(),
  designStyle: z.string().optional(),
  colorStyle: z.string().optional(),
  features: z.array(z.string()).optional(),
});

/**
 * GET — list professional app templates + component library.
 * POST — run App Design Engine (blueprint only, no code generation).
 */
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const templateId = searchParams.get("templateId");

  if (templateId) {
    const template = listAppTemplates().find((t) => t.id === templateId);
    if (!template) {
      return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Template not found.");
    }
    return NextResponse.json({
      template,
      components: listComponentsForTemplate(template.id),
    });
  }

  return NextResponse.json({
    templates: listAppTemplates().map((t) => ({
      id: t.id,
      label: t.label,
      description: t.description,
      industry: t.industry,
      architecture: t.architecture,
      defaultFeatures: t.defaultFeatures,
      screenCount: t.screens.length,
      modelCount: t.dataModels.length,
      roleCount: t.roles.length,
      userFlows: t.userFlows,
    })),
    componentCount: listComponentsForTemplate("saas-dashboard").length,
  });
}

export async function POST(request: Request) {
  let json: unknown;
  try {
    json = await request.json();
  } catch {
    return apiValidationError("Invalid JSON.");
  }

  const parsed = designSchema.safeParse(json);
  if (!parsed.success) {
    return apiValidationError(parsed.error.issues[0]?.message);
  }

  const matched = matchTemplateFromSignals({
    appType: parsed.data.appType,
    prompt: parsed.data.prompt,
  });
  const designed = runAppDesignEngine(parsed.data);

  return NextResponse.json({
    matchedTemplate: {
      id: matched.id,
      label: matched.label,
      architecture: matched.architecture,
    },
    blueprint: designed.blueprint,
    model: designed.model,
  });
}

import { handleBillingWebhook } from "@/lib/billing";
import { API_ERROR_CODES, apiErrorResponse, apiNotFoundError, apiValidationError } from "@/lib/i18n/api-errors";
import { enforceWebhookRateLimit } from "@/lib/api/rate-limit";
import { NextResponse } from "next/server";

type RouteContext = { params: Promise<{ provider: string }> };

export async function POST(request: Request, context: RouteContext) {
  const { provider: raw } = await context.params;
  if (raw !== "paypal" && raw !== "card") {
    return apiNotFoundError(API_ERROR_CODES.NOT_FOUND, "Unsupported billing provider.");
  }

  const limited = enforceWebhookRateLimit(raw);
  if (limited) return limited;

  const rawBody = await request.text();
  const result = await handleBillingWebhook({
    provider: raw,
    headers: request.headers,
    rawBody,
  });

  if (!result.ok) {
    return apiErrorResponse(API_ERROR_CODES.SERVER_ERROR, result.status, result.error);
  }

  return NextResponse.json({ received: true, ...result }, { status: result.status });
}

