  const body = await parseJsonBody<unknown>(request);
  if (body instanceof NextResponse) return body;

  const parsed = getWorkspaceDefinition(type).inputSchema.safeParse(body);
  if (!parsed.success) {
    return apiValidationError(parsed.error.issues[0]?.message);
  }

  const mode = parsed.data.mode ?? "generate";
  const encoder = new TextEncoder();
  const aiLanguage = getRequestAiLanguage(request, parsed.data.language, parsed.data.country);

  let previousOutput = undefined as WorkspaceGeneration["output"] | undefined;
  let parentPromptVersions = undefined as WorkspaceGeneration["prompt_versions"];

  if (parsed.data.parentGenerationId) {
    const { data: parent } = await auth.supabase
      .from("workspace_generations")
      .select("*")
      .eq("id", parsed.data.parentGenerationId)
      .eq("user_id", auth.user!.id)
      .eq("workspace_type", type)
      .maybeSingle();

    if (parent) {
      const row = parent as WorkspaceGeneration;
      previousOutput = row.output;
      parentPromptVersions = row.prompt_versions;
    }
  }

  const stream = new ReadableStream({
    async start(controller) {
      const send = (event: string, data: unknown) => {
        controller.enqueue(encoder.encode(sseEncode(event, data)));
      };

      try {
        send("progress", { message: "Starting AI engine...", progress: 8 });

        const { output, source, provider, usage, generationTimeMs } =
          await generateWorkspaceProject(
            type,
            {
              ...parsed.data,
              language: aiLanguage,
              mode,
              previousOutput,
            },
            {
              onProgress: (message) => {
                send("progress", { message, progress: null });
              },
            },
          );

        send("progress", { message: "Saving to Supabase...", progress: 92 });

        const savedOutput = {
          ...output,
          productId: parsed.data.productId,
          depth: parsed.data.depth,
          progressEvents: [
            ...(output.progressEvents ?? []),
            "Saving project to workspace...",
            "Project saved.",
            "Done.",
          ],
        };

        const features = [
          ...(parsed.data.features ?? []),
          ...(parsed.data.productId ? [`product:${parsed.data.productId}`] : []),
          ...(parsed.data.depth ? [`depth:${parsed.data.depth}`] : []),
        ];

        const project = await ensureProjectForGeneration(auth.supabase, {
          userId: auth.user!.id,
          productId: parsed.data.productId,
          workspaceType: type,
          name: savedOutput.title,
          projectId: parsed.data.projectId,
        });

        const promptVersions = appendPromptVersion(
          parentPromptVersions,
          parsed.data.prompt,
          mode,
        );

        const row = buildCompletedGenerationRow({
          title: savedOutput.title,
          brief: parsed.data.prompt,
          template: parsed.data.template ?? null,
          language: aiLanguage,
          theme: parsed.data.theme ?? "Gold",
          features,
          output: savedOutput,
          projectId: project?.id ?? parsed.data.projectId,
          productId: parsed.data.productId,
          mode,
          parentGenerationId: parsed.data.parentGenerationId,
          provider,
          usage,
          generationTimeMs,
          promptVersions,
          attachments: parsed.data.attachments ?? [],
        });

        const { data, error } = await insertWorkspaceGeneration(auth.supabase, {
          user_id: auth.user!.id,
          workspace_type: type,
          ...row,
        });

        if (error) {
          await creditLease.release(auth.supabase);
          send("error", { error: error.message });
          controller.close();
          return;
        }

        await creditLease.settle(auth.supabase);
        send("complete", {
          generation: data as WorkspaceGeneration,
          output: savedOutput,
          source,
          message:
            source && source !== "structured"
              ? "Workspace project generated and saved with AI."
              : "Workspace project generated and saved.",
        });
      } catch (error) {
        await creditLease.release(auth.supabase);
        const message =
          error instanceof Error ? error.message : "Unable to generate workspace project.";

        try {
          await auth.supabase.from("workspace_generations").insert({
            user_id: auth.user!.id,
            workspace_type: type,
            title: "Failed generation",
            brief: parsed.data.prompt,
            template: parsed.data.template ?? null,
            language: aiLanguage,
            theme: parsed.data.theme ?? "Gold",
            features: parsed.data.features ?? [],
            output: {
              title: "Failed generation",
              summary: message,
              sections: [],
              deliverables: [],
              productId: parsed.data.productId,
              mode,
            },
            product_id: parsed.data.productId ?? null,
            project_id: parsed.data.projectId ?? null,
            status: "failed",
            mode,
            parent_generation_id: parsed.data.parentGenerationId ?? null,
            error_message: message,
            prompt_versions: appendPromptVersion([], parsed.data.prompt, mode),
            attachments: parsed.data.attachments ?? [],
            is_favorite: false,
          });
        } catch {
          // ignore
        }

        send("error", { error: message });
      } finally {
        controller.close();
      }
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "text/event-stream; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
      Connection: "keep-alive",
    },
  });
}

"use client";

import { useState } from "react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { dashboardInputClass, dashboardSelectClass } from "@/components/dashboard/ui/dashboard-styles";
import { AGENT_TYPES, AGENT_TOOLS, AGENT_CATEGORIES } from "@/lib/constants/ai-agents";
import { CheckboxToggle } from "@/components/dashboard/builder-shared";
import type { Agent } from "@/types/agents";
import { useTranslation } from "@/lib/i18n/client";
import { useProductT } from "@/lib/i18n/use-scoped-t";
import { resolveLabel } from "@/lib/i18n/resolve-constant-label";

type Props = { agent?: Agent | null; onSaved?: () => void; onCancel?: () => void };

export function AgentEditor({ agent, onSaved, onCancel }: Props) {
  const { t } = useTranslation();
  const p = useProductT("aiAgents");
  const [name, setName] = useState(agent?.name ?? "");
  const [description, setDescription] = useState(agent?.description ?? "");
  const [agentType, setAgentType] = useState(agent?.agent_type ?? "custom");
  const [category, setCategory] = useState(agent?.category ?? "general");
  const [systemPrompt, setSystemPrompt] = useState(agent?.system_prompt ?? "");
  const [tools, setTools] = useState<string[]>((agent?.tools as string[]) ?? []);
  const [temperature, setTemperature] = useState(String(agent?.temperature ?? 0.7));
  const [loading, setLoading] = useState(false);

  const save = async () => {
    if (!name.trim()) return toast.error(p("errors.agentNameRequired"));
    setLoading(true);
    try {
      if (agent?.id) {
        const res = await fetch(`/api/ai-agents/${agent.id}`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ name, description, system_prompt: systemPrompt, tools, temperature: parseFloat(temperature) }),
        });
        if (!res.ok) throw new Error((await res.json()).error ?? p("toasts.failed"));
        toast.success(p("toasts.agentUpdated"));
      } else {
        const res = await fetch("/api/ai-agents", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            action: "create-agent",
            name, description, agentType, category, systemPrompt, tools,
            temperature: parseFloat(temperature),
          }),
        });
        if (!res.ok) throw new Error((await res.json()).error ?? p("toasts.failed"));
        toast.success(p("toasts.agentCreated"));
      }
      onSaved?.();
    } catch (e) {
      toast.error(e instanceof Error ? e.message : p("toasts.failed"));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-4 rounded-xl border border-white/[0.08] bg-white/[0.02] p-4">
      <p className="text-xs uppercase text-white/40">{agent ? p("editor.titleEdit") : p("editor.titleCreate")}</p>
      <div className="grid gap-3 sm:grid-cols-2">
        <Input value={name} onChange={(e) => setName(e.target.value)} placeholder={p("editor.agentNamePlaceholder")} className={dashboardInputClass} />
        <select value={agentType} onChange={(e) => setAgentType(e.target.value)} className={dashboardSelectClass}>
          {AGENT_TYPES.map((type) => <option key={type.id} value={type.id}>{resolveLabel(t, type)}</option>)}
        </select>
      </div>
      <Input value={description} onChange={(e) => setDescription(e.target.value)} placeholder={p("editor.descriptionPlaceholder")} className={dashboardInputClass} />
      <select value={category} onChange={(e) => setCategory(e.target.value)} className={dashboardSelectClass}>
        {AGENT_CATEGORIES.map((c) => <option key={c.id} value={c.id}>{p(`editor.categories.${c.id}`)}</option>)}
      </select>
      <textarea value={systemPrompt} onChange={(e) => setSystemPrompt(e.target.value)} rows={4} placeholder={p("editor.systemPromptPlaceholder")} className={dashboardInputClass} />
      <div className="flex flex-wrap gap-2">
        {AGENT_TOOLS.map((tool) => (
          <CheckboxToggle key={tool.id} label={p(`editor.tools.${tool.id}`)} checked={tools.includes(tool.id)}
            onChange={(c) => setTools((prev) => c ? [...prev, tool.id] : prev.filter((x) => x !== tool.id))} />
        ))}
      </div>
      <div className="flex gap-2">
        {onCancel ? <Button variant="outline" onClick={onCancel}>{p("editor.cancel")}</Button> : null}
        <Button onClick={() => void save()} disabled={loading}>{loading ? p("editor.saving") : p("editor.saveAgent")}</Button>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { dashboardInputClass } from "@/components/dashboard/ui/dashboard-styles";
import { useProductT } from "@/lib/i18n/use-scoped-t";

type KB = { id: string; name: string; document_count: number; indexing_status: string };

export function KnowledgeManager() {
  const pt = useProductT("aiAgents");
  const [bases, setBases] = useState<KB[]>([]);
  const [selectedId, setSelectedId] = useState("");
  const [name, setName] = useState("");
  const [docTitle, setDocTitle] = useState("");
  const [docContent, setDocContent] = useState("");

  const load = () => void fetch("/api/ai-agents/knowledge").then((r) => r.json()).then((d) => {
    setBases(d.knowledgeBases ?? []);
    if (!selectedId && d.knowledgeBases?.[0]) setSelectedId(d.knowledgeBases[0].id);
  }).catch(() => undefined);

  useEffect(() => { load(); }, []);

  const createKb = async () => {
    if (!name.trim()) return;
    const res = await fetch("/api/ai-agents/knowledge", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name }) });
    if (!res.ok) return toast.error(pt("toasts.failed"));
    setName(""); load(); toast.success(pt("panels.knowledge.kbCreated"));
  };

  const addDoc = async () => {
    if (!selectedId || !docTitle.trim() || !docContent.trim()) return toast.error(pt("panels.knowledge.fillAllFields"));
    const res = await fetch("/api/ai-agents/knowledge", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ knowledgeBaseId: selectedId, title: docTitle, content: docContent }),
    });
    if (!res.ok) return toast.error(pt("toasts.failed"));
    setDocTitle(""); setDocContent(""); load(); toast.success(pt("panels.knowledge.documentAdded"));
  };

  return (
    <div className="space-y-4">
      <div className="flex gap-2">
        <Input value={name} onChange={(e) => setName(e.target.value)} placeholder={pt("panels.knowledge.newKbPlaceholder")} className={dashboardInputClass} />
        <Button onClick={() => void createKb()}>{pt("panels.knowledge.createKb")}</Button>
      </div>
      <div className="grid gap-3 sm:grid-cols-2">
        {bases.map((b) => (
          <button key={b.id} type="button" onClick={() => setSelectedId(b.id)}
            className={`rounded-lg border p-3 text-left ${selectedId === b.id ? "border-premium-gold/40 bg-premium-gold/5" : "border-white/5"}`}>
            <p className="text-sm font-medium text-white">{b.name}</p>
            <p className="text-xs text-white/40">{pt("panels.knowledge.docsCount", { count: b.document_count, status: b.indexing_status })}</p>
          </button>
        ))}
      </div>
      {selectedId ? (
        <div className="space-y-2 rounded-xl border border-white/[0.08] p-4">
          <p className="text-xs uppercase text-white/40">{pt("panels.knowledge.addDocument")}</p>
          <Input value={docTitle} onChange={(e) => setDocTitle(e.target.value)} placeholder={pt("panels.knowledge.title")} className={dashboardInputClass} />
          <textarea value={docContent} onChange={(e) => setDocContent(e.target.value)} rows={4} placeholder={pt("panels.knowledge.content")} className={dashboardInputClass} />
          <Button onClick={() => void addDoc()}>{pt("panels.knowledge.addDocumentBtn")}</Button>
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
