  const logos = bp?.logoVariants ?? bp?.logos ?? [];

  const refresh = useCallback(async () => {
    const res = await fetch(`/api/brand-identity/${generation.id}`);
    if (!res.ok) return;
    const data = await res.json();
    if (data.generation) setGeneration(data.generation);
  }, [generation.id]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const handleColorChange = async (index: number, hex: string) => {
    if (!bp) return;
    const colors = bp.colorPalette.map((c, i) => (i === index ? { ...c, hex } : c));
    const res = await fetch(`/api/brand-identity/${generation.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ colors }),
    });
    if (res.ok) {
      toast.success(p("toasts.colorsUpdated"));
      await refresh();
    }
  };

  const handleTypographySave = async () => {
    if (!bp?.typography) return;
    const res = await fetch(`/api/brand-identity/${generation.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ typography: bp.typography }),
    });
    if (res.ok) {
      toast.success(p("toasts.typographySaved"));
      await refresh();
    }
  };

  const handleGenerateLogos = async () => {
    setLogoBusy(true);
    try {
      const res = await fetch(`/api/brand-identity/${generation.id}/logos`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ conceptCount: 3 }),
      });
      const data = await res.json();
      if (!res.ok) {
        toast.error(data.error ?? p("errors.logoGenerationFailed"));
        return;
      }
      toast.success(data.message ?? p("toasts.logosGenerated"));
      if (data.generation) setGeneration(data.generation);
    } finally {
      setLogoBusy(false);
    }
  };

  const handleCreateKit = async () => {
    setKitBusy(true);
    try {
      const res = await fetch(`/api/brand-identity/${generation.id}/kit`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: generation.brand_name }),
      });
      const data = await res.json();
      if (!res.ok) {
        toast.error(data.error ?? p("errors.kitCreationFailed"));
        return;
      }
      setShareUrl(data.shareUrl ?? null);
      toast.success(data.message ?? p("toasts.kitCreated"));
    } finally {
      setKitBusy(false);
    }
  };

  const handleAssistant = async () => {
    if (!assistantMsg.trim()) return;
    setAssistantBusy(true);
    try {
      const res = await fetch(`/api/brand-identity/${generation.id}/assistant`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: assistantMsg }),
      });
      const data = await res.json();
      if (!res.ok) {
        toast.error(data.error ?? p("errors.assistantFailed"));
        return;
      }
      toast.success(data.message);
      setAssistantMsg("");
      if (data.generation) setGeneration(data.generation);
    } finally {
      setAssistantBusy(false);
    }
  };

  const handleExport = async (format: "json" | "html" | "markdown") => {
    window.open(`/api/brand-identity/${generation.id}/export?format=${format}`, "_blank");
  };

  const handleApply = async (target: string) => {
    const res = await fetch(`/api/brand-identity/${generation.id}/export?applyTo=${target}`);
    const data = await res.json();
    if (res.ok) {
      await navigator.clipboard.writeText(JSON.stringify(data.apply, null, 2));
      toast.success(p("management.tokensCopied", { target }));
    }
  };

  if (!bp) {
    return (
      <DashboardPanel className="py-16 text-center">
        <p className="text-white/50">{p("management.noBlueprint")}</p>
        <Button variant="outline" className="mt-4" onClick={() => router.push("/dashboard/brand-studio")}>
          {p("management.backToStudio")}
        </Button>
      </DashboardPanel>
    );
  }

  const tabs: { key: Tab; label: string }[] = [
    { key: "overview", label: p("management.tabs.overview") },
    { key: "colors", label: p("management.tabs.colors") },
    { key: "typography", label: p("management.tabs.fonts") },
    { key: "voice", label: p("management.tabs.voice") },
    { key: "logos", label: p("management.tabs.logos") },
    { key: "assets", label: p("management.tabs.assets") },
    { key: "assistant", label: p("management.tabs.assistant") },
    { key: "apply", label: p("management.tabs.apply") },
  ];

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center gap-3">
        <Link href="/dashboard/brand-studio">
          <Button variant="ghost" size="icon-xs" className="text-white/40 hover:text-white">
            <ArrowLeft className="size-4" />
          </Button>
        </Link>
        <div className="min-w-0 flex-1">
          <h2 className="truncate text-xl font-bold text-white">{bp.title}</h2>
          <p className="text-xs text-white/40">
            {generation.brand_type} · {p("management.qualityScore", { score: bp.qualityScore ?? "—" })}
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button variant="outline" size="sm" className="gap-1.5 text-xs" onClick={() => void handleGenerateLogos()} disabled={logoBusy}>
            <RefreshCw className={cn("size-3", logoBusy && "animate-spin")} /> {p("management.logosBtn")}
          </Button>
          <Button variant="outline" size="sm" className="gap-1.5 text-xs" onClick={() => void handleCreateKit()} disabled={kitBusy}>
            <Sparkles className="size-3" /> {p("management.createKit")}
          </Button>
          <Button variant="outline" size="sm" className="gap-1.5 text-xs" onClick={() => void handleExport("html")}>
            <Download className="size-3" /> {p("management.pdfHtml")}
          </Button>
          {shareUrl ? (
            <Button variant="outline" size="sm" className="gap-1.5 text-xs" onClick={() => { navigator.clipboard.writeText(shareUrl); toast.success(p("management.shareLinkCopied")); }}>
              <Share2 className="size-3" /> {p("management.share")}
            </Button>
          ) : null}
        </div>
      </div>

      <div className="flex gap-1 overflow-x-auto pb-1">
        {tabs.map(({ key, label }) => (
          <button
            key={key}
            onClick={() => setTab(key)}
            className={cn(
              "whitespace-nowrap rounded-lg px-3 py-1.5 text-xs font-medium transition-all",
              tab === key ? "bg-premium-gold/15 text-premium-gold-light" : "text-white/40 hover:bg-white/5",
            )}
          >
            {label}
          </button>
        ))}
      </div>

      {tab === "overview" && (
        <div className="grid gap-4 sm:grid-cols-2">
          <DashboardPanel className="space-y-2 p-5">
            <span className="text-xs font-bold uppercase tracking-wider text-premium-gold-light">{p("management.mission")}</span>
            <p className="text-sm text-white/70">{bp.mission}</p>
          </DashboardPanel>
          <DashboardPanel className="space-y-2 p-5">
            <span className="text-xs font-bold uppercase tracking-wider text-premium-gold-light">{p("management.vision")}</span>
            <p className="text-sm text-white/70">{bp.vision}</p>
          </DashboardPanel>
          <DashboardPanel className="space-y-2 p-5 sm:col-span-2">
            <span className="text-xs font-bold uppercase tracking-wider text-premium-gold-light">{p("management.tagline")}</span>
            <p className="text-lg font-semibold text-white/80">{bp.voiceTone.tagline || "—"}</p>
          </DashboardPanel>
        </div>
      )}

      {tab === "colors" && (
        <div className="grid gap-3 sm:grid-cols-2">
          {bp.colorPalette.map((c, i) => (
            <DashboardPanel key={i} className="flex items-center gap-3 p-4">
              <input
                type="color"
                value={c.hex}
                onChange={(e) => void handleColorChange(i, e.target.value)}
                className="size-10 cursor-pointer rounded-lg border-0 bg-transparent"
              />
              <div className="min-w-0 flex-1">
                <p className="text-sm font-semibold text-white/80">{c.name}</p>
                <p className="text-xs text-white/40">{c.role}</p>
              </div>
              <code className="text-xs text-white/50">{c.hex}</code>
            </DashboardPanel>
          ))}
        </div>
      )}

      {tab === "typography" && (
        <DashboardCard>
          <DashboardCardHeader>
            <DashboardCardTitle className="flex items-center gap-2"><Type className="size-4" /> {p("management.typography")}</DashboardCardTitle>
          </DashboardCardHeader>
          <DashboardCardContent className="grid gap-4 sm:grid-cols-2">
            <div>
              <label className="mb-1 block text-xs text-white/50">{p("management.primaryHeadings")}</label>
              <Input
                value={bp.typography.primary}
                onChange={(e) =>
                  setGeneration((g) => ({
                    ...g,
                    blueprint: g.blueprint ? { ...g.blueprint, typography: { ...g.blueprint.typography, primary: e.target.value } } : g.blueprint,
                  }))
                }
                className={dashboardInputClass}
              />
            </div>
            <div>
              <label className="mb-1 block text-xs text-white/50">{p("management.secondaryBody")}</label>
              <Input
                value={bp.typography.secondary}
                onChange={(e) =>
                  setGeneration((g) => ({
                    ...g,
                    blueprint: g.blueprint ? { ...g.blueprint, typography: { ...g.blueprint.typography, secondary: e.target.value } } : g.blueprint,
                  }))
                }
                className={dashboardInputClass}
              />
            </div>
            <Button onClick={() => void handleTypographySave()} className="btn-gold sm:col-span-2 w-fit">
              Save Fonts
            </Button>
          </DashboardCardContent>
        </DashboardCard>
      )}

      {tab === "voice" && (
        <DashboardPanel className="space-y-4 p-5">
          <p className="text-sm text-white/70"><strong>{p("management.toneLabel")}</strong> {bp.voiceTone.tone}</p>
          <p className="text-sm text-white/70">{bp.voiceTone.elevatorPitch}</p>
        </DashboardPanel>
      )}

      {tab === "logos" && (
        <div className="space-y-4">
          {!logos.length ? (
            <DashboardPanel className="py-12 text-center">
              <Palette className="mx-auto size-8 text-white/20" />
              <p className="mt-3 text-sm text-white/50">{p("management.noLogosYet")}</p>
              <Button className="btn-gold mt-4" onClick={() => void handleGenerateLogos()} disabled={logoBusy}>
                Generate Logo Concepts
              </Button>
            </DashboardPanel>
          ) : (
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {(bp.logoVariants ?? []).map((v) => (
                <DashboardPanel key={v.id} className="space-y-3 p-4">
                  <p className="text-sm font-semibold text-white/80">{v.name}</p>
                  {v.svg ? (
                    <div className="flex justify-center rounded-lg bg-white p-4" dangerouslySetInnerHTML={{ __html: sanitizeSvgContent(v.svg) }} />
                  ) : null}
                  <Button variant="outline" size="sm" className="w-full text-xs" onClick={() => v.svg && navigator.clipboard.writeText(v.svg)}>
                    Copy SVG
                  </Button>
                </DashboardPanel>
              ))}
            </div>
          )}
        </div>
      )}

      {tab === "assets" && (
        <div className="grid gap-3 sm:grid-cols-2">
          {bp.assets.map((a, i) => (
            <DashboardPanel key={i} className="p-4">
              <p className="text-sm font-semibold text-white/80">{a.name}</p>
              <p className="text-xs text-white/40">{a.category} · {a.format}</p>
            </DashboardPanel>
          ))}
        </div>
      )}

      {tab === "assistant" && (
        <DashboardCard>
          <DashboardCardHeader>
            <DashboardCardTitle className="flex items-center gap-2"><MessageSquare className="size-4" /> {p("management.brandAssistant")}</DashboardCardTitle>
          </DashboardCardHeader>
          <DashboardCardContent className="space-y-3">
            <p className="text-xs text-white/40">
              {p("management.assistantHint")}
            </p>
            <Textarea
              value={assistantMsg}
              onChange={(e) => setAssistantMsg(e.target.value)}
              placeholder={p("placeholders.assistantMessage")}
              className={cn(dashboardInputClass, "min-h-[100px]")}
            />
            <Button onClick={() => void handleAssistant()} disabled={assistantBusy || !assistantMsg.trim()} className="btn-gold gap-2">
              <Wand2 className="size-4" /> {assistantBusy ? p("management.applying") : p("management.apply")}
            </Button>
          </DashboardCardContent>
        </DashboardCard>
      )}

      {tab === "apply" && (
        <div className="grid gap-3 sm:grid-cols-3">
          {(["website-builder", "app-builder", "video-studio"] as const).map((target) => (
            <DashboardPanel key={target} className="space-y-3 p-5">
              <p className="text-sm font-semibold capitalize text-white/80">{target.replace("-", " ")}</p>
              <p className="text-xs text-white/40">{p("management.copyTokensFor", { target })}</p>
              <Button variant="outline" size="sm" className="gap-1.5 text-xs" onClick={() => void handleApply(target)}>
                <ExternalLink className="size-3" /> {p("management.copyTokens")}
              </Button>
            </DashboardPanel>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { toast } from "sonner";
import { LayoutGrid, List, GanttChart, Plus, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import { groupTasksByStatus, TASK_STATUSES } from "@/lib/business-manager/tasks";
import type { BusinessProject, Task, Milestone } from "@/types/business-manager";
import { useWorkspaceT } from "@/lib/i18n/use-scoped-t";

type View = "kanban" | "list" | "timeline";

type Props = {
  initialProjects?: BusinessProject[];
  initialTasks?: Task[];
  initialMilestones?: Milestone[];
};

export function ProjectsPanel({
  initialProjects = [],
  initialTasks = [],
  initialMilestones = [],
}: Props) {
  const wt = useWorkspaceT("businessManager");
  const [projects, setProjects] = useState(initialProjects);
  const [tasks, setTasks] = useState(initialTasks);
  const [milestones, setMilestones] = useState(initialMilestones);
  const [view, setView] = useState<View>("kanban");
  const [selectedId, setSelectedId] = useState<string | null>(initialProjects[0]?.id ?? null);
  const [brief, setBrief] = useState("");
  const [generating, setGenerating] = useState(false);
  const [newTaskTitle, setNewTaskTitle] = useState("");

  const selected = projects.find((p) => p.id === selectedId) ?? null;
  const projectTasks = useMemo(
    () => (selected ? tasks.filter((t) => t.project_id === selected.id) : []),
    [tasks, selected],
  );
  const projectMilestones = useMemo(
    () => (selected ? milestones.filter((m) => m.project_id === selected.id) : []),
    [milestones, selected],
  );
  const kanban = useMemo(() => groupTasksByStatus(projectTasks), [projectTasks]);

  const generateProject = async () => {
    if (!brief.trim()) return toast.error(wt("toasts.briefRequired"));
    setGenerating(true);
    try {
      const res = await fetch("/api/business-manager/projects", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: brief.slice(0, 60), brief, generate: true, status: "active" }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? wt("toasts.failed"));
      setProjects([data.project, ...projects]);
      setSelectedId(data.project.id);
      setBrief("");
      toast.success(wt("toasts.projectCreated"));
    } catch (e) {
      toast.error(e instanceof Error ? e.message : wt("toasts.failed"));
    } finally {
      setGenerating(false);
    }
  };

  const addTask = async () => {
    if (!selected || !newTaskTitle.trim()) return;
    const res = await fetch("/api/business-manager/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: newTaskTitle, projectId: selected.id, status: "todo" }),
    });
    const data = await res.json();
    if (!res.ok) return toast.error(data.error ?? wt("toasts.failed"));
    setTasks([data.task, ...tasks]);
    setNewTaskTitle("");
  };

  const moveTask = async (taskId: string, status: Task["status"]) => {
    const res = await fetch(`/api/business-manager/tasks/${taskId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status }),
    });
    const data = await res.json();
    if (!res.ok) return toast.error(data.error ?? wt("toasts.failed"));
    setTasks(tasks.map((t) => (t.id === taskId ? data.task : t)));
  };

  const archiveProject = async () => {
    if (!selected) return;
    const res = await fetch(`/api/business-manager/projects/${selected.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ archive: true }),
    });
    const data = await res.json();
    if (!res.ok) return toast.error(data.error ?? wt("toasts.failed"));
    setProjects(projects.map((p) => (p.id === selected.id ? data.project : p)));
    toast.success(wt("toasts.projectArchived"));
  };

  return (
    <div className="grid gap-6 lg:grid-cols-[280px_1fr]">
      <div className="space-y-4">
        <div className="rounded-xl border border-white/[0.08] bg-white/[0.02] p-4">
          <p className="mb-2 text-xs font-medium uppercase text-white/40">{wt("projects.aiPlanner")}</p>
          <Textarea
            value={brief}
            onChange={(e) => setBrief(e.target.value)}
            placeholder={wt("projects.briefPlaceholder")}
            rows={3}
            className="border-white/10 bg-white/5 text-white"
          />
          <Button className="mt-2 w-full" onClick={() => void generateProject()} disabled={generating}>
            <Sparkles className="mr-2 size-4" />
            {generating ? wt("projects.creating") : wt("projects.createProject")}
          </Button>
        </div>
        <div className="space-y-2">
          {projects.map((p) => (
            <button
              key={p.id}
              type="button"
              onClick={() => setSelectedId(p.id)}
              className={cn(
                "w-full rounded-lg border px-3 py-2 text-left text-sm",
                selectedId === p.id
                  ? "border-premium-gold/40 bg-premium-gold/10 text-premium-gold-light"
                  : "border-white/[0.06] bg-white/[0.02] text-white/70 hover:bg-white/5",
              )}
            >
              <p className="font-medium">{p.name}</p>
              <p className="text-xs capitalize text-white/40">
                {p.status} · {p.progress}%
              </p>
            </button>
          ))}
        </div>
      </div>

      {selected ? (
        <div className="space-y-4">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <div>
              <h3 className="text-lg font-semibold text-white">{selected.name}</h3>
              <p className="text-sm text-white/40">{selected.description || wt("projects.noDescription")}</p>
            </div>
            <div className="flex gap-1">
              {(
                [
                  { key: "kanban" as const, icon: LayoutGrid, label: wt("projects.kanban") },
                  { key: "list" as const, icon: List, label: wt("projects.list") },
                  { key: "timeline" as const, icon: GanttChart, label: wt("projects.timeline") },
                ] as const
              ).map(({ key, icon: Icon, label }) => (
                <button
                  key={key}
                  onClick={() => setView(key)}
                  className={cn(
                    "flex items-center gap-1 rounded-lg px-3 py-1.5 text-xs",
                    view === key ? "bg-premium-gold/15 text-premium-gold-light" : "text-white/40 hover:bg-white/5",
                  )}
                >
                  <Icon className="size-3.5" />
                  {label}
                </button>
              ))}
              <Button variant="outline" size="sm" onClick={() => void archiveProject()}>
                {wt("projects.archive")}
              </Button>
            </div>
          </div>

          <div className="flex gap-2">
            <Input
              value={newTaskTitle}
              onChange={(e) => setNewTaskTitle(e.target.value)}
              placeholder={wt("projects.newTaskPlaceholder")}
              className="border-white/10 bg-white/5 text-white"
            />
            <Button onClick={() => void addTask()}>
              <Plus className="size-4" />
            </Button>
          </div>

          {view === "kanban" && (
            <div className="grid gap-3 md:grid-cols-3 xl:grid-cols-5">
              {TASK_STATUSES.map((status) => (
                <div key={status} className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
                  <p className="mb-2 text-xs font-medium uppercase text-white/40">{wt(`taskStatuses.${status}`)}</p>
                  <div className="space-y-2">
                    {kanban[status].map((task) => (
                      <div key={task.id} className="rounded-lg border border-white/[0.06] bg-white/[0.03] p-2 text-sm">
                        <p className="text-white">{task.title}</p>
                        <p className="text-xs capitalize text-white/40">{task.priority}</p>
                        {status !== "done" && (
                          <button
                            type="button"
                            className="mt-1 text-xs text-premium-gold-light"
                            onClick={() => void moveTask(task.id, status === "todo" ? "in_progress" : "done")}
                          >
                            {wt("projects.advance")}
                          </button>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          )}

          {view === "list" && (
            <div className="rounded-xl border border-white/[0.08] bg-white/[0.02]">
              {projectTasks.map((task) => (
                <div
                  key={task.id}
                  className="flex items-center justify-between border-b border-white/[0.04] px-4 py-3 last:border-0"
                >
                  <div>
                    <p className="text-white">{task.title}</p>
                    <p className="text-xs text-white/40">
                      {task.assignee_name || wt("projects.unassigned")} · {task.priority}
                    </p>
                  </div>
                  <span className="text-xs capitalize text-white/50">{wt(`taskStatuses.${task.status}`)}</span>
                </div>
              ))}
              {projectTasks.length === 0 && (
                <p className="p-4 text-sm text-white/30">{wt("projects.noTasks")}</p>
              )}
            </div>
          )}

          {view === "timeline" && (
            <div className="space-y-3">
              {projectMilestones.map((m) => (
                <div key={m.id} className="flex items-center gap-4 rounded-xl border border-white/[0.08] bg-white/[0.02] p-4">
                  <div className="size-2 rounded-full bg-premium-gold" />
                  <div className="flex-1">
                    <p className="font-medium text-white">{m.title}</p>
                    <p className="text-xs text-white/40">
                      {m.target_date ?? wt("projects.noDate")} · {m.status}
                    </p>
                  </div>
                </div>
              ))}
              {projectTasks
                .filter((t) => t.due_date)
                .map((t) => (
                  <div key={t.id} className="ml-6 flex items-center gap-4 rounded-lg border border-white/[0.06] px-4 py-2">
                    <p className="text-sm text-white">{t.title}</p>
                    <p className="text-xs text-white/40">{t.due_date?.slice(0, 10)}</p>
                  </div>
                ))}
              {projectMilestones.length === 0 && projectTasks.length === 0 && (
                <p className="text-sm text-white/30">{wt("projects.timelineEmpty")}</p>
              )}
            </div>
          )}
        </div>
      ) : (
        <div className="flex items-center justify-center rounded-xl border border-dashed border-white/10 p-12 text-white/30">
          {wt("projects.selectOrCreate")}
        </div>
      )}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  Bold,
  Heading1,
  Heading2,
  Italic,
  List,
  ListOrdered,
  Minus,
  Sparkles,
  Strikethrough,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { useTranslation } from "@/lib/i18n/client";
import { useProductT } from "@/lib/i18n/use-scoped-t";
import { countCharacters, countWords } from "@/lib/content-studio/documents";
import { CONTENT_PLATFORM_STYLES, CONTENT_PLATFORM_TONES } from "@/lib/constants/content-studio";
import type { ContentActionType } from "@/types/content";
import { toast } from "sonner";

type Props = {
  documentId?: string;
  title: string;
  body: string;
  status?: "draft" | "published" | "archived";
  brandIdentityId?: string | null;
  onTitleChange: (title: string) => void;
  onBodyChange: (body: string) => void;
  onStatusChange?: (status: "draft" | "published" | "archived") => void;
  onAutosave?: (payload: { title: string; body: string }) => Promise<void>;
  className?: string;
};

const AI_ACTION_KEYS: { action: ContentActionType; key: string }[] = [
  { action: "improve", key: "editor.improve" },
  { action: "rewrite", key: "editor.rewrite" },
  { action: "expand", key: "editor.expand" },
  { action: "shorten", key: "editor.shorten" },
  { action: "summarize", key: "editor.summarize" },
  { action: "translate", key: "editor.translate" },
  { action: "change_tone", key: "editor.changeTone" },
  { action: "change_style", key: "editor.changeStyle" },
];

export function ContentEditor({
  documentId,
  title,
  body,
  status = "draft",
  brandIdentityId,
  onTitleChange,
  onBodyChange,
  onStatusChange,
  onAutosave,
  className,
}: Props) {
  const { t } = useTranslation();
  const p = useProductT("contentStudio");
  const editorRef = useRef<HTMLDivElement>(null);
  const [aiTone, setAiTone] = useState("Professional");
  const [aiStyle, setAiStyle] = useState("Standard");
  const [aiBusy, setAiBusy] = useState(false);
  const [viewMode, setViewMode] = useState<"rich" | "markdown">("rich");
  const saveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const wordCount = countWords(body);
  const charCount = countCharacters(body);

  useEffect(() => {
    if (viewMode !== "rich" || !editorRef.current) return;
    if (editorRef.current.innerText !== body) {
      editorRef.current.innerHTML = bodyToHtml(body);
    }
  }, [body, viewMode]);

  const scheduleAutosave = useCallback(
    (nextTitle: string, nextBody: string) => {
      if (!onAutosave) return;
      if (saveTimer.current) clearTimeout(saveTimer.current);
      saveTimer.current = setTimeout(() => {
        void onAutosave({ title: nextTitle, body: nextBody });
      }, 1500);
    },
    [onAutosave],
  );

  const handleEditorInput = () => {
    const html = editorRef.current?.innerHTML ?? "";
    const text = htmlToText(html);
    onBodyChange(text);
    scheduleAutosave(title, text);
  };

  const exec = (command: string, value?: string) => {
    document.execCommand(command, false, value);
    editorRef.current?.focus();
    handleEditorInput();
  };

  const runAiAction = async (action: ContentActionType) => {
    const selection = window.getSelection()?.toString().trim();
    const text = selection || body;
    if (!text.trim()) {
      toast.error(p("errors.selectTextFirst"));
      return;
    }

    setAiBusy(true);
    try {
      const res = await fetch("/api/content-studio/actions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action,
          text,
          tone: action === "change_tone" ? aiTone : undefined,
          style: action === "change_style" ? aiStyle : undefined,
          brandIdentityId: brandIdentityId ?? undefined,
          documentId,
          saveToDocument: Boolean(documentId && !selection),
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? p("errors.actionFailed"));

      if (selection && editorRef.current) {
        document.execCommand("insertText", false, data.result);
        handleEditorInput();
      } else {
        onBodyChange(data.result);
        scheduleAutosave(title, data.result);
      }
      toast.success(p("toasts.actionComplete", { action: action.replace("_", " ") }));
    } catch (e) {
      toast.error(e instanceof Error ? e.message : p("errors.aiActionFailed"));
    } finally {
      setAiBusy(false);
    }
  };

  return (
    <div className={cn("flex h-full flex-col rounded-xl border border-white/[0.08] bg-white/[0.02]", className)}>
      <div className="flex flex-wrap items-center gap-1 border-b border-white/[0.06] p-2">
        <Button type="button" size="sm" variant="ghost" className="h-8 w-8 p-0 text-white/60" onClick={() => exec("bold")}>
          <Bold className="size-4" />
        </Button>
        <Button type="button" size="sm" variant="ghost" className="h-8 w-8 p-0 text-white/60" onClick={() => exec("italic")}>
          <Italic className="size-4" />
        </Button>
        <Button type="button" size="sm" variant="ghost" className="h-8 w-8 p-0 text-white/60" onClick={() => exec("strikeThrough")}>
          <Strikethrough className="size-4" />
        </Button>
        <Button type="button" size="sm" variant="ghost" className="h-8 w-8 p-0 text-white/60" onClick={() => exec("formatBlock", "h1")}>
          <Heading1 className="size-4" />
        </Button>
        <Button type="button" size="sm" variant="ghost" className="h-8 w-8 p-0 text-white/60" onClick={() => exec("formatBlock", "h2")}>
          <Heading2 className="size-4" />
        </Button>
        <Button type="button" size="sm" variant="ghost" className="h-8 w-8 p-0 text-white/60" onClick={() => exec("insertUnorderedList")}>
          <List className="size-4" />
        </Button>
        <Button type="button" size="sm" variant="ghost" className="h-8 w-8 p-0 text-white/60" onClick={() => exec("insertOrderedList")}>
          <ListOrdered className="size-4" />
        </Button>
        <Button type="button" size="sm" variant="ghost" className="h-8 w-8 p-0 text-white/60" onClick={() => exec("insertHorizontalRule")}>
          <Minus className="size-4" />
        </Button>

        <div className="mx-2 h-5 w-px bg-white/10" />

        <select
          value={viewMode}
          onChange={(e) => setViewMode(e.target.value as "rich" | "markdown")}
          className="h-8 rounded-lg border border-white/10 bg-white/5 px-2 text-xs text-white/70"
        >
          <option value="rich">{p("editor.richText")}</option>
          <option value="markdown">{p("editor.markdown")}</option>
        </select>

        {onStatusChange && (
          <select
            value={status}
            onChange={(e) => onStatusChange(e.target.value as "draft" | "published" | "archived")}
            className="h-8 rounded-lg border border-white/10 bg-white/5 px-2 text-xs text-white/70"
          >
            <option value="draft">{p("editor.draft")}</option>
            <option value="published">{p("editor.published")}</option>
            <option value="archived">{p("editor.archived")}</option>
          </select>
        )}

        <div className="ml-auto flex items-center gap-2 text-xs text-white/40">
          <span>{p("editor.wordCount", { count: wordCount })}</span>
          <span>{p("editor.charCount", { count: charCount })}</span>
        </div>
      </div>

      <div className="border-b border-white/[0.06] p-2">
        <div className="flex flex-wrap items-center gap-2">
          <Sparkles className="size-4 text-premium-gold" />
          {AI_ACTION_KEYS.map(({ action, key }) => (
            <Button
              key={action}
              type="button"
              size="sm"
              variant="outline"
              disabled={aiBusy}
              className="h-7 rounded-lg border-white/10 text-xs text-white/70"
              onClick={() => void runAiAction(action)}
            >
              {p(key)}
            </Button>
          ))}
          <select
            value={aiTone}
            onChange={(e) => setAiTone(e.target.value)}
            className="h-7 rounded-lg border border-white/10 bg-white/5 px-2 text-xs text-white/60"
          >
            {CONTENT_PLATFORM_TONES.map((t) => (
              <option key={t} value={t}>{t}</option>
            ))}
          </select>
          <select
            value={aiStyle}
            onChange={(e) => setAiStyle(e.target.value)}
            className="h-7 rounded-lg border border-white/10 bg-white/5 px-2 text-xs text-white/60"
          >
            {CONTENT_PLATFORM_STYLES.map((s) => (
              <option key={s} value={s}>{s}</option>
            ))}
          </select>
        </div>
      </div>

      <input
        value={title}
        onChange={(e) => {
          onTitleChange(e.target.value);
          scheduleAutosave(e.target.value, body);
        }}
        placeholder={p("placeholders.documentTitle")}
        className="border-b border-white/[0.06] bg-transparent px-4 py-3 text-lg font-semibold text-white outline-none placeholder:text-white/30"
      />

      {viewMode === "rich" ? (
        <div
          ref={editorRef}
          contentEditable
          suppressContentEditableWarning
          onInput={handleEditorInput}
          className="min-h-[420px] flex-1 overflow-y-auto px-4 py-4 text-sm leading-relaxed text-white/80 outline-none prose-invert"
        />
      ) : (
        <textarea
          value={body}
          onChange={(e) => {
            onBodyChange(e.target.value);
            scheduleAutosave(title, e.target.value);
          }}
          className="min-h-[420px] flex-1 resize-none bg-transparent px-4 py-4 font-mono text-sm leading-relaxed text-white/80 outline-none"
          placeholder={p("placeholders.writeMarkdown")}
        />
      )}
    </div>
  );
}

function bodyToHtml(text: string): string {
  if (text.includes("<p>") || text.includes("<h")) return text;
  return text
    .split(/\n\n+/)
    .map((p) => `<p>${escapeHtml(p).replace(/\n/g, "<br>")}</p>`)
    .join("");
}

function htmlToText(html: string): string {
  const div = document.createElement("div");
  div.innerHTML = html;
  return div.innerText;
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import {
  Clock,
  FileText,
  Folder,
  FolderOpen,
  Plus,
  Search,
  Star,
  History,
} from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { useTranslation } from "@/lib/i18n/client";
import { useProductT } from "@/lib/i18n/use-scoped-t";
import { ContentEditor } from "@/components/dashboard/content-studio/content-editor";
import { ContentTemplatesPanel } from "@/components/dashboard/content-studio/content-templates-panel";
import type { ContentDocument, ContentProject, ContentVersion } from "@/types/content";

type BrandOption = { id: string; brand_name: string };

type Props = {
  initialDocuments?: ContentDocument[];
  initialProjects?: ContentProject[];
};

export function ContentPlatformWorkspace({ initialDocuments = [], initialProjects = [] }: Props) {
  const { t } = useTranslation();
  const p = useProductT("contentStudio");
  const [documents, setDocuments] = useState<ContentDocument[]>(initialDocuments);
  const [projects, setProjects] = useState<ContentProject[]>(initialProjects);
  const [brands, setBrands] = useState<BrandOption[]>([]);
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState<"all" | "favorites" | "recent">("all");
  const [activeDoc, setActiveDoc] = useState<ContentDocument | null>(null);
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [status, setStatus] = useState<"draft" | "published" | "archived">("draft");
  const [brandId, setBrandId] = useState<string | null>(null);
  const [versions, setVersions] = useState<ContentVersion[]>([]);
  const [showTemplates, setShowTemplates] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);

  const refreshDocuments = useCallback(async () => {
    const params = new URLSearchParams({ limit: "50" });
    if (search.trim()) params.set("search", search.trim());
    if (filter === "favorites") params.set("favorite", "true");
    if (filter === "recent") params.set("recent", "true");
    if (selectedProjectId) params.set("projectId", selectedProjectId);

    const res = await fetch(`/api/content-studio/documents?${params}`);
    const data = await res.json();
    setDocuments(data.documents ?? []);
  }, [search, filter, selectedProjectId]);

  const refreshProjects = useCallback(async () => {
    const res = await fetch("/api/content-studio/projects");
    const data = await res.json();
    setProjects(data.projects ?? []);
  }, []);

  useEffect(() => {
    void refreshDocuments();
  }, [refreshDocuments]);

  useEffect(() => {
    void refreshProjects();
    void fetch("/api/content-studio/projects")
      .then(() => refreshProjects());
    void fetch("/api/brand-identity?limit=20")
      .then((r) => r.json())
      .then((d) => {
        const list = (d.generations ?? []).map((g: { id: string; brand_name: string }) => ({
          id: g.id,
          brand_name: g.brand_name,
        }));
        setBrands(list);
      })
      .catch(() => {});
  }, [refreshProjects]);

  const openDocument = async (doc: ContentDocument) => {
    setActiveDoc(doc);
    setTitle(doc.title);
    setBody(doc.body);
    setStatus(doc.status);
    setBrandId(doc.brand_identity_id);
    setShowTemplates(false);

    const res = await fetch(`/api/content-studio/versions?documentId=${doc.id}&limit=10`);
    const data = await res.json();
    setVersions(data.versions ?? []);
  };

  const createDocument = async (projectId?: string | null) => {
    const res = await fetch("/api/content-studio/documents", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: p("workspace.untitledDocument"),
        body: "",
        projectId: projectId ?? selectedProjectId ?? undefined,
        status: "draft",
      }),
    });
    const data = await res.json();
    if (!res.ok) {
      toast.error(data.error ?? p("errors.createDocumentFailed"));
      return;
    }
    await refreshDocuments();
    void openDocument(data.document);
  };

  const createFolder = async () => {
    const name = window.prompt(p("workspace.folderNamePrompt"));
    if (!name?.trim()) return;
    const res = await fetch("/api/content-studio/projects", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name: name.trim(), isFolder: true, parentId: selectedProjectId }),
    });
    if (!res.ok) {
      toast.error(p("errors.createFolderFailed"));
      return;
    }
    await refreshProjects();
  };

  const createProject = async () => {
    const name = window.prompt(p("workspace.projectNamePrompt"));
    if (!name?.trim()) return;
    const res = await fetch("/api/content-studio/projects", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name: name.trim(), isFolder: false }),
    });
    if (!res.ok) {
      toast.error(p("errors.createProjectFailed"));
      return;
    }
    await refreshProjects();
  };

  const autosave = async (payload: { title: string; body: string }) => {
    if (!activeDoc) return;
    await fetch(`/api/content-studio/documents/${activeDoc.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: payload.title,
        body: payload.body,
        autosave: true,
        brandIdentityId: brandId,
        status,
      }),
    });
  };

  const toggleFavorite = async (doc: ContentDocument) => {
    await fetch(`/api/content-studio/documents/${doc.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ is_favorite: !doc.is_favorite }),
    });
    await refreshDocuments();
  };

  const restoreVersion = async (versionId: string) => {
    if (!activeDoc) return;
    const res = await fetch("/api/content-studio/versions", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "restore", documentId: activeDoc.id, versionId }),
    });
    const data = await res.json();
    if (!res.ok) {
      toast.error(data.error ?? p("errors.restoreFailed"));
      return;
    }
    void openDocument(data.document);
    toast.success(p("toasts.versionRestored"));
  };

  const folders = useMemo(
    () => projects.filter((p) => p.is_folder),
    [projects],
  );
  const projectList = useMemo(
    () => projects.filter((p) => !p.is_folder),
    [projects],
  );

  return (
    <div className="grid gap-4 lg:grid-cols-[280px_1fr]">
      <aside className="space-y-4 rounded-xl border border-white/[0.08] bg-white/[0.02] p-4">
        <div className="flex gap-2">
          <Button size="sm" className="flex-1 rounded-lg" onClick={() => void createDocument()}>
            <Plus className="mr-1 size-4" /> {p("workspace.newDoc")}
          </Button>
          <Button size="sm" variant="outline" className="rounded-lg border-white/10" onClick={() => void createProject()}>
            Project
          </Button>
          <Button size="sm" variant="outline" className="rounded-lg border-white/10" onClick={() => void createFolder()}>
            <Folder className="size-4" />
          </Button>
        </div>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-white/30" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder={p("placeholders.searchDocuments")}
            className="rounded-lg border-white/10 bg-white/5 pl-9 text-sm text-white"
          />
        </div>

        <div className="flex gap-1">
          {(["all", "favorites", "recent"] as const).map((f) => (
            <button
              key={f}
              type="button"
              onClick={() => setFilter(f)}
              className={cn(
                "flex-1 rounded-lg px-2 py-1.5 text-xs capitalize",
                filter === f ? "bg-premium-gold/15 text-premium-gold-light" : "text-white/40 hover:bg-white/5",
              )}
            >
              {f}
            </button>
          ))}
        </div>

        <div>
          <p className="mb-2 text-xs font-medium uppercase tracking-wide text-white/40"> {p("workspace.projects")}</p>
          <div className="space-y-1">
            <button
              type="button"
              onClick={() => setSelectedProjectId(null)}
              className={cn(
                "flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-sm",
                !selectedProjectId ? "bg-white/10 text-white" : "text-white/50 hover:bg-white/5",
              )}
            >
              <FolderOpen className="size-4" /> {p("workspace.allDocuments")}
            </button>
            {projectList.map((p) => (
              <button
                key={p.id}
                type="button"
                onClick={() => setSelectedProjectId(p.id)}
                className={cn(
                  "flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-sm",
                  selectedProjectId === p.id ? "bg-white/10 text-white" : "text-white/50 hover:bg-white/5",
                )}
              >
                <FileText className="size-4" style={{ color: p.color }} /> {p.name}
              </button>
            ))}
          </div>
        </div>

        {folders.length > 0 && (
          <div>
            <p className="mb-2 text-xs font-medium uppercase tracking-wide text-white/40"> {p("workspace.folders")}</p>
            <div className="space-y-1">
              {folders.map((f) => (
                <button
                  key={f.id}
                  type="button"
                  onClick={() => setSelectedProjectId(f.id)}
                  className="flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-sm text-white/50 hover:bg-white/5"
                >
                  <Folder className="size-4" /> {f.name}
                </button>
              ))}
            </div>
          </div>
        )}

        <div>
          <p className="mb-2 text-xs font-medium uppercase tracking-wide text-white/40"> {p("workspace.documents")}</p>
          <div className="max-h-[320px] space-y-1 overflow-y-auto">
            {documents.map((doc) => (
              <div
                key={doc.id}
                className={cn(
                  "group flex items-center gap-1 rounded-lg px-2 py-1.5",
                  activeDoc?.id === doc.id ? "bg-premium-gold/10" : "hover:bg-white/5",
                )}
              >
                <button
                  type="button"
                  onClick={() => void openDocument(doc)}
                  className="flex min-w-0 flex-1 items-center gap-2 text-left text-sm text-white/70"
                >
                  <FileText className="size-4 shrink-0 text-white/40" />
                  <span className="truncate">{doc.title}</span>
                </button>
                <button
                  type="button"
                  onClick={() => void toggleFavorite(doc)}
                  className="opacity-0 group-hover:opacity-100"
                >
                  <Star className={cn("size-3.5", doc.is_favorite ? "fill-premium-gold text-premium-gold" : "text-white/30")} />
                </button>
              </div>
            ))}
            {documents.length === 0 && (
              <p className="px-2 py-4 text-center text-xs text-white/30"> {p("workspace.noDocuments")}</p>
            )}
          </div>
        </div>
      </aside>

      <section className="space-y-4">
        <div className="flex flex-wrap items-center gap-2">
          <Button
            size="sm"
            variant={showTemplates ? "default" : "outline"}
            className="rounded-lg border-white/10"
            onClick={() => setShowTemplates((v) => !v)}
          >
            Templates
          </Button>
          {activeDoc && (
            <Button
              size="sm"
              variant={showHistory ? "default" : "outline"}
              className="rounded-lg border-white/10"
              onClick={() => setShowHistory((v) => !v)}
            >
              <History className="mr-1 size-4" /> {p("workspace.history")}
            </Button>
          )}
          {brands.length > 0 && (
            <select
              value={brandId ?? ""}
              onChange={(e) => setBrandId(e.target.value || null)}
              className="h-9 rounded-lg border border-white/10 bg-white/5 px-3 text-sm text-white/70"
            >
              <option value="">{p("workspace.noBrandVoice")}</option>
              {brands.map((b) => (
                <option key={b.id} value={b.id}>{b.brand_name}</option>
              ))}
            </select>
          )}
        </div>

        {showTemplates && (
          <ContentTemplatesPanel
            onSelect={async ({ prompt, contentTool, contentType }) => {
              if (!activeDoc) await createDocument();
              setBody(prompt);
              setShowTemplates(false);
              toast.success(p("toasts.templateLoaded", { tool: contentTool, type: contentType }));
            }}
          />
        )}

        {showHistory && activeDoc && (
          <div className="rounded-xl border border-white/[0.08] bg-white/[0.02] p-4">
            <p className="mb-3 text-sm font-medium text-white"> {p("workspace.versionHistory")}</p>
            <div className="space-y-2">
              {versions.map((v) => (
                <div key={v.id} className="flex items-center justify-between rounded-lg border border-white/[0.06] px-3 py-2">
                  <div>
                    <p className="text-sm text-white/80">v{v.version_number} — {v.change_summary}</p>
                    <p className="text-xs text-white/40">
                      <Clock className="mr-1 inline size-3" />
                      {new Date(v.created_at).toLocaleString()}
                    </p>
                  </div>
                  <Button size="sm" variant="outline" className="rounded-lg border-white/10 text-xs" onClick={() => void restoreVersion(v.id)}>
                    Restore
                  </Button>
                </div>
              ))}
              {versions.length === 0 && <p className="text-sm text-white/40"> {p("workspace.noVersions")}</p>}
            </div>
          </div>
        )}

        {activeDoc ? (
          <ContentEditor
            documentId={activeDoc.id}
            title={title}
            body={body}
            status={status}
            brandIdentityId={brandId}
            onTitleChange={setTitle}
            onBodyChange={setBody}
            onStatusChange={setStatus}
            onAutosave={autosave}
          />
        ) : (
          <div className="flex min-h-[480px] flex-col items-center justify-center rounded-xl border border-dashed border-white/10 bg-white/[0.02] p-8 text-center">
            <FileText className="size-12 text-white/20" />
            <p className="mt-4 text-white/50"> {p("workspace.selectDocument")}</p>
            <Button className="mt-4 rounded-xl" onClick={() => void createDocument()}>
              <Plus className="mr-2 size-4" /> {p("workspace.newDocument")}
            </Button>
          </div>
        )}
      </section>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { FileText, Search } from "lucide-react";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { useTranslation } from "@/lib/i18n/client";
import { useProductT } from "@/lib/i18n/use-scoped-t";
import { applyTemplateVariables } from "@/lib/content-studio/templates";
import type { ContentTemplate, ContentTemplateVariable } from "@/types/content";

type Props = {
  onSelect: (payload: {
    template: ContentTemplate;
    prompt: string;
    contentTool: string;
    contentType: string;
  }) => void;
};

export function ContentTemplatesPanel({ onSelect }: Props) {
  const { t } = useTranslation();
  const p = useProductT("contentStudio");
  const [templates, setTemplates] = useState<ContentTemplate[]>([]);
  const [categories, setCategories] = useState<string[]>([]);
  const [category, setCategory] = useState<string>("all");
  const [search, setSearch] = useState("");
  const [values, setValues] = useState<Record<string, string>>({});
  const [active, setActive] = useState<ContentTemplate | null>(null);
  const [loaded, setLoaded] = useState(false);

  const load = async () => {
    if (loaded) return;
    const res = await fetch("/api/content-studio/templates");
    const data = await res.json();
    setTemplates(data.templates ?? []);
    setCategories(data.categories ?? []);
    setLoaded(true);
  };

  useEffect(() => {
    void load();
  }, []);

  const filtered = templates.filter((t) => {
    if (category !== "all" && t.category !== category) return false;
    if (!search.trim()) return true;
    const q = search.toLowerCase();
    return t.name.toLowerCase().includes(q) || t.description.toLowerCase().includes(q);
  });

  const openTemplate = (t: ContentTemplate) => {
    setActive(t);
    const defaults: Record<string, string> = {};
    for (const v of t.variables ?? []) {
      if (v.default) defaults[v.key] = v.default;
    }
    setValues(defaults);
  };

  const useTemplate = () => {
    if (!active) return;
    const prompt = applyTemplateVariables(
      active.prompt_structure,
      values,
      active.variables as ContentTemplateVariable[],
    );
    onSelect({
      template: active,
      prompt,
      contentTool: active.content_tool,
      contentType: active.content_type,
    });
    setActive(null);
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap gap-2">
        <div className="relative min-w-[200px] flex-1">
          <Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-white/30" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder={p("placeholders.searchTemplates")}
            className="rounded-xl border-white/10 bg-white/5 pl-9 text-white"
          />
        </div>
        <select
          value={category}
          onChange={(e) => setCategory(e.target.value)}
          className="h-10 rounded-xl border border-white/10 bg-white/5 px-3 text-sm text-white/70"
        >
          <option value="all">{p("sections.templates")}</option>
          {categories.map((c) => (
            <option key={c} value={c}>{c}</option>
          ))}
        </select>
      </div>

      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {filtered.map((t) => (
          <button
            key={t.id}
            type="button"
            onClick={() => openTemplate(t)}
            className="rounded-xl border border-white/[0.08] bg-white/[0.02] p-4 text-left transition hover:border-premium-gold/30 hover:bg-white/[0.04]"
          >
            <div className="flex items-start gap-3">
              <FileText className="mt-0.5 size-5 shrink-0 text-premium-gold" />
              <div>
                <p className="font-medium text-white">{t.name}</p>
                <p className="mt-1 text-xs text-premium-gold/80">{t.category}</p>
                <p className="mt-2 line-clamp-2 text-sm text-white/50">{t.preview || t.description}</p>
              </div>
            </div>
          </button>
        ))}
      </div>

      {active && (
        <div className="rounded-xl border border-premium-gold/20 bg-premium-gold/5 p-4">
          <p className="font-medium text-white">{active.name}</p>
          <p className="mt-1 text-sm text-white/50">{active.description}</p>
          <div className="mt-4 grid gap-3 sm:grid-cols-2">
            {(active.variables as ContentTemplateVariable[]).map((v) => (
              <div key={v.key}>
                <label className="text-xs text-white/50">{v.label}</label>
                <Input
                  value={values[v.key] ?? ""}
                  onChange={(e) => setValues((prev) => ({ ...prev, [v.key]: e.target.value }))}
                  placeholder={v.placeholder}
                  className="mt-1 rounded-lg border-white/10 bg-white/5 text-white"
                />
              </div>
            ))}
          </div>
          <div className="mt-4 flex gap-2">
            <button
              type="button"
              onClick={useTemplate}
              className="rounded-lg bg-premium-gold/20 px-4 py-2 text-sm font-medium text-premium-gold-light"
            >
              {p("actions.applyTemplate")}
            </button>
            <button
              type="button"
              onClick={() => setActive(null)}
              className="rounded-lg px-4 py-2 text-sm text-white/50"
            >
              {t("common.cancel")}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  Copy,
  Heart,
  LayoutTemplate,
  Loader2,
  Monitor,
  Plus,
  Smartphone,
  Star,
  Tablet,
  Upload,
  UserRound,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { DashboardPanel } from "@/components/dashboard/ui/dashboard-card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { cn } from "@/lib/utils";
import { useFormatter } from "@/lib/i18n/use-formatter";
import { useProductT } from "@/lib/i18n/use-scoped-t";
import { useTranslation } from "@/lib/i18n/client";
import {
  CREATOR_MARKETPLACE_CATEGORIES,
  type CreatorMarketplaceCategory,
  type CreatorTemplateListing,
  type MarketplaceCreatorProfile,
} from "@/lib/marketplace/templates";

type CatalogResponse = {
  listings: CreatorTemplateListing[];
  categories: Array<{ id: CreatorMarketplaceCategory; label: string }>;
  styles: string[];
  creators: MarketplaceCreatorProfile[];
  count: number;
};

type DetailResponse = {
  listing: CreatorTemplateListing;
  previewHtml: string;
  builderHref?: string;
};

type CreatorMeResponse = {
  profile: MarketplaceCreatorProfile;
  listings: CreatorTemplateListing[];
  count: number;
};

type Viewport = "desktop" | "tablet" | "mobile";

const VIEWPORT_WIDTH: Record<Viewport, string> = {
  desktop: "100%",
  tablet: "768px",
  mobile: "390px",
};

export function CreatorMarketplace() {
  const pt = useProductT("creatorMarketplace");
  const { formatCurrency } = useFormatter();
  const formatListingPrice = (cents: number) =>
    cents <= 0 ? pt("free") : formatCurrency(cents);
  const router = useRouter();
  const [catalog, setCatalog] = useState<CatalogResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [category, setCategory] = useState<CreatorMarketplaceCategory | "all">(
    "all",
  );
  const [style, setStyle] = useState<string>("all");
  const [price, setPrice] = useState<"all" | "free" | "paid">("all");
  const [sort, setSort] = useState("popular");
  const [query, setQuery] = useState("");
  const [favoritesOnly, setFavoritesOnly] = useState(false);

  const [preview, setPreview] = useState<DetailResponse | null>(null);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [viewport, setViewport] = useState<Viewport>("desktop");
  const [previewLoading, setPreviewLoading] = useState(false);
  const [usingId, setUsingId] = useState<string | null>(null);

  const [uploadOpen, setUploadOpen] = useState(false);
  const [creatorOpen, setCreatorOpen] = useState(false);
  const [creatorMe, setCreatorMe] = useState<CreatorMeResponse | null>(null);
  const [creatorLoading, setCreatorLoading] = useState(false);

  const loadCatalog = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (category !== "all") params.set("category", category);
      if (style !== "all") params.set("style", style);
      if (price !== "all") params.set("price", price);
      if (sort) params.set("sort", sort);
      if (query.trim()) params.set("q", query.trim());
      if (favoritesOnly) params.set("favorites", "1");
      const res = await fetch(`/api/marketplace/templates?${params}`);
      if (!res.ok) throw new Error(pt("errors.loadFailed"));
      const data = (await res.json()) as CatalogResponse;
      setCatalog(data);
    } catch {
      setCatalog(null);
    } finally {
      setLoading(false);
    }
  }, [category, style, price, sort, query, favoritesOnly]);

  useEffect(() => {
    const t = setTimeout(() => {
      void loadCatalog();
    }, 120);
    return () => clearTimeout(t);
  }, [loadCatalog]);

  const openPreview = async (id: string) => {
    setPreviewLoading(true);
    setPreviewOpen(true);
    setViewport("desktop");
    try {
      const res = await fetch(
        `/api/marketplace/templates/${encodeURIComponent(id)}`,
      );
      if (!res.ok) throw new Error(pt("errors.previewFailed"));
      const data = (await res.json()) as DetailResponse;
      setPreview(data);
    } catch {
      setPreview(null);
    } finally {
      setPreviewLoading(false);
    }
  };

  const toggleFavorite = async (listing: CreatorTemplateListing) => {
    const res = await fetch(
      `/api/marketplace/templates/${encodeURIComponent(listing.id)}/favorite`,
      { method: "POST" },
    );
    if (res.status === 401) {
      router.push("/login");
      return;
    }
    if (!res.ok) return;
    void loadCatalog();
    if (preview?.listing.id === listing.id) {
      const fav = (await res.json()) as { favorited: boolean };
      setPreview({
        ...preview,
        listing: { ...preview.listing, favorited: fav.favorited },
      });
    }
  };

  const applyListingTemplate = async (listingId: string) => {
    setUsingId(listingId);
    try {
      const res = await fetch(
        `/api/marketplace/templates/${encodeURIComponent(listingId)}/use`,
        { method: "POST" },
      );
      if (!res.ok) throw new Error(pt("errors.useFailed"));
      const data = (await res.json()) as { builderHref: string };
      router.push(data.builderHref);
    } catch {
      setUsingId(null);
    }
  };

  const openCreator = async () => {
    setCreatorOpen(true);
    setCreatorLoading(true);
    try {
      const res = await fetch("/api/marketplace/creators/me");
      if (res.status === 401) {
        router.push("/login");
        return;
      }
      if (!res.ok) throw new Error("Failed");
      setCreatorMe((await res.json()) as CreatorMeResponse);
    } catch {
      setCreatorMe(null);
    } finally {
      setCreatorLoading(false);
    }
  };

  const listings = catalog?.listings ?? [];
  const categories =
    catalog?.categories?.length
      ? catalog.categories
      : CREATOR_MARKETPLACE_CATEGORIES;
  const styles = catalog?.styles?.length
    ? catalog.styles
    : [
        "luxury",
        "modern",
        "corporate",
        "creative",
        "minimal",
        "premium-saas",
        "technology",
      ];

  const featured = useMemo(
    () =>
      [...listings]
        .sort((a, b) => b.analytics.uses - a.analytics.uses)
        .slice(0, 4),
    [listings],
  );

  return (
    <div className="space-y-8">
      <DashboardPanel className="p-5 sm:p-6">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
          <div>
            <div className="mb-2 inline-flex items-center gap-2 rounded-full border border-premium-gold/25 bg-premium-gold/10 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-[0.14em] text-premium-gold">
              <LayoutTemplate className="size-3" />
              {pt("badge")}
            </div>
            <h2 className="text-xl font-bold text-white sm:text-2xl">
              {pt("title")}
            </h2>
            <p className="mt-1 max-w-2xl text-[13px] leading-relaxed text-white/45">
              {pt("description")}
            </p>
          </div>
          <div className="flex flex-wrap gap-2">
            <Button
              variant="outline"
              className="border-white/15 text-white"
              onClick={() => void openCreator()}
            >
              <UserRound className="size-4" />
              {pt("creatorProfile")}
            </Button>
            <Button
              className="bg-premium-gold text-black hover:bg-premium-gold/90"
              onClick={() => setUploadOpen(true)}
            >
              <Upload className="size-4" />
              {pt("uploadTemplate")}
            </Button>
          </div>
        </div>

        <div className="mt-6 grid gap-3 lg:grid-cols-6">
          <Input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder={pt("searchPlaceholder")}
            className="border-white/10 bg-white/5 text-white placeholder:text-white/30 lg:col-span-2"
          />
          <select
            value={category}
            onChange={(e) =>
              setCategory(e.target.value as CreatorMarketplaceCategory | "all")
            }
            className="h-10 rounded-md border border-white/10 bg-[#121212] px-3 text-sm text-white"
          >
            <option value="all">{pt("allIndustries")}</option>
            {categories.map((c) => (
              <option key={c.id} value={c.id}>
                {c.label}
              </option>
            ))}
          </select>
          <select
            value={style}
            onChange={(e) => setStyle(e.target.value)}
            className="h-10 rounded-md border border-white/10 bg-[#121212] px-3 text-sm text-white"
          >
            <option value="all">{pt("allStyles")}</option>
            {styles.map((s) => (
              <option key={s} value={s}>
                {s}
              </option>
            ))}
          </select>
          <select
            value={price}
            onChange={(e) =>
              setPrice(e.target.value as "all" | "free" | "paid")
            }
            className="h-10 rounded-md border border-white/10 bg-[#121212] px-3 text-sm text-white"
          >
            <option value="all">{pt("anyPrice")}</option>
            <option value="free">{pt("free")}</option>
            <option value="paid">{pt("paid")}</option>
          </select>
          <select
            value={sort}
            onChange={(e) => setSort(e.target.value)}
            className="h-10 rounded-md border border-white/10 bg-[#121212] px-3 text-sm text-white"
          >
            <option value="popular">{pt("sort.popular")}</option>
            <option value="newest">{pt("sort.newest")}</option>
            <option value="rating">{pt("sort.rating")}</option>
            <option value="price-asc">{pt("sort.priceAsc")}</option>
            <option value="price-desc">{pt("sort.priceDesc")}</option>
          </select>
        </div>

        <div className="mt-3 flex flex-wrap items-center gap-2">
          <Button
            size="sm"
            variant={favoritesOnly ? "default" : "outline"}
            className={cn(
              favoritesOnly
                ? "bg-premium-gold text-black"
                : "border-white/15 text-white",
            )}
            onClick={() => setFavoritesOnly((v) => !v)}
          >
            <Heart className={cn("size-3.5", favoritesOnly && "fill-current")} />
            {pt("favorites")}
          </Button>
          <Link href="/dashboard/website-builder">
            <Button
              size="sm"
              variant="outline"
              className="border-white/15 text-white"
            >
              {pt("openWebsiteBuilder")}
            </Button>
          </Link>
        </div>
      </DashboardPanel>

      {featured.length > 0 && !favoritesOnly && !query ? (
        <section>
          <h3 className="mb-3 text-sm font-semibold text-white/80">
            {pt("trending")}
          </h3>
          <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
            {featured.map((l) => (
              <ListingCard
                key={l.id}
                listing={l}
                using={usingId === l.id}
                onPreview={() => void openPreview(l.id)}
                onFavorite={() => void toggleFavorite(l)}
                onUse={() => void applyListingTemplate(l.id)}
              />
            ))}
          </div>
        </section>
      ) : null}

      <section>
        <div className="mb-3 flex items-center justify-between">
          <h3 className="text-sm font-semibold text-white/80">
            {pt("marketplace")} {catalog ? `(${catalog.count})` : ""}
          </h3>
        </div>
        {loading ? (
          <div className="flex items-center gap-2 py-16 text-white/40">
            <Loader2 className="size-4 animate-spin" />
            {pt("loading")}
          </div>
        ) : listings.length === 0 ? (
          <DashboardPanel className="p-8 text-center text-sm text-white/40">
            {pt("noResults")}
          </DashboardPanel>
        ) : (
          <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
            {listings.map((l) => (
              <ListingCard
                key={l.id}
                listing={l}
                using={usingId === l.id}
                onPreview={() => void openPreview(l.id)}
                onFavorite={() => void toggleFavorite(l)}
                onUse={() => void applyListingTemplate(l.id)}
              />
            ))}
          </div>
        )}
      </section>

      <Dialog open={previewOpen} onOpenChange={setPreviewOpen}>
        <DialogContent className="max-h-[92vh] max-w-5xl overflow-hidden border-white/10 bg-[#0c0c0c] text-white sm:max-w-5xl">
          <DialogHeader>
            <DialogTitle>
              {preview?.listing.title || pt("previewTitle")}
            </DialogTitle>
            <DialogDescription className="text-white/45">
              {preview?.listing.description || pt("previewDescription")}
            </DialogDescription>
          </DialogHeader>

          <div className="flex flex-wrap items-center gap-2">
            {(
              [
                ["desktop", Monitor],
                ["tablet", Tablet],
                ["mobile", Smartphone],
              ] as const
            ).map(([key, Icon]) => (
              <Button
                key={key}
                size="sm"
                variant={viewport === key ? "default" : "outline"}
                className={cn(
                  viewport === key
                    ? "bg-premium-gold text-black"
                    : "border-white/15 text-white",
                )}
                onClick={() => setViewport(key)}
              >
                <Icon className="size-3.5" />
                {pt(`viewports.${key}`)}
              </Button>
            ))}
          </div>

          <div className="mt-3 flex justify-center overflow-auto rounded-xl border border-white/10 bg-[#080808] p-3">
            {previewLoading ? (
              <div className="flex h-[420px] items-center justify-center text-white/40">
                <Loader2 className="size-5 animate-spin" />
              </div>
            ) : preview?.previewHtml ? (
              <iframe
                title={pt("previewIframe")}
                srcDoc={preview.previewHtml}
                className="h-[520px] rounded-lg border border-white/10 bg-white transition-all"
                style={{ width: VIEWPORT_WIDTH[viewport], maxWidth: "100%" }}
              />
            ) : (
              <div className="flex h-[320px] items-center justify-center text-sm text-white/40">
                {pt("previewUnavailable")}
              </div>
            )}
          </div>

          {preview?.listing ? (
            <div className="grid gap-3 text-[12px] text-white/55 sm:grid-cols-4">
              <div>
                <p className="font-semibold text-white/80">{pt("author")}</p>
                <p>{preview.listing.author.displayName}</p>
                <p>@{preview.listing.author.handle}</p>
              </div>
              <div>
                <p className="font-semibold text-white/80">{pt("rating")}</p>
                <p>
                  {preview.listing.reviews.averageRating.toFixed(1)} ·{" "}
                  {pt("reviews", { count: preview.listing.reviews.reviewCount })}
                </p>
                <p>{formatListingPrice(preview.listing.commerce.priceCents)}</p>
              </div>
              <div>
                <p className="font-semibold text-white/80">{pt("version")}</p>
                <p>
                  {preview.listing.versions.find((v) => v.isLatest)?.version ||
                    "1.0.0"}
                </p>
                <p className="line-clamp-2">
                  {preview.listing.versions.find((v) => v.isLatest)
                    ?.changelog || "—"}
                </p>
              </div>
              <div>
                <p className="font-semibold text-white/80">{pt("features")}</p>
                <p className="line-clamp-3">
                  {preview.listing.features.join(" · ")}
                </p>
              </div>
            </div>
          ) : null}

          <DialogFooter className="gap-2 sm:justify-between">
            <Button
              variant="outline"
              className="border-white/15 text-white"
              disabled={!preview?.listing}
              onClick={() =>
                preview?.listing && void toggleFavorite(preview.listing)
              }
            >
              <Heart
                className={cn(
                  "size-4",
                  preview?.listing.favorited && "fill-premium-gold text-premium-gold",
                )}
              />
              {preview?.listing.favorited ? pt("favorited") : pt("favorite")}
            </Button>
            {preview?.listing ? (
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  className="border-white/15 text-white"
                  disabled={usingId === preview.listing.id}
                  onClick={() => void applyListingTemplate(preview.listing.id)}
                >
                  <Copy className="size-4" />
                  {pt("duplicate")}
                </Button>
                <Button
                  className="bg-premium-gold text-black hover:bg-premium-gold/90"
                  disabled={usingId === preview.listing.id}
                  onClick={() => void applyListingTemplate(preview.listing.id)}
                >
                  {usingId === preview.listing.id ? (
                    <Loader2 className="size-4 animate-spin" />
                  ) : null}
                  {pt("useTemplate")}
                </Button>
              </div>
            ) : null}
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <UploadTemplateDialog
        open={uploadOpen}
        onOpenChange={setUploadOpen}
        categories={categories}
        styles={styles}
        onUploaded={() => {
          setUploadOpen(false);
          void loadCatalog();
        }}
      />

      <CreatorProfileDialog
        open={creatorOpen}
        onOpenChange={setCreatorOpen}
        loading={creatorLoading}
        data={creatorMe}
        onRefresh={() => void openCreator()}
        onPreview={(id) => void openPreview(id)}
      />
    </div>
  );
}

function ListingCard(props: {
