function UploadTemplateDialog(props: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  categories: Array<{ id: CreatorMarketplaceCategory; label: string }>;
  styles: string[];
  onUploaded: () => void;
}) {
  const pt = useProductT("creatorMarketplace");
  const { t } = useTranslation();
  const router = useRouter();
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [title, setTitle] = useState("");
  const [tagline, setTagline] = useState("");
  const [description, setDescription] = useState("");
  const [category, setCategory] =
    useState<CreatorMarketplaceCategory>("saas");
  const [style, setStyle] = useState("modern");
  const [features, setFeatures] = useState("");
  const [priceCents, setPriceCents] = useState("0");
  const [version, setVersion] = useState("1.0.0");
  const [changelog, setChangelog] = useState(pt("upload.initialChangelog"));

  const reset = () => {
    setTitle("");
    setTagline("");
    setDescription("");
    setCategory("saas");
    setStyle("modern");
    setFeatures("");
    setPriceCents("0");
    setVersion("1.0.0");
    setChangelog(pt("upload.initialChangelog"));
    setError(null);
  };

  const submit = async () => {
    setSaving(true);
    setError(null);
    try {
      const res = await fetch("/api/marketplace/templates", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title,
          tagline: tagline || undefined,
          description,
          category,
          style,
          features: features
            .split(",")
            .map((s) => s.trim())
            .filter(Boolean),
          priceCents: Math.max(0, Number(priceCents) || 0),
          priceModel: Number(priceCents) > 0 ? "paid" : "free",
          version,
          changelog,
          status: "published",
        }),
      });
      if (res.status === 401) {
        router.push("/login");
        return;
      }
      if (!res.ok) {
        const data = (await res.json()) as { error?: string };
        throw new Error(data.error || pt("upload.uploadFailed"));
      }
      reset();
      props.onUploaded();
    } catch (err) {
      setError(err instanceof Error ? err.message : pt("upload.uploadFailed"));
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog
      open={props.open}
      onOpenChange={(open) => {
        if (!open) reset();
        props.onOpenChange(open);
      }}
    >
      <DialogContent className="max-h-[90vh] overflow-y-auto border-white/10 bg-[#0c0c0c] text-white sm:max-w-xl">
        <DialogHeader>
          <DialogTitle>{pt("upload.title")}</DialogTitle>
          <DialogDescription className="text-white/45">
            {pt("upload.description")}
          </DialogDescription>
        </DialogHeader>

        <div className="grid gap-3">
          <Input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder={pt("upload.titlePlaceholder")}
            className="border-white/10 bg-white/5 text-white"
          />
          <Input
            value={tagline}
            onChange={(e) => setTagline(e.target.value)}
            placeholder={pt("upload.taglinePlaceholder")}
            className="border-white/10 bg-white/5 text-white"
          />
          <Textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder={pt("upload.descriptionPlaceholder")}
            className="min-h-[96px] border-white/10 bg-white/5 text-white"
          />
          <div className="grid gap-3 sm:grid-cols-2">
            <select
              value={category}
              onChange={(e) =>
                setCategory(e.target.value as CreatorMarketplaceCategory)
              }
              className="h-10 rounded-md border border-white/10 bg-[#121212] px-3 text-sm text-white"
            >
              {props.categories.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.label}
                </option>
              ))}
            </select>
            <select
              value={style}
              onChange={(e) => setStyle(e.target.value)}
              className="h-10 rounded-md border border-white/10 bg-[#121212] px-3 text-sm text-white"
            >
              {props.styles.map((s) => (
                <option key={s} value={s}>
                  {s}
                </option>
              ))}
            </select>
          </div>
          <Input
            value={features}
            onChange={(e) => setFeatures(e.target.value)}
            placeholder={pt("upload.featuresPlaceholder")}
            className="border-white/10 bg-white/5 text-white"
          />
          <div className="grid gap-3 sm:grid-cols-3">
            <Input
              value={priceCents}
              onChange={(e) => setPriceCents(e.target.value)}
              placeholder={pt("upload.pricePlaceholder")}
              className="border-white/10 bg-white/5 text-white"
            />
            <Input
              value={version}
              onChange={(e) => setVersion(e.target.value)}
              placeholder={pt("upload.versionPlaceholder")}
              className="border-white/10 bg-white/5 text-white"
            />
            <Input
              value={changelog}
              onChange={(e) => setChangelog(e.target.value)}
              placeholder={pt("upload.changelogPlaceholder")}
              className="border-white/10 bg-white/5 text-white"
            />
          </div>
          {error ? (
            <p className="text-[12px] text-red-400">{error}</p>
          ) : null}
        </div>

        <DialogFooter>
          <Button
            variant="outline"
            className="border-white/15 text-white"
            onClick={() => props.onOpenChange(false)}
          >
            {t("common.cancel")}
          </Button>
          <Button
            className="bg-premium-gold text-black hover:bg-premium-gold/90"
            disabled={saving || title.trim().length < 3}
            onClick={() => void submit()}
          >
            {saving ? (
              <Loader2 className="size-4 animate-spin" />
            ) : (
              <Plus className="size-4" />
            )}
            {pt("upload.publishListing")}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

function CreatorProfileDialog(props: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  loading: boolean;
  data: CreatorMeResponse | null;
  onRefresh: () => void;
  onPreview: (id: string) => void;
}) {
  const pt = useProductT("creatorMarketplace");
  const { t } = useTranslation();
  const { formatCurrency } = useFormatter();
  const formatListingPrice = (cents: number) =>
    cents <= 0 ? pt("free") : formatCurrency(cents);
  const [versionListingId, setVersionListingId] = useState<string | null>(null);
  const [version, setVersion] = useState("");
  const [changelog, setChangelog] = useState("");
  const [savingVersion, setSavingVersion] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const addVersion = async () => {
    if (!versionListingId) return;
    setSavingVersion(true);
    setError(null);
    try {
      const res = await fetch(
        `/api/marketplace/templates/${encodeURIComponent(versionListingId)}/versions`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ version, changelog }),
        },
      );
      if (!res.ok) {
        const data = (await res.json()) as { error?: string };
        throw new Error(data.error || pt("creator.versionFailed"));
      }
      setVersionListingId(null);
      setVersion("");
      setChangelog("");
      props.onRefresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : pt("creator.versionFailed"));
    } finally {
      setSavingVersion(false);
    }
  };

  return (
    <Dialog open={props.open} onOpenChange={props.onOpenChange}>
      <DialogContent className="max-h-[90vh] overflow-y-auto border-white/10 bg-[#0c0c0c] text-white sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>{pt("creator.title")}</DialogTitle>
          <DialogDescription className="text-white/45">
            {pt("creator.description")}
          </DialogDescription>
        </DialogHeader>

        {props.loading ? (
          <div className="flex items-center gap-2 py-10 text-white/40">
            <Loader2 className="size-4 animate-spin" />
            {pt("creator.loading")}
          </div>
        ) : props.data ? (
          <div className="space-y-5">
            <div className="flex items-start gap-4">
              <div
                className="size-14 shrink-0 rounded-full"
                style={{ background: props.data.profile.avatarGradient }}
              />
              <div>
                <h3 className="text-lg font-bold text-white">
                  {props.data.profile.displayName}
                </h3>
                <p className="text-[12px] text-white/45">
                  @{props.data.profile.handle} ·{" "}
                  {pt("creator.templatesCount", { count: props.data.profile.templateCount })} ·{" "}
                  {pt("creator.payouts", {
                    status: props.data.profile.payoutReady
                      ? pt("creator.payoutsReady")
                      : pt("creator.payoutsPending"),
                  })}
                </p>
                <p className="mt-2 text-[13px] text-white/55">
                  {props.data.profile.bio}
                </p>
              </div>
            </div>

            <div>
              <h4 className="mb-2 text-sm font-semibold text-white/80">
                {pt("creator.yourListings", { count: props.data.count })}
              </h4>
              {props.data.listings.length === 0 ? (
                <p className="text-[12px] text-white/40">
                  {pt("creator.noUploads")}
                </p>
              ) : (
                <div className="space-y-2">
                  {props.data.listings.map((l) => (
                    <div
                      key={l.id}
                      className="flex flex-wrap items-center justify-between gap-2 rounded-lg border border-white/10 bg-white/[0.03] px-3 py-2"
                    >
                      <div>
                        <p className="text-[13px] font-medium text-white">
                          {l.title}
                        </p>
                        <p className="text-[11px] text-white/40">
                          {l.category} · v
                          {l.versions.find((v) => v.isLatest)?.version || "1.0.0"}{" "}
                          · {formatListingPrice(l.commerce.priceCents)}
                        </p>
                      </div>
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          variant="outline"
                          className="border-white/15 text-white"
                          onClick={() => props.onPreview(l.id)}
                        >
                          {pt("creator.preview")}
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          className="border-white/15 text-white"
                          onClick={() => {
                            setVersionListingId(l.id);
                            setVersion("");
                            setChangelog("");
                            setError(null);
                          }}
                        >
                          {pt("creator.newVersion")}
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {versionListingId ? (
              <div className="space-y-2 rounded-lg border border-premium-gold/25 bg-premium-gold/5 p-3">
                <p className="text-[12px] font-semibold text-premium-gold">
                  {pt("creator.addVersion")}
                </p>
                <Input
                  value={version}
                  onChange={(e) => setVersion(e.target.value)}
                  placeholder={pt("creator.versionPlaceholder")}
                  className="border-white/10 bg-white/5 text-white"
                />
                <Textarea
                  value={changelog}
                  onChange={(e) => setChangelog(e.target.value)}
                  placeholder={pt("creator.changelogPlaceholder")}
                  className="min-h-[72px] border-white/10 bg-white/5 text-white"
                />
                {error ? (
                  <p className="text-[12px] text-red-400">{error}</p>
                ) : null}
                <div className="flex gap-2">
                  <Button
                    size="sm"
                    variant="outline"
                    className="border-white/15 text-white"
                    onClick={() => setVersionListingId(null)}
                  >
                    {t("common.cancel")}
                  </Button>
                  <Button
                    size="sm"
                    className="bg-premium-gold text-black"
                    disabled={
                      savingVersion || !version.trim() || !changelog.trim()
                    }
                    onClick={() => void addVersion()}
                  >
                    {savingVersion ? (
                      <Loader2 className="size-3.5 animate-spin" />
                    ) : null}
                    {pt("creator.saveVersion")}
                  </Button>
                </div>
              </div>
            ) : null}
          </div>
        ) : (
          <p className="py-8 text-center text-sm text-white/40">
            {pt("creator.loadFailed")}
          </p>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import type { ErpAccount, ErpCompany, ErpExpense, ErpInvoice } from "@/types/erp";
import { useWorkspaceT } from "@/lib/i18n/use-scoped-t";

type Props = {
  companyId: string;
  initialAccounts?: ErpAccount[];
  initialInvoices?: ErpInvoice[];
  initialExpenses?: ErpExpense[];
  initialCompanies?: ErpCompany[];
};

export function FinanceDashboard({
  companyId,
  initialAccounts = [],
  initialInvoices = [],
  initialExpenses = [],
  initialCompanies = [],
}: Props) {
  const wt = useWorkspaceT("erp");
  const [accounts, setAccounts] = useState(initialAccounts);
  const [invoices, setInvoices] = useState(initialInvoices);
  const [expenses, setExpenses] = useState(initialExpenses);
  const [companies, setCompanies] = useState(initialCompanies);
  const [activeCompany, setActiveCompany] = useState(companyId);
  const [customerName, setCustomerName] = useState("");
  const [invoiceAmount, setInvoiceAmount] = useState("0");
  const [expenseTitle, setExpenseTitle] = useState("");
  const [expenseAmount, setExpenseAmount] = useState("0");
  const [companyName, setCompanyName] = useState("");

  const money = (c: number) => `$${(c / 100).toLocaleString()}`;
  const cid = activeCompany || companyId;

  const createCompany = async () => {
    if (!companyName.trim()) return toast.error(wt("panels.finance.companyNameRequired"));
    const res = await fetch("/api/erp/companies", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name: companyName }),
    });
    const data = await res.json();
    if (!res.ok) return toast.error(data.error ?? wt("toasts.failed"));
    setCompanies([data.company, ...companies]);
    setActiveCompany(data.company.id);
    setCompanyName("");
    toast.success(wt("toasts.companyCreated"));
  };

  const createInvoice = async () => {
    if (!cid) return toast.error(wt("panels.finance.createCompanyFirst"));
    const res = await fetch("/api/erp/invoices", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ companyId: cid, customerName, amountCents: Number(invoiceAmount) * 100 }),
    });
    const data = await res.json();
    if (!res.ok) return toast.error(data.error ?? wt("toasts.failed"));
    setInvoices([data.invoice, ...invoices]);
    toast.success(wt("toasts.invoiceCreated"));
  };

  const createExpense = async () => {
    if (!cid) return toast.error(wt("panels.finance.createCompanyFirst"));
    const res = await fetch("/api/erp/expenses", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ companyId: cid, title: expenseTitle, amountCents: Number(expenseAmount) * 100 }),
    });
    const data = await res.json();
    if (!res.ok) return toast.error(data.error ?? wt("toasts.failed"));
    setExpenses([data.expense, ...expenses]);
    toast.success(wt("toasts.expenseRecorded"));
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap gap-2">
        <Input value={companyName} onChange={(e) => setCompanyName(e.target.value)} placeholder={wt("forms.newCompany")} className="border-white/10 bg-white/5 text-white" />
        <Button onClick={() => void createCompany()}>{wt("panels.finance.addCompany")}</Button>
        {companies.length > 0 && (
          <select value={cid} onChange={(e) => setActiveCompany(e.target.value)} className="rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white">
            {companies.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
        )}
      </div>

      <div className="grid gap-4 lg:grid-cols-2">
        <div className="rounded-xl border border-white/[0.08] bg-white/[0.02] p-4 space-y-3">
          <p className="text-xs uppercase text-white/40">{wt("panels.finance.chartOfAccounts")}</p>
          {accounts.map((a) => (
            <div key={a.id} className="text-sm text-white/70">{a.code} · {a.name} <span className="text-white/40">({a.account_type})</span></div>
          ))}
          {accounts.length === 0 && <p className="text-sm text-white/30">{wt("panels.finance.defaultCoa")}</p>}
        </div>
        <div className="rounded-xl border border-white/[0.08] bg-white/[0.02] p-4 space-y-3">
          <p className="text-xs uppercase text-white/40">{wt("panels.finance.newInvoice")}</p>
          <Input value={customerName} onChange={(e) => setCustomerName(e.target.value)} placeholder={wt("forms.customer")} className="border-white/10 bg-white/5 text-white" />
          <Input value={invoiceAmount} onChange={(e) => setInvoiceAmount(e.target.value)} placeholder={wt("forms.amountUsd")} className="border-white/10 bg-white/5 text-white" />
          <Button onClick={() => void createInvoice()}>{wt("panels.finance.createInvoice")}</Button>
        </div>
      </div>

      <div className="grid gap-4 lg:grid-cols-2">
        <div className="space-y-2">
          <p className="text-xs uppercase text-white/40">{wt("panels.finance.invoices")}</p>
          {invoices.map((i) => (
            <div key={i.id} className="rounded-lg border border-white/[0.06] px-3 py-2 text-sm text-white/70">
              {i.invoice_number} · {i.customer_name} · {money(i.amount_cents)} · {i.status}
            </div>
          ))}
        </div>
        <div className="space-y-3">
          <p className="text-xs uppercase text-white/40">{wt("panels.finance.expenses")}</p>
          <Input value={expenseTitle} onChange={(e) => setExpenseTitle(e.target.value)} placeholder={wt("forms.expenseTitle")} className="border-white/10 bg-white/5 text-white" />
          <Input value={expenseAmount} onChange={(e) => setExpenseAmount(e.target.value)} placeholder={wt("forms.amountUsd")} className="border-white/10 bg-white/5 text-white" />
          <Button onClick={() => void createExpense()}>{wt("panels.finance.addExpense")}</Button>
          {expenses.map((e) => (
            <div key={e.id} className="rounded-lg border border-white/[0.06] px-3 py-2 text-sm text-white/70">
              {e.title} · {money(e.amount_cents)} · {e.status}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

