import { cn } from "@/lib/utils";
import { useTranslation } from "@/lib/i18n/client";
import { useProductT } from "@/lib/i18n/use-scoped-t";

type MarketAnalysisToolProps = {
  initialAnalyses?: MarketAnalysis[];
  initialTotal?: number;
};

function AnalysisView({
  result,
  onToggleFavorite,
  onDelete,
  actionLoading,
}: {
  result: MarketAnalysis;
  onToggleFavorite: (analysis: MarketAnalysis) => void;
  onDelete: (id: string) => void;
  actionLoading: boolean;
}) {
  const p = useProductT("marketAnalysis");
  return (
    <>
      <div className="grid gap-4 sm:grid-cols-2">
        <DashboardCard className="glass-panel glass-panel-premium">
          <DashboardCardHeader className="pb-2">
            <DashboardCardDescription>{p("results.marketSize")}</DashboardCardDescription>
            <DashboardCardTitle className="text-xl text-white">{result.market_size}</DashboardCardTitle>
          </DashboardCardHeader>
        </DashboardCard>
        <DashboardCard className="glass-panel glass-panel-premium">
          <DashboardCardHeader className="pb-2">
            <DashboardCardDescription>{p("results.growthRate")}</DashboardCardDescription>
            <DashboardCardTitle className="flex items-center gap-2 text-xl text-emerald-400">
              <TrendingUp className="size-5" />
              {result.growth_rate}
            </DashboardCardTitle>
          </DashboardCardHeader>
        </DashboardCard>
      </div>

      <MarketAnalysisChart
        opportunities={result.opportunities}
        risks={result.risks}
        competitors={result.competitors}
      />

      <DashboardCard className="glass-panel glass-panel-premium">
        <DashboardCardHeader>
          <div className="flex items-start justify-between gap-4">
            <div>
              {result.is_favorite && (
                <Badge className={cn("mb-2", dashboardBadgeGold)}>{p("results.favorite")}</Badge>
              )}
              <DashboardCardTitle>
                {result.industry} — {result.region}
              </DashboardCardTitle>
            </div>
            <div className="flex items-center gap-1">
              <Button
                variant="ghost"
                size="icon-sm"
                className={dashboardIconButtonClass}
                onClick={() => onToggleFavorite(result)}
                disabled={actionLoading}
                aria-label={result.is_favorite ? p("aria.removeFavorite") : p("aria.addFavorite")}
              >
                {actionLoading ? (
                  <Loader2 className="size-4 animate-spin" />
                ) : (
                  <Star
                    className={cn(
                      "size-4",
                      result.is_favorite && "fill-premium-gold text-premium-gold",
                    )}
                  />
                )}
              </Button>
              <Button
                variant="ghost"
                size="icon-sm"
                className={cn(dashboardIconButtonClass, "text-destructive hover:text-destructive")}
                onClick={() => onDelete(result.id)}
                disabled={actionLoading}
                aria-label={p("aria.deleteAnalysis")}
              >
                {actionLoading ? (
                  <Loader2 className="size-4 animate-spin" />
                ) : (
                  <Trash2 className="size-4" />
                )}
              </Button>
            </div>
          </div>
          <DashboardCardDescription className="text-[15px] text-white/65">
            {result.summary}
          </DashboardCardDescription>
        </DashboardCardHeader>
      </DashboardCard>

      <div className="grid gap-4 md:grid-cols-3">
        <DashboardCard className="glass-panel glass-panel-premium">
          <DashboardCardHeader>
            <DashboardCardTitle className="flex items-center gap-2 text-base">
              <Target className="size-4 text-blue-500" />
              {p("results.opportunities")}
            </DashboardCardTitle>
          </DashboardCardHeader>
          <DashboardCardContent>
            <ul className="space-y-2">
              {result.opportunities.map((item, i) => (
                <li key={i} className="flex gap-2 text-sm">
                  <Badge variant="secondary" className="shrink-0 border-white/10 bg-white/[0.06] text-white/70">{i + 1}</Badge>
                  <span className="text-white/75">{item}</span>
                </li>
              ))}
            </ul>
          </DashboardCardContent>
        </DashboardCard>
        <DashboardCard className="glass-panel glass-panel-premium">
          <DashboardCardHeader>
            <DashboardCardTitle className="flex items-center gap-2 text-base">
              <AlertTriangle className="size-4 text-amber-500" />
              {p("results.risks")}
            </DashboardCardTitle>
          </DashboardCardHeader>
          <DashboardCardContent>
            <ul className="space-y-2">
              {result.risks.map((item, i) => (
                <li key={i} className="flex gap-2 text-sm">
                  <Badge variant="outline" className="shrink-0 border-white/15 text-white/65">{i + 1}</Badge>
                  <span className="text-white/75">{item}</span>
                </li>
              ))}
            </ul>
          </DashboardCardContent>
        </DashboardCard>
        <DashboardCard className="glass-panel glass-panel-premium">
          <DashboardCardHeader>
            <DashboardCardTitle className="text-base">{p("results.competitors")}</DashboardCardTitle>
          </DashboardCardHeader>
          <DashboardCardContent>
            <ul className="space-y-2">
              {result.competitors.map((item, i) => (
                <li key={i} className="text-sm text-white/70">• {item}</li>
              ))}
            </ul>
          </DashboardCardContent>
        </DashboardCard>
      </div>
    </>
