}

export function MarketAnalysisTool({
  initialAnalyses = [],
  initialTotal = 0,
}: MarketAnalysisToolProps) {
  const { t } = useTranslation();
  const p = useProductT("marketAnalysis");
  const {
    items: analyses,
    page,
    total,
    totalPages,
    search,
    favoriteFilter,
    extraFilter,
    loading,
    refresh,
    applyFilters,
    goToPage,
  } = usePaginatedResource<MarketAnalysis>({
    endpoint: "/api/market-analysis",
    dataKey: "analyses",
    initialData: initialAnalyses,
    initialTotal,
  });

  const [generating, setGenerating] = useState(false);
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  const industries = [...new Set(analyses.map((a) => a.industry))];

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setGenerating(true);

    const formData = new FormData(e.currentTarget);
    const body = {
      industry: formData.get("industry") as string,
      region: formData.get("region") as string,
      targetAudience: formData.get("targetAudience") as string,
    };

    try {
      await apiMutation(
        "/api/market-analysis",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(body),
        },
        p("toasts.analysisSaved"),
      );
      refresh();
    } catch {
      // handled
    } finally {
      setGenerating(false);
    }
  }

  async function toggleFavorite(analysis: MarketAnalysis) {
    setActionLoading(analysis.id);
    try {
      await apiMutation(`/api/market-analysis/${analysis.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ is_favorite: !analysis.is_favorite }),
      });
      refresh();
    } catch {
      // handled
    } finally {
      setActionLoading(null);
    }
  }

  async function deleteAnalysis(id: string) {
    setActionLoading(id);
    try {
      await apiMutation(`/api/market-analysis/${id}`, { method: "DELETE" });
      refresh();
    } catch {
      // handled
    } finally {
      setActionLoading(null);
    }
  }

  const showEmptyState = !generating && !loading && analyses.length === 0;

  return (
    <div className="grid gap-8 lg:grid-cols-[360px_1fr]">
      <DashboardCard className="glass-panel glass-panel-premium lg:sticky lg:top-28 lg:self-start">
        <DashboardCardHeader>
          <DashboardCardTitle className="flex items-center gap-3">
            <DashboardIconBox icon={LineChart} className="size-9" />
            {p("form.title")}
          </DashboardCardTitle>
          <DashboardCardDescription>
            {p("form.description")}
          </DashboardCardDescription>
        </DashboardCardHeader>
        <DashboardCardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="industry">{p("form.industry")}</Label>
              <Input
                id="industry"
                name="industry"
                placeholder={p("form.industryPlaceholder")}
                className={dashboardInputClass}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="region">{p("form.region")}</Label>
              <Input
                id="region"
                name="region"
                placeholder={p("form.regionPlaceholder")}
                className={dashboardInputClass}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="targetAudience">{p("form.targetAudience")}</Label>
              <Input
                id="targetAudience"
                name="targetAudience"
                placeholder={p("form.targetAudiencePlaceholder")}
                className={cn(dashboardInputClass, dashboardSelectClass)}
                required
              />
            </div>
            <Button
              type="submit"
              className="h-11 w-full rounded-xl btn-gold font-bold text-luxury-black"
              disabled={generating}
            >
              {generating ? (
                <>
                  <Loader2 className="size-4 animate-spin" />
                  {p("form.analyzing")}
                </>
              ) : (
                <>
                  <LineChart className="size-4" />
                  {p("form.runAnalysis")}
                </>
              )}
            </Button>
          </form>
        </DashboardCardContent>
      </DashboardCard>

      <div className="space-y-4">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <h2 className="text-lg font-bold text-white sm:text-xl">
            {analyses.length > 0
              ? (total === 1 ? p("results.analysisSaved", { count: total }) : p("results.analysesSaved", { count: total }))
              : p("results.emptyHeading")}
          </h2>
          <ListFilters
            search={search}
            favoriteFilter={favoriteFilter}
            extraFilter={extraFilter}
            extraLabel={p("results.industriesFilter")}
            extraOptions={industries}
            onApply={applyFilters}
          />
        </div>

        {(generating || loading) && <DashboardListSkeleton count={2} />}

        {!generating &&
          !loading &&
          analyses.map((analysis) => (
            <div key={analysis.id} className="space-y-4">
              <AnalysisView
                result={analysis}
                onToggleFavorite={toggleFavorite}
                onDelete={deleteAnalysis}
                actionLoading={actionLoading === analysis.id}
              />
            </div>
          ))}

        {showEmptyState && (
          <DashboardEmptyState
            icon={LineChart}
            title={p("empty.title")}
            description={p("empty.description")}
          />
        )}

        <PaginationControls page={page} totalPages={totalPages} total={total} onPageChange={goToPage} />
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { toast } from "sonner";
import { Plus, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import type { MarketingCampaign } from "@/types/marketing";
import { CampaignEditor } from "@/components/dashboard/marketing/campaign-editor";
import { useWorkspaceT } from "@/lib/i18n/use-scoped-t";
import { useTranslation } from "@/lib/i18n/client";
import { GlsGenerationLanguageSelect } from "@/components/dashboard/language/gls-generation-language-select";
import {
  getInitialGlsGenerationLanguage,
  glsGenerationLanguagePayload,
} from "@/lib/language-platform/generation/service";

type Props = {
  campaigns: MarketingCampaign[];
  onCampaignsChange: (campaigns: MarketingCampaign[]) => void;
  selectedId?: string | null;
  onSelect: (id: string | null) => void;
};

export function CampaignList({ campaigns, onCampaignsChange, selectedId, onSelect }: Props) {
  const wt = useWorkspaceT("marketing");
  const { t, locale } = useTranslation();
  const [brief, setBrief] = useState("");
  const [language, setLanguage] = useState(() =>
    getInitialGlsGenerationLanguage({ fallback: "ui-locale", uiLocale: locale }),
  );
  const [generating, setGenerating] = useState(false);

  const generate = async () => {
    if (!brief.trim()) {
      toast.error(wt("campaignList.briefRequired"));
      return;
    }
    setGenerating(true);
    try {
      const res = await fetch("/api/marketing/campaigns", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ brief, generate: true, ...glsGenerationLanguagePayload(language) }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? wt("campaignList.failed"));
      onCampaignsChange([data.campaign, ...campaigns]);
      onSelect(data.campaign.id);
      setBrief("");
      toast.success(wt("campaignList.generated"));
    } catch (e) {
      toast.error(e instanceof Error ? e.message : wt("campaignList.failed"));
    } finally {
      setGenerating(false);
    }
  };

  const selected = campaigns.find((c) => c.id === selectedId) ?? null;

  return (
    <div className="grid gap-6 lg:grid-cols-[300px_1fr]">
      <div className="space-y-4">
        <div className="rounded-xl border border-white/[0.08] bg-white/[0.02] p-4">
          <p className="mb-2 text-xs font-medium uppercase text-white/40">{wt("campaignList.generatorTitle")}</p>
          <Textarea
            value={brief}
            onChange={(e) => setBrief(e.target.value)}
            placeholder={wt("campaignList.briefPlaceholder")}
            rows={4}
            className="border-white/10 bg-white/5 text-white"
          />
          <div className="mt-2">
            <label className="mb-1.5 block text-xs font-medium text-white/60">{t("common.language")}</label>
            <GlsGenerationLanguageSelect serviceId="marketing-ai" value={language} onChange={setLanguage} />
          </div>
          <Button className="mt-2 w-full rounded-lg" onClick={() => void generate()} disabled={generating}>
            <Sparkles className="mr-2 size-4" />
            {generating ? wt("campaignList.generating") : wt("campaignList.generateCampaign")}
          </Button>
        </div>

        <div className="space-y-2">
          {campaigns.map((c) => (
            <button
              key={c.id}
              type="button"
              onClick={() => onSelect(c.id)}
              className={`w-full rounded-lg border px-3 py-2 text-left text-sm transition ${
                selectedId === c.id
                  ? "border-premium-gold/40 bg-premium-gold/10 text-premium-gold-light"
                  : "border-white/[0.06] bg-white/[0.02] text-white/70 hover:bg-white/5"
              }`}
            >
              <p className="font-medium">{c.name}</p>
              <p className="text-xs capitalize text-white/40">{c.status}</p>
            </button>
          ))}
          {campaigns.length === 0 && (
            <p className="text-sm text-white/30">{wt("campaignList.empty")}</p>
          )}
        </div>
      </div>

      {selected ? (
        <CampaignEditor
          campaign={selected}
          onUpdated={(updated) => {
            onCampaignsChange(campaigns.map((c) => (c.id === updated.id ? updated : c)));
          }}
        />
      ) : (
        <div className="flex items-center justify-center rounded-xl border border-dashed border-white/10 p-12 text-white/30">
          {wt("campaignList.selectOrGenerate")}
        </div>
      )}
    </div>
  );
}

"use client";

import type { MarketingCampaign, CustomerPersona } from "@/types/marketing";
import type { MarketingAnalyticsSummary } from "@/lib/marketing/analytics";
import { useWorkspaceT } from "@/lib/i18n/use-scoped-t";

type Props = {
  campaigns: MarketingCampaign[];
  summary: MarketingAnalyticsSummary;
};

export function MarketingDashboard({ campaigns, summary }: Props) {
  const wt = useWorkspaceT("marketing");
  const active = campaigns.filter((c) => c.status === "active").length;
  const planned = campaigns.filter((c) => c.status === "planned" || c.status === "draft").length;

  return (
    <div className="space-y-4">
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {[
          { label: wt("dashboard.totalCampaigns"), value: campaigns.length },
          { label: wt("dashboard.active"), value: active },
          { label: wt("dashboard.plannedDraft"), value: planned },
          { label: wt("dashboard.leads"), value: summary.totalLeads },
        ].map(({ label, value }) => (
          <div key={label} className="rounded-xl border border-white/[0.08] bg-white/[0.02] p-4">
            <p className="text-xs uppercase tracking-wide text-white/40">{label}</p>
            <p className="mt-1 text-2xl font-semibold text-white">{value}</p>
          </div>
        ))}
      </div>

      <div className="rounded-xl border border-white/[0.08] bg-white/[0.02] p-4">
        <p className="text-xs uppercase tracking-wide text-white/40">{wt("dashboard.analytics")}</p>
        <div className="mt-3 grid gap-4 sm:grid-cols-3 lg:grid-cols-6">
          {[
            { label: wt("dashboard.impressions"), value: summary.totalImpressions },
            { label: wt("dashboard.clicks"), value: summary.totalClicks },
            { label: wt("dashboard.conversions"), value: summary.totalConversions },
            { label: wt("dashboard.revenue"), value: `$${summary.totalRevenue}` },
            { label: wt("dashboard.spend"), value: `$${summary.totalSpend}` },
            { label: wt("dashboard.avgRoi"), value: `${summary.avgRoi}%` },
          ].map(({ label, value }) => (
            <div key={label}>
              <p className="text-xs text-white/40">{label}</p>
              <p className="text-lg font-medium text-white">{value}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

