            onUploadClick={onUploadBackground}
            onMediaLibraryClick={onMediaLibraryBackground}
            onAiGenerateClick={() => onMediaLibraryBackground()}
          />
        </div>
      ) : null}

      <div>
        <FieldLabel>{st("ai")}</FieldLabel>
        <div className="grid grid-cols-2 gap-1.5">
