type WebsiteBuilderToolProps = {
  /** Serializable product id only — never pass ProductDefinition (contains LucideIcon). */
  productId?: ProductId;
  initialGenerations?: WebsiteGeneration[];
};

type WorkspaceProject = {
  id: string;
  title: string;
  type: string;
  style: string;
  theme: string;
  language: string;
  features: string[];
  createdAt: string;
  favorite: boolean;
  description: string;
  generatedProject?: GeneratedWebsiteProject;
  build?: PreviewBuildState;
  mode?: GenerationMode;
  status?: GenerationStatus;
  errorMessage?: string | null;
  parentGenerationId?: string | null;
  projectId?: string | null;
  promptVersions?: PromptVersion[];
};

/** Minimal project identity for ZIP export (full workspace or recent-projects list). */
type DownloadableProject = Pick<WorkspaceProject, "id" | "title">;

function isWorkspaceProject(
  project: DownloadableProject | WorkspaceProject,
): project is WorkspaceProject {
  return "style" in project;
}

type PreviewBuildState = {
  status: "idle" | "building" | "success" | "error";
  previewUrl?: string;
  buildOutput?: string;
  error?: string;
};

const PAGES = ["Home", "About", "Services", "Pricing", "Dashboard", "Admin", "Contact"];

type GenerateProjectResponse =
  | {
      project: GeneratedWebsiteProject;
      generation: WebsiteGeneration;
      message?: string;
    }
  | { error?: string };

function formatGenerationDate(value: string) {
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(new Date(value));
}

function isGeneratedWebsiteProject(value: unknown): value is GeneratedWebsiteProject {
  return (
    Boolean(value) &&
    typeof value === "object" &&
    Array.isArray((value as GeneratedWebsiteProject).files)
  );
}

function sanitizeZipPath(filePath: string) {
  const normalized = filePath.replaceAll("\\", "/").replace(/^\/+/, "");
  const parts = normalized.split("/").filter(Boolean);

  if (
    !parts.length ||
    parts.some((part) => part === "." || part === "..") ||
    normalized.startsWith("node_modules/") ||
    normalized.startsWith(".next/")
  ) {
    return null;
  }

  return parts.join("/");
}

function stubRunningProject(params: {
  id: string;
  title: string;
  description: string;
  type: string;
  style: string;
  theme: string;
  language: string;
  features: string[];
  mode?: GenerationMode;
}): WorkspaceProject {
  return {
    id: params.id,
    title: params.title,
    type: params.type,
    style: params.style,
    theme: params.theme,
    language: params.language,
    features: params.features,
    createdAt: formatGenerationDate(new Date().toISOString()),
    favorite: false,
    description: params.description,
    generatedProject: {
      projectKind: "website",
      title: params.title,
      description: params.description,
      pages: [],
      sections: [],
      colorPalette: [],
      typography: [],
      components: [],
      content: [],
      seo: [],
      roadmap: [],
      files: [],
    },
    build: { status: "idle" },
    mode: params.mode,
    status: "running",
  };
}

const ACTIVE_GENERATION_STORAGE_KEY = "wb-active-generation-id";

function restoreTemplateStateFromSettings(
  settings: Record<string, unknown> | undefined,
  handlers: {
    setWebsiteStructureTemplateId: (id: string) => void;
    setSelectedTemplateId: (id: string) => void;
    setTemplateIntelligenceId: (id: string) => void;
  },
) {
  const structureId =
    typeof settings?.websiteStructureTemplateId === "string"
      ? settings.websiteStructureTemplateId
      : typeof settings?.templatePackageId === "string"
        ? settings.templatePackageId
        : null;
  const tiId =
    typeof settings?.templateIntelligenceId === "string"
      ? settings.templateIntelligenceId
      : null;
  if (structureId) {
    const resolvedStructureId = resolveBuilderTemplatePackageId(structureId);
    handlers.setWebsiteStructureTemplateId(resolvedStructureId);
    handlers.setSelectedTemplateId(resolvedStructureId);
  }
  if (tiId) handlers.setTemplateIntelligenceId(tiId);
}

function toProject(generation: WebsiteGeneration): WorkspaceProject {
  const generatedProject = isGeneratedWebsiteProject(generation.blueprint)
    ? generation.blueprint
    : undefined;

  const blueprintTitle = generatedProject?.title?.trim() || "";
  const projectName = generation.project_name?.trim() || "";
  const title = isGeneratingWebsitePlaceholderTitle(blueprintTitle)
    ? projectName || blueprintTitle
    : blueprintTitle || projectName;

  return {
    id: generation.id,
    title,
    type: generation.website_type,
    style: generation.design_style,
    theme: generation.color_style,
    language: generation.language,
    features: generation.features ?? [],
    createdAt: formatGenerationDate(generation.created_at),
    favorite: Boolean(generation.is_favorite),
    description: generation.business_description,
    generatedProject,
    build: { status: "idle" },
    mode: generation.mode,
    status: generation.status,
    errorMessage: generation.error_message,
    parentGenerationId: generation.parent_generation_id,
    projectId: generation.project_id,
    promptVersions: generation.prompt_versions,
  };
}

function mapIndustryToProjectType(industry: string): string | null {
  const key = industry.toLowerCase().replace(/_/g, "-");
  if (key === "restaurant") return "Restaurant";
  if (key === "healthcare" || key === "clinic") return "Clinic";
  if (key === "real-estate") return "Real Estate";
  if (key === "education") return "Education";
  if (key === "saas") return "AI SaaS";
  if (key === "ecommerce") return "E-commerce";
  if (key === "agency" || key === "luxury-business" || key === "automotive") {
    return "Business Website";
  }
  return null;
}

export function WebsiteBuilderTool({
  productId,
  initialGenerations = [],
}: WebsiteBuilderToolProps) {
  const { t } = useTranslation();
  const wb = useProductT("websiteBuilder");
  const product = productId ? getProductDefinition(productId) : undefined;
  const [projectBrief, setProjectBrief] = useState("");
  const onePrompt = getOnePromptProduct("website-builder");
  const applyIdea = useCallback((idea: string) => {
    setProjectBrief(idea);
  }, [setProjectBrief]);
  useIdeaQueryParam(applyIdea);
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
  const [marketplaceTemplateId, setMarketplaceTemplateId] = useState<string | null>(
    null,
  );
  const [templateStyle, setTemplateStyle] = useState<string | null>(null);
  const [designPreset, setDesignPreset] = useState<string | null>(null);
  const [templateIndustry, setTemplateIndustry] = useState<string | null>(null);
  const [templateComponents, setTemplateComponents] = useState<string[]>([]);
  const [templateDesignSystem, setTemplateDesignSystem] = useState<
    TemplateUsePayload["designSystem"] | null
  >(null);
  const [templateIntelligenceId, setTemplateIntelligenceId] = useState<
    string | null
  >(null);
  const [templateIntelligenceCategory, setTemplateIntelligenceCategory] =
    useState<string | null>(null);
  const [websiteStructureTemplateId, setWebsiteStructureTemplateId] = useState<
    string | null
  >(null);
  const builderTemplatePackageId = resolveBuilderTemplatePackageId(
    websiteStructureTemplateId ?? selectedTemplateId ?? "",
  ) || null;
  const {
    model: templateRuntimeModel,
    error: templateRuntimeError,
    loading: templateRuntimeLoading,
  } = useBuilderTemplateRuntime(builderTemplatePackageId);
  const templateRuntimeModelRef = useRef(templateRuntimeModel);
  useEffect(() => {
    templateRuntimeModelRef.current = templateRuntimeModel;
  }, [templateRuntimeModel]);
  void templateRuntimeError;
  void templateRuntimeLoading;
  const [websiteThemeId, setWebsiteThemeId] = useState<string | null>(null);
  const [brandIdentityId, setBrandIdentityId] = useState<string | null>(null);
  const [language, setLanguage] = useState(() => getInitialGlsGenerationLanguage());
  const [imageStrategyMode, setImageStrategyMode] =
    useState<SiteImageStrategyMode>("with-images");
  const [visualSkinId, setVisualSkinId] = useState<string | null>(
    DEFAULT_VISUAL_SKIN_ID,
  );
  const visualSkinsPublished = hasPublishedVisualSkins();
  const proWorkspaceEnabled = isProWorkspaceClientEnabled();
  const [features, setFeatures] = useState<BuilderPanelFeatureLabel[]>([
    ...DEFAULT_BUILDER_PANEL_FEATURES,
  ]);

  // Template Marketplace handoff: ?templateId=&applyTemplate=1&generation=
  const pendingStructureTemplateApplyRef = useRef<string | null>(null);
  const [streamStatus, setStreamStatus] = useState<string | null>(null);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const params = new URLSearchParams(window.location.search);
    const tid = params.get("templateId")?.trim();
    const mid = params.get("marketplaceTemplateId")?.trim();
    const style = params.get("templateStyle")?.trim();
    const preset = params.get("designPreset")?.trim();
    const applyTemplate = params.get("applyTemplate") === "1";

    if (tid) {
      setSelectedTemplateId(tid);
      setWebsiteStructureTemplateId(tid);
    }
    if (mid) setMarketplaceTemplateId(mid);
    if (style) setTemplateStyle(style);
    if (preset) setDesignPreset(preset);

    if (applyTemplate && tid) {
      pendingStructureTemplateApplyRef.current = tid;
    } else if (tid || mid) {
      setStreamStatus(
        mid
          ? `Marketplace template selected: ${mid}`
          : `Template selected: ${tid}`,
      );
    }
  }, []);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isApplyingTemplate, setIsApplyingTemplate] = useState(false);
  const [apiError, setApiError] = useState<string | null>(null);
  const [elapsedSeconds, setElapsedSeconds] = useState(0);
  const [editMode, setEditMode] = useState(false);
  const [selectedFilePath, setSelectedFilePath] = useState<string>("");
  const [outputTab, setOutputTab] = useState<OutputTab>(
    "preview",
  );
  const [previewRevision, setPreviewRevision] = useState(0);
  const [fileSearch, setFileSearch] = useState("");
  const [renameOpen, setRenameOpen] = useState(false);
  const [renameValue, setRenameValue] = useState("");
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<WorkspaceProject | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);
  const [visualEditorDirty, setVisualEditorDirty] = useState(false);
  const [actionError, setActionError] = useState<string | null>(null);
  const [projects, setProjects] = useState<WorkspaceProject[]>(() =>
    initialGenerations.map(toProject),
  );
  const [activeProject, setActiveProject] = useState<WorkspaceProject | null>(() =>
    initialGenerations[0] ? toProject(initialGenerations[0]) : null,
  );

  useEffect(() => {
    const savedSkinId =
      activeProject?.generatedProject?.settings?.visualSkinId?.trim() || null;
    if (savedSkinId && getVisualSkin(savedSkinId)) {
      setVisualSkinId(savedSkinId);
    }
  }, [activeProject?.generatedProject?.settings?.visualSkinId]);

  /** Optimistic Recent Projects + active workspace sync (instant UI update). */
  const commitWorkspaceProject = useCallback(
    (project: WorkspaceProject, options?: { activate?: boolean }) => {
      setProjects((items) => upsertRecentProject(items, project));
      if (options?.activate === false) {
        setActiveProject((current) =>
          current?.id === project.id ? project : current,
        );
      } else {
        setActiveProject(project);
      }
    },
    [],
  );

  const refetchRecentProjects = useCallback(
    async (options?: {
      expectedId?: string;
      ensureProject?: WorkspaceProject;
    }) => {
      const expectedId = options?.expectedId;
      const ensureProject = options?.ensureProject;

      const loadList = async (): Promise<WebsiteGeneration[]> => {
        const url = new URL("/api/website-builder", window.location.origin);
        url.searchParams.set("limit", String(MAX_RECENT_PROJECTS));
        url.searchParams.set("page", "1");
        url.searchParams.set("_", String(Date.now()));

        const response = await fetch(url.toString(), {
          method: "GET",
          cache: "no-store",
          headers: {
            Accept: "application/json",
            "Cache-Control": "no-cache",
            Pragma: "no-cache",
          },
        });
        if (!response.ok) return [];
        const data = (await response.json()) as {
          generations?: WebsiteGeneration[];
        };
        return data.generations ?? [];
      };

      try {
        let rows = await loadList();
        if (expectedId && !rows.some((row) => row.id === expectedId)) {
          await new Promise((resolve) => window.setTimeout(resolve, 600));
          rows = await loadList();
        }

        const pinned =
          options?.ensureProject ?? activeProjectRef.current ?? undefined;
        const preserveLocalIds = pinned ? [pinned.id] : [];

        setProjects((current) =>
          mergeRecentProjectsList(
            current,
            rows.map(toProject),
            {
              ensureProject: pinned,
              preserveLocalIds,
            },
          ),
        );
      } catch {
        const pinned =
          options?.ensureProject ?? activeProjectRef.current ?? undefined;
        if (pinned) {
          setProjects((items) => upsertRecentProject(items, pinned));
        }
      }
    },
    [],
  );

  const upsertProjectInList = useCallback((project: WorkspaceProject) => {
    setProjects((items) => upsertRecentProject(items, project));
  }, []);

  const inferredFromBrief = useMemo(
    () =>
      inferWebsiteOnboardingDefaults(
        projectBrief || activeProject?.description || "",
      ),
    [projectBrief, activeProject?.description],
  );

  const streamAbortRef = useRef<AbortController | null>(null);
  const activeStreamSessionRef = useRef<string | null>(null);
  const activeProjectRef = useRef<typeof activeProject>(null);
  useEffect(() => {
    activeProjectRef.current = activeProject;
  }, [activeProject]);

  const workspaceProjectsValue = useMemo(
    () => ({ projects, activeProject }),
    [projects, activeProject],
  );
  const progressStep = useCoreProgress({
    events: streamStatus ? [`[generation] ${streamStatus}`] : [],
    active: isGenerating,
    complete: !isGenerating && !!activeProject,
  });

  const openGenerationFromQuery = useCallback(
    async (generationId: string) => {
      if (visualEditorDirty && outputTab === "canvas") {
        if (!window.confirm(wb("dialogs.unsavedEditorWarning"))) return;
        setVisualEditorDirty(false);
      }
      try {
        const response = await fetch(`/api/website-builder/${generationId}`);
        if (!response.ok) {
          toast.error(wb("errors.noProject"));
          return;
        }
        const data = (await response.json()) as { generation?: WebsiteGeneration };
        if (!data.generation) {
          toast.error(wb("errors.noProject"));
          return;
        }
        const project = toProject(data.generation);
        commitWorkspaceProject(project);
        setSelectedFilePath(project.generatedProject?.files[0]?.path ?? "");
        setFileSearch("");
        setEditMode(false);
        setOutputTab("preview");
        restoreTemplateStateFromSettings(
          project.generatedProject?.settings as Record<string, unknown> | undefined,
          {
            setWebsiteStructureTemplateId,
            setSelectedTemplateId,
            setTemplateIntelligenceId,
          },
        );
        if (typeof window !== "undefined") {
          const url = new URL(window.location.href);
          url.searchParams.delete("generation");
          window.history.replaceState(
            {},
            "",
            `${url.pathname}${url.search}${url.hash}`,
          );
        }
      } catch {
        toast.error(wb("errors.api"));
      }
    },
    [visualEditorDirty, outputTab, wb, commitWorkspaceProject, setVisualEditorDirty, setSelectedFilePath, setFileSearch, setEditMode, setOutputTab],
  );

  useGenerationQueryParam(openGenerationFromQuery, () => {
    toast.error(wb("errors.noProject"));
  });

  useEffect(() => {
    if (!visualEditorDirty || outputTab !== "canvas") return;
    const onBeforeUnload = (event: BeforeUnloadEvent) => {
      event.preventDefault();
      event.returnValue = "";
    };
    window.addEventListener("beforeunload", onBeforeUnload);
    return () => window.removeEventListener("beforeunload", onBeforeUnload);
  }, [visualEditorDirty, outputTab]);

  function handleOutputTabChange(tab: OutputTab) {
    if (visualEditorDirty && outputTab === "canvas" && tab !== "canvas") {
      if (!window.confirm(wb("dialogs.unsavedEditorWarning"))) return;
      setVisualEditorDirty(false);
    }
    setOutputTab(tab);
  }

  function requestDelete(target: WorkspaceProject | string) {
    const project =
      typeof target === "string"
        ? projects.find((item) => item.id === target)
        : target;
    if (!project || isDeleting) return;
    setDeleteTarget(project);
    setDeleteOpen(true);
  }

  async function confirmDeleteProject() {
    if (!deleteTarget || isDeleting) return;
    setIsDeleting(true);
    try {
      await deleteProject(deleteTarget.id);
      setDeleteOpen(false);
      setDeleteTarget(null);
    } finally {
      setIsDeleting(false);
    }
  }

  useEffect(() => {
    if (!isGenerating) {
      setElapsedSeconds(0);
      return;
    }
    setElapsedSeconds(0);
    const timer = window.setInterval(() => {
      setElapsedSeconds((value) => value + 1);
    }, 1000);
    return () => window.clearInterval(timer);
  }, [isGenerating]);

  useEffect(() => {
    const active = activeProject;
    if (!active?.id || active.generatedProject?.files?.length) return;
    let cancelled = false;
    void (async () => {
      try {
        const response = await fetch(`/api/website-builder/${active.id}`);
        if (!response.ok || cancelled) return;
        const data = (await response.json()) as { generation?: WebsiteGeneration };
        if (!data.generation || cancelled) return;
        const hydrated = toProject(data.generation);
        commitWorkspaceProject(hydrated);
        setSelectedFilePath(hydrated.generatedProject?.files[0]?.path ?? "");
      } catch {
        // Keep stub until user selects again
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [activeProject?.id, commitWorkspaceProject]);

  useEffect(() => {
    if (!isWebsiteIncrementalPreviewEnabled() || !isGenerating) return;
    const generationId = activeProject?.id;
    if (!generationId || activeProject?.status !== "running") return;

    let cancelled = false;
    void (async () => {
      try {
        const response = await fetch(`/api/website-builder/${generationId}`);
        if (!response.ok || cancelled) return;
        const data = (await response.json()) as { generation?: WebsiteGeneration };
        if (!data.generation || cancelled) return;
        const hydrated = toProject(data.generation);
        if (cancelled || !isGenerating) return;
        upsertProjectInList(hydrated);
        setActiveProject((current) => {
          if (current?.id !== hydrated.id) return current;
          const currentProject = current.generatedProject;
          const nextProject = hydrated.generatedProject;
          const currentFiles = currentProject?.files?.length ?? 0;
          const nextFiles = nextProject?.files?.length ?? 0;
          const currentAssets =
            currentProject?.assetManifest?.items?.filter((item) => item.url?.trim())
              .length ?? 0;
          const nextAssets =
            nextProject?.assetManifest?.items?.filter((item) => item.url?.trim())
              .length ?? 0;
          if (
            nextFiles < currentFiles ||
            (currentAssets > 0 && nextAssets < currentAssets)
          ) {
            return current;
          }
          return hydrated;
        });
        if (hydrated.generatedProject?.files?.length) {
          setSelectedFilePath((current) =>
            current && hydrated.generatedProject?.files.some((f) => f.path === current)
              ? current
              : (hydrated.generatedProject?.files[0]?.path ?? ""),
          );
        }
      } catch {
        // Keep last checkpoint snapshot
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [previewRevision, isGenerating, activeProject?.id, activeProject?.status, upsertProjectInList]);

  const currentPages = useMemo(() => {
    const featurePages = features.includes("Blog") ? ["Blog"] : [];
    const appPages = features.includes("Payments") ? ["Checkout"] : [];
    return [...PAGES, ...featurePages, ...appPages].slice(0, 8);
  }, [features]);
  const activeFiles = activeProject?.generatedProject?.files ?? [];
  const activeFile =
    activeFiles.find((file) => file.path === selectedFilePath) ?? activeFiles[0] ?? null;

  async function selectProject(
    project: WorkspaceProject,
    options?: { skipDirtyCheck?: boolean },
  ): Promise<boolean> {
    if (
      !options?.skipDirtyCheck &&
      visualEditorDirty &&
      outputTab === "canvas" &&
      activeProject?.id !== project.id
    ) {
      if (!window.confirm(wb("dialogs.unsavedEditorWarning"))) return false;
      setVisualEditorDirty(false);
    }
    const needsHydration = !project.generatedProject?.files?.length;
    if (needsHydration) {
      try {
        const response = await fetch(`/api/website-builder/${project.id}`);
        if (response.ok) {
          const data = (await response.json()) as { generation?: WebsiteGeneration };
          if (data.generation) {
            const hydrated = toProject(data.generation);
            commitWorkspaceProject(hydrated);
            if (hydrated.language && isGlsGenerationLanguage(hydrated.language)) {
              setLanguage(normalizeGlsGenerationLanguage(hydrated.language));
            } else if (!hydrated.language) {
              setLanguage("English");
            }
            if (hydrated.features?.length) {
              setFeatures(hydrateBuilderPanelFeatures(hydrated.features));
            }
            setSelectedFilePath(hydrated.generatedProject?.files[0]?.path ?? "");
            setFileSearch("");
            restoreTemplateStateFromSettings(
              hydrated.generatedProject?.settings as
                | Record<string, unknown>
                | undefined,
              {
                setWebsiteStructureTemplateId,
                setSelectedTemplateId,
                setTemplateIntelligenceId,
              },
            );
            return true;
          }
        }
      } catch {
        // Fall through
      }
    }
    setActiveProject(project);
    if (project.language && isGlsGenerationLanguage(project.language)) {
      setLanguage(normalizeGlsGenerationLanguage(project.language));
    } else if (!project.language) {
      setLanguage("English");
    }
    if (project.features?.length) {
      setFeatures(hydrateBuilderPanelFeatures(project.features));
    }
    setSelectedFilePath(project.generatedProject?.files[0]?.path ?? "");
    setFileSearch("");
    restoreTemplateStateFromSettings(
      project.generatedProject?.settings as Record<string, unknown> | undefined,
      {
        setWebsiteStructureTemplateId,
        setSelectedTemplateId,
        setTemplateIntelligenceId,
      },
    );
    return true;
  }

  function updateProject(projectId: string, patch: Partial<WorkspaceProject>) {
    setProjects((items) =>
      items.map((item) => (item.id === projectId ? { ...item, ...patch } : item)),
    );
    setActiveProject((project) =>
      project?.id === projectId ? { ...project, ...patch } : project,
    );
  }


  function toggleFeature(feature: BuilderPanelFeatureLabel) {
    setFeatures((items) =>
      items.includes(feature)
        ? items.filter((item) => item !== feature)
        : [...items, feature],
    );
  }

  function patchProject(id: string, generation: WebsiteGeneration) {
    const nextProject = toProject(generation);

    upsertProjectInList(nextProject);
    setActiveProject((project) => (project?.id === id ? nextProject : project));
    setSelectedFilePath((path) => path || nextProject.generatedProject?.files[0]?.path || "");
  }

  async function createInterfaceProject(options?: {
    regenerate?: boolean;
    continue?: boolean;
    /** Resume an incomplete / failed generation from saved partial files. */
    resume?: boolean;
    /** AI Website Optimizer Engine — audit + apply fixes */
    optimize?: boolean;
    /** Start a new project from a marketplace template selection. */
    fromTemplate?: TemplateUsePayload;
    /** Layer-specific improve instruction (strategy / design / assets). */
    continueInstruction?: string;
    layerImprove?: "strategy" | "design" | "assets";
  }) {
    const tpl = options?.fromTemplate;
    const mode = options?.resume
      ? "continue"
      : options?.continue || options?.optimize || options?.layerImprove
        ? "continue"
        : options?.regenerate
          ? "regenerate"
          : "generate";

    const layerInstruction = options?.continueInstruction?.trim();

    if (mode === "continue") {
      if (!activeProject?.id) {
        toast.error(wb("toasts.selectWebsiteFirst"));
        return;
      }
      if (
        options?.layerImprove &&
        !activeProject.generatedProject?.files?.length
      ) {
        toast.error(wb("designEngine.generateBeforeLayerImprove"));
        return;
      }
      if (
        !options?.optimize &&
        !options?.resume &&
        !layerInstruction &&
        !projectBrief.trim()
      ) {
        toast.error(wb("toasts.describeChanges"));
        setEditMode(true);
        return;
      }
    }

    const optimizeInstruction =
      "[optimize] Improve headlines, CTA buttons, service descriptions, layout structure, mobile responsiveness, conversion, and brand consistency.";
    const resumeInstruction =
      "[resume] Finish the incomplete website generation. Reuse already generated files, complete missing files, and finalize the project without starting over.";

    const resolvedLanguage =
      mode === "continue" && activeProject?.language
        ? activeProject.language
        : language;

    const templateBriefForLog = tpl
      ? buildBriefFromTemplatePayload(tpl, resolvedLanguage)
      : null;

    let effectiveProjectBrief = resolveEffectiveProjectBrief({
      projectBrief,
      language: resolvedLanguage,
      tpl,
      websiteStructureTemplateId:
        templateRuntimeModelRef.current?.template.id ?? websiteStructureTemplateId,
      templateIndustry,
      templateComponents,
      templateRuntimeModel: templateRuntimeModelRef.current,
      placeholderFallback: product?.promptPlaceholder ?? onePrompt.placeholder,
    });

    if (
      mode === "regenerate" &&
      !effectiveProjectBrief.trim() &&
      activeProject?.description
    ) {
      effectiveProjectBrief = activeProject.description;
    }

    if (effectiveProjectBrief.trim() && effectiveProjectBrief !== projectBrief.trim()) {
      setProjectBrief(effectiveProjectBrief);
    }

    const promptResult = resolveGenerationPrompt({
      mode,
      projectBrief: effectiveProjectBrief,
      activeProjectDescription: activeProject?.description,
      resume: options?.resume,
      iterationOnActiveProject:
        mode === "continue" &&
        Boolean(
          options?.resume ||
            options?.continue ||
            options?.optimize ||
            options?.layerImprove,
        ),
    });

    if (!promptResult.ok) {
      toast.error(wb("errors.noBrief"));
      if (mode === "generate") {
        setEditMode(false);
      }
      return;
    }

    const apiPrompt = promptResult.prompt;

    const resolvedTemplateId = resolveBuilderTemplatePackageId(
      tpl?.templateId ?? selectedTemplateId ?? "",
    ) || null;
    const resolvedMarketplaceId =
      tpl?.marketplaceTemplateId ?? marketplaceTemplateId;
    const resolvedStyle = tpl?.style ?? templateStyle;
    const resolvedPreset = tpl?.designPreset ?? designPreset;
    const resolvedIndustry = tpl?.industry ?? templateIndustry;
    const resolvedComponents = tpl?.components?.length
      ? tpl.components
      : templateComponents;
    const resolvedDesignSystem = tpl?.designSystem ?? templateDesignSystem;
    const resolvedThemeStyle = resolvedStyle
      ? ` ${resolvedStyle}`
      : templateStyle
        ? ` ${templateStyle}`
        : "";
    const inferred = inferWebsiteOnboardingDefaults(apiPrompt);
    const resolvedProjectType =
      (tpl?.industry ? mapIndustryToProjectType(tpl.industry) : null) ||
      inferred.projectType;
    const inferredTheme = resolvedStyle
      ? `${inferred.colorTheme} ${resolvedStyle}`
      : templateStyle
        ? `${inferred.colorTheme} ${templateStyle}`
        : inferred.theme;

    setIsGenerating(true);
    setApiError(null);
    setOutputTab("preview");

    const autoTiId = templateIntelligenceId;
    const autoTiCategory = templateIntelligenceCategory;
    const autoPreset = resolvedPreset;
    const autoComponents = resolvedComponents;
    const autoTemplateId = resolvedTemplateId;

    setStreamStatus(
      options?.layerImprove === "strategy"
        ? wb("designEngine.improvingStrategy")
        : options?.layerImprove === "design"
          ? wb("designEngine.improvingDesign")
          : options?.layerImprove === "assets"
            ? wb("designEngine.improvingAssets")
            : options?.optimize
              ? wb("stream.runningOptimizer")
              : options?.resume
                ? wb("stream.resuming")
                : tpl
                  ? `Creating website from template: ${tpl.name}…`
                  : wb("stream.connecting"),
    );

    const mergedDesignSystem = {
      ...inferred.designSystem,
      ...(resolvedDesignSystem ?? {}),
    };

    const requestBody = {
      prompt: apiPrompt,
      projectType: resolvedProjectType,
      ...glsGenerationLanguagePayload(resolvedLanguage),
      theme: `${inferredTheme}${resolvedThemeStyle}`,
      features: [
        ...features,
        ...(product?.id ? [`product:${product.id}`] : []),
        ...(autoTemplateId ? [`template:${autoTemplateId}`] : []),
        ...(resolvedMarketplaceId
          ? [`marketplace:${resolvedMarketplaceId}`]
          : []),
        ...(autoComponents.length
          ? autoComponents.map((c) => `component:${c}`)
          : []),
        ...(templateRuntimeModelRef.current
          ? [`wb-template-package:${templateRuntimeModelRef.current.template.id}`]
          : []),
      ],
      productId: product?.id ?? "website-builder",
      projectId: tpl ? undefined : activeProject?.projectId ?? undefined,
      templateId: resolveBuilderTemplatePackageId(autoTemplateId || "") || undefined,
      marketplaceTemplateId: resolvedMarketplaceId || undefined,
      templateStyle: resolvedStyle || inferred.designStyle || undefined,
      designPreset: autoPreset || inferred.designPreset || undefined,
      industryId: resolvedIndustry || inferred.industryId || undefined,
      components: autoComponents.length ? autoComponents : undefined,
      designSystem: mergedDesignSystem,
      templateIntelligenceId: autoTiId || undefined,
      templateIntelligenceCategory: autoTiCategory || undefined,
      websiteStructureTemplateId:
        resolveBuilderTemplatePackageId(
          templateRuntimeModelRef.current?.template.id ??
            websiteStructureTemplateId ??
            "",
        ) || undefined,
      websiteThemeId: websiteThemeId || undefined,
      brandIdentityId: brandIdentityId || undefined,
      locale: resolvedLanguage || undefined,
      mode: tpl ? "generate" : mode,
      parentGenerationId:
        tpl || mode === "generate" ? undefined : activeProject?.id,
      continueInstruction:
        tpl || mode !== "continue"
          ? undefined
          : options?.resume
            ? resumeInstruction
            : layerInstruction ||
              projectBrief.trim() ||
              (options?.optimize ? optimizeInstruction : undefined),
      optimizeWithAi: Boolean(options?.optimize),
      imageStrategyMode,
      ...(visualSkinId ? { visualSkinId } : {}),
    };

    const applySavedGeneration = (
      generatedProject: GeneratedWebsiteProject,
      generation: WebsiteGeneration,
    ) => {
      generationAppliedToWorkspace = true;
      const nextProject = toProject({
        ...generation,
        blueprint: generatedProject as unknown as WebsiteGeneration["blueprint"],
      });

      // 1) Optimistic — show in Recent Projects + activate immediately.
      commitWorkspaceProject(nextProject);
      // 2) Background sync — merge API list without wiping the optimistic row.
      void refetchRecentProjects({
        expectedId: nextProject.id,
        ensureProject: nextProject,
      });
      setSelectedFilePath(
        generatedProject.files.find((f) => f.path.includes("preview/"))?.path ||
          generatedProject.files[0]?.path ||
          "",
      );
      setOutputTab("review");
      setEditMode(false);
      setStreamStatus(wb("stream.websiteSaved"));
      toast.success(
        options?.layerImprove
          ? wb("designEngine.layerImproveComplete")
          : wb("toasts.createdAndSaved"),
      );
    };

    const recoveryMessages = {
      connectionInterrupted: wb("stream.connectionInterrupted"),
      generationFailedResume: wb("stream.generationFailedResume"),
      stillGenerating: wb("stream.stillGenerating"),
      stillGeneratingWithFiles: wb("stream.stillGeneratingWithFiles"),
      finalizing: wb("stream.finalizingSavedProject"),
    };

    const recoveryPollMs = getClientStreamRecoveryPollMs();

    const tryApplyRecoveredGeneration = async (
      generationId: string,
      lastProgressMessage: string | null,
    ): Promise<boolean> => {
      const recovered = await tryRecoverCompletedWebsiteGeneration(generationId, {
        onStatus: setStreamStatus,
        messages: recoveryMessages,
        lastProgressMessage,
        pollMs: recoveryPollMs,
      });
      if (!recovered) return false;
      applySavedGeneration(recovered.project, recovered.generation);
      setPreviewRevision((n) => n + 1);
      setApiError(null);
      return true;
    };

    console.info("[website-builder] prompt verification", {
      generationMode: requestBody.mode ?? mode,
      projectBrief: effectiveProjectBrief.trim(),
      requestBodyPrompt: requestBody.prompt,
      templateBrief: templateBriefForLog,
      activeProjectDescription: activeProject?.description ?? null,
    });

    streamAbortRef.current?.abort();
    const streamAbort = new AbortController();
    streamAbortRef.current = streamAbort;
    activeStreamSessionRef.current = null;

    let sessionGenerationId: string | null = null;
    let generationAppliedToWorkspace = false;

    try {
      const streamResponse = await fetch("/api/website-builder/stream", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "text/event-stream",
        },
        body: JSON.stringify(requestBody),
        signal: streamAbort.signal,
      });

      if (streamResponse.ok && streamResponse.body) {
        let incrementalPreview = isWebsiteIncrementalPreviewEnabled();
        let lastPreviewBumpAt = 0;
        let handoffRecoveryStarted = false;
        let handoffRecoveryPromise: Promise<boolean> | null = null;

        const startHandoffRecovery = (generationId: string, message?: string | null) => {
          if (handoffRecoveryStarted) return;
          handoffRecoveryStarted = true;
          handoffRecoveryPromise = tryApplyRecoveredGeneration(
            generationId,
            message ?? null,
          );
          void handoffRecoveryPromise.then((recovered) => {
            if (recovered) {
              setPreviewRevision((n) => n + 1);
              setApiError(null);
            }
          });
        };

        const sseResult = await readSseStream<{
          project?: GeneratedWebsiteProject;
          generation?: WebsiteGeneration;
          generationId?: string;
          summary?: {
            title?: string;
            fileCount?: number;
            projectKind?: string;
          };
          message?: string;
          fileCount?: number;
        }>(streamResponse, {
          onProgress: (message, _progress, meta) => {
            setStreamStatus(message);
            if (meta?.generationId) {
              sessionGenerationId = meta.generationId;
              activeStreamSessionRef.current = meta.generationId;
            }
            if (!incrementalPreview) return;
            const fileCount = meta?.fileCount ?? 0;
            if (fileCount <= 0) return;
            const now = Date.now();
            if (now - lastPreviewBumpAt < 4000) return;
            lastPreviewBumpAt = now;
            setPreviewRevision((n) => n + 1);
          },
          onSession: (session) => {
            sessionGenerationId = session.generationId;
            activeStreamSessionRef.current = session.generationId;
            if (session.incrementalPreview) incrementalPreview = true;
            const stub = stubRunningProject({
              id: session.generationId,
              title: wb("statuses.generating"),
              description:
                typeof requestBody.prompt === "string"
                  ? requestBody.prompt
                  : apiPrompt,
              type: resolvedProjectType,
              style: inferred.designStyle,
              theme: inferred.colorTheme,
              language: resolvedLanguage,
              features,
              mode: requestBody.mode as GenerationMode | undefined,
            });
            commitWorkspaceProject(stub);
            if (!incrementalPreview) return;
            setOutputTab("preview");
            setPreviewRevision((n) => n + 1);
          },
          onHandoff: (handoff) => {
            if (handoff.message) setStreamStatus(handoff.message);
            if (handoff.generationId) {
              sessionGenerationId = handoff.generationId;
              activeStreamSessionRef.current = handoff.generationId;
              if (handoff.pollMode) {
                startHandoffRecovery(handoff.generationId, handoff.message);
              }
            }
          },
          onComplete: async (payload) => {
            if (payload.project && payload.generation?.id) {
              applySavedGeneration(payload.project, payload.generation);
              setPreviewRevision((n) => n + 1);
              return;
            }

            if (payload.summary?.title) {
              setActiveProject((current) => {
                if (!current?.id) return current;
                if (!isGeneratingWebsitePlaceholderTitle(current.title)) return current;
                return { ...current, title: payload.summary!.title! };
              });
            }

            const generationId =
              payload.generationId ?? payload.generation?.id ?? sessionGenerationId;
            if (!generationId) {
              throw new Error(wb("errors.noSavedGeneration"));
            }

            const recovered = await tryApplyRecoveredGeneration(
              generationId,
              payload.message ?? null,
            );
            if (!recovered) {
              throw new Error(wb("errors.noSavedGeneration"));
            }
          },
          onError: (message) => {
            setApiError(message);
            setStreamStatus(message);
          },
        }, { signal: streamAbort.signal });

        if (sseResult.generationId) {
          sessionGenerationId = sseResult.generationId;
          activeStreamSessionRef.current = sseResult.generationId;
        }

        if (!sseResult.completed && !sseResult.aborted) {
          const recoveryId = sessionGenerationId ?? sseResult.generationId;
          if (recoveryId) {
            const recovered = await recoverAfterIncompleteSse(
              handoffRecoveryStarted,
              handoffRecoveryPromise,
              recoveryId,
              sseResult.lastProgressMessage,
              tryApplyRecoveredGeneration,
            );
            if (!recovered) {
              // Keep partial project selectable for Resume.
              try {
                const detail = await fetch(`/api/website-builder/${recoveryId}`);
                if (detail.ok) {
                  const data = (await detail.json()) as {
                    generation?: WebsiteGeneration;
                  };
                  if (data.generation) {
                    const partial = toProject(data.generation);
                    commitWorkspaceProject(partial);
                  }
                }
              } catch {
                // ignore
              }
              throw new Error(
                sseResult.error || wb("errors.generationDisconnected"),
              );
            }
          } else {
            throw new Error(
              sseResult.error || wb("errors.generationDisconnected"),
            );
          }
        } else if (!sseResult.completed && sseResult.error) {
          const recoveryId = sessionGenerationId ?? sseResult.generationId;
          if (recoveryId) {
            const recovered = await tryApplyRecoveredGeneration(
              recoveryId,
              sseResult.lastProgressMessage,
            );
            if (recovered) return;
          }
          throw new Error(sseResult.error);
        }
      } else if (
        // Only fall back when the stream route is missing — never after a charged
        // stream attempt (401/402/429/5xx), which would double-debit AI credits.
        streamResponse.status === 404 ||
        streamResponse.status === 405
      ) {
        const response = await fetch("/api/website-builder", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(requestBody),
        });
        const data = (await response.json()) as GenerateProjectResponse;

        if (!response.ok) {
          throw new Error(
            await readWebsiteBuilderApiError(response, t, wb),
          );
        }

        if (!("project" in data) || !data.project || !data.generation?.id) {
          throw new Error(wb("errors.noSavedGeneration"));
        }

        applySavedGeneration(data.project, data.generation);
        setPreviewRevision((n) => n + 1);
      } else {
        const detail = await readWebsiteBuilderApiError(streamResponse, t, wb);
        throw new Error(detail);
      }
    } catch (error) {
      const recoveryId = activeStreamSessionRef.current;
      if (
        recoveryId &&
        !streamAbort.signal.aborted &&
        !(error instanceof DOMException && error.name === "AbortError")
      ) {
        const ok = await tryApplyRecoveredGeneration(recoveryId, null);
        if (ok) return;
      }

      setApiError(
        error instanceof Error
          ? error.message
          : wb("errors.generic"),
      );
      setStreamStatus(null);
    } finally {
      if (streamAbortRef.current === streamAbort) {
        streamAbortRef.current = null;
      }
      setIsGenerating(false);
      if (
        !generationAppliedToWorkspace &&
        (sessionGenerationId || activeStreamSessionRef.current)
      ) {
        void refetchRecentProjects({
          expectedId:
            sessionGenerationId ?? activeStreamSessionRef.current ?? undefined,
          ensureProject: activeProjectRef.current ?? undefined,
        });
      }
      window.setTimeout(() => setStreamStatus(null), 1200);
    }
  }

  function clearTemplateSelection() {
    setSelectedTemplateId(null);
    setMarketplaceTemplateId(null);
    setTemplateStyle(null);
    setDesignPreset(null);
    setTemplateIndustry(null);
    setTemplateComponents([]);
    setTemplateDesignSystem(null);
    setTemplateIntelligenceId(null);
    setTemplateIntelligenceCategory(null);
    setWebsiteStructureTemplateId(null);
    setWebsiteThemeId(null);
    setBrandIdentityId(null);
    setVisualSkinId(DEFAULT_VISUAL_SKIN_ID);
    setStreamStatus(null);
  }

  function syncThemeChoice(choice: WebsiteThemeChoice) {
    setWebsiteThemeId(choice.id);
    if (choice.designPreset) setDesignPreset(choice.designPreset);
    setTemplateDesignSystem({
      primary: choice.colors.primary,
      secondary: choice.colors.secondary,
      accent: choice.colors.accent,
      background: choice.colors.background,
      foreground: choice.colors.foreground,
      displayFont: choice.typography.display,
      bodyFont: choice.typography.body,
    });
  }

  async function handleVisualSkinSelect(skinId: string) {
    const skin = getVisualSkin(skinId);
    if (!skin) return;
    setVisualSkinId(skinId);
    if (!activeProject?.id) {
      return;
    }
    if (
      activeProject.generatedProject?.settings?.visualSkinId === skinId
    ) {
      return;
    }
    setIsApplyingTemplate(true);
    try {
      const res = await fetch(
        `/api/website-builder/${activeProject.id}/visual-skin`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ visualSkinId: skinId }),
        },
      );
      const data = (await res.json()) as {
        error?: string;
        project?: GeneratedWebsiteProject;
      };
      if (!res.ok) {
        throw new Error(data.error ?? wb("panels.failedApplyTemplate"));
      }
      if (data.project && activeProject) {
        commitWorkspaceProject({
          ...activeProject,
          generatedProject: data.project,
        });
        setPreviewRevision((n) => n + 1);
      }
      toast.success(wb("templates.structureRedesigned", { name: skin.label }));
    } catch (error) {
      toast.error(
        error instanceof Error ? error.message : wb("panels.failedApplyTemplate"),
      );
    } finally {
      setIsApplyingTemplate(false);
    }
  }

  function handleStructureTemplateSelect(
    choice: WebsiteStructureTemplateChoice,
  ) {
    void handleVisualSkinSelect(choice.skinId);
  }

  function handleThemeSelect(choice: WebsiteThemeChoice) {
    syncThemeChoice(choice);
    if (activeProject?.id) {
      return;
    }
    toast.success(wb("templates.themeApplied", { name: choice.name }));
  }

  async function applyStructureTemplateToActiveProject(
    choice: WebsiteStructureTemplateChoice,
  ): Promise<boolean> {
    await handleVisualSkinSelect(choice.skinId);
    return true;
  }

  async function applyTemplateIntelligenceToActiveProject(
    templateIntelligenceId: string,
  ): Promise<boolean> {
    if (!activeProject?.id) return false;
    setIsApplyingTemplate(true);
    setApiError(null);
    setStreamStatus(wb("stream.applyingEdit"));
    try {
      const res = await fetch(
        `/api/website-builder/${activeProject.id}/template`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ templateIntelligenceId }),
        },
      );
      const data = (await res.json()) as {
        error?: string;
        generation?: unknown;
        project?: unknown;
        template?: {
          id: string;
          name: string;
          category: string;
          designPreset: string;
          designStyle: string;
          premiumTemplateId?: string;
          components: string[];
        };
      };
      if (!res.ok) {
        throw new Error(data.error || wb("panels.failedApplyTemplate"));
      }
      if (data.generation && data.project) {
        handleTemplateIntelligenceApplied({
          generation: data.generation,
          project: data.project,
          template: data.template,
        });
      }
      return true;
    } catch (error) {
      const message =
        error instanceof Error ? error.message : wb("errors.generic");
      setApiError(message);
      toast.error(message);
      return false;
    } finally {
      setIsApplyingTemplate(false);
      window.setTimeout(() => setStreamStatus(null), 800);
    }
  }

  function handleThemeApplied(payload: {
    generation: unknown;
    project: unknown;
    theme: WebsiteThemeChoice;
  }) {
    syncThemeChoice(payload.theme);
    const generation = payload.generation as WebsiteGeneration;
    const project = payload.project as GeneratedWebsiteProject;
    if (!generation?.id || !project) return;

    const nextProject = toProject({
      ...generation,
      blueprint: project as unknown as WebsiteGeneration["blueprint"],
    });
    commitWorkspaceProject(nextProject);
    setSelectedFilePath(
      project.files.find((f) => f.path.includes("preview/"))?.path ||
        project.files[0]?.path ||
        "",
    );
    setOutputTab("preview");
    setPreviewRevision((n) => n + 1);
    toast.success(
      wb("templates.themeRedesigned", { name: payload.theme.name }),
    );
  }

  function handleTemplateIntelligenceApplied(payload: {
    generation: unknown;
    project: unknown;
    template?: {
      id: string;
      name: string;
      category: string;
      designPreset: string;
      designStyle: string;
      premiumTemplateId?: string;
      components: string[];
      colors?: WebsiteThemeChoice["colors"];
      typography?: WebsiteThemeChoice["typography"];
    };
  }) {
    const generation = payload.generation as WebsiteGeneration;
    const project = payload.project as GeneratedWebsiteProject;
    if (!generation?.id || !project) return;

    if (payload.template) {
      syncThemeChoice({
        id: payload.template.id as WebsiteThemeChoice["id"],
        label: payload.template.name,
        description: "",
        templateIntelligenceId: payload.template.id,
        designPreset: payload.template.designPreset as WebsiteThemeChoice["designPreset"],
        layoutType: "",
        heroType: "",
        navigationType: "",
        footerType: "",
        animationProfile: "",
        cardStyle: "",
        sectionPreview: [],
        pageTopology: "classic-stack",
        name: payload.template.name,
        colors: payload.template.colors ?? {
          primary: project.designSystem?.colors.primary ?? "#111",
          secondary: project.designSystem?.colors.secondary ?? "#333",
          accent: project.designSystem?.colors.accent ?? "#2563EB",
          background: project.designSystem?.colors.background ?? "#fff",
          foreground: project.designSystem?.colors.foreground ?? "#111",
          surface: project.designSystem?.colors.surface ?? "#f5f5f5",
        },
        typography: payload.template.typography ?? {
          display: project.typography?.[0] ?? "Inter",
          heading: project.typography?.[0] ?? "Inter",
          body: project.typography?.[1] ?? "Inter",
        },
      });
    }

    const nextProject = toProject({
      ...generation,
      blueprint: project as unknown as WebsiteGeneration["blueprint"],
    });
    commitWorkspaceProject(nextProject);
    setSelectedFilePath(
      project.files.find((f) => f.path.includes("preview/"))?.path ||
        project.files[0]?.path ||
        "",
    );
    setOutputTab("preview");
    setPreviewRevision((n) => n + 1);
    setVisualEditorDirty(false);
    restoreTemplateStateFromSettings(
      project.settings as Record<string, unknown> | undefined,
      {
        setWebsiteStructureTemplateId,
        setSelectedTemplateId,
        setTemplateIntelligenceId,
      },
    );
    toast.success(wb("toasts.templateApplied"));
  }

  useEffect(() => {
    if (!activeProject?.id || typeof window === "undefined") return;
    sessionStorage.setItem(ACTIVE_GENERATION_STORAGE_KEY, activeProject.id);
  }, [activeProject?.id]);

  useEffect(() => {
    const rawPendingId = pendingStructureTemplateApplyRef.current;
    if (!rawPendingId || !activeProject?.id || isApplyingTemplate) return;
    const pendingId = resolveBuilderTemplatePackageId(rawPendingId);
    pendingStructureTemplateApplyRef.current = null;

    const url = new URL(window.location.href);
    url.searchParams.delete("applyTemplate");
    window.history.replaceState(
      {},
      "",
      `${url.pathname}${url.search}${url.hash}`,
    );

    void handleVisualSkinSelect(pendingId);
  }, [activeProject?.id, isApplyingTemplate]);

  async function handleUseTemplate(payload: TemplateUsePayload) {
    const resolvedTemplateId = resolveBuilderTemplatePackageId(payload.templateId);
    setSelectedTemplateId(resolvedTemplateId);
    setMarketplaceTemplateId(payload.marketplaceTemplateId);
    setTemplateStyle(payload.style);
    setDesignPreset(payload.designPreset);
    setTemplateIndustry(payload.industry);
    setTemplateComponents(payload.components);
    setTemplateDesignSystem(payload.designSystem);
    setEditMode(false);
    setOutputTab("preview");

    if (activeProject?.id) {
      await handleVisualSkinSelect(resolvedTemplateId);
      return;
    }

    toast.success(wb("templates.usingTemplate", { name: payload.name }));
    void createInterfaceProject({ fromTemplate: payload });
  }

  async function applyWebsiteEditorEdit(params: {
    generationId: string;
    command: string;
    suggestionId?: string;
  }) {
    setIsGenerating(true);
    setApiError(null);
    setStreamStatus(wb("stream.applyingEdit"));
    try {
      const response = await fetch(
        `/api/website-builder/${params.generationId}/edit`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            command: params.command,
            suggestionId: params.suggestionId,
            applyAi: true,
          }),
        },
      );
      const data = (await response.json()) as {
        project?: GeneratedWebsiteProject;
        generation?: WebsiteGeneration;
        editResult?: { summary?: string };
        error?: string;
        message?: string;
      };
      if (!response.ok || !data.project || !data.generation) {
        throw new Error(
          formatWebsiteBuilderApiError({
            status: response.status,
            code: (data as { code?: string }).code,
            message: data.error,
            t,
            wb,
          }),
        );
      }
      const nextProject = toProject({
        ...data.generation,
        blueprint: data.project as unknown as WebsiteGeneration["blueprint"],
      });
      commitWorkspaceProject(nextProject);
      setSelectedFilePath(
        data.project.files.find((f) => f.path.includes("preview/"))?.path ||
          data.project.files[0]?.path ||
          "",
      );
      setOutputTab("preview");
      setStreamStatus(wb("stream.editSaved"));
      toast.success(data.editResult?.summary || data.message || wb("toasts.edited"));
    } catch (error) {
      const message =
        error instanceof Error ? error.message : wb("errors.generic");
      setApiError(message);
      toast.error(message);
    } finally {
      setIsGenerating(false);
      window.setTimeout(() => setStreamStatus(null), 1200);
    }
  }

  async function toggleFavorite(id: string) {
    const project = projects.find((item) => item.id === id);
    if (!project) return;

    try {
      const response = await fetch(`/api/website-builder/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ is_favorite: !project.favorite }),
      });
      const data = (await response.json()) as { generation?: WebsiteGeneration; error?: string };

      if (!response.ok || !data.generation) {
        throw new Error(data.error ?? wb("errors.favorite"));
