  async function downloadProject(
    input: DownloadableProject | WorkspaceProject | null | undefined = activeProject,
  ) {
    if (!input?.id) return;
    let workspaceProject: WorkspaceProject | null = isWorkspaceProject(input)
      ? input
      : null;

    try {
      // Prefer server export — always hydrates full blueprint from DB.
      const exportResponse = await fetch(
        `/api/website-builder/${input.id}/export`,
      );

      if (exportResponse.ok) {
        const blob = await exportResponse.blob();
        const disposition = exportResponse.headers.get("Content-Disposition");
        const match = disposition?.match(/filename="([^"]+)"/);
        const filename =
          match?.[1] ??
          `${input.title.toLowerCase().replace(/[^a-z0-9]+/g, "-") || "website-project"}.zip`;
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = filename;
        link.click();
        URL.revokeObjectURL(url);
        toast.success(wb("toasts.zipDownloadStarted"));
        return;
      }

      if (exportResponse.status === 409 || exportResponse.status === 422) {
        // Hydrate client copy, then fall back to prepared client ZIP if files appear.
        const detail = await fetch(`/api/website-builder/${input.id}`);
        if (detail.ok) {
          const data = (await detail.json()) as {
            generation?: WebsiteGeneration;
          };
          if (data.generation) {
            patchProject(input.id, data.generation);
            const hydrated = toProject(data.generation);
            if (hydrated.generatedProject?.files?.length) {
              workspaceProject = hydrated;
            }
          }
        }
      } else {
        const data = (await exportResponse.json().catch(() => null)) as {
          error?: string;
        } | null;
        throw new Error(data?.error ?? wb("errors.download"));
      }

      const rawFiles = workspaceProject?.generatedProject?.files ?? [];
      if (!rawFiles.length) {
        toast.error(
          wb("errors.download"),
        );
        return;
      }

      const prepared = prepareWebsiteProjectForExport(rawFiles);
      if (!prepared.ready) {
        throw new Error(
          prepared.blockingIssues[0] ??
            "This project has export blockers. Fix validation issues in Website Builder, then try again.",
        );
      }

      const JSZip = (await import("jszip")).default;
      const zip = new JSZip();
      let skippedFiles = 0;
      prepared.files.forEach((file) => {
        const safePath = sanitizeZipPath(file.path);
        if (!safePath) {
          skippedFiles += 1;
          return;
        }
        zip.file(safePath, file.content);
      });

      const blob = await zip.generateAsync({ type: "blob" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `${input.title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}.zip`;
      link.click();
      URL.revokeObjectURL(url);
      toast.success(
        skippedFiles
          ? `ZIP download started. Skipped ${skippedFiles} unsafe file path${skippedFiles === 1 ? "" : "s"}.`
          : wb("toasts.zipDownloadStarted"),
      );
    } catch (error) {
      toast.error(
        error instanceof Error ? error.message : wb("errors.download"),
      );
    }
  }

  async function importProject(file: File) {
    try {
      const form = new FormData();
      form.append("file", file);
      form.append("title", file.name.replace(/\.zip$/i, ""));
      const res = await fetch("/api/website-builder/import", {
        method: "POST",
        body: form,
      });
      const json = (await res.json()) as {
        generation?: WebsiteGeneration;
        error?: string;
        warnings?: string[];
      };
      if (!res.ok || !json.generation) {
        throw new Error(json.error || "Import failed");
      }
      const imported = toProject(json.generation);
      commitWorkspaceProject(imported);
      toast.success("Project imported successfully");
      if (json.warnings?.length) {
        toast.message(json.warnings[0]);
      }
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Import failed");
    }
  }

