          toast.success(wb("toasts.seoFixApplied"));
        }}
        onReviewApplied={({ project: savedProject, generation }) => {
          const nextProject = toProject({
            ...generation,
            blueprint:
              savedProject as unknown as WebsiteGeneration["blueprint"],
          });
          commitWorkspaceProject(nextProject);
          setPreviewRevision((n) => n + 1);
          toast.success(wb("toasts.reviewImprovementApplied"));
        }}
        onIntelligenceApply={(command) => {
          if (!activeProject?.id) return;
          setEditMode(true);
          setProjectBrief(command);
          void applyWebsiteEditorEdit({
            generationId: activeProject.id,
            command,
          });
        }}
        generationStreamMessage={streamStatus}
        onCanvasAiCommand={(command) => {
          if (!activeProject?.id) return;
          setEditMode(true);
          setProjectBrief(command);
          void applyWebsiteEditorEdit({
            generationId: activeProject.id,
            command,
          });
        }}
        onTemplateSelect={handleStructureTemplateSelect}
        proWorkspaceEnabled={proWorkspaceEnabled}
        onProProjectChange={(savedProject) => {
          if (!activeProject) return;
          const nextProject = {
            ...activeProject,
            generatedProject: savedProject,
          };
          commitWorkspaceProject(nextProject);
          setPreviewRevision((n) => n + 1);
        }}
        onFavorite={() => {
          if (activeProject) void toggleFavorite(activeProject.id);
        }}
      />

      <Dialog open={renameOpen} onOpenChange={setRenameOpen}>
        <DialogContent className="border-white/10 bg-[#141414]/95 text-white">
          <DialogHeader>
            <DialogTitle>{wb("dialogs.renameTitle")}</DialogTitle>
            <DialogDescription className="text-white/45">
              {wb("dialogs.renameDescriptionWorkspace")}
            </DialogDescription>
          </DialogHeader>
          <Input
            value={renameValue}
            onChange={(event) => setRenameValue(event.target.value)}
            className="h-11 rounded-xl border-white/[0.1] bg-black/25 text-white"
            placeholder={wb("placeholders.rename")}
          />
          <DialogFooter className="border-white/10 bg-white/[0.03]">
            <Button
              type="button"
              variant="outline"
              className="btn-ghost-gold"
              onClick={() => setRenameOpen(false)}
            >
              {t("common.cancel")}
            </Button>
            <Button
              type="button"
              className="btn-gold text-luxury-black"
              onClick={renameProject}
              disabled={!renameValue.trim()}
            >
              {t("common.save")}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={deleteOpen} onOpenChange={(open) => !isDeleting && setDeleteOpen(open)}>
        <DialogContent className="border-white/10 bg-[#141414]/95 text-white">
          <DialogHeader>
            <DialogTitle>{wb("dialogs.deleteTitle")}</DialogTitle>
            <DialogDescription className="text-white/45">
              {deleteTarget
                ? `${wb("dialogs.deleteDescription")} (${deleteTarget.title})`
                : wb("dialogs.deleteDescription")}
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="border-white/10 bg-white/[0.03]">
            <Button
              type="button"
              variant="outline"
              className="btn-ghost-gold"
              onClick={() => setDeleteOpen(false)}
              disabled={isDeleting}
            >
              {t("common.cancel")}
            </Button>
            <Button
              type="button"
              className="bg-red-500 text-white hover:bg-red-600"
              onClick={() => void confirmDeleteProject()}
              disabled={isDeleting || !deleteTarget}
            >
              {isDeleting ? (
                <Loader2 className="size-4 animate-spin" />
              ) : null}
              {wb("dialogs.confirm")}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <BottomWorkspace
        onSelectProject={(projectId) => {
          const project = projects.find((item) => item.id === projectId);
          if (project) void selectProject(project);
        }}
        onFavorite={toggleFavorite}
        onDuplicate={(projectId) => {
          const project = projects.find((item) => item.id === projectId);
          if (project) void duplicateProject(project);
        }}
        onDelete={requestDelete}
        onDownload={downloadProject}
      />

    </div>
    </WebsiteBuilderProjectsProvider>
  );
}

