          </Button>
        </div>
      </div>
    </aside>
  );
}

function BottomWorkspace({
  onSelectProject,
  onFavorite,
  onDuplicate,
  onDelete,
  onDownload,
}: {
  onSelectProject: (projectId: string) => void;
  onFavorite: (id: string) => void;
  onDuplicate: (projectId: string) => void;
  onDelete: (id: string) => void;
  onDownload: (project?: DownloadableProject | WorkspaceProject | null) => void;
}) {
  const { t } = useTranslation();
  const wb = useProductT("websiteBuilder");
  const { projects, activeProject } = useWebsiteBuilderProjects();

  return (
    <div className="grid gap-6">
      <DashboardPanel>
        <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <SectionHeader icon={History} title={wb("sections.recentProjects")} description={wb("sectionDescriptions.recentProjects")} />
          <div className="flex flex-wrap gap-2">
            <Button
              type="button"
              variant="outline"
              className="btn-ghost-gold rounded-xl"
              onClick={() => onDownload(activeProject)}
              disabled={!activeProject}
            >
              <ArrowDownToLine className="size-4" />
              {t("common.export")}
            </Button>
            <Button
              type="button"
              variant="outline"
              className="btn-ghost-gold rounded-xl"
              onClick={() => onDownload(activeProject)}
              disabled={!activeProject}
            >
              <Download className="size-4" />
              {t("common.download")}
            </Button>
          </div>
        </div>

        <RecentProjectsGrid
          onSelect={onSelectProject}
          onFavorite={onFavorite}
          onDuplicate={onDuplicate}
          onDelete={onDelete}
          onDownload={(projectId) => {
            const project = projects.find((item) => item.id === projectId);
            onDownload(project ?? null);
          }}
        />
      </DashboardPanel>
    </div>
  );
}

function IconAction({
  icon: Icon,
  label,
  onClick,
  active,
  danger,
}: {
  icon: LucideIcon;
  label: string;
  onClick: () => void;
  active?: boolean;
  danger?: boolean;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "inline-flex items-center gap-1.5 rounded-xl border px-2.5 py-1.5 text-[12px] font-medium transition-colors",
        danger
          ? "border-red-400/15 text-red-300 hover:bg-red-400/10"
          : active
            ? "border-premium-gold/25 bg-premium-gold/10 text-premium-gold-light"
            : "border-white/[0.08] text-white/45 hover:border-premium-gold/25 hover:text-premium-gold-light",
      )}
