  );
}

"use client";

import { type ReactNode, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { History, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  VisualWebsiteEditor,
  type VisualWebsiteEditorHandle,
} from "@/components/dashboard/visual-editor/visual-website-editor";
import { BuilderPagesSidebar } from "@/components/dashboard/website-builder/builder-pages-sidebar";
import { BuilderSectionsPanel } from "@/components/dashboard/website-builder/builder-sections-panel";
import {
  BuilderToolRail,
  type BuilderToolId,
} from "@/components/dashboard/website-builder/builder-tool-rail";
import { DesignSystemPanel } from "@/components/dashboard/website-builder/design-system-panel";
import { BlocksPanel } from "@/components/dashboard/website-builder/blocks-panel";
import { AiBuilderPanel } from "@/components/dashboard/website-builder/ai-builder-panel";
import { ProfessionalPanel } from "@/components/dashboard/website-builder/professional-panel";
import { BusinessHubPanel } from "@/components/dashboard/website-builder/business-hub-panel";
import { PublishingHubPanel } from "@/components/dashboard/website-builder/publishing-hub-panel";
import { EnterprisePanel } from "@/components/dashboard/website-builder/enterprise-panel";
import { SiteImageManagerPanel } from "@/components/dashboard/website-builder/site-image-manager-panel";
import { LockedToolGate } from "@/components/dashboard/website-builder/locked-tool-gate";
import type { WebsiteStructureTemplateChoice } from "@/components/dashboard/website-builder/templates-panel";
import type { GeneratedProjectFile } from "@/lib/ai/types";
import type { GeneratedWebsiteProject } from "@/plugins/website/types";
import type { WebsiteGeneration } from "@/types/database";
import type { VisualDesignTokens, VisualViewport } from "@/lib/ai-core/visual-editor/types";
import {
  listBuilderVersionSnapshots,
  pushBuilderVersionSnapshot,
  resolveBuilderDesignTokens,
  resolveBuilderWorkspaceStructure,
  sectionToCopilotSelection,
  type BuilderAutosaveState,
  type BuilderBlockView,
  type BuilderVersionSnapshot,
} from "@/lib/website/builder";
import { useBuilderLocale } from "@/lib/website/builder/use-builder-locale";
import { refreshCapabilities } from "@/lib/website/builder/capabilities/service";
import { resolveBuilderToolbar } from "@/lib/website/builder/tools/resolve";
import { VisualSkinCatalogPanel } from "@/components/dashboard/website-builder/visual-skin-catalog-panel";
import { hasPublishedVisualSkins, getVisualSkin } from "@/lib/website/visual-skin/registry";

type BuilderWorkspaceProps = {
  generationId: string;
  files: GeneratedProjectFile[];
  project: GeneratedWebsiteProject;
  disabled?: boolean;
  promptHint?: string | null;
  managementHref?: string;
  copilotSlot: ReactNode;
  aiLoading?: boolean;
  aiStreamMessage?: string | null;
  onDirtyChange?: (dirty: boolean) => void;
  onSelectionChange?: (selection: {
    nodeId: string;
    nodeLabel: string;
    sectionKind?: string;
    componentExportName?: string;
  } | null) => void;
  onAiCommand?: (command: string, useStream?: boolean) => void;
  onOpenWorkspaceTab?: (tab: "analytics" | "experiments" | "deploy") => void;
  onTemplateSelect?: (choice: WebsiteStructureTemplateChoice) => void;
  onSaved: (payload: {
    project: GeneratedWebsiteProject;
    generation: WebsiteGeneration;
  }) => void;
};

export function BuilderWorkspace({
  generationId,
  files,
  project,
  disabled,
  promptHint,
  managementHref = "",
  copilotSlot,
  aiLoading,
  aiStreamMessage,
  onDirtyChange,
  onSelectionChange,
  onAiCommand,
  onOpenWorkspaceTab,
  onTemplateSelect,
  onSaved,
}: BuilderWorkspaceProps) {
  const { wb, dir } = useBuilderLocale();
  const editorRef = useRef<VisualWebsiteEditorHandle>(null);
  const [activeTool, setActiveTool] = useState<BuilderToolId>("structure");
  const [selectedPageRoute, setSelectedPageRoute] = useState("/");
  const [selectedSectionId, setSelectedSectionId] = useState<string | null>(null);
  const [autosaveState, setAutosaveState] = useState<BuilderAutosaveState>("idle");
  const [versions, setVersions] = useState<BuilderVersionSnapshot[]>([]);
  const [tokens, setTokens] = useState<VisualDesignTokens>(() =>
    resolveBuilderDesignTokens(project),
  );
  const [viewport, setViewport] = useState<VisualViewport>("desktop");
  const [backingUp, setBackingUp] = useState(false);
  const [, setStructureKey] = useState(0);

  const structure = resolveBuilderWorkspaceStructure({
    generationId,
    project,
    promptHint,
    selectedPageRoute,
  });

  const capabilityContext = useMemo(
    () => refreshCapabilities(project, { files }),
    [project, files],
  );
  const capabilityService = capabilityContext.service;

  const resolvedToolbar = useMemo(
    () => resolveBuilderToolbar(capabilityService),
    [capabilityService],
  );

  const activeResolvedTool = useMemo(
    () => resolvedToolbar.tools.find((tool) => tool.id === activeTool),
    [resolvedToolbar.tools, activeTool],
  );

  useEffect(() => {
    setVersions(listBuilderVersionSnapshots(generationId));
  }, [generationId]);

  const handleSelectPage = useCallback(
    (route: string) => {
      const page = structure.pages.find((p) => p.route === route);
      if (!page?.editableInCanvas) {
        toast.message(wb("builder.workspace.openManagementHint"));
        return;
      }
      setSelectedPageRoute(route);
    },
    [structure.pages, wb],
  );

  const handleSelectSection = useCallback(
    (sectionId: string) => {
      setSelectedSectionId(sectionId);
      editorRef.current?.selectNode(sectionId);
      const section = structure.sections.find((s) => s.id === sectionId);
      if (section) onSelectionChange?.(sectionToCopilotSelection(section));
    },
    [onSelectionChange, structure.sections],
  );

  const handleReorderSection = useCallback((fromIndex: number, toIndex: number) => {
    editorRef.current?.moveSection(fromIndex, toIndex);
    setStructureKey((k) => k + 1);
  }, []);

  const handleEditorSelection = useCallback(
    (
      selection: {
        nodeId: string;
        nodeLabel: string;
        sectionKind?: string;
        componentExportName?: string;
      } | null,
    ) => {
      setSelectedSectionId(selection?.nodeId ?? null);
      onSelectionChange?.(selection);
    },
    [onSelectionChange],
  );

  const handleSaved = useCallback(
    (payload: { project: GeneratedWebsiteProject; generation: WebsiteGeneration }) => {
      pushBuilderVersionSnapshot({
        generationId,
        project: payload.project,
        label:
          autosaveState === "saving"
            ? wb("builder.workspace.autosaveSaving")
            : wb("builder.publishing.backup"),
      });
      setVersions(listBuilderVersionSnapshots(generationId));
      setStructureKey((k) => k + 1);
      onSaved(payload);
    },
    [autosaveState, generationId, onSaved],
  );

  const restoreVersion = useCallback(
    (snapshot: BuilderVersionSnapshot) => {
      onSaved({
        project: snapshot.project as GeneratedWebsiteProject,
        generation: {
          id: generationId,
          updated_at: snapshot.createdAt,
        } as WebsiteGeneration,
      });
      toast.success(wb("builder.workspace.restored", { label: snapshot.label }));
    },
    [generationId, onSaved, wb],
  );

  const saveServerBackup = useCallback(async () => {
    setBackingUp(true);
    try {
      const res = await fetch(
        `/api/website-builder/${generationId}/builder/snapshots`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ label: wb("builder.publishing.backup") }),
        },
      );
      if (!res.ok) throw new Error(wb("builder.workspace.backupFailed"));
      toast.success(wb("builder.workspace.backupSaved"));
    } catch {
      toast.error(wb("builder.workspace.backupFailed"));
    } finally {
      setBackingUp(false);
    }
  }, [generationId, wb]);

  const handleTokensChange = useCallback((patch: Partial<VisualDesignTokens>) => {
    editorRef.current?.updateTokens(patch);
    setTokens((prev) => ({ ...prev, ...patch }));
  }, []);

  const handleViewportChange = useCallback((v: VisualViewport) => {
    editorRef.current?.setViewport(v);
    setViewport(v);
  }, []);

  const handleInsertBlock = useCallback((block: BuilderBlockView) => {
    editorRef.current?.insertBlock({
      exportName: block.exportName,
      path: block.path,
      sectionKind: block.sectionKind,
      name: block.name,
    });
    setStructureKey((k) => k + 1);
  }, []);

  const renderLeftPanel = () => {
    if (activeResolvedTool && !activeResolvedTool.enabled) {
      return (
        <LockedToolGate
          tool={activeResolvedTool}
          disabled={disabled}
          onEnable={() => {
            if (activeResolvedTool.unlockCopilotCommand) {
              onAiCommand?.(activeResolvedTool.unlockCopilotCommand, true);
            }
          }}
        />
      );
    }

    if (activeTool === "design") {
      return (
        <DesignSystemPanel
          tokens={tokens}
          viewport={viewport}
          disabled={disabled}
          onTokensChange={handleTokensChange}
          onViewportChange={handleViewportChange}
        />
      );
    }
    if (activeTool === "blocks") {
      return (
        <BlocksPanel
          disabled={disabled}
          capabilityService={capabilityService}
          onInsert={handleInsertBlock}
        />
      );
    }
    if (activeTool === "media") {
      return (
        <SiteImageManagerPanel
          generationId={generationId}
          disabled={disabled}
          onProjectUpdated={(project) =>
            onSaved({
              project: project as GeneratedWebsiteProject,
              generation: { id: generationId } as WebsiteGeneration,
            })
          }
          className="h-full p-3"
        />
      );
    }
    if (activeTool === "ai") {
      return (
        <AiBuilderPanel
          capabilityService={capabilityService}
          disabled={disabled}
          loading={aiLoading}
          streamMessage={aiStreamMessage}
          onRun={(command, useStream) => onAiCommand?.(command, useStream)}
        />
      );
    }
    if (activeTool === "professional") {
      return (
        <ProfessionalPanel
          capabilityService={capabilityService}
          managementHref={managementHref}
          disabled={disabled}
          selectedVisualSkinId={project.settings?.visualSkinId}
          onCopilotCommand={(command) => onAiCommand?.(command, true)}
          onTemplateSelect={onTemplateSelect}
        />
      );
    }
    if (activeTool === "business") {
      return (
        <BusinessHubPanel
          capabilityService={capabilityService}
          managementHref={managementHref}
          disabled={disabled}
          onOpenWorkspaceTab={onOpenWorkspaceTab}
          onCopilotCommand={(command) => onAiCommand?.(command, true)}
        />
      );
    }
    if (activeTool === "publish") {
      return (
        <PublishingHubPanel
          capabilityService={capabilityService}
          files={files}
          disabled={disabled}
          onOpenDeploy={() => onOpenWorkspaceTab?.("deploy")}
          onBackup={() => void saveServerBackup()}
          backingUp={backingUp}
        />
      );
    }
    if (activeTool === "enterprise") {
      return <EnterprisePanel generationId={generationId} disabled={disabled} />;
    }
    return (
      <>
        <BuilderPagesSidebar
          pages={structure.pages}
          selectedRoute={structure.selectedPageRoute}
          managementHref={managementHref}
          onSelectPage={handleSelectPage}
        />
        <BuilderSectionsPanel
          sections={structure.sections}
          selectedSectionId={selectedSectionId}
          onSelectSection={handleSelectSection}
          onReorderSection={handleReorderSection}
        />
      </>
    );
  };

  const leftIsStructure = activeTool === "structure";

  return (
    <div
      dir={dir}
      className="flex min-h-[760px] flex-col overflow-hidden rounded-2xl border border-white/[0.08] bg-[#050505]"
    >
      <div className="flex flex-wrap items-center gap-2 border-b border-white/[0.08] px-3 py-2">
        <p className="me-auto text-xs font-semibold text-white/70">
          {wb("builder.workspace.title")}
        </p>
        {autosaveState !== "idle" ? (
          <span className="text-[10px] text-white/45">
            {autosaveState === "pending"
              ? wb("builder.workspace.autosavePending")
              : autosaveState === "saving"
                ? wb("builder.workspace.autosaveSaving")
                : autosaveState === "saved"
                  ? wb("builder.workspace.autosaveSaved")
                  : wb("builder.workspace.autosaveError")}
          </span>
        ) : null}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              type="button"
              size="sm"
              variant="outline"
              className="h-8 border-white/15 text-white"
              disabled={!versions.length}
            >
              <History className="size-3.5" aria-hidden />
              {wb("builder.workspace.versions")} ({versions.length})
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="max-h-64 overflow-y-auto">
            {versions.map((snapshot) => (
              <DropdownMenuItem key={snapshot.id} onClick={() => restoreVersion(snapshot)}>
                <span className="block text-xs font-medium">{snapshot.label}</span>
                <span className="block text-[10px] text-muted-foreground">
                  {new Date(snapshot.createdAt).toLocaleString()}
                </span>
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
        {autosaveState === "saving" ? (
          <Loader2 className="size-4 animate-spin text-premium-gold" />
        ) : null}
      </div>

      <BuilderToolRail
        active={activeTool}
        onChange={setActiveTool}
        tools={resolvedToolbar.tools}
      />

      {hasPublishedVisualSkins() && onTemplateSelect ? (
        <div className="border-b border-white/[0.08] px-3 py-2">
          <p className="mb-2 text-[10px] font-semibold uppercase tracking-[0.14em] text-white/35">
            {wb("sections.visualSkin")}
          </p>
          <VisualSkinCatalogPanel
            compact
            disabled={disabled}
            selectedId={project.settings?.visualSkinId}
            onSelect={(skinId) => {
              onTemplateSelect?.({
                skinId,
                label: getVisualSkin(skinId)?.label ?? skinId,
              });
            }}
          />
        </div>
      ) : null}

      <div
        className={cn(
          "grid min-h-0 flex-1",
          leftIsStructure
            ? "lg:grid-cols-[200px_180px_minmax(0,1fr)_minmax(280px,320px)]"
            : "lg:grid-cols-[240px_minmax(0,1fr)_minmax(280px,320px)]",
        )}
      >
        {leftIsStructure ? (
          renderLeftPanel()
        ) : (
          <div className="border-r border-white/[0.08] bg-black/30">{renderLeftPanel()}</div>
        )}
        <div className="min-h-[680px] min-w-0">
          <VisualWebsiteEditor
            ref={editorRef}
            chrome="workspace"
            generationId={generationId}
            files={files}
            project={project}
            disabled={disabled}
            autosaveEnabled
            onAutosaveStateChange={setAutosaveState}
            onDirtyChange={onDirtyChange}
            onSelectionChange={handleEditorSelection}
            onTokensChange={setTokens}
            onSaved={handleSaved}
          />
        </div>
        <aside className="min-h-0 overflow-y-auto border-l border-white/[0.08] bg-black/20 p-3">
          {copilotSlot}
        </aside>
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { buildWorkspaceSnapshot } from "@/lib/website/workspace/file-contracts";
import type { GeneratedWebsiteProject } from "@/lib/website/types/generation";
import type { GeneratedProjectFile } from "@/lib/ai/types";
import type { WebsiteGeneration } from "@/types/database";
import { CopilotCommandPanel } from "@/components/dashboard/website-builder/copilot-command-panel";
import { ProWorkspaceFileTree } from "@/components/dashboard/website-builder/pro-workspace-file-tree";
import { ProWorkspacePreviewPane } from "@/components/dashboard/website-builder/pro-workspace-preview-pane";
import { VisualWebsiteEditor } from "@/components/dashboard/visual-editor/visual-website-editor";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

type ProWorkspaceShellProps = {
  generationId: string;
  project: GeneratedWebsiteProject;
  onProjectChange?: (project: GeneratedWebsiteProject) => void;
};

function defaultSelectedPath(files: GeneratedProjectFile[]): string {
  return (
    files.find((f) => f.path.includes("preview/"))?.path ||
    files.find((f) => f.path.endsWith("page.tsx"))?.path ||
    files[0]?.path ||
    ""
  );
}

/**
 * Pro workspace layout (WB_PRO_WORKSPACE) — file tree + editor/code + live preview + agent.
 */
export function ProWorkspaceShell({
  generationId,
  project,
  onProjectChange,
}: ProWorkspaceShellProps) {
  const [localProject, setLocalProject] = useState(project);
  const [selectedPath, setSelectedPath] = useState(() =>
    defaultSelectedPath(project.files ?? []),
  );
  const [fileDraft, setFileDraft] = useState("");
  const [isDirty, setIsDirty] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [previewRevision, setPreviewRevision] = useState(0);
  const [centerMode, setCenterMode] = useState<"visual" | "code">("visual");

  useEffect(() => {
    setLocalProject(project);
    if (!project.files?.some((f) => f.path === selectedPath)) {
      setSelectedPath(defaultSelectedPath(project.files ?? []));
    }
  }, [project, selectedPath]);

  const files = localProject.files ?? [];
  const snapshot = useMemo(
    () => buildWorkspaceSnapshot(files, previewRevision),
    [files, previewRevision],
  );
  const selectedFile = files.find((f) => f.path === selectedPath) ?? null;

  useEffect(() => {
    setFileDraft(selectedFile?.content ?? "");
    setIsDirty(false);
  }, [selectedFile?.path, selectedFile?.content]);

  const applyProjectUpdate = useCallback(
    (next: GeneratedWebsiteProject) => {
      setLocalProject(next);
      onProjectChange?.(next);
      setPreviewRevision((n) => n + 1);
      setIsDirty(false);
    },
    [onProjectChange],
  );

  const handleCopilotApplied = useCallback(
    (payload: {
      project: GeneratedWebsiteProject;
      generation: WebsiteGeneration;
    }) => {
      void payload.generation;
      applyProjectUpdate(payload.project);
    },
    [applyProjectUpdate],
  );

  const handleFileSelect = useCallback(
    (path: string) => {
      if (path === selectedPath) return;
      if (isDirty) {
        const discard = window.confirm(
          "You have unsaved changes. Discard and switch files?",
        );
        if (!discard) return;
        setIsDirty(false);
      }
      setSelectedPath(path);
      setCenterMode(
        path.includes("preview/") || path.endsWith("page.tsx")
          ? "visual"
          : "code",
      );
    },
    [isDirty, selectedPath],
  );

  const saveFile = useCallback(async () => {
    if (!selectedPath || !isDirty) return;
    setIsSaving(true);
    try {
      const res = await fetch(`/api/website-builder/${generationId}/files`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: selectedPath, content: fileDraft }),
      });
      const data = (await res.json()) as {
        error?: string;
        project?: GeneratedWebsiteProject;
      };
      if (!res.ok) {
        throw new Error(data.error ?? "Failed to save file");
      }
      if (data.project) applyProjectUpdate(data.project);
      toast.success("File saved");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Save failed");
    } finally {
      setIsSaving(false);
    }
  }, [
    applyProjectUpdate,
    fileDraft,
    generationId,
    isDirty,
    selectedPath,
  ]);

  return (
    <div className="flex min-h-[75vh] flex-col gap-4">
      <div className="flex flex-wrap items-center gap-2 text-xs">
        <button
          type="button"
          onClick={() => setCenterMode("visual")}
          className={cn(
            "rounded-lg px-3 py-1.5 font-semibold transition-colors",
            centerMode === "visual"
              ? "bg-premium-gold/15 text-premium-gold-light"
              : "text-white/45 hover:text-white/70",
          )}
        >
          Visual
        </button>
        <button
          type="button"
          onClick={() => setCenterMode("code")}
          className={cn(
            "rounded-lg px-3 py-1.5 font-semibold transition-colors",
            centerMode === "code"
              ? "bg-cyan-400/15 text-cyan-200"
              : "text-white/45 hover:text-white/70",
          )}
        >
          Source
        </button>
        {centerMode === "code" && isDirty ? (
          <Button
            type="button"
            size="sm"
            className="ml-auto h-8 rounded-lg bg-cyan-500 text-xs text-white hover:bg-cyan-600"
            disabled={isSaving}
            onClick={() => void saveFile()}
          >
            {isSaving ? "Saving…" : "Save file"}
          </Button>
        ) : null}
      </div>

      <div className="grid min-h-0 flex-1 gap-4 lg:grid-cols-[220px_1fr_300px]">
        <aside className="flex min-h-[420px] flex-col rounded-2xl border border-white/10 bg-black/30 p-3 lg:min-h-0">
          <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-white/45">
            Files
          </p>
          <ProWorkspaceFileTree
            files={snapshot.files}
            selectedPath={selectedPath}
            onSelect={handleFileSelect}
          />
        </aside>

        <main className="grid min-h-[420px] min-w-0 gap-3 lg:min-h-0 lg:grid-cols-2">
          <div className="min-h-0 overflow-hidden rounded-2xl border border-white/10 bg-black/20">
            {centerMode === "visual" ? (
              <VisualWebsiteEditor
                generationId={generationId}
                project={localProject}
                files={files}
                chrome="workspace"
                onSaved={({ project: savedProject }) => applyProjectUpdate(savedProject)}
              />
            ) : (
              <div className="flex h-full min-h-[320px] flex-col">
                <div className="border-b border-white/10 px-3 py-2 text-xs text-white/45">
                  {selectedFile?.path ?? "Select a file"}
                </div>
                <textarea
                  value={fileDraft}
                  onChange={(e) => {
                    setFileDraft(e.target.value);
                    setIsDirty(true);
                  }}
                  className="min-h-0 flex-1 resize-none bg-transparent p-4 font-mono text-[12px] leading-relaxed text-white/85 outline-none"
                  spellCheck={false}
                />
              </div>
            )}
          </div>
          <ProWorkspacePreviewPane
            generationId={generationId}
            title={localProject.title || "Preview"}
            revision={previewRevision}
            className="min-h-[320px]"
          />
        </main>

        <aside className="min-h-[320px] overflow-hidden rounded-2xl border border-white/10 bg-black/30 lg:min-h-0">
          <CopilotCommandPanel
            generationId={generationId}
            onApplied={handleCopilotApplied}
          />
        </aside>
      </div>
    </div>
  );
}

