            result.reason ||
            "Marketing AI failed validation.",
        );
      }
      return report;
    },

    async finalize(_brief, _artifacts, generation, ctx) {
      const finished = output ?? generation;
      await marketingPlugin.export(finished, ctx);
      output = finished;
