export function priorArtifactsFromWebsiteInput(
  input: WebsiteGenerationInput,
): Partial<CoreLayerArtifacts> | undefined {
  const reuseModes = new Set(["continue", "regenerate", "retry"]);
  if (!input.mode || !reuseModes.has(input.mode)) {
    return undefined;
  }
  if (
    !input.previousBusinessProfile &&
    !input.previousStrategy &&
    !input.previousDesignSystem &&
    !input.previousAssetManifest
  ) {
    return undefined;
  }
  return {
    businessProfile: input.previousBusinessProfile as
      | CoreBusinessProfile
      | undefined,
    strategy: input.previousStrategy as CoreProductStrategy | undefined,
    designSystem: input.previousDesignSystem as CoreDesignSystem | undefined,
    assetManifest: input.previousAssetManifest as CoreAssetManifest | undefined,
  };
}

import type { AgencyBrandKit } from "@/lib/ai-core/agency-brand-kit/types";

export type BrandLogoAssets = {
  logoLight: string;
  logoDark: string;
  monogram: string;
  favicon: string;
};

function initials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length >= 2) {
    return (parts[0]![0]! + parts[1]![0]!).toUpperCase();
  }
  return name.slice(0, 2).toUpperCase();
}

function wordmarkSvg(params: {
  name: string;
  fg: string;
  accent: string;
  width?: number;
  height?: number;
}): string {
  const w = params.width ?? 240;
  const h = params.height ?? 48;
  const mono = initials(params.name);
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" role="img" aria-label="${params.name}">
  <rect x="0" y="4" width="40" height="40" rx="10" fill="${params.accent}"/>
  <text x="20" y="30" text-anchor="middle" fill="#ffffff" font-family="system-ui,sans-serif" font-size="16" font-weight="700">${mono}</text>
  <text x="52" y="32" fill="${params.fg}" font-family="system-ui,sans-serif" font-size="20" font-weight="600" letter-spacing="-0.02em">${params.name}</text>
</svg>`;
}

function monogramSvg(accent: string, fg: string, letters: string): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64" role="img" aria-label="Logo">
  <rect width="64" height="64" rx="16" fill="${accent}"/>
  <text x="32" y="42" text-anchor="middle" fill="${fg}" font-family="system-ui,sans-serif" font-size="24" font-weight="700">${letters}</text>
</svg>`;
}

function faviconSvg(accent: string, letters: string): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" width="32" height="32">
  <rect width="32" height="32" rx="8" fill="${accent}"/>
  <text x="16" y="22" text-anchor="middle" fill="#ffffff" font-family="system-ui,sans-serif" font-size="12" font-weight="700">${letters.slice(0, 1)}</text>
</svg>`;
}

/** Generate professional SVG logo assets from brand kit. */
export function generateBrandLogoAssets(brandKit: AgencyBrandKit): BrandLogoAssets {
  const letters = initials(brandKit.companyName);
  const { primary, accent, foreground, background } = brandKit.colorPalette;

  return {
    logoLight: wordmarkSvg({
      name: brandKit.companyName,
      fg: foreground,
      accent: primary,
    }),
    logoDark: wordmarkSvg({
      name: brandKit.companyName,
      fg: "#ffffff",
      accent: accent,
    }),
    monogram: monogramSvg(primary, "#ffffff", letters),
    favicon: faviconSvg(accent, letters),
  };
}

export function brandLogoReactComponent(brandKit: AgencyBrandKit, assets: BrandLogoAssets): string {
  const light = assets.logoLight.replace(/"/g, '\\"').replace(/\n/g, "");
  const dark = assets.logoDark.replace(/"/g, '\\"').replace(/\n/g, "");
  return `"use client";

export function BrandLogo({ variant = "light" }: { variant?: "light" | "dark" }) {
  const svg = variant === "dark"
    ? "${dark}"
  : "${light}";
  return (
    <div
      className="inline-flex items-center"
      dangerouslySetInnerHTML={{ __html: svg }}
      aria-label="${brandKit.companyName}"
    />
  );
}
`;
}

import type { GeneratedProjectFile } from "@/lib/ai/types";
import type { AgencyGenerationContract } from "@/lib/ai-core/agency-orchestrator/types";
import {
  validateGenerationAgainstBusinessProfile,
  type BusinessQualityReport,
} from "@/lib/ai-core/business-intelligence/validate";
import {
  validateAccessibility,
  repairAccessibility,
  type AccessibilityReport,
} from "@/lib/ai-core/accessibility/validate";

export type AgencyQualityReport = {
  passed: boolean;
  score: number;
  businessValidation: BusinessQualityReport | null;
  accessibilityReport: AccessibilityReport | null;
  designConsistency: {
    passed: boolean;
    issues: string[];
  };
  contentQuality: {
    passed: boolean;
    issues: string[];
  };
  seoReadiness: {
    passed: boolean;
    issues: string[];
  };
  blockers: string[];
  warnings: string[];
  summary: string;
};

function extractHeroText(files: GeneratedProjectFile[]): string {
  for (const file of files) {
    if (!/hero/i.test(file.path)) continue;
    const match = file.content.match(/>([^<]{20,120})</);
    if (match?.[1]) return match[1].trim();
  }
  const home = files.find((f) => /page\.tsx$|home/i.test(f.path));
  if (!home) return "";
  const h1 = home.content.match(/<h1[^>]*>([^<]+)</i);
  return h1?.[1]?.trim() || "";
}

function extractSectionLabels(files: GeneratedProjectFile[]): string[] {
  const labels: string[] = [];
  const headingRe = /<h2[^>]*>([^<]+)</gi;
  for (const file of files) {
    if (!/components\/|page\.tsx/.test(file.path)) continue;
    let match: RegExpExecArray | null;
    while ((match = headingRe.exec(file.content)) !== null) {
      const label = match[1].trim();
      if (label.length > 2 && label.length < 80) labels.push(label);
    }
  }
  return Array.from(new Set(labels)).slice(0, 12);
}

function extractCtaLabels(files: GeneratedProjectFile[]): string[] {
  const ctas: string[] = [];
  const buttonRe = /<(?:button|a)[^>]*>([^<]{2,40})</gi;
  for (const file of files) {
    let match: RegExpExecArray | null;
    while ((match = buttonRe.exec(file.content)) !== null) {
      const label = match[1].trim();
      if (!/menu|close|toggle|submit/i.test(label)) ctas.push(label);
    }
  }
  return Array.from(new Set(ctas)).slice(0, 8);
}

function checkDesignConsistency(
  files: GeneratedProjectFile[],
  contract: AgencyGenerationContract,
): { passed: boolean; issues: string[] } {
  const issues: string[] = [];
  const combined = files.map((f) => f.content).join("\n");
  const dna = contract.designDNA;

  if (!/className=.*(?:py-1[26]|py-2[04]|py-3[02])/.test(combined)) {
    issues.push("Missing generous section spacing (agency DNA requires breathing room)");
  }
  if (!/className=.*(?:rounded-(?:lg|xl|2xl)|rounded-\[)/.test(combined)) {
    issues.push("Missing modern border-radius on components");
  }
  if (dna.benchmark === "linear-quality" && !/dark|bg-(?:zinc|slate|neutral)-9/.test(combined)) {
    issues.push("Linear-quality DNA expects dark-first surfaces");
  }
  if (!/<h1\b/i.test(combined)) {
    issues.push("Missing H1 heading — breaks visual hierarchy");
  }
  const h1count = (combined.match(/<h1\b/gi) || []).length;
  if (h1count > 1) {
    issues.push(`Multiple H1 tags (${h1count}) — should be exactly one per page`);
  }

  return { passed: issues.length === 0, issues };
}

function checkContentQuality(
  files: GeneratedProjectFile[],
  contract: AgencyGenerationContract,
): { passed: boolean; issues: string[] } {
  const issues: string[] = [];
  const combined = files.map((f) => f.content).join("\n").toLowerCase();
  const genericPhrases = [
    "lorem ipsum",
    "your company",
    "company name",
    "placeholder text",
    "sample text",
    "todo:",
  ];
  for (const phrase of genericPhrases) {
    if (combined.includes(phrase)) {
      issues.push(`Generic placeholder detected: "${phrase}"`);
    }
  }
  const companyName = contract.brandKit.companyName.toLowerCase();
  if (!combined.includes(companyName)) {
    issues.push(`Brand name "${contract.brandKit.companyName}" not found in generated content`);
  }
  return { passed: issues.length === 0, issues };
}

function checkSeoReadiness(files: GeneratedProjectFile[]): {
  passed: boolean;
  issues: string[];
} {
  const issues: string[] = [];
  const layout = files.find((f) => /layout\.tsx$/.test(f.path));
  const combined = files.map((f) => f.content).join("\n");

  if (!layout && !/metadata|title|description/i.test(combined)) {
    issues.push("Missing page metadata (title/description)");
  }
  if (!/application\/ld\+json|structured-data|schema\.org/i.test(combined)) {
    issues.push("Missing structured data (JSON-LD)");
  }
  if (!/og:|openGraph|twitter/i.test(combined)) {
    issues.push("Missing Open Graph / Twitter card metadata");
  }
  return { passed: issues.length === 0, issues };
}

function runAccessibilityCheck(files: GeneratedProjectFile[]): {
  passed: boolean;
  issues: string[];
  report: AccessibilityReport;
} {
  const report = validateAccessibility(files);
  return {
    passed: report.passed,
    issues: report.issues
      .filter((i) => i.severity === "blocker")
      .map((i) => i.detail),
    report,
  };
}

/**
 * Unified agency quality gate — validates business relevance, design, content, SEO, a11y.
 */
export function runAgencyQualityGate(params: {
  files: GeneratedProjectFile[];
  contract: AgencyGenerationContract;
  imagePrompts?: Array<{ id: string; prompt: string; alt?: string }>;
}): AgencyQualityReport {
  const { files, contract } = params;
  const profile = contract.businessIntelligence.profile;
  const thresholds = contract.qualityThresholds;

  const heroText = extractHeroText(files) || contract.content.hero.headline;
  const sectionLabels = extractSectionLabels(files);
  const ctaLabels = extractCtaLabels(files);

  const businessValidation = thresholds.requireBusinessValidation
    ? validateGenerationAgainstBusinessProfile({
        profile,
        imagePrompts: params.imagePrompts,
        heroText,
        sectionLabels,
        ctaLabels: ctaLabels.length ? ctaLabels : [contract.content.hero.ctaPrimary],
      })
    : null;

  const designConsistency = checkDesignConsistency(files, contract);
  const contentQuality = checkContentQuality(files, contract);
  const seoReadiness = checkSeoReadiness(files);
  const a11y = runAccessibilityCheck(files);

  const blockers: string[] = [];
  const warnings: string[] = [];

  if (businessValidation && !businessValidation.passed) {
    blockers.push(...businessValidation.issues);
  }
  if (!designConsistency.passed) {
    warnings.push(...designConsistency.issues);
  }
  if (!contentQuality.passed) {
    blockers.push(...contentQuality.issues);
  }
  if (!a11y.passed) {
    blockers.push(...a11y.issues);
  }
  if (!seoReadiness.passed) {
    warnings.push(...seoReadiness.issues);
  }
  warnings.push(
    ...a11y.report.issues
      .filter((i) => i.severity === "warning")
      .map((i) => i.detail),
  );

  const scores = [
    businessValidation?.score ?? 100,
    designConsistency.passed ? 85 : 55,
    contentQuality.passed ? 90 : 40,
    seoReadiness.passed ? 80 : 50,
    a11y.report.score,
  ];
  const score = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);

  const passed =
    blockers.length === 0 &&
    score >= thresholds.minOverallScore &&
    (businessValidation?.score ?? 100) >= thresholds.minIndustryRelevance;

  return {
    passed,
    score,
    businessValidation,
    accessibilityReport: a11y.report,
    designConsistency,
    contentQuality,
    seoReadiness,
    blockers,
    warnings,
    summary: passed
      ? `Agency quality passed · score ${score} · ${contract.brandKit.companyName}`
      : `Agency quality failed · ${blockers.length} blocker(s) · score ${score}`,
  };
}

/**
 * AI App Assistant Agent — AI Core + structured mutations + file sync.
 */

import { getDefaultTextProvider } from "@/lib/ai/provider-config";
import { providerManager } from "@/lib/ai/provider-manager";
import type {
  AppAssistantResult,
  StructuredAppModel,
} from "@/lib/ai-core/app-design-platform/types";
import { runAppAssistant } from "@/lib/ai-core/app-design-platform/assistant";
import { addScreen, updateAppSettings } from "@/lib/ai-core/app-design-platform/model-builder";
import { applyBrandKitToModel } from "@/lib/ai-core/app-design-platform/brand";
import { upsertDataModel, connectScreenToData } from "@/lib/ai-core/app-design-platform/data";
import { upsertRole } from "@/lib/ai-core/app-design-platform/roles";
import { runAppQualityChecks } from "@/lib/ai-core/app-design-platform/quality";
import { syncAppModelToFiles } from "@/lib/ai-core/app-design-platform/sync";
import type { GeneratedProjectFile } from "@/lib/ai/types";

export type AppAssistantAgentResult = AppAssistantResult & {
  sync?: { updatedPaths: string[]; notes: string[] };
  quality?: ReturnType<typeof runAppQualityChecks>;
  files?: GeneratedProjectFile[];
};

const COMMAND_PATTERNS: Array<{
  pattern: RegExp;
  apply: (model: StructuredAppModel, match: RegExpMatchArray) => StructuredAppModel;
  label: string;
}> = [
  {
    pattern: /add\s+payment\s+system/i,
    label: "Add payment system",
    apply: (model) =>
      upsertDataModel(
        {
          ...model,
          featureFlags: Array.from(new Set([...model.featureFlags, "payments", "stripe"])),
        },
        {
          name: "Payment",
          label: "Payments",
          fields: [
            { name: "amount", type: "money", required: true },
            { name: "status", type: "enum", enumValues: ["pending", "paid", "failed"] },
            { name: "customerId", type: "relation", relationTo: "Customer" },
          ],
          relations: [],
          crud: ["create", "read", "list"],
        },
      ),
  },
  {
    pattern: /create\s+orders?\s+dashboard/i,
    label: "Create orders dashboard",
    apply: (model) => {
      const next = addScreen(model, {
        name: "Orders Dashboard",
        path: "/orders",
        purpose: "Track and manage orders",
        roles: ["admin", "manager"],
      });
      const screen = next.screens[next.screens.length - 1]!;
      return connectScreenToData(next, screen.id, "Order");
    },
  },
  {
    pattern: /add\s+customer\s+management/i,
    label: "Add customer management",
    apply: (model) =>
      upsertDataModel(model, {
        name: "Customer",
        label: "Customers",
        fields: [
          { name: "name", type: "string", required: true },
          { name: "email", type: "string", unique: true },
          { name: "phone", type: "string" },
        ],
        relations: [],
        crud: ["create", "read", "update", "delete", "list"],
      }),
  },
  {
    pattern: /change\s+application\s+design|redesign\s+app/i,
    label: "Change application design",
    apply: (model) =>
      applyBrandKitToModel(model, {
        name: model.brand.businessName,
        primary: "#6366F1",
        accent: "#22D3EE",
        secondary: "#1E293B",
      }),
  },
  {
    pattern: /create\s+admin\s+panel/i,
    label: "Create admin panel",
    apply: (model) => {
      let next = addScreen(model, {
        name: "Admin Panel",
        path: "/admin",
        purpose: "Administrative controls",
        roles: ["admin"],
      });
      next = upsertRole(next, {
        name: "admin",
        description: "Full administrative access",
        permissions: {
          screens: next.screens.map((s) => s.id),
          actions: ["*"],
          dataAccess: "all",
        },
      });
      return next;
    },
  },
  {
    pattern: /connect\s+database/i,
    label: "Connect database",
    apply: (model) => ({
      ...model,
      featureFlags: Array.from(new Set([...model.featureFlags, "database", "supabase"])),
      settings: {
        ...model.settings,
        features: Array.from(new Set([...model.settings.features, "database"])),
      },
      updatedAt: new Date().toISOString(),
      version: model.version + 1,
    }),
  },
];

async function tryLlmPlan(
  message: string,
  model: StructuredAppModel,
): Promise<string[] | null> {
  try {
    const providerName = getDefaultTextProvider();
    const provider = providerManager.resolve(providerName);
    if (!provider || !providerManager.isConfigured(provider)) return null;

    const prompt = `You are an App Builder assistant. Given the user command and app summary, return ONLY a JSON array of action strings (max 5) to apply. No markdown.

App: ${model.settings.appName} (${model.templateId})
Screens: ${model.screens.map((s) => s.name).join(", ")}
Data models: ${model.dataModels.map((d) => d.name).join(", ")}

User: ${message}`;

    const text = await providerManager.generateText(
      { prompt, temperature: 0.2 },
      providerName,
    );
    const match = text.match(/\[[\s\S]*\]/);
    if (!match) return null;
    const parsed = JSON.parse(match[0]) as unknown;
    return Array.isArray(parsed) ? parsed.map(String) : null;
  } catch {
    return null;
  }
}

export async function runAppAssistantAgent(params: {
  message: string;
  model: StructuredAppModel;
  files?: GeneratedProjectFile[];
  syncFiles?: boolean;
}): Promise<AppAssistantAgentResult> {
  const message = params.message.trim();
  let model = params.model;
  const actions: string[] = [];
  const notes: string[] = [];
  let applied = false;

  for (const cmd of COMMAND_PATTERNS) {
    const match = message.match(cmd.pattern);
    if (match) {
      model = cmd.apply(model, match);
      actions.push(cmd.label);
      applied = true;
    }
  }

  if (!applied) {
    const fallback = runAppAssistant({ message, model: params.model });
    if (fallback.applied && fallback.model) {
      model = fallback.model;
      actions.push(...fallback.actions);
      notes.push(...fallback.notes);
      applied = true;
    } else {
      const llmActions = await tryLlmPlan(message, params.model);
      if (llmActions?.length) {
        notes.push(`AI plan: ${llmActions.join(" → ")}`);
        for (const action of llmActions) {
          const inner = await runAppAssistantAgent({
            message: action,
            model,
            files: params.files,
            syncFiles: false,
          });
          if (inner.applied && inner.model) {
            model = inner.model;
            actions.push(...inner.actions);
            applied = true;
          }
        }
      }
      if (!applied) {
        return {
          ...fallback,
          understood: message,
          quality: runAppQualityChecks({ model: params.model, files: params.files }),
        };
      }
    }
  }

  let syncResult;
  let files = params.files;
  if (params.syncFiles !== false && files) {
    syncResult = syncAppModelToFiles(model, files);
    files = syncResult.files;
    notes.push(...syncResult.notes);
  }

  const quality = runAppQualityChecks({ model, files: files ?? [] });

  return {
    understood: message,
    actions,
    applied: true,
    notes,
    model,
    command: actions[0],
    sync: syncResult ? { updatedPaths: syncResult.updatedPaths, notes: syncResult.notes } : undefined,
    quality,
    files,
  };
}

/**
 * Visual editor — drag/drop, add/remove components, screen reorder, styles.
 */

import { getAppComponent, listComponentsForTemplate } from "@/lib/ai-core/app-design-platform/components";
import { slugId } from "@/lib/ai-core/app-design-platform/ids";
import type {
  StructuredAppModel,
  VisualEditorNode,
  VisualEditorState,
} from "@/lib/ai-core/app-design-platform/types";

export {
  buildEditorTreeForScreen,
  createVisualEditorState,
  selectScreen,
  updateNodeProps,
  applyEditorTreeToModel,
  reorderChild,
} from "@/lib/ai-core/app-design-platform/visual-editor-core";

import {
  buildEditorTreeForScreen,
  createVisualEditorState,
  selectScreen,
  updateNodeProps,
  applyEditorTreeToModel,
  reorderChild,
} from "@/lib/ai-core/app-design-platform/visual-editor-core";

export function selectNode(state: VisualEditorState, nodeId: string | null): VisualEditorState {
  return { ...state, selectedNodeId: nodeId };
}

export function updateNodeStyles(
  state: VisualEditorState,
  nodeId: string,
  style: Record<string, string>,
): VisualEditorState {
  return updateNodeProps(state, nodeId, {
    style: { ...(state.tree.find((n) => n.id === nodeId)?.props?.style as object), ...style },
  });
}

export function addComponentToScreen(
  model: StructuredAppModel,
  screenId: string,
  componentType: string,
): { model: StructuredAppModel; componentId: string } {
  const def = getAppComponent(componentType);
  const id = slugId("comp", `${screenId}-${componentType}`, model.components.length);
  const instance = {
    id,
    type: componentType,
    screenId,
    props: { ...(def?.defaultProps || {}), title: def?.label || componentType },
    children: [] as string[],
  };

  const screens = model.screens.map((s) =>
    s.id === screenId
      ? { ...s, components: Array.from(new Set([...s.components, componentType])) }
      : s,
  );

  return {
    model: {
      ...model,
      screens,
      components: [...model.components, instance],
      updatedAt: new Date().toISOString(),
      version: model.version + 1,
    },
    componentId: id,
  };
}

export function removeComponentFromModel(
  model: StructuredAppModel,
  componentId: string,
): StructuredAppModel {
  const target = model.components.find((c) => c.id === componentId);
  if (!target) return model;

  return {
    ...model,
    components: model.components.filter((c) => c.id !== componentId),
    screens: model.screens.map((s) =>
      s.id === target.screenId
        ? {
            ...s,
            components: s.components.filter((t) => t !== target.type),
          }
        : s,
    ),
    updatedAt: new Date().toISOString(),
    version: model.version + 1,
  };
}

export function reorderScreens(
  model: StructuredAppModel,
  fromIndex: number,
  toIndex: number,
): StructuredAppModel {
  const screens = [...model.screens].sort((a, b) => a.order - b.order);
  const [moved] = screens.splice(fromIndex, 1);
  if (!moved) return model;
  screens.splice(toIndex, 0, moved);
  return {
    ...model,
    screens: screens.map((s, i) => ({ ...s, order: i })),
    updatedAt: new Date().toISOString(),
    version: model.version + 1,
  };
}

export function reorderComponentsOnScreen(
  model: StructuredAppModel,
  screenId: string,
  fromIndex: number,
  toIndex: number,
): StructuredAppModel {
  const onScreen = model.components.filter((c) => c.screenId === screenId);
  const other = model.components.filter((c) => c.screenId !== screenId);
  const list = [...onScreen];
  const [moved] = list.splice(fromIndex, 1);
  if (!moved) return model;
  list.splice(toIndex, 0, moved);
  return {
    ...model,
    components: [...other, ...list],
    updatedAt: new Date().toISOString(),
    version: model.version + 1,
  };
}

export function listEditorComponentPalette(templateId: string) {
  return listComponentsForTemplate(templateId).map((c) => ({
    id: c.id,
    label: c.label,
    category: c.category,
    description: c.description,
  }));
}

export function applyEditorReorder(
  model: StructuredAppModel,
  state: VisualEditorState,
  parentId: string,
  fromIndex: number,
  toIndex: number,
): { model: StructuredAppModel; state: VisualEditorState } {
  const nextState = reorderChild(state, parentId, fromIndex, toIndex);
  if (!state.selectedScreenId) return { model, state: nextState };

  const parent = nextState.tree.find((n) => n.id === parentId);
  if (!parent) return { model, state: nextState };

  const order = parent.children.map((c) => c.id);
  const onScreen = model.components.filter((c) => c.screenId === state.selectedScreenId);
  const other = model.components.filter((c) => c.screenId !== state.selectedScreenId);
  const sorted = order
    .map((id) => onScreen.find((c) => c.id === id))
    .filter((c): c is (typeof onScreen)[0] => Boolean(c));

  return {
    model: {
      ...model,
      components: [...other, ...sorted],
      updatedAt: new Date().toISOString(),
      version: model.version + 1,
    },
    state: nextState,
  };
}

/**
 * Brand Studio platform health report.
 */

import { existsSync, readdirSync } from "node:fs";
import { join } from "node:path";

export type BrandStudioHealthReport = {
  status: "healthy" | "degraded";
  productId: string;
  version: string;
  checks: Array<{ id: string; ok: boolean; detail?: string }>;
};

const REQUIRED_MODULES = [
  "lib/ai-core/brand-studio/engine.ts",
  "lib/ai-core/brand-studio/model.ts",
  "lib/ai-core/brand-studio/logos.ts",
  "lib/ai-core/brand-studio/kit.ts",
  "lib/ai-core/brand-studio/templates.ts",
  "lib/ai-core/brand-studio/assistant.ts",
  "app/api/brand-identity/health/route.ts",
  "app/api/brand-identity/templates/route.ts",
  "app/api/brand-identity/stream/route.ts",
  "components/dashboard/brand-identity/brand-management-dashboard.tsx",
  "app/(dashboard)/dashboard/brand-studio/[id]/page.tsx",
];

export function buildBrandStudioHealthReport(root = process.cwd()): BrandStudioHealthReport {
  const checks = REQUIRED_MODULES.map((rel) => ({
    id: rel,
    ok: existsSync(join(root, rel)),
    detail: existsSync(join(root, rel)) ? "present" : "missing",
  }));

  const migrations = ["048", "049", "050", "051", "052"].map((n) => {
    const pattern = `supabase/migrations/${n}_`;
    const ok =
      existsSync(join(root, "supabase/migrations")) &&
      readdirSync(join(root, "supabase/migrations")).some((f) => f.startsWith(`${n}_`));
    return { id: `migration_${n}`, ok, detail: ok ? "present" : "missing" };
  });

  const all = [...checks, ...migrations];
  const ok = all.every((c) => c.ok);

  return {
    status: ok ? "healthy" : "degraded",
    productId: "brand-designer",
    version: "2.0.0",
    checks: all,
  };
}

/**
 * Convert between plugin output, AI Core brief, and canonical BrandIdentityModel.
 */

import type { BrandIdentityBrief } from "@/lib/ai-core/brand-identity/types";
import type {
  BrandAnalysis,
  BrandOutput,
  BrandPlanResult,
  BrandIdentityPluginInput,
} from "@/plugins/brand-identity/types";
