    logoDirection: {
      style: plan?.brandArchetype || "Modern wordmark",
      iconConcept: "",
      symbolism: [],
      usageGuidelines: output.logoGuidelines
        ? output.logoGuidelines.split("\n").filter((l) => l.trim().startsWith("-"))
