    return {
      ...pack,
      heroEyebrow: "",
      brandTagline: "",
      servicesEyebrow: "",
      servicesTitle: "",
      servicesSubtitle: "",
      services: [],
      featuresEyebrow: "",
      featuresTitle: "",
      featuresSubtitle: "",
      features: [],
      testimonialsEyebrow: "",
      testimonialsTitle: "",
      testimonialsSubtitle: "",
      testimonials: [],
      faqEyebrow: "",
      faqTitle: "",
      faqSubtitle: "",
      faqs: [],
      pricingEyebrow: "",
      pricingTitle: "",
      pricingSubtitle: "",
      pricing: [],
      galleryEyebrow: "",
      galleryTitle: "",
      gallerySubtitle: "",
      galleryItems: [],
      ctaEyebrow: "",
      ctaTitle: "",
      ctaBody: "",
      contactTitle: "",
      contactSubtitle: "",
