import assert from "node:assert/strict";
import { describe, it, before, after } from "node:test";
import type { PlannedFile } from "@/lib/ai/planner";
import type { GeneratedProjectFile } from "@/lib/ai/types";
import {
  buildImportGraphEdges,
  collectDirectImportDeps,
  collectUpstreamDeps,
  resolvePromptContext,
  resolveSmartContextFiles,
} from "@/lib/ai-core/context-engine";
import { buildStructuralContextGraph } from "@/lib/ai-core/context-engine/graphs";

function planned(path: string, category: PlannedFile["category"]): PlannedFile {
  return { path, purpose: path, language: "tsx", category };
}

function file(
  path: string,
  content: string,
  language = "tsx",
): GeneratedProjectFile {
  return { path, content, language };
}

const layout = file("app/layout.tsx", "export default function Layout() {}");
const sectionShell = file(
  "components/ui/section-shell.tsx",
  "export function SectionShell() {}",
);
const motion = file("components/ui/motion.tsx", "export function Motion() {}");
const hero = file(
  "components/sections/HeroLuxury.tsx",
  `import { Motion } from "@/components/ui/motion";\nexport function HeroLuxury() {}`,
);
const services = file(
  "components/sections/ServicesModern.tsx",
  `import { SectionShell } from "@/components/ui/section-shell";\nexport function ServicesModern() {}`,
);
const homePage = file(
  "app/page.tsx",
  `import { HeroLuxury } from "@/components/sections/HeroLuxury";\nimport { ServicesModern } from "@/components/sections/ServicesModern";\nexport default function Page() {}`,
);
const unrelated = file("lib/utils.ts", "export const x = 1;");

const filePlans: PlannedFile[] = [
  planned(layout.path, "layout"),
  planned(sectionShell.path, "components"),
  planned(motion.path, "components"),
  planned(hero.path, "components"),
  planned(services.path, "components"),
  planned(homePage.path, "pages"),
  planned(unrelated.path, "lib"),
];

const allFiles = [layout, sectionShell, motion, hero, services, homePage, unrelated];

describe("context-engine import graph", () => {
  it("detects import edges between project files", () => {
    const edges = buildImportGraphEdges(allFiles);
    assert.ok(
      edges.some(
        (edge) =>
          edge.from === motion.path && edge.to === hero.path && edge.graph === "import",
      ),
    );
  });

  it("collects direct import deps for a section", () => {
    const deps = collectDirectImportDeps(hero.path, allFiles);
    assert.ok(deps.has(motion.path));
  });
});

describe("context-engine structural graph", () => {
  it("includes upstream deps for home page", () => {
    const edges = buildStructuralContextGraph(filePlans);
    const upstream = collectUpstreamDeps(homePage.path, edges);
    assert.ok(upstream.has(hero.path));
    assert.ok(upstream.has(services.path));
  });
});

describe("context-engine resolver", () => {
  const originalEnv = process.env.WB_SMART_CONTEXT;

  after(() => {
    if (originalEnv === undefined) {
      delete process.env.WB_SMART_CONTEXT;
    } else {
      process.env.WB_SMART_CONTEXT = originalEnv;
    }
  });

  it("returns all files when smart context is disabled", () => {
    process.env.WB_SMART_CONTEXT = "0";
    const result = resolveSmartContextFiles({
      targetPath: hero.path,
      targetCategory: "components",
      availableFiles: allFiles,
      filePlans,
    });
    assert.equal(result.files.length, allFiles.length);
    assert.equal(result.stats.filesPruned, 0);
  });

  it("prunes unrelated files when smart context is enabled", () => {
    process.env.WB_SMART_CONTEXT = "1";
    const result = resolveSmartContextFiles({
      targetPath: hero.path,
      targetCategory: "components",
      availableFiles: allFiles,
      filePlans,
    });
    assert.ok(!result.files.some((entry) => entry.path === unrelated.path));
    assert.ok(result.files.some((entry) => entry.path === motion.path));
    assert.ok(result.stats.filesPruned > 0);
  });

  it("includes all sections for home page compose context", () => {
    process.env.WB_SMART_CONTEXT = "1";
    const result = resolveSmartContextFiles({
      targetPath: homePage.path,
      targetCategory: "pages",
      availableFiles: allFiles,
      filePlans,
      composeHomePage: true,
    });
    assert.ok(result.files.some((entry) => entry.path === hero.path));
    assert.ok(result.files.some((entry) => entry.path === services.path));
    assert.ok(result.files.some((entry) => entry.path === layout.path));
  });

  it("produces deterministic output across runs", () => {
    process.env.WB_SMART_CONTEXT = "1";
    const options = {
      targetPath: hero.path,
      targetCategory: "components" as const,
      availableFiles: allFiles,
      filePlans,
    };
    const first = resolveSmartContextFiles(options);
    const second = resolveSmartContextFiles(options);
    assert.deepEqual(
      first.files.map((entry) => entry.path),
      second.files.map((entry) => entry.path),
    );
  });

  it("resolvePromptContext maps truncated prompt files", () => {
    process.env.WB_SMART_CONTEXT = "1";
    const longContent = "x".repeat(5000);
    const heavy = file("components/sections/Heavy.tsx", longContent);
    const result = resolvePromptContext({
      targetPath: heavy.path,
      targetCategory: "components",
      availableFiles: [...allFiles, heavy],
      filePlans: [...filePlans, planned(heavy.path, "components")],
      charLimitPerFile: 100,
    });
    assert.ok(result.promptFiles.every((entry) => entry.content.length <= 150));
  });
});

import { applyBrandIdentityToDesignPlan } from "@/lib/ai-core/brand-identity/apply";
import { runBrandIdentityIntelligence } from "@/lib/ai-core/brand-identity/engine";
import type { BrandIdentityBrief } from "@/lib/ai-core/brand-identity/types";
import {
  runDesignIntelligenceEngine,
  type RunDesignIntelligenceEngineParams,
} from "@/lib/ai-core/design-intelligence/die-engine";
import {
  DESIGN_INTELLIGENCE_SPEC_KEY,
  DESIGN_INTELLIGENCE_TRACE_KEY,
  type DesignIntelligenceEngineResult,
} from "@/lib/ai-core/design-intelligence/die-types";
import {
  getWorkflowStateFromBrief,
  superviseAgentSync,
} from "@/lib/ai-core/multi-agent-orchestration";
import { buildVisualDesignPlan } from "@/lib/ai-core/design-plan/build";
import type { VisualDesignPlan } from "@/lib/ai-core/design-plan/types";
import type {
  CoreBrief,
  CoreBusinessProfile,
  CoreProductStrategy,
} from "@/lib/ai-core/layers/types";
import type { TemplateDNAProfile } from "@/lib/ai-core/template-intelligence/template-dna";
import type { MasterWebsitePlan } from "@/lib/ai-core/master-planner/types";
import type { WebsiteGenerationPlan } from "@/lib/ai-core/architecture-validation/types";
import type { BusinessIntelligenceProfile } from "@/lib/ai-core/business-intelligence/types";

export type RunDesignPlanningPhaseParams = {
  profile?: CoreBusinessProfile | null;
  strategy?: CoreProductStrategy | null;
  industryId?: string | null;
  theme?: string | null;
  designStyle?: string | null;
  preferredStyle?: string | null;
  prompt?: string | null;
  templateDna?: TemplateDNAProfile | null;
  masterPlan?: MasterWebsitePlan | null;
  websiteGenerationPlan?: WebsiteGenerationPlan | null;
  businessProfile?: BusinessIntelligenceProfile | null;
  brief?: CoreBrief | null;
  onProgress?: (message: string) => void;
};

export type DesignPlanningPhaseResult = {
  plan: VisualDesignPlan;
  brandIdentity: BrandIdentityBrief;
  designIntelligence: DesignIntelligenceEngineResult;
};

/**
 * Design Planning Phase — runs BEFORE code generation.
 * 1) Brand Identity Intelligence (complete brand system)
 * 2) Design Intelligence (layout + premium style)
 * 3) Visual Design Plan (approved) seeded by brand identity
 */
export function runDesignPlanningPhase(
  params: RunDesignPlanningPhaseParams,
): VisualDesignPlan {
  return runDesignPlanningPhaseWithBrand(params).plan;
}

/** Full planning result including brand identity for adapters. */
export function runDesignPlanningPhaseWithBrand(
  params: RunDesignPlanningPhaseParams,
): DesignPlanningPhaseResult {
  params.onProgress?.(
    "Design Planning Phase: Brand Identity → Design Intelligence → Visual Plan…",
  );

  const brandIdentity = runBrandIdentityIntelligence({
    profile: params.profile,
    strategy: params.strategy,
    industryId: params.industryId,
    theme: params.theme,
    preferredStyle: params.preferredStyle || params.designStyle,
    onProgress: params.onProgress,
  });

  const dieParams = {
    profile: params.profile,
    strategy: params.strategy,
    industryId: params.industryId,
    theme: params.theme,
    designStyle: params.designStyle || brandIdentity.strategy.visualDirection,
    preferredStyle:
      params.preferredStyle ||
      brandIdentity.premiumStyleId ||
      brandIdentity.presetId,
    templateDna: params.templateDna,
    masterPlan: params.masterPlan,
    websiteGenerationPlan: params.websiteGenerationPlan,
    businessProfile: params.businessProfile,
    prompt: params.prompt,
    onProgress: params.onProgress,
  };

  let dieResult: DesignIntelligenceEngineResult;
  if (params.brief && getWorkflowStateFromBrief(params.brief)) {
    const supervised = superviseAgentSync({
      agentId: "DIE",
      brief: params.brief,
      relaxedDependencies: true,
      onProgress: params.onProgress,
      executor: () => runDesignIntelligenceEngine(dieParams),
      updateBrief: (result, currentBrief) => ({
        ...currentBrief,
        metadata: {
          ...(currentBrief.metadata ?? {}),
          [DESIGN_INTELLIGENCE_TRACE_KEY]: result.trace,
          [DESIGN_INTELLIGENCE_SPEC_KEY]: result.spec,
          designIntelligenceValidation: result.validation,
        },
      }),
      shareArtifacts: (result) => ({
        designSystemSpec: result.spec,
      }),
    });
    dieResult = supervised.result;
  } else {
    dieResult = runDesignIntelligenceEngine(dieParams);
  }

  const mergedIntelligence = {
    ...dieResult.intelligence,
    premiumStyleId:
      brandIdentity.premiumStyleId || dieResult.intelligence.premiumStyleId,
    enginePreset:
      brandIdentity.enginePreset || dieResult.intelligence.enginePreset,
    imageStyle:
      brandIdentity.imageDirection || dieResult.intelligence.imageStyle,
    animationDirection:
      brandIdentity.animationDirection ||
      dieResult.intelligence.animationDirection,
    componentStyle:
      brandIdentity.componentStyle || dieResult.intelligence.componentStyle,
    colorDirection:
      brandIdentity.colors.direction || dieResult.intelligence.colorDirection,
    typographyDirection:
      brandIdentity.typography.direction ||
      dieResult.intelligence.typographyDirection,
    spacingDirection:
      brandIdentity.spacing.notes || dieResult.intelligence.spacingDirection,
    artDirectionNotes: [
      ...brandIdentity.artDirectionNotes,
      ...dieResult.intelligence.artDirectionNotes,
    ].slice(0, 16),
  };

  let plan = buildVisualDesignPlan({
    intelligence: mergedIntelligence,
    profile: params.profile,
    strategy: params.strategy,
    industryId: params.industryId,
    prompt: params.prompt,
    brandIdentity,
    templateDna: params.templateDna,
    designSpec: dieResult.spec,
  });

  plan = applyBrandIdentityToDesignPlan(plan, brandIdentity);

  if (plan.status !== "approved") {
    plan.status = "approved";
    plan.approvedAt = new Date().toISOString();
  }

  params.onProgress?.(
    `[design-plan] APPROVED · brand=${brandIdentity.presetId} · ${plan.visualIdentity} · ${plan.websiteStyle.heroTreatment} · ${plan.sectionStructure.length} sections`,
  );
  params.onProgress?.(plan.summary);

  return { plan, brandIdentity, designIntelligence: dieResult };
}

export function assertDesignPlanApproved(
  plan: VisualDesignPlan | null | undefined,
): VisualDesignPlan {
  if (!plan || plan.status !== "approved") {
    throw new Error(
      "Website generation blocked: Design Planning Phase must approve a VisualDesignPlan before writing code.",
    );
  }
  return plan;
}

import { performance } from "node:perf_hooks";
import type { PlannedFile } from "@/lib/ai/planner";
import type { GeneratedProjectFile } from "@/lib/ai/types";
import {
  COMPONENTS_WAVE_NAME,
  isComponentsSectionsPath,
} from "@/lib/ai-core/file-generation/constants";
import {
  createContextSnapshot,
  mergeSnapshotFile,
  resolveTaskContextFiles,
  snapshotFilesForTask,
  type ContextSnapshot,
} from "@/lib/ai-core/file-generation/context-snapshot";
import { runBoundedWorkerPool } from "@/lib/ai-core/file-generation/worker-pool";
import type {
  FileGenerationSchedulerOptions,
  FileGenerationSchedulerResult,
  FileGenerationTask,
  FileGenerationWave,
  FileTaskExecutionContext,
} from "@/lib/ai-core/file-generation/types";

type WaveGroup = {
  wave: FileGenerationWave;
  tasks: FileGenerationTask[];
};

type RunState = {
  snapshot: ContextSnapshot;
  workingFiles: GeneratedProjectFile[];
  completedWaves: string[];
  completedPaths: string[];
  failedPaths: Array<{ path: string; error: string }>;
  stats: FileGenerationSchedulerResult["stats"];
};

function groupTasksByWave(
  executionOrder: FileGenerationTask[],
  waveById: Map<string, FileGenerationWave>,
): WaveGroup[] {
  const groups: WaveGroup[] = [];

  for (const task of executionOrder) {
    const wave = waveById.get(task.waveId);
    if (!wave) {
      throw new Error(`Wave scheduler missing wave definition: ${task.waveId}`);
    }

    const last = groups[groups.length - 1];
    if (last && last.wave.id === wave.id) {
      last.tasks.push(task);
      continue;
    }

    groups.push({ wave, tasks: [task] });
  }

  return groups;
}

function applyTaskResult(
  state: RunState,
  task: FileGenerationTask,
  result: GeneratedProjectFile | null,
  options: FileGenerationSchedulerOptions,
): void {
  state.stats.tasksExecuted += 1;
  if (task.kind === "llm") {
    state.stats.llmTasks += 1;
  }

  if (result) {
    state.workingFiles = state.workingFiles.filter(
      (file) => file.path !== result.path,
    );
    state.workingFiles.push(result);
    state.snapshot = mergeSnapshotFile(state.snapshot, result);
    state.completedPaths.push(result.path);
    options.onTaskComplete?.(task, result, [...state.workingFiles]);
  } else {
    state.stats.tasksSkipped += 1;
    options.onTaskComplete?.(task, null, [...state.workingFiles]);
  }
}

async function executeSingleTask(
  options: FileGenerationSchedulerOptions,
  state: RunState,
  task: FileGenerationTask,
  wave: FileGenerationWave,
  taskIndex: number,
  totalTasks: number,
  waveEntrySnapshot: ContextSnapshot,
): Promise<GeneratedProjectFile | null> {
  const contextFiles = snapshotFilesForTask(
    waveEntrySnapshot,
    state.workingFiles,
    task.contextPolicy,
  );

  const resolvedContextFiles = options.filePlans
    ? resolveTaskContextFiles({
        targetPath: task.path,
        targetCategory: task.plannedFile.category,
        contextFiles,
        filePlans: options.filePlans,
        dependsOn: task.dependsOn,
        contextPolicy: task.contextPolicy,
        composeHomePage: options.composeHomePage,
      })
    : contextFiles;

  const executionContext: FileTaskExecutionContext = {
    waveId: wave.id,
    task,
    snapshotFiles: waveEntrySnapshot.files,
    contextFiles: resolvedContextFiles,
    workingFiles: [...state.workingFiles],
    taskIndex,
    totalTasks,
  };

  const run = () => options.executeTask(executionContext);

  if (task.kind === "llm" && options.llmGate) {
    return options.llmGate.run(run);
  }

  return run();
}

async function runWaveSerial(
  options: FileGenerationSchedulerOptions,
  state: RunState,
  wave: FileGenerationWave,
  tasks: FileGenerationTask[],
): Promise<void> {
  const totalTasks = tasks.length;

  for (let index = 0; index < tasks.length; index += 1) {
    const task = tasks[index]!;
    try {
      const result = await executeSingleTask(
        options,
        state,
        task,
        wave,
        index + 1,
        totalTasks,
        state.snapshot,
      );
      applyTaskResult(state, task, result, options);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      state.failedPaths.push({ path: task.path, error: message });
      throw error;
    }
  }
}

async function runComponentsWave(
  options: FileGenerationSchedulerOptions,
  state: RunState,
  wave: FileGenerationWave,
  tasks: FileGenerationTask[],
): Promise<void> {
  const totalTasks = tasks.length;
  let taskIndex = 0;
  let parallelBatch: FileGenerationTask[] = [];

  const flushParallelBatch = async () => {
    if (parallelBatch.length === 0) return;

    const batch = [...parallelBatch].sort((a, b) =>
      a.path.localeCompare(b.path),
    );
    parallelBatch = [];
    const batchSnapshot = state.snapshot;

    const concurrency = Math.min(wave.maxConcurrency, batch.length);

    const results = await runBoundedWorkerPool({
      items: batch,
      concurrency,
      worker: async (task) => {
        const result = await executeSingleTask(
          options,
          state,
          task,
          wave,
          tasks.indexOf(task) + 1,
          totalTasks,
          batchSnapshot,
        );
        return { task, result };
      },
    });

    for (const entry of results.sort((a, b) =>
      a.task.path.localeCompare(b.task.path),
    )) {
      applyTaskResult(state, entry.task, entry.result, options);
    }
  };

  for (const task of tasks) {
    taskIndex += 1;

    const canParallelize =
      wave.name === COMPONENTS_WAVE_NAME &&
      isComponentsSectionsPath(task.path) &&
      wave.maxConcurrency > 1;

    if (canParallelize) {
      parallelBatch.push(task);
      continue;
    }

    await flushParallelBatch();

    try {
      const result = await executeSingleTask(
        options,
        state,
        task,
        wave,
        taskIndex,
        totalTasks,
        state.snapshot,
      );
      applyTaskResult(state, task, result, options);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      state.failedPaths.push({ path: task.path, error: message });
      throw error;
    }
  }

  await flushParallelBatch();
}

function shouldRunComponentsWaveParallel(wave: FileGenerationWave): boolean {
  return wave.name === COMPONENTS_WAVE_NAME && wave.maxConcurrency > 1;
}

/**
 * Execute a wave plan.
 * Phase 2.2: parallel bounded pool for components/sections/* only; all other waves serial.
 */
export async function runFileGenerationScheduler(
  options: FileGenerationSchedulerOptions,
): Promise<FileGenerationSchedulerResult> {
  const started = performance.now();
  const state: RunState = {
    snapshot: createContextSnapshot(options.initialFiles),
    workingFiles: [...options.initialFiles],
    completedWaves: [],
    completedPaths: [],
    failedPaths: [],
    stats: {
      wavesExecuted: 0,
      tasksExecuted: 0,
      tasksSkipped: 0,
      llmTasks: 0,
      totalDurationMs: 0,
    },
  };

  const waveById = new Map(
    options.wavePlan.waves.map((wave) => [wave.id, wave]),
  );

  const waveGroups = groupTasksByWave(
    options.wavePlan.executionOrder,
    waveById,
  );

  for (const { wave, tasks } of waveGroups) {
    options.onWaveStart?.(wave);

    if (shouldRunComponentsWaveParallel(wave)) {
      await runComponentsWave(options, state, wave, tasks);
    } else {
      await runWaveSerial(options, state, wave, tasks);
    }

    state.completedWaves.push(wave.id);
    state.stats.wavesExecuted += 1;
    options.onWaveComplete?.(wave, [...state.workingFiles]);
  }

  state.stats.totalDurationMs = Math.round(performance.now() - started);

  return {
    files: state.workingFiles,
    completedWaves: state.completedWaves,
    completedPaths: state.completedPaths,
    failedPaths: state.failedPaths,
    stats: state.stats,
  };
}

import type { PlannedFile } from "@/lib/ai/planner";
import {
  buildFileDependencyGraph,
  type WebsiteDependencyGraphOptions,
} from "@/lib/ai-core/file-generation/dependency-graph";
import {
  COMPONENTS_SECTIONS_PREFIX,
  COMPONENTS_WAVE_NAME,
} from "@/lib/ai-core/file-generation/constants";
import {
  fileGenerationFlags,
  resolveLlmConcurrencyCap,
} from "@/lib/ai-core/file-generation/flags";
import type {
  BuildWavePlanOptions,
  FileGenerationTask,
  FileGenerationWave,
  FileGenerationWavePlan,
  FileTaskKind,
} from "@/lib/ai-core/file-generation/types";

function resolveWaveName(
  plannedFile: PlannedFile,
  depth: number,
  kind: FileTaskKind,
): string {
  if (kind === "scaffold") return "static-scaffold";
  switch (plannedFile.category) {
    case "layout":
    case "lib":
    case "types":
      return "foundation";
    case "hooks":
      return "hooks-api";
    case "components":
      return COMPONENTS_WAVE_NAME;
    case "pages":
      return "pages";
    case "api":
      return "hooks-api";
    default:
      return depth <= 1 ? "foundation" : "configs-tail";
  }
}

const WAVE_EXECUTION_ORDER = [
  "static-scaffold",
  "foundation",
  COMPONENTS_WAVE_NAME,
  "hooks-api",
  "pages",
  "configs-tail",
] as const;

function waveIndexForName(name: string): number {
  const index = WAVE_EXECUTION_ORDER.indexOf(
    name as (typeof WAVE_EXECUTION_ORDER)[number],
  );
  return index === -1 ? WAVE_EXECUTION_ORDER.length : index;
}

function resolveContextPolicy(
  plannedFile: PlannedFile,
  strictSerialContext: boolean,
): "snapshot" | "strict-serial" {
  if (strictSerialContext) return "strict-serial";
  if (plannedFile.path.startsWith(COMPONENTS_SECTIONS_PREFIX)) {
    return "snapshot";
  }
  return "strict-serial";
}

function checkpointForWave(name: string, hasLlmTask: boolean): FileGenerationWave["checkpoint"] {
  if (name === "static-scaffold") return "none";
  if (hasLlmTask) return "per-task";
  return "end";
}

function resolveWaveConcurrency(
  waveName: string,
  profile: string,
  adapter: BuildWavePlanOptions["adapter"],
): number {
  if (waveName !== COMPONENTS_WAVE_NAME) {
    return 1;
  }
  const profileCap = adapter.waveConcurrencyForProfile(profile, waveName);
  const globalCap = resolveLlmConcurrencyCap();
  return Math.min(profileCap, globalCap);
}

/**
 * Assign each planned file to a wave using longest-path depth + task kind.
 */
export function buildFileGenerationWavePlan(
  options: BuildWavePlanOptions,
  graphOptions: WebsiteDependencyGraphOptions = {},
): FileGenerationWavePlan {
  const {
    filePlans,
    adapter,
    kindContext,
    strictSerialContext = fileGenerationFlags.strictSerialContext,
    maxGlobalConcurrency = resolveLlmConcurrencyCap(),
  } = options;

  const graph = buildFileDependencyGraph(filePlans, {
    composeHomePage: kindContext.composeHomePage,
    extraEdges: adapter.buildDependencyEdges(filePlans, kindContext),
  });

  const taskByPath = new Map<string, FileGenerationTask>();

  for (const plannedFile of filePlans) {
    const kind = adapter.resolveTaskKind(plannedFile, kindContext);
    const depth = graph.depthByPath.get(plannedFile.path) ?? 0;
    const waveName = resolveWaveName(plannedFile, depth, kind);
    const dependsOn = graph.edges
      .filter((edge) => edge.to === plannedFile.path)
      .map((edge) => edge.from)
      .sort((a, b) => a.localeCompare(b));

    const task: FileGenerationTask = {
      id: plannedFile.path,
      path: plannedFile.path,
      waveId: `W${waveIndexForName(waveName)}-${waveName}`,
      kind,
      plannedFile,
      dependsOn,
      contextPolicy: resolveContextPolicy(plannedFile, strictSerialContext),
    };
    taskByPath.set(plannedFile.path, task);
  }

  const waveBuckets = new Map<string, FileGenerationTask[]>();
  for (const task of taskByPath.values()) {
    const bucket = waveBuckets.get(task.waveId) ?? [];
    bucket.push(task);
    waveBuckets.set(task.waveId, bucket);
  }

  const waves: FileGenerationWave[] = [...waveBuckets.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([waveId, tasks], index) => {
      const sortedTasks = [...tasks].sort((a, b) =>
        a.path.localeCompare(b.path),
      );
      const waveName = sortedTasks[0]?.waveId.split("-").slice(1).join("-") ?? "unknown";
      const hasLlmTask = sortedTasks.some((task) => task.kind === "llm");
      return {
        id: waveId,
        index,
        name: waveName,
        tasks: sortedTasks,
        maxConcurrency: resolveWaveConcurrency(
          waveName,
          kindContext.generationProfile,
          adapter,
        ),
        checkpoint: checkpointForWave(waveName, hasLlmTask),
      };
    });

  const executionOrder = filePlans.map((plannedFile) => {
    const task = taskByPath.get(plannedFile.path);
    if (!task) {
      throw new Error(`Wave planner missing task for ${plannedFile.path}`);
    }
    return task;
  });

  return {
    waves,
    executionOrder,
    strictSerialContext,
    maxGlobalConcurrency,
    taskByPath,
  };
}

/** Flatten wave plan tasks in deterministic serial order (matches category sort). */
export function flattenWavePlanTasks(wavePlan: FileGenerationWavePlan): FileGenerationTask[] {
  return wavePlan.waves.flatMap((wave) => wave.tasks);
}

/** Verify wave plan preserves original file plan order when executed serially. */
export function assertWavePlanCoversFiles(
  filePlans: PlannedFile[],
  wavePlan: FileGenerationWavePlan,
): void {
  if (filePlans.length !== wavePlan.executionOrder.length) {
    throw new Error(
      `Wave plan path count mismatch: ${filePlans.length} planned vs ${wavePlan.executionOrder.length} execution tasks`,
    );
  }

  for (let i = 0; i < filePlans.length; i += 1) {
    const plannedPath = filePlans[i]!.path;
    const taskPath = wavePlan.executionOrder[i]?.path;
    if (plannedPath !== taskPath) {
      throw new Error(
        `Wave execution order mismatch at index ${i}: expected ${plannedPath}, got ${taskPath ?? "none"}`,
      );
    }
  }
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import {
  TBGE2_PHASE,
  TBGE2_SPEC_VERSION,
  analyzeIntent,
  analyzeBusiness,
  analyzeRequirements,
  planWebsite,
  planPages,
  planSections,
  planContent,
  buildLlmRequest,
  planToStructuredOutput,
  containsForbiddenMarkup,
  isStructuredPlan,
  runTbge2PlanningPipeline,
  validatePlanningInput,
  validatePlanningPlan,
  bridgeToTbgePlanDraft,
  bridgeFromWebsiteGenerationInput,
  enrichPlanWithGls,
  TBGE2_PLANNING_LIFECYCLE,
  TBGE2_INTENT_PATTERNS,
  TBGE2_REQUIREMENT_PATTERNS,
} from "@/lib/ai-core/generation-engine";

describe("TBGE2 Generation Engine — Phase 1", () => {
  it("exports phase constants", () => {
    assert.equal(TBGE2_PHASE, "planning-1");
    assert.equal(TBGE2_SPEC_VERSION, "2.0.0");
  });

  it("defines full planning lifecycle", () => {
    assert.equal(TBGE2_PLANNING_LIFECYCLE.length, 10);
    const llmStages = TBGE2_PLANNING_LIFECYCLE.filter((p) => p.usesLlm);
    assert.equal(llmStages.length, 1);
    assert.equal(llmStages[0]?.stage, "structured_output");
  });

  it("registers intent patterns", () => {
    assert.ok(TBGE2_INTENT_PATTERNS.length >= 10);
    assert.ok(TBGE2_INTENT_PATTERNS.some((p) => p.category === "restaurant"));
    assert.ok(TBGE2_INTENT_PATTERNS.some((p) => p.category === "saas"));
  });

  it("registers requirement patterns", () => {
    assert.ok(TBGE2_REQUIREMENT_PATTERNS.length >= 15);
    assert.ok(TBGE2_REQUIREMENT_PATTERNS.some((p) => p.id === "booking"));
    assert.ok(TBGE2_REQUIREMENT_PATTERNS.some((p) => p.id === "payments"));
  });

  it("analyzes restaurant intent from prompt", () => {
    const intent = analyzeIntent({
      userPrompt: "Create a modern restaurant website with online booking and menu",
    });
    assert.equal(intent.category, "restaurant");
    assert.ok(intent.confidence > 0.5);
    assert.equal(intent.source, "keyword");
  });

  it("analyzes SaaS business from prompt", () => {
    const intent = analyzeIntent({ userPrompt: "Build a B2B SaaS platform website with pricing" });
    const business = analyzeBusiness({ userPrompt: "Build a B2B SaaS platform website with pricing" }, intent);
    assert.equal(intent.category, "saas");
    assert.equal(business.industryId, "saas");
    assert.ok(business.audience.length > 0);
  });

  it("detects requirements from prompt", () => {
    const intent = analyzeIntent({ userPrompt: "Medical clinic with booking and FAQ" });
    const reqs = analyzeRequirements({ userPrompt: "Medical clinic with booking and FAQ" }, intent);
    assert.ok(reqs.required.includes("booking"));
    assert.ok(reqs.required.includes("faq"));
    assert.ok(reqs.required.includes("contact"));
  });

  it("plans website with navigation and CTAs", () => {
    const intent = analyzeIntent({ userPrompt: "SaaS startup website" });
    const business = analyzeBusiness({ userPrompt: "SaaS startup website" }, intent);
    const reqs = analyzeRequirements({ userPrompt: "SaaS startup website" }, intent);
    const website = planWebsite(intent, business, reqs);
    assert.equal(website.websiteType, "saas");
    assert.ok(website.navigation.length >= 3);
    assert.ok(website.primaryCta.length > 0);
  });

  it("plans pages and sections for restaurant", () => {
    const intent = analyzeIntent({ userPrompt: "Italian restaurant in Dubai" });
    const reqs = analyzeRequirements({ userPrompt: "Italian restaurant in Dubai" }, intent);
    const website = planWebsite(intent, analyzeBusiness({ userPrompt: "Italian restaurant in Dubai" }, intent), reqs);
    const pages = planPages(intent, reqs, website.primaryCta);
    const sections = planSections(pages, intent, reqs);
    assert.ok(pages.some((p) => p.kind === "menu"));
    assert.ok(sections.some((s) => s.type === "hero"));
    assert.ok(sections.some((s) => s.type === "footer"));
  });

  it("plans content blocks with tone and localization", () => {
    const intent = analyzeIntent({ userPrompt: "Luxury hotel website", language: "Arabic" });
    const business = analyzeBusiness({ userPrompt: "Luxury hotel website", language: "Arabic" }, intent);
    const reqs = analyzeRequirements({ userPrompt: "Luxury hotel website", language: "Arabic" }, intent);
    const website = planWebsite(intent, business, reqs);
    const pages = planPages(intent, reqs, website.primaryCta);
    const sections = planSections(pages, intent, reqs);
    const content = planContent(sections, business, reqs);
    assert.ok(content.blocks.length > 0);
    assert.equal(content.localizationStrategy, "rtl-aware");
  });

  it("runs full planning pipeline without LLM", async () => {
    const result = await runTbge2PlanningPipeline({
      userPrompt: "Create a portfolio website for a creative agency in London",
    });
    assert.equal(result.ok, true);
    if (!result.ok) return;
    assert.ok(result.plan.pages.length >= 3);
    assert.ok(result.plan.sections.length >= 5);
    assert.ok(result.meta.planHash.length === 16);
    assert.ok(result.meta.stagesCompleted.includes("content"));
    assert.ok(!result.meta.stagesCompleted.includes("structured_output"));
  });

  it("builds LLM request without raw user prompt", async () => {
    const result = await runTbge2PlanningPipeline({
      userPrompt: "Secret raw prompt that must not leak to LLM",
    });
    assert.equal(result.ok, true);
    if (!result.ok) return;
    assert.ok(!result.llmRequest.userPrompt.includes("Secret raw prompt"));
    assert.ok(result.llmRequest.systemPrompt.includes("JSON"));
    assert.ok(result.llmRequest.schema);
  });

  it("produces structured JSON output", async () => {
    const result = await runTbge2PlanningPipeline({
      userPrompt: "E-commerce store for handmade jewelry",
    });
    assert.equal(result.ok, true);
    if (!result.ok) return;
    const structured = planToStructuredOutput(result.plan);
    assert.equal(structured.version, "2.0.0");
    assert.ok(isStructuredPlan(structured));
  });

  it("rejects forbidden markup in LLM output", () => {
    assert.ok(containsForbiddenMarkup('<div className="hero">Hello</div>'));
    assert.ok(!containsForbiddenMarkup('{"version":"2.0.0"}'));
  });

  it("validates planning input and plan", async () => {
    const badInput = validatePlanningInput({ userPrompt: "" });
    assert.equal(badInput.valid, false);

    const result = await runTbge2PlanningPipeline({
      userPrompt: "Professional law firm website",
    });
    assert.equal(result.ok, true);
    if (!result.ok) return;
    const planValid = validatePlanningPlan(result.plan);
    assert.equal(planValid.valid, true);
  });

  it("bridges to TBGE v1 plan draft format", async () => {
    const result = await runTbge2PlanningPipeline({
      userPrompt: "Dental clinic with appointment booking",
    });
    assert.equal(result.ok, true);
    if (!result.ok) return;
    const draft = bridgeToTbgePlanDraft(result.plan);
    assert.ok(draft.business.name);
    assert.ok(draft.structure.pages.length > 0);
    assert.equal(draft.capabilities.auth, false);
  });

  it("bridges from website generation input", () => {
    const input = bridgeFromWebsiteGenerationInput({
      prompt: "Modern cafe website",
      language: "English",
      industry: "restaurant",
    });
    assert.equal(input.userPrompt, "Modern cafe website");
    assert.equal(input.industry, "restaurant");
  });

  it("enriches plan with GLS language context", async () => {
    const result = await runTbge2PlanningPipeline({
      userPrompt: "Arabic restaurant website",
      language: "Arabic",
    });
    assert.equal(result.ok, true);
    if (!result.ok) return;
    const enriched = enrichPlanWithGls(result.plan);
    assert.ok("language" in enriched);
    assert.equal((enriched as { language: { website: { direction: string } } }).language.website.direction, "rtl");
  });
});

import type { MasterPlanContentLlmRequest } from "@/lib/ai-core/generation-engine/master-plan/llm-request-builder";
import { validateMasterPlan } from "@/lib/ai-core/generation-engine/master-plan/validate";
import type { MasterPlan } from "@/lib/ai-core/generation-engine/master-plan/types";
import type { GeneratedWebsiteProject } from "@/lib/website/types";
import type {
  IntegrationValidationResult,
  MasterPlanIntegrationStage,
  StructuredContentResult,
} from "@/lib/ai-core/generation-engine/integration/types";

/** Before generation — validate Master Plan authority. */
export function validateBeforeGeneration(plan: MasterPlan): IntegrationValidationResult {
  const result = validateMasterPlan(plan);
  if (!result.valid) {
    return { valid: false, errors: result.errors, stage: "master_plan" };
  }
  return { valid: true };
}

/** Before LLM — validate content tasks are copy-only. */
export function validateContentTasks(
  request: MasterPlanContentLlmRequest,
): IntegrationValidationResult {
  const errors: string[] = [];

  if (!request.systemPrompt.includes("LOCKED Master Plan")) {
    errors.push("Content request must reference locked Master Plan");
  }
  if (!request.userPrompt.includes("copyTasks")) {
    errors.push("Content request must include copyTasks");
  }
  try {
    const parsed = JSON.parse(request.userPrompt) as { locked?: boolean };
    if (!parsed || typeof parsed !== "object") {
      errors.push("Content request userPrompt must be valid JSON");
    } else if (parsed.locked !== true) {
      errors.push("Content request must be locked to Master Plan");
    }
  } catch {
    errors.push("Content request userPrompt must be valid JSON");
  }

  return errors.length === 0
    ? { valid: true }
    : { valid: false, errors, stage: "content_tasks" };
}

/** After LLM — validate structured content response. */
export function validateStructuredContent(
  plan: MasterPlan,
  content: StructuredContentResult,
): IntegrationValidationResult {
  const errors: string[] = [];

  if (content.masterPlanId !== plan.id) {
    errors.push("Structured content masterPlanId mismatch");
  }
  if (!Array.isArray(content.content)) {
    errors.push("Structured content must include content array");
  }

  const blockIds = new Set(
    plan.sections.flatMap((s) => s.contentBlocks),
  );
  for (const item of content.content) {
    if (!blockIds.has(item.blockId)) {
      errors.push(`Unknown content block: ${item.blockId}`);
    }
    for (const value of Object.values(item.fields)) {
      if (typeof value !== "string") {
        errors.push(`Content field for ${item.blockId} must be string`);
      }
    }
  }

  return errors.length === 0
    ? { valid: true }
    : { valid: false, errors, stage: "structured_content" };
}

/** Before builder — validate required fields from Master Plan. */
export function validateBeforeBuilder(plan: MasterPlan): IntegrationValidationResult {
  const errors: string[] = [];

  if (!plan.pages.length) errors.push("Master Plan must have pages");
  if (!plan.sections.length) errors.push("Master Plan must have sections");
  if (!plan.navigation.length) errors.push("Master Plan must have navigation");
  if (!plan.ctaStrategy.primary) errors.push("Master Plan must have primary CTA");
  if (!plan.localization.language) errors.push("Master Plan must have language");

  return errors.length === 0
    ? { valid: true }
    : { valid: false, errors, stage: "builder" };
}

/** Before export — validate generated website has required artifacts. */
export function validateBeforeExport(
  project: Pick<GeneratedWebsiteProject, "pages" | "sections" | "files" | "title">,
): IntegrationValidationResult {
  const errors: string[] = [];

  if (!project.title?.trim()) errors.push("Project title required");
  if (!project.pages?.length) errors.push("Project pages required");
  if (!project.files?.length) errors.push("Project files required");

  return errors.length === 0
    ? { valid: true }
    : { valid: false, errors, stage: "export" };
}

export function assertIntegrationValid(
  result: IntegrationValidationResult,
  label: string,
): void {
  if (!result.valid) {
    throw new Error(
      `[master-plan-integration] ${label} failed at ${result.stage}: ${result.errors.join("; ")}`,
    );
  }
}

import { createHash, randomUUID } from "node:crypto";
import { resolveGlsWebsiteLocale } from "@/lib/language-platform";
import type { Tbge2PlanningInput, Tbge2PlanningPlan } from "@/lib/ai-core/generation-engine/core/types";
import { MASTER_PLAN_SCHEMA_VERSION } from "@/lib/ai-core/generation-engine/master-plan/constants";
import {
  buildAccessibilityTargets,
  buildContentStrategy,
  buildCtaStrategy,
  buildFutureExpansion,
  buildLegalPages,
  buildMediaStrategy,
  buildPerformanceTargets,
  buildSeoStrategy,
  buildTrustStrategy,
  resolveComponentForSection,
} from "@/lib/ai-core/generation-engine/master-plan/strategies";
import type {
  MasterPlan,
  MasterPlanComponent,
  MasterPlanInput,
  MasterPlanNavigationItem,
  MasterPlanPage,
  MasterPlanSection,
} from "@/lib/ai-core/generation-engine/master-plan/types";

function hashPrompt(prompt: string): string {
  return createHash("sha256").update(prompt).digest("hex").slice(0, 16);
}

/**
 * Master Plan Builder — converts TBGE2 analysis into the authoritative Master Plan.
 * All planning decisions are made here; LLMs never modify this output.
 */
export function buildMasterPlan(
  plan: Tbge2PlanningPlan,
  input: MasterPlanInput,
): MasterPlan {
  const locale = resolveGlsWebsiteLocale(plan.business.language);
  const projectId = randomUUID();
  const now = new Date().toISOString();

  const sections: MasterPlanSection[] = plan.sections.map((section) => ({
    ...section,
    componentId: resolveComponentForSection(section.type),
    contentBlocks: plan.content.blocks
      .filter((b) => b.sectionId === section.id)
      .map((b) => b.id),
  }));

  const pages: MasterPlanPage[] = plan.pages.map((page) => ({
    ...page,
    sections: sections
      .filter((s) => s.pageId === page.id)
      .sort((a, b) => a.order - b.order)
      .map((s) => s.id),
  }));

  const navigation: MasterPlanNavigationItem[] = plan.website.navigation.map((item, index) => ({
    ...item,
    order: index,
  }));

  const componentsNeeded: MasterPlanComponent[] = dedupeComponents(sections);

  return {
    id: projectId,
    version: 1,
    createdAt: now,
    schemaVersion: MASTER_PLAN_SCHEMA_VERSION,
    providerIndependent: true,

    project: {
      id: projectId,
      name: input.projectName ?? plan.business.businessName ?? `${plan.business.industry} Website`,
      productId: input.productId ?? "website-builder",
      sourcePromptHash: hashPrompt(input.userPrompt),
    },

    business: {
      name: plan.business.businessName ?? plan.business.industry,
      industry: plan.business.industry,
      industryId: plan.business.industryId,
      businessType: plan.business.businessType,
      offer: plan.business.offer,
      confidence: plan.business.confidence,
    },

    audience: plan.business.audience,
    goals: plan.business.goals,
    brand: {
      style: plan.business.brandStyle,
      tone: plan.content.tone,
      voice: plan.content.voice,
    },

    localization: {
      language: plan.business.language,
      country: plan.business.country,
      strategy: plan.content.localizationStrategy,
      direction: locale.dir,
      htmlLang: locale.htmlLang,
      localeCode: locale.localeCode,
    },

    websiteType: plan.website.websiteType,
    conversionStrategy: plan.website.conversionStrategy,

    pages,
    navigation,
    sections,
    componentsNeeded,
    businessFeatures: plan.requirements.required,

    seoStrategy: buildSeoStrategy(plan.intent, plan.business, plan.website, plan.requirements),
    contentStrategy: buildContentStrategy(plan.content),
    mediaStrategy: buildMediaStrategy(plan.intent, plan.requirements, plan.business.brandStyle),
    ctaStrategy: buildCtaStrategy(plan.website, plan),
    trustStrategy: buildTrustStrategy(plan.intent, plan.requirements),
    legalPages: buildLegalPages(plan.requirements),
    performanceTargets: buildPerformanceTargets(plan.website.websiteType),
    accessibilityTargets: buildAccessibilityTargets(),
    futureExpansion: buildFutureExpansion(),
  };
}

function dedupeComponents(sections: MasterPlanSection[]): MasterPlanComponent[] {
  const seen = new Set<string>();
  const components: MasterPlanComponent[] = [];

  for (const section of sections) {
    if (seen.has(section.componentId)) continue;
    seen.add(section.componentId);
    components.push({
      id: `component-${section.type}`,
      sectionType: section.type,
      componentPath: section.componentId,
      required: section.required,
    });
  }

  return components;
}

import type { MasterPlan, MasterPlanSection } from "@/lib/ai-core/generation-engine/master-plan/types";
import type {
  AwqeAccessibilitySpec,
  AwqeConversionSpec,
  AwqePerformanceSpec,
  AwqeSeoSpec,
  AwqeSpecPage,
  AwqeSpecSection,
} from "@/lib/ai-core/generation-engine/quality-engine/types";

export function optimizeSeo(
  plan: MasterPlan,
  sections: MasterPlanSection[],
): AwqeSeoSpec {
  const pageTitles: Record<string, string> = {};
  const headingHierarchy: Record<string, string[]> = {};

  for (const page of plan.pages) {
    const title = `${page.name} | ${plan.business.name}`;
    pageTitles[page.id] = title;
    headingHierarchy[page.id] = ["h1", "h2", "h3"];
  }

  const internalLinks = plan.navigation
    .filter((n) => n.href !== "/")
    .map((n) => ({
      from: plan.pages.find((p) => p.kind === "home")?.id ?? plan.pages[0]!.id,
      to: plan.pages.find((p) => p.path === n.href)?.id ?? "",
      label: n.label,
    }))
    .filter((l) => l.to);

  return {
    pageTitles,
    headingHierarchy,
    internalLinks,
    schemaRecommendations: plan.seoStrategy.structuredData,
    metadataRequirements: [
      "meta description per page",
      "canonical URL",
      "og:title",
      "og:description",
      plan.seoStrategy.hreflang ? "hreflang alternates" : "single-locale meta",
    ],
    targetKeywords: plan.seoStrategy.targetKeywords,
    contentDepthPolicy:
      plan.websiteType === "landing" ? "hero-focused" :
      plan.websiteType === "blog" ? "comprehensive" : "minimum-300-words-per-page",
  };
}

export function optimizeConversion(
  plan: MasterPlan,
  sections: MasterPlanSection[],
): AwqeConversionSpec {
  const ctaSections = sections.filter((s) => s.type === "cta" || s.type === "hero");
  const socialProof = sections.filter((s) =>
    s.type === "testimonials" || s.type === "trust-badges" || s.type === "stats",
  );

  return {
    primaryCta: plan.ctaStrategy.primary,
    secondaryCta: plan.ctaStrategy.secondary,
    leadCaptureSections: sections
      .filter((s) => s.type === "contact" || s.type === "newsletter")
      .map((s) => s.id),
    trustIndicators: socialProof.map((s) => s.id),
    urgencySignals: plan.websiteType === "ecommerce" || plan.websiteType === "saas"
      ? ["limited-time-offer", "free-trial"]
      : [],
    socialProofSections: sections.filter((s) => s.type === "testimonials").map((s) => s.id),
    ctaPlacements: ctaSections.map((s, i) => ({
      pageId: s.pageId,
      sectionId: s.id,
      priority: s.type === "hero" ? 1 : i + 2,
    })),
  };
}

export function optimizeAccessibility(
  plan: MasterPlan,
  sections: MasterPlanSection[],
): AwqeAccessibilitySpec {
  const headingStructure: Record<string, string[]> = {};
  for (const page of plan.pages) {
    const pageSections = sections.filter((s) => s.pageId === page.id).sort((a, b) => a.order - b.order);
    headingStructure[page.id] = pageSections.map((s, i) =>
      i === 0 ? "h1" : i < 3 ? "h2" : "h3",
    );
  }

  return {
    wcagLevel: plan.accessibilityTargets.wcagLevel,
    headingStructure,
    ariaRecommendations: sections.map((s) => ({
      sectionId: s.id,
      recommendation:
        s.type === "hero" ? "role=banner aria-label=Hero" :
        s.type === "footer" ? "role=contentinfo" :
        `aria-labelledby=${s.id}-heading`,
    })),
    contrastRequirements: {
      minimumRatio: plan.accessibilityTargets.colorContrastRatio,
      largeTextRatio: 3.0,
    },
    keyboardNavigationHints: [
      "Skip to main content link",
      "Focus visible on all interactive elements",
      plan.accessibilityTargets.keyboardNavigation ? "Tab order follows visual order" : "Verify tab order",
      plan.accessibilityTargets.reducedMotionSupport ? "Respect prefers-reduced-motion" : "Add reduced motion support",
    ],
  };
}

export function optimizePerformance(
  plan: MasterPlan,
  sections: MasterPlanSection[],
): AwqePerformanceSpec {
  const homePageId = plan.pages.find((p) => p.kind === "home")?.id ?? plan.pages[0]?.id;
  const homeSections = sections
    .filter((s) => s.pageId === homePageId)
    .sort((a, b) => a.order - b.order);

  const aboveTheFold = homeSections
    .filter((s) => s.order <= 1 || s.type === "hero")
    .map((s) => s.id);

  return {
    imageStrategy: plan.mediaStrategy.gallery ? "lazy-load-below-fold" : "eager-hero-only",
    lazyLoading: true,
    criticalContentSections: aboveTheFold,
    aboveTheFoldSections: aboveTheFold,
    targets: {
      lighthousePerformance: plan.performanceTargets.lighthousePerformance,
      firstContentfulPaintMs: plan.performanceTargets.firstContentfulPaintMs,
      largestContentfulPaintMs: plan.performanceTargets.largestContentfulPaintMs,
    },
  };
}

export function buildSpecPages(
  plan: MasterPlan,
  seo: AwqeSeoSpec,
): AwqeSpecPage[] {
  return plan.pages.map((page) => ({
    id: page.id,
    name: page.name,
    path: page.path,
    purpose: page.purpose,
    sections: page.sections,
    metaTitle: seo.pageTitles[page.id] ?? `${page.name} | ${plan.business.name}`,
    metaDescription: `${plan.business.offer ?? plan.business.industry} — ${page.purpose}`,
    headingHierarchy: seo.headingHierarchy[page.id] ?? ["h1", "h2"],
    internalLinks: seo.internalLinks
      .filter((l) => l.from === page.id || l.to === page.id)
      .map((l) => ({ label: l.label, href: plan.pages.find((p) => p.id === l.to)?.path ?? "/" })),
    contentDepth: page.seoPriority === "high" ? "deep" : page.seoPriority === "medium" ? "medium" : "shallow",
    seoPriority: page.seoPriority,
  }));
}

export function buildSpecSections(
  sections: MasterPlanSection[],
  performance: AwqePerformanceSpec,
  accessibility: AwqeAccessibilitySpec,
): AwqeSpecSection[] {
  return sections.map((section) => ({
    ...section,
    aboveTheFold: performance.aboveTheFoldSections.includes(section.id),
    ariaLabel: accessibility.ariaRecommendations.find((a) => a.sectionId === section.id)?.recommendation,
  }));
}

import type { ImageBlueprint } from "@/types/image-generation";
import type {
  BrandKitContext,
  ImageDesignModel,
  ImageRasterAsset,
} from "@/lib/ai-core/image-design-platform/types";
import type { ImageOutput, ImagePluginInput } from "@/plugins/image-generator/types";
import { mapAspectRatio, mapStylePreset } from "@/lib/ai-core/image-design-platform/providers";
import type { ImageQuality } from "@/lib/ai-core/assets/settings";

export function outputToModel(params: {
  output: ImageOutput;
  input: ImagePluginInput;
  rasterAssets?: ImageRasterAsset[];
  brand?: BrandKitContext;
  templateId?: string;
  quality?: ImageQuality;
  providerUsed?: string;
}): ImageDesignModel {
  const { output, input } = params;
  return {
    title: output.title,
    description: output.description,
    imageType: output.imageType,
    style: output.style,
    aspectRatio: input.aspectRatio,
    mood: input.mood,
    quality: params.quality ?? "standard",
    stylePreset: mapStylePreset(input.style),
    preferredProvider: undefined,
    negativePrompt: input.negativePrompt,
    concepts: output.concepts,
    rasterAssets: params.rasterAssets ?? [],
    colorDirection: output.colorDirection,
    moodBoard: output.moodBoard,
    promptLibrary: output.promptLibrary,
    files: output.files,
    brand: params.brand,
    templateId: params.templateId,
    qualityScore: 0,
    qualityIssues: [],
    providerUsed: params.providerUsed,
    generatedAt: new Date().toISOString(),
  };
}

export function modelToBlueprint(model: ImageDesignModel, prompt: string, negativePrompt: string): ImageBlueprint {
  return {
    title: model.title,
    description: model.description,
    imageType: model.imageType,
    style: model.style,
    concepts: model.concepts,
    colorDirection: model.colorDirection,
    moodBoard: model.moodBoard,
    promptLibrary: model.promptLibrary,
    files: model.files,
    prompt,
    negativePrompt,
    generatedAt: model.generatedAt,
    model,
    rasterAssets: model.rasterAssets,
    qualityScore: model.qualityScore,
    templateId: model.templateId,
    brand: model.brand,
    providerUsed: model.providerUsed,
  };
}

export function blueprintToModel(blueprint: ImageBlueprint): ImageDesignModel {
  if (blueprint.model) return blueprint.model;
  return outputToModel({
    output: {
      title: blueprint.title,
      description: blueprint.description,
      imageType: blueprint.imageType,
      style: blueprint.style,
      concepts: blueprint.concepts,
      colorDirection: blueprint.colorDirection,
      moodBoard: blueprint.moodBoard,
      promptLibrary: blueprint.promptLibrary,
      files: blueprint.files,
    },
    input: {
      prompt: blueprint.prompt,
      negativePrompt: blueprint.negativePrompt,
      imageType: blueprint.imageType,
      style: blueprint.style,
      aspectRatio: "1:1",
      mood: "Professional",
      options: [],
      batchCount: blueprint.concepts.length || 1,
      brandColors: [],
    },
    rasterAssets: blueprint.rasterAssets,
    brand: blueprint.brand,
    templateId: blueprint.templateId,
    providerUsed: blueprint.providerUsed,
  });
}

export function brandTokensToContext(tokens: {
  brandName?: string;
  primary?: string;
  secondary?: string;
  accent?: string;
  headingFont?: string;
  bodyFont?: string;
  voiceTone?: string;
  tagline?: string;
  logoSvg?: string;
}): BrandKitContext {
  const colors = [tokens.primary, tokens.secondary, tokens.accent].filter(Boolean);
  return {
    brandName: tokens.brandName,
    primary: tokens.primary,
    secondary: tokens.secondary,
    accent: tokens.accent,
    headingFont: tokens.headingFont,
    bodyFont: tokens.bodyFont,
    voiceTone: tokens.voiceTone,
    tagline: tokens.tagline,
    logoSvg: tokens.logoSvg,
    instructions: colors.length
      ? `Use brand colors: ${colors.join(", ")}. Typography: ${tokens.headingFont ?? "brand"} / ${tokens.bodyFont ?? "brand"}. Voice: ${tokens.voiceTone ?? "on-brand"}.`
      : undefined,
  };
}

export function enrichInputWithBrand(
  input: ImagePluginInput,
  brand?: BrandKitContext,
): ImagePluginInput {
  if (!brand?.instructions && !brand?.primary) return input;
  const colors = [brand.primary, brand.secondary, brand.accent].filter(Boolean) as string[];
  return {
    ...input,
    brandColors: colors.length ? colors : input.brandColors,
    prompt: brand.instructions
      ? `${input.prompt}\n\nBrand direction: ${brand.instructions}`
      : input.prompt,
  };
}

import type { GeneratedProjectFile } from "@/lib/ai/types";
import type { CoreAssetManifest } from "@/lib/ai-core/layers/types";
import type { ImageSystemSpec } from "@/lib/ai-core/image-intelligence/iie-types";
import {
  resolveSiteImageStrategy,
  siteImageStrategyUsesGeneration,
  type SiteImageStrategy,
} from "@/lib/website/site-plan/image-strategy";
import { resolveImageRoutingFromContext } from "@/lib/website/site-plan/resolve-image-routing";
import { preferAiImages } from "@/lib/ai-core/image-engine/prefer";
import {
  isPremiumStockUrl,
  normalizePremiumStockUrl,
  resolvePremiumStockUrl,
} from "@/lib/ai-core/image-engine/stock";
import { optimizePhotoUrlForRole } from "@/lib/ai-core/image-engine/optimize";
import { buildSiteVideoModule } from "@/lib/ai-core/image-engine/video";
import {
  enrichManifestWithProfileSlots,
  hydrateSlotsFromManifest,
} from "@/lib/ai-core/image-engine/profile-engine";
import {
  resolveStockIndustryForRole,
  resolveRequiredPhotoRoleCounts,
  capSubjectSparingGalleryUrls,
  capSubjectSparingSectionUrls,
  getIndustryVisualPolicy,
  isHeroDominantIndustry,
  isAutomotiveVehiclePhotoUrl,
  isSubjectPackPhotoUrl,
  isSubjectSparingIndustry,
  stripSubjectPackPhotos,
} from "@/lib/ai-core/image-engine/industry-slot-policy";
import { slotUrls } from "@/lib/ai-core/image-engine/slots";

const SITE_IMAGES_PATH = "lib/site-images.ts";
const SITE_VIDEOS_PATH = "lib/site-videos.ts";

const PLACEHOLDER_URL_RE =
  /(?:https?:\/\/(?:placehold\.co|via\.placeholder\.com|picsum\.photos|dummyimage\.com)[^\s"'`)]+|\/placeholder(?:[-_/][^\s"'`)]*)?|data:image\/svg\+xml[^"'`]*)/gi;

const EMPTY_IMG_SRC_RE = /(<img\b[^>]*\bsrc\s*=\s*)(["'])\2/gi;

const REQUIRED_PHOTO_ROLES = [
  "hero",
  "product",
  "service",
  "background",
  "section",
  "gallery",
  "testimonial",
] as const;

function sanitizeHeroDominantManifestItems(
  items: CoreAssetManifest["items"],
  hero: string,
  serviceFallback: string | null,
): CoreAssetManifest["items"] {
  return items.map((item) => {
    const role = item.role;
    if (role === "hero") return item;
    if (role === "product" || role === "gallery" || role === "brand") {
      return { ...item, url: hero };
    }
    if (item.url && isSubjectPackPhotoUrl(item.url, "automotive")) {
      const replacement =
        serviceFallback && !isSubjectPackPhotoUrl(serviceFallback, "automotive")
          ? serviceFallback
          : resolvePremiumStockUrl({
              routingIndustryId: "business",
              industry: "business",
              role,
              seed: item.id,
            });
      return { ...item, url: replacement };
    }
    return item;
  });
}

/**
 * Emit a typed site image map and replace template layout placeholders with
 * ImageSpecification-driven photographic URLs only.
 */
export function injectAiImagesIntoProject(params: {
  files: GeneratedProjectFile[];
  assetManifest: CoreAssetManifest;
  industry?: string | null;
  routingIndustryId?: string | null;
  imageSystemSpec?: ImageSystemSpec | null;
}): GeneratedProjectFile[] {
  const routingIndustryId =
    params.routingIndustryId ?? params.industry ?? null;
  const manifest = ensureRequiredPhotoAssets(
    preferAiImages(params.assetManifest),
    params.industry,
    {
      imageSystemSpec: params.imageSystemSpec,
      routingIndustryId,
    },
  );
  let enriched = enrichManifestWithProfileSlots(
    manifest,
    {
      industry: params.industry,
      routingIndustryId,
    },
    { projectSeed: params.industry ?? "website" },
  );
  const slotResult = hydrateSlotsFromManifest(
    enriched,
    {
      industry: params.industry,
      routingIndustryId,
    },
    { projectSeed: params.industry ?? "website" },
  );
  const hero = firstUrl(groupByRole(enriched), "hero");
  const servicePreview = firstUrl(groupByRole(enriched), "service");
  if (isHeroDominantIndustry(routingIndustryId) && hero) {
    enriched = {
      ...enriched,
      items: sanitizeHeroDominantManifestItems(
        enriched.items,
        hero,
        servicePreview,
      ),
    };
  }
  const byRole = groupByRole(enriched);
  const product = isHeroDominantIndustry(routingIndustryId) && hero
    ? hero
    : firstUrl(byRole, "product");
  const service = firstUrl(byRole, "service");
  const background = firstUrl(byRole, "background");
  const brand = firstUrl(byRole, "brand");
  const sections = isSubjectSparingIndustry(routingIndustryId)
    ? capSubjectSparingSectionUrls(
        routingIndustryId,
        hero,
        urlsForRole(byRole, "section"),
        service,
      )
    : urlsForRole(byRole, "section");
  const gallery = isSubjectSparingIndustry(routingIndustryId)
    ? capSubjectSparingGalleryUrls(
        routingIndustryId,
        hero,
        urlsForRole(byRole, "gallery"),
      )
    : urlsForRole(byRole, "gallery");
  const testimonials = urlsForRole(byRole, "testimonial");

  const hasPhotos = enriched.items.some(
    (i) =>
      Boolean(i.url) &&
      !i.url!.startsWith("data:image/svg") &&
      (i.status === "generated" ||
        i.metadata?.provider === "premium-stock" ||
        isPremiumStockUrl(i.url)),
  );

  const siteImagesSource = buildSiteImagesModule({
    hero,
    product,
    service,
    background,
    brand,
    sections,
    gallery,
    testimonials,
    about: slotUrls(slotResult.slots, "about"),
    features: slotUrls(slotResult.slots, "features"),
    team: slotUrls(slotResult.slots, "team"),
    items: enriched.items,
    routingIndustryId,
  });

  const out: GeneratedProjectFile[] = [];
  let sawSiteImages = false;
  let sawSiteVideos = false;

  for (const file of params.files) {
    if (file.path === SITE_IMAGES_PATH || file.path === "lib/site-images.js") {
      sawSiteImages = true;
      out.push({
        ...file,
        path: SITE_IMAGES_PATH,
        content: siteImagesSource,
        language: "typescript",
      });
      continue;
    }
    if (file.path === SITE_VIDEOS_PATH || file.path === "lib/site-videos.js") {
      sawSiteVideos = true;
      if (enriched.videoPackage) {
        out.push({
          ...file,
          path: SITE_VIDEOS_PATH,
          content: buildSiteVideoModule(enriched.videoPackage),
          language: "typescript",
        });
        continue;
      }
    }

    let content = file.content;
    if (hasPhotos && /\.(tsx?|jsx?)$/.test(file.path)) {
      content = rewritePlaceholders(content, {
        hero,
        product,
        service,
        background,
        sections,
        gallery,
        testimonials,
      });
      content = fillEmptyImageSrcs(content, {
        hero,
        product,
        service,
        background,
        sections,
        gallery,
        testimonials,
      });
      // Strip decorative empty gradient-only hero branches when we have photos
      content = content.replace(
        /\{!src \? \(\s*<div className="[^"]*bg-gradient-hero[^"]*"[^>]*\/>\s*\) : null\}/g,
        "",
      );
    }
    out.push({ ...file, content });
  }

  if (!sawSiteImages) {
    out.push({
      path: SITE_IMAGES_PATH,
      content: siteImagesSource,
      language: "typescript",
    });
  }
  if (!sawSiteVideos && enriched.videoPackage) {
    out.push({
      path: SITE_VIDEOS_PATH,
      content: buildSiteVideoModule(enriched.videoPackage),
      language: "typescript",
    });
  }

  return out;
}

export type ImageInjectionProject = {
  files: GeneratedProjectFile[];
  assetManifest?: CoreAssetManifest | null;
  businessProfile?: { industry?: string; routingIndustryId?: string } | null;
  designSystem?: { industryPattern?: string } | null;
  sitePlan?: {
    imageStrategy?: SiteImageStrategy;
    archetypeId?: string;
  } | null;
  prompt?: string | null;
  title?: string | null;
  description?: string | null;
  settings?: {
    businessIndustry?: string;
    sitePlanArchetype?: string;
  } | null;
};

/**
 * Definitive image injection pass for completed generation output.
 * Call once after all file generation, quality passes, and V2 template finalize.
 */
export function applyFinalImageInjectionToProject<T extends ImageInjectionProject>(
  project: T,
  options?: { imageStrategy?: SiteImageStrategy },
): T {
  if (!project.files?.length) {
    return project;
  }

  const imageStrategy = resolveSiteImageStrategy(
    options?.imageStrategy ?? project.sitePlan?.imageStrategy,
  );
  if (!siteImageStrategyUsesGeneration(imageStrategy)) {
    return project;
  }

  const routing = resolveImageRoutingFromContext({
    prompt: project.prompt,
    title: project.title,
    description: project.description,
    industryId:
      project.businessProfile?.routingIndustryId ??
      project.settings?.businessIndustry,
    businessIndustry:
      project.settings?.businessIndustry ??
      project.businessProfile?.routingIndustryId,
    sitePlanArchetype:
      project.settings?.sitePlanArchetype ?? project.sitePlan?.archetypeId,
    archetypeId: project.sitePlan?.archetypeId as
      | import("@/lib/website/site-plan/types").SiteArchetypeId
      | undefined,
  });

  const industry =
    project.businessProfile?.routingIndustryId ??
    routing.routingIndustryId ??
    project.businessProfile?.industry ??
    project.designSystem?.industryPattern;

  const manifest = project.assetManifest?.items?.length
    ? project.assetManifest
    : ensureRequiredPhotoAssets(
        {
          items: [],
          engine: "premium-stock-fallback",
          generatedAt: new Date().toISOString(),
        },
        industry,
        { routingIndustryId: routing.routingIndustryId },
      );

  const files = injectAiImagesIntoProject({
    files: project.files,
    assetManifest: manifest,
    industry,
    routingIndustryId: routing.routingIndustryId,
  });

  return { ...project, files, assetManifest: manifest };
}

function isPhotographicUrl(url: string | null | undefined): boolean {
  if (!url) return false;
  if (
    url.startsWith("data:image/svg") ||
    url.includes("image/svg+xml") ||
    /placehold\.co|via\.placeholder|picsum\.photos|dummyimage/i.test(url)
  ) {
    return false;
  }
  return true;
}

/**
 * Guarantee hero / service / product / background / section / gallery /
 * testimonial URLs exist so components never render empty visual areas.
 * Uses premium stock only — never SVG placeholders for photos.
 */
export function ensureRequiredPhotoAssets(
  manifest: CoreAssetManifest,
  industry?: string | null,
  options?: {
    routingIndustryId?: string | null;
    imageSystemSpec?: ImageSystemSpec | null;
  },
): CoreAssetManifest {
  const items = [...manifest.items];
  const specById = new Map(
    (options?.imageSystemSpec?.specifications ?? []).map((s) => [s.id, s]),
  );

  const semanticForItem = (item: (typeof items)[number]) => {
    const spec = specById.get(item.id);
    return (
      spec?.providerPrompt ||
      spec?.visualConcept ||
      item.metadata?.prompt ||
      item.prompt
    );
  };

  // Replace SVG / generic placeholders with spec-aligned premium stock photography.
  for (let i = 0; i < items.length; i += 1) {
    const item = items[i]!;
    if (item.role === "icon") continue;
    if (isPhotographicUrl(item.url)) continue;
    const semanticQuery = semanticForItem(item);
    items[i] = {
      ...item,
      url: resolvePremiumStockUrl({
        industry,
        routingIndustryId: options?.routingIndustryId,
        role: item.role,
        seed: item.id,
        semanticQuery,
      }),
      status: "generated",
      mimeType: "image/jpeg",
      metadata: {
        ...item.metadata,
        purpose: (item.metadata?.purpose || item.role) as "hero",
        provider: "premium-stock",
        style: item.metadata?.style || "premium-stock",
        prompt: semanticQuery || `Semantic ${item.role} photography`,
        visualConcept: specById.get(item.id)?.visualConcept,
        sectionPurpose: specById.get(item.id)?.sectionPurpose,
      },
    };
  }

  const routingId = options?.routingIndustryId ?? industry ?? "business";
  const roleCounts = resolveRequiredPhotoRoleCounts(routingId);

  for (const role of REQUIRED_PHOTO_ROLES) {
    const haveCount = items.filter(
      (i) => i.role === role && isPhotographicUrl(i.url),
    ).length;
    const need = roleCounts[role] ?? 1;
    if (need <= 0) continue;
    for (let i = haveCount; i < need; i += 1) {
      const id = need === 1 ? role : `${role}-${i + 1}`;
      if (items.some((item) => item.id === id && isPhotographicUrl(item.url))) {
        continue;
      }
      const spec =
        specById.get(id) ||
        [...specById.values()].find((s) => s.role === role);
      const semanticQuery =
        spec?.providerPrompt || spec?.visualConcept || undefined;
      const url = resolvePremiumStockUrl({
        industry,
        routingIndustryId: options?.routingIndustryId,
        role,
        seed: `${id}-${industry || "business"}`,
        semanticQuery,
      });
      items.push({
        id: spec?.id || id,
        role,
        name: `${role} image ${need === 1 ? "" : i + 1}`.trim(),
        prompt: semanticQuery || `Semantic ${role} photography for ${industry || "business"}`,
        alt: spec?.accessibility.altText || `Premium ${role} photography`,
        url,
        storagePath: null,
        status: "generated",
        mimeType: "image/jpeg",
        metadata: {
          purpose: role as "hero",
          provider: "premium-stock",
          style: "premium-stock",
          prompt: semanticQuery || `Semantic ${role} photography`,
          visualConcept: spec?.visualConcept,
          sectionPurpose: spec?.sectionPurpose,
        },
      });
    }
  }

  return {
    ...manifest,
    engine: manifest.engine || "ai-assets-engine",
    items,
  };
}

/** True when the project has a real hero photo URL (not empty / SVG). */
export function hasPublishableHeroImage(manifest: CoreAssetManifest): boolean {
  return manifest.items.some(
    (i) =>
      i.role === "hero" &&
      Boolean(i.url) &&
      !i.url!.startsWith("data:image/svg") &&
      i.mimeType !== "image/svg+xml",
  );
}

function groupByRole(manifest: CoreAssetManifest) {
  const map = new Map<string, typeof manifest.items>();
  for (const item of manifest.items) {
    const list = map.get(item.role) ?? [];
    list.push(item);
    map.set(item.role, list);
  }
  return map;
}

function firstUrl(
  byRole: Map<string, CoreAssetManifest["items"]>,
  role: string,
): string | null {
  const item = byRole.get(role)?.find((i) => i.url);
  return item?.url ?? null;
}

function urlsForRole(
  byRole: Map<string, CoreAssetManifest["items"]>,
  role: string,
): string[] {
  return (byRole.get(role) ?? [])
    .map((i) => i.url)
    .filter((u): u is string => Boolean(u));
}

function normalizePhotoUrl(
  url: string | null | undefined,
  role = "section",
): string | null {
  if (!url?.trim()) return null;
  return optimizePhotoUrlForRole(normalizePremiumStockUrl(url.trim()), role);
}

function buildSiteImagesModule(params: {
  hero: string | null;
  product: string | null;
  service: string | null;
  background: string | null;
  brand: string | null;
  sections: string[];
  gallery: string[];
  testimonials: string[];
  about: string[];
  features: string[];
  team: string[];
  items: CoreAssetManifest["items"];
  routingIndustryId?: string | null;
}): string {
  const meta = params.items.map((item) => ({
    id: item.id,
    role: item.role,
    name: item.name,
    alt: item.alt,
    url: normalizePhotoUrl(item.url, item.role),
    status: item.status,
    purpose: item.metadata?.purpose ?? item.role,
    section: item.metadata?.section,
    style: item.metadata?.style,
    prompt: item.metadata?.prompt ?? item.prompt,
    provider: item.metadata?.provider,
    artDirection: item.metadata?.artDirection,
  }));

  // Never export null for primary roles when any photo exists in the pool.
  const pool = [
    params.hero,
    params.product,
    params.service,
    params.background,
    ...params.sections,
    ...params.gallery,
    ...params.testimonials,
  ]
    .map((url, i) =>
      normalizePhotoUrl(url, i === 0 ? "hero" : "section"),
    )
    .filter((u): u is string => Boolean(u));
  const fallback = pool[0] ?? null;
  const policy = getIndustryVisualPolicy(params.routingIndustryId);
  const subjectSparing = Boolean(policy);
  const heroDominant = policy?.heroDominant ?? false;
  const hero = normalizePhotoUrl(params.hero, "hero") || fallback;
  const product = heroDominant
    ? hero
    : normalizePhotoUrl(params.product, "product") || hero || fallback;
  const service = normalizePhotoUrl(params.service, "service") || product || fallback;
  const rawBackground =
    normalizePhotoUrl(params.background, "background") || service || fallback;
  const background =
    policy &&
    heroDominant &&
    isSubjectPackPhotoUrl(rawBackground, policy.subjectPackId)
      ? service && !isSubjectPackPhotoUrl(service, policy.subjectPackId)
        ? service
        : rawBackground
      : rawBackground;
  const sections = subjectSparing
    ? capSubjectSparingSectionUrls(
        params.routingIndustryId,
        hero,
        params.sections
          .map((url) => normalizePhotoUrl(url, "section")!)
          .filter(Boolean),
        service,
      )
    : params.sections.length > 0
      ? params.sections
          .map((url) => normalizePhotoUrl(url, "section")!)
          .filter(Boolean)
      : ([service, product, hero].filter(Boolean) as string[]);
  const gallery = subjectSparing
    ? capSubjectSparingGalleryUrls(params.routingIndustryId, hero, params.gallery)
    : params.gallery.length > 0
      ? params.gallery
          .map((url) => normalizePhotoUrl(url, "gallery")!)
          .filter(Boolean)
      : ([product, hero, service].filter(Boolean) as string[]);
  const testimonials =
    params.testimonials.length > 0
      ? params.testimonials
          .map((url) => normalizePhotoUrl(url, "testimonial")!)
          .filter(Boolean)
      : heroDominant
        ? []
        : ([hero, product].filter(Boolean) as string[]);
  const about = subjectSparing && policy
    ? stripSubjectPackPhotos(
        params.about.length > 0
          ? params.about.map((url) => normalizePhotoUrl(url, "about")!).filter(Boolean)
          : sections,
        policy.subjectPackId,
        hero,
      ).slice(0, 2)
    : params.about.length > 0
      ? params.about.map((url) => normalizePhotoUrl(url, "about")!).filter(Boolean)
      : sections;
  const features = subjectSparing && policy
    ? stripSubjectPackPhotos(
        params.features.length > 0
          ? params.features
              .map((url) => normalizePhotoUrl(url, "features")!)
              .filter(Boolean)
          : ([service].filter(Boolean) as string[]),
        policy.subjectPackId,
        hero,
      ).slice(0, 2)
    : params.features.length > 0
      ? params.features
          .map((url) => normalizePhotoUrl(url, "features")!)
          .filter(Boolean)
      : heroDominant
        ? ([service].filter(Boolean) as string[])
        : ([service, product].filter(Boolean) as string[]);
  const team =
    params.team.length > 0
      ? params.team.map((url) => normalizePhotoUrl(url, "team")!).filter(Boolean)
      : testimonials;

  const exportMeta = heroDominant
    ? meta.map((item) => {
        if (item.role === "hero") return item;
        if (item.role === "product" || item.role === "gallery" || item.role === "brand") {
          return { ...item, url: hero };
        }
        if (item.url && isAutomotiveVehiclePhotoUrl(item.url)) {
          return {
            ...item,
            url:
              service && !isAutomotiveVehiclePhotoUrl(service)
                ? service
                : resolvePremiumStockUrl({
                    routingIndustryId: "business",
                    industry: "business",
                    role: item.role,
                    seed: item.id,
                  }),
          };
        }
        return item;
      })
    : meta;

  return `/**
 * Website Builder Image Engine — generated site imagery.
 * Semantic slots: hero, gallery, about, features, team, products, testimonials, backgrounds.
 */

export const HERO_IMAGE = ${JSON.stringify(hero)};
export const PRODUCT_IMAGE = ${JSON.stringify(product)};
export const SERVICE_IMAGE = ${JSON.stringify(service)};
export const BACKGROUND_IMAGE = ${JSON.stringify(background)};
export const ABOUT_IMAGE = ${JSON.stringify(about[0] ?? hero)};
export const BRAND_IMAGE = ${JSON.stringify(normalizePhotoUrl(params.brand, "brand") || hero)};
export const SECTION_IMAGES = ${JSON.stringify(about.length ? about : sections)} as const;
export const FEATURE_IMAGES = ${JSON.stringify(features)} as const;
export const TEAM_IMAGES = ${JSON.stringify(team)} as const;
export const GALLERY_IMAGES = ${JSON.stringify(gallery)} as const;
export const TESTIMONIAL_IMAGES = ${JSON.stringify(testimonials)} as const;

export type ImageSlotKind =
  | "hero"
  | "gallery"
  | "about"
  | "features"
  | "team"
  | "products"
  | "testimonials"
  | "backgrounds";

export type SiteImageMeta = {
  id: string;
  role: string;
  name: string;
  alt: string;
  url: string | null;
  status: string;
  purpose?: string;
  section?: string;
  style?: string;
  prompt?: string;
  provider?: string;
  artDirection?: string;
  slot?: ImageSlotKind;
  objectPosition?: string;
  isUserOverride?: boolean;
};

export const SITE_IMAGES: SiteImageMeta[] = ${JSON.stringify(exportMeta, null, 2)};

export function siteImagePool(): string[] {
  return [
    HERO_IMAGE,
    PRODUCT_IMAGE,
    SERVICE_IMAGE,
    BACKGROUND_IMAGE,
    ABOUT_IMAGE,
    ...SECTION_IMAGES,
    ...FEATURE_IMAGES,
    ...TEAM_IMAGES,
    ...GALLERY_IMAGES,
    ...TESTIMONIAL_IMAGES,
  ].filter((u): u is string => Boolean(u));
}

export function slotImages(kind: ImageSlotKind): readonly string[] {
  switch (kind) {
    case "hero":
      return [HERO_IMAGE];
    case "gallery":
      return GALLERY_IMAGES;
    case "about":
      return SECTION_IMAGES.length ? SECTION_IMAGES : [ABOUT_IMAGE];
    case "features":
      return FEATURE_IMAGES.length ? FEATURE_IMAGES : SECTION_IMAGES;
    case "team":
      return TEAM_IMAGES;
    case "products":
      return [PRODUCT_IMAGE, ...GALLERY_IMAGES].filter(Boolean);
    case "testimonials":
      return TESTIMONIAL_IMAGES;
    case "backgrounds":
      return [BACKGROUND_IMAGE, HERO_IMAGE].filter(Boolean);
    default:
      return siteImagePool();
  }
}

export function imageByRole(role: string): string | null {
  const hit = SITE_IMAGES.find((i) => i.role === role && i.url);
  return hit?.url ?? null;
}

function sharpenUnsplashUrl(url: string, role: string): string {
  if (!url?.trim()) return "";
  const trimmed = url.trim();
  if (!trimmed.includes("images.unsplash.com")) return trimmed;
  const base = trimmed.split("?")[0]!;
  const w =
    role === "hero" || role === "background"
      ? 2400
      : role === "testimonial" || role === "team"
        ? 960
        : 1920;
  const q = w >= 2400 ? 90 : 88;
  return \`\${base}?auto=format&fit=crop&w=\${w}&q=\${q}\`;
}

export function resolveSlotImage(
  kind: ImageSlotKind,
  index = 0,
  preferred?: string | null,
): string {
  if (preferred?.trim()) return sharpenUnsplashUrl(preferred.trim(), kind);
  const images = slotImages(kind);
  if (images.length > 0) {
    return sharpenUnsplashUrl(images[index % images.length]!, kind);
  }
  return resolveSiteImage(null, index);
}

/** Resolve a photographic URL for a slot — never returns empty string when pool has images. */
export function resolveSiteImage(
  preferred?: string | null,
  index = 0,
): string {
  if (preferred?.trim()) {
    return sharpenUnsplashUrl(preferred.trim(), index === 0 ? "hero" : "section");
  }
  const pool = siteImagePool();
  if (!pool.length) return "";
  return sharpenUnsplashUrl(pool[index % pool.length]!, "section");
}
`;
}

function photoPool(urls: {
  hero: string | null;
  product: string | null;
  service: string | null;
  background: string | null;
  sections: string[];
  gallery: string[];
  testimonials?: string[];
}): string[] {
  return [
    urls.hero,
    ...urls.gallery,
    ...urls.sections,
    ...(urls.testimonials ?? []),
    urls.product,
    urls.service,
    urls.background,
  ].filter((u): u is string => Boolean(u));
}

function rewritePlaceholders(
  content: string,
  urls: {
    hero: string | null;
    product: string | null;
    service: string | null;
    background: string | null;
    sections: string[];
    gallery: string[];
    testimonials?: string[];
  },
): string {
  const pool = photoPool(urls);
  if (!pool.length) return content;

  if (!PLACEHOLDER_URL_RE.test(content)) {
    PLACEHOLDER_URL_RE.lastIndex = 0;
  } else {
    PLACEHOLDER_URL_RE.lastIndex = 0;
    let index = 0;
    content = content.replace(PLACEHOLDER_URL_RE, () => {
      const next = pool[index % pool.length]!;
      index += 1;
      return next;
    });
  }

  return content;
}

function fillEmptyImageSrcs(
  content: string,
  urls: {
    hero: string | null;
    product: string | null;
    service: string | null;
    background: string | null;
    sections: string[];
    gallery: string[];
    testimonials?: string[];
  },
): string {
  const pool = photoPool(urls);
  if (!pool.length) return content;

  let index = 0;
  EMPTY_IMG_SRC_RE.lastIndex = 0;
  return content.replace(EMPTY_IMG_SRC_RE, (_match, prefix: string, quote: string) => {
    const next = pool[index % pool.length]!;
    index += 1;
    return `${prefix}${quote}${next}${quote}`;
  });
}

import type { BrandIdentityBrief } from "@/lib/ai-core/brand-identity/types";
import type {
  CoreBusinessProfile,
  CoreDesignSystem,
  CoreProductStrategy,
} from "@/lib/ai-core/layers/types";
import type { TemplateSelection } from "@/lib/ai-core/templates/types";
import { buildImageArtDirection } from "@/lib/ai-core/image-engine/art-direction";
import {
  buildAccessibleAltText,
  buildImageIntelligence,
  composeImagePrompt,
  defaultAspectForPurpose,
  resolveShotBriefForRole,
  styleFromContext,
} from "@/lib/ai-core/image-engine/intelligence";
import {
  getSectionStrategy,
  inferSectionKey,
  type SectionKey,
} from "@/lib/ai-core/image-engine/section-strategies";
import type {
  DesignPlanImageContext,
  ImageEnginePlanItem,
  ImagePurpose,
  StructuredImageRequirement,
} from "@/lib/ai-core/image-engine/types";
import type { MasterWebsitePlan } from "@/lib/ai-core/master-planner/types";

/**
 * Plan professional AI images for every major website surface with
 * section-specific strategies — never reuse hero prompts for all sections.
 */
export function planWebsiteImages(params: {
  strategy: CoreProductStrategy;
  designSystem: CoreDesignSystem;
  profile?: CoreBusinessProfile;
  templateSelection?: TemplateSelection;
  preferredStyle?: string | null;
  brandIdentity?: BrandIdentityBrief | null;
  structuredRequirements?: StructuredImageRequirement[];
  designPlanContext?: DesignPlanImageContext;
  maxItems?: number;
  masterPlan?: MasterWebsitePlan | null;
  businessProfile?: import("@/lib/ai-core/business-intelligence/types").BusinessIntelligenceProfile | null;
}): ImageEnginePlanItem[] {
  const maxItems = params.maxItems ?? 14;
  const ctx = buildImageIntelligence({
    ...params,
    structuredRequirements: params.structuredRequirements,
    masterPlan: params.masterPlan,
    businessProfile: params.businessProfile,
  });
  const style = styleFromContext(ctx);
  const sections = Array.isArray(params.strategy.sectionPlan)
    ? params.strategy.sectionPlan
    : [];
  const designSections = params.designPlanContext?.sections ?? [];
  const usedBriefs = new Set<string>();
  const planned: ImageEnginePlanItem[] = [];
  let varietyIndex = 0;

  const push = (
    purpose: ImagePurpose,
    opts: {
      id: string;
      name: string;
      role: ImageEnginePlanItem["role"];
      kind?: ImageEnginePlanItem["kind"];
      sectionName?: string;
      sectionKey?: SectionKey;
      shotBrief?: string;
      contentNotes?: string;
    },
  ) => {
    const sectionKey =
      opts.sectionKey ||
      inferSectionKey(opts.sectionName || purpose);
    const shotBrief =
      opts.shotBrief ||
      resolveShotBriefForRole(
        ctx,
        purpose,
        sectionKey,
        varietyIndex,
        usedBriefs,
        opts.sectionName,
        opts.contentNotes,
      );
    if (shotBrief) {
      usedBriefs.add(shotBrief);
      varietyIndex += 1;
    }

    const art = buildImageArtDirection({
      purpose,
      ctx,
      brandIdentity: params.brandIdentity,
      sectionName: opts.sectionName || sectionKey,
    });
    const prompt = composeImagePrompt({
      purpose,
      ctx,
      sectionName: opts.sectionName,
      sectionKey,
      shotBrief,
      contentNotes: opts.contentNotes,
      artDirectionFragment: art.promptFragment,
      varietyIndex,
    });
    const accessibility = buildAccessibleAltText({
      ctx,
      purpose,
      sectionName: opts.sectionName,
      sectionKey,
      shotBrief,
    });
    const strategy = getSectionStrategy(sectionKey);

    planned.push({
      id: opts.id,
      kind: opts.kind ?? purposeToKind(purpose),
      role: opts.role,
      name: opts.name,
      prompt,
      alt: accessibility.alt,
      caption: accessibility.caption,
      seoDescription: accessibility.seoDescription,
      realistic: true,
      aspectRatio: defaultAspectForPurpose(purpose, sectionKey),
      sectionKey,
      metadata: {
        purpose,
        section: opts.sectionName || sectionKey,
        style,
        prompt,
        artDirection: art.summary,
      },
    });
  };

  // Hero — always first, wide cinematic.
  const heroSection = designSections.find((s) =>
    /hero/i.test(s.key || s.label),
  );
  push("hero", {
    id: "hero",
    name: "Hero image",
    role: "hero",
    sectionKey: "hero",
    sectionName: heroSection?.label || sections[0]?.name,
    shotBrief: resolveShotBriefForRole(ctx, "hero", "hero", 0, usedBriefs),
    contentNotes: sections[0]?.contentNotes || heroSection?.purpose,
  });

  // Core photographic roles with distinct section strategies.
  push("product", {
    id: "product",
    name: "Product visual",
    role: "product",
    sectionKey: "features",
    shotBrief: resolveShotBriefForRole(ctx, "product", "features", varietyIndex, usedBriefs),
  });

  push("service", {
    id: "service",
    name: "Service visual",
    role: "service",
    sectionKey: "services",
    shotBrief: resolveShotBriefForRole(ctx, "service", "services", varietyIndex, usedBriefs),
  });

  push("background", {
    id: "background",
    name: "Background atmosphere",
    role: "background",
    sectionKey: "cta",
    shotBrief: resolveShotBriefForRole(ctx, "background", "cta", varietyIndex, usedBriefs),
  });

  // Section images from design plan / strategy — each gets unique section key.
  const sectionSources =
    designSections.length > 0
      ? designSections
          .filter((s) => !/hero/i.test(s.key || s.label))
          .map((s) => ({
            name: s.label,
            key: s.key,
            contentNotes: s.purpose,
            assetRole: s.assetRole,
          }))
      : sections
          .filter((s) => !/hero/i.test(s.name))
          .map((s) => ({
            name: s.name,
            key: s.name,
            contentNotes: s.contentNotes,
            assetRole: undefined as string | undefined,
          }));

  const sectionKeysSeen = new Set<SectionKey>();
  const sectionCandidates = sectionSources.slice(0, 5);

  if (sectionCandidates.length) {
    sectionCandidates.forEach((section, index) => {
      const sectionKey = inferSectionKey(section.key || section.name);
      sectionKeysSeen.add(sectionKey);
      const purpose = sectionKeyToPurpose(sectionKey, section.assetRole);
      push(purpose, {
        id: `section-${sectionKey}-${index + 1}`,
        name: `${section.name} visual`,
        role: purposeToRole(purpose),
        sectionName: section.name,
        sectionKey,
        contentNotes: section.contentNotes,
        shotBrief: resolveShotBriefForRole(
          ctx,
          purpose,
          sectionKey,
          varietyIndex,
          usedBriefs,
        ),
      });
    });
  } else {
    const fallbackSections: SectionKey[] = ["about", "features", "contact"];
    fallbackSections.forEach((sectionKey, index) => {
      push("section", {
        id: `section-${sectionKey}-${index + 1}`,
        name: `${sectionKey} visual`,
        role: "section",
        sectionKey,
        shotBrief: resolveShotBriefForRole(
          ctx,
          "section",
          sectionKey,
          varietyIndex,
          usedBriefs,
        ),
      });
    });
  }

  // Gallery — diverse industry shots, never duplicate briefs.
  const galleryCount = 3;
  for (let i = 0; i < galleryCount; i += 1) {
    const galleryKey: SectionKey = i % 2 === 0 ? "gallery" : "portfolio";
    push("gallery", {
      id: `gallery-${i + 1}`,
      name: `Gallery image ${i + 1}`,
      role: "gallery",
      kind: "realistic",
      sectionKey: galleryKey,
      shotBrief: resolveShotBriefForRole(
        ctx,
        "gallery",
        galleryKey,
        varietyIndex + i,
        usedBriefs,
      ),
    });
  }

  // Testimonial portraits — distinct from team section.
  for (let i = 0; i < 2; i += 1) {
    push("testimonial", {
      id: `testimonial-${i + 1}`,
      name: `Testimonial portrait ${i + 1}`,
      role: "testimonial",
      kind: "realistic",
      sectionKey: "testimonials",
      shotBrief: resolveShotBriefForRole(
        ctx,
        "testimonial",
        "testimonials",
        varietyIndex + i,
        usedBriefs,
      ),
    });
  }

  // Optional footer background if room in budget.
  if (planned.length < maxItems) {
    push("background", {
      id: "footer-background",
      name: "Footer atmosphere",
      role: "background",
      sectionKey: "footer",
      shotBrief: resolveShotBriefForRole(
        ctx,
        "background",
        "footer",
        varietyIndex,
        usedBriefs,
      ),
    });
  }

  return dedupeSimilarPrompts(planned).slice(0, maxItems);
}

function sectionKeyToPurpose(
  sectionKey: SectionKey,
  assetRole?: string,
): ImagePurpose {
  if (assetRole) {
    const r = assetRole.toLowerCase();
    if (r === "hero") return "hero";
    if (r === "product") return "product";
    if (r === "service") return "service";
    if (r === "gallery") return "gallery";
    if (r === "testimonial") return "testimonial";
    if (r === "background") return "background";
  }
  switch (sectionKey) {
    case "services":
      return "service";
    case "gallery":
    case "portfolio":
      return "gallery";
    case "testimonials":
      return "testimonial";
    case "pricing":
    case "faq":
    case "cta":
    case "footer":
      return "background";
    default:
      return "section";
  }
}

function purposeToRole(
  purpose: ImagePurpose,
): ImageEnginePlanItem["role"] {
  return purpose as ImageEnginePlanItem["role"];
}

function purposeToKind(
  purpose: ImagePurpose,
): ImageEnginePlanItem["kind"] {
  switch (purpose) {
    case "hero":
      return "hero";
    case "product":
      return "product";
    case "service":
      return "service";
    case "background":
      return "background";
    case "gallery":
    case "testimonial":
      return "realistic";
    case "section":
      return "section";
    case "brand":
      return "brand";
    default:
      return "realistic";
  }
}

/** Remove near-duplicate prompts to increase visual variety. */
function dedupeSimilarPrompts(
  items: ImageEnginePlanItem[],
): ImageEnginePlanItem[] {
  const seen = new Set<string>();
  return items.map((item) => {
    const fingerprint = item.prompt
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .split(" ")
      .filter((w) => w.length > 5)
      .slice(0, 12)
      .join(" ");
    if (seen.has(fingerprint)) {
      const varied = {
        ...item,
        prompt: `${item.prompt} Unique angle variant ${item.id}, distinct composition.`,
      };
      return varied;
    }
    seen.add(fingerprint);
    return item;
  });
}

import type { CoreAssetManifest } from "@/lib/ai-core/layers/types";
import { resolveImageProfile } from "@/lib/ai-core/image-engine/profiles";
import type { ImageProfileContext } from "@/lib/ai-core/image-engine/profiles/types";
import {
  emptySlotMap,
  flattenSlotUrls,
  IMAGE_SLOT_KINDS,
  roleToSlotKind,
  type ImageSlotAssignment,
  type ImageSlotKind,
  type SiteImageSlotMap,
} from "@/lib/ai-core/image-engine/slots";
import { runIndustryImageRulesEngine } from "@/lib/ai-core/image-engine/rules";
import { resolveIndustrySlotCounts } from "@/lib/ai-core/image-engine/industry-slot-policy";

export type ProfileEngineResult = {
  slots: SiteImageSlotMap;
  profileId: string;
  visualStyle: string;
  colorMood: string;
  usedUrls: string[];
};

function hashSeed(seed: string): number {
  let hash = 0;
  for (let i = 0; i < seed.length; i += 1) {
    hash = (hash + seed.charCodeAt(i) * (i + 1)) % 997;
  }
  return hash;
}

function pickUnique(
  pool: string[],
  used: Set<string>,
  seed: string,
  allowReuse: boolean,
): string {
  if (!pool.length) return "";
  const start = hashSeed(seed) % pool.length;
  for (let offset = 0; offset < pool.length; offset += 1) {
    const url = pool[(start + offset) % pool.length]!;
    if (allowReuse || !used.has(url)) {
      if (!allowReuse) used.add(url);
      return url;
    }
  }
  return pool[start % pool.length]!;
}

/**
 * Build a deduplicated semantic slot map from an industry profile.
 */
export function buildSlotsFromProfile(
  ctx: ImageProfileContext,
  opts?: { projectSeed?: string },
): ProfileEngineResult {
  const resolved = resolveImageProfile(ctx);
  const { profile } = resolved;
  const used = new Set<string>();
  const slots = emptySlotMap();
  const seedBase = opts?.projectSeed || ctx.industry || profile.id;
  const slotCounts = resolveIndustrySlotCounts(ctx);

  for (const kind of IMAGE_SLOT_KINDS) {
    const pool = profile.slots[kind] ?? [];
    const count = Math.min(
      slotCounts[kind],
      pool.length > 0 ? pool.length : slotCounts[kind],
    );
    for (let i = 0; i < count; i += 1) {
      const url = pickUnique(
        pool.length ? pool : profile.slots.hero,
        used,
        `${seedBase}:${kind}:${i}`,
        profile.allowReuse === true,
      );
      if (!url) continue;
      slots[kind].push({
        id: `${kind}-${i + 1}`,
        kind,
        url,
        alt: `${profile.label} ${kind} photography`,
        industryId: profile.id,
        provider: "premium-stock",
      });
    }
  }

  const repaired = runIndustryImageRulesEngine({
    slots,
    ctx,
  });
  return {
    slots: repaired.slots,
    profileId: profile.id,
    visualStyle: profile.visualStyle,
    colorMood: profile.colorMood,
    usedUrls: flattenSlotUrls(repaired.slots),
  };
}

/**
 * Merge manifest assets into semantic slots, filling gaps from industry profile.
 */
export function hydrateSlotsFromManifest(
  manifest: CoreAssetManifest,
  ctx: ImageProfileContext,
  opts?: { projectSeed?: string },
): ProfileEngineResult {
  const base = buildSlotsFromProfile(ctx, opts);
  const slots = { ...base.slots };

  for (const item of manifest.items) {
    if (!item.url || item.role === "icon") continue;
    const kind = roleToSlotKind(item.role);
    const existing = slots[kind];
    const duplicate = existing.some((s) => s.url === item.url);
    if (duplicate) continue;
    existing.push({
      id: item.id,
      kind,
      url: item.url,
      alt: item.alt || `${kind} photography`,
      industryId: base.profileId,
      provider: item.metadata?.provider,
    });
  }

  const resolved = resolveImageProfile(ctx);
  const repaired = runIndustryImageRulesEngine({
    slots,
    ctx,
  });
  return {
    ...base,
    slots: repaired.slots,
    usedUrls: flattenSlotUrls(repaired.slots),
  };
}

/**
 * Convert semantic slots to CoreAssetManifest items for injection.
 */
export function slotsToManifestItems(
  slots: SiteImageSlotMap,
  profileId: string,
): CoreAssetManifest["items"] {
  const items: CoreAssetManifest["items"] = [];
  for (const kind of IMAGE_SLOT_KINDS) {
    for (const slot of slots[kind]) {
      items.push({
        id: slot.id,
        role:
          kind === "products"
            ? "product"
            : kind === "backgrounds"
              ? "background"
              : kind === "testimonials"
                ? "testimonial"
                : kind === "features"
                  ? "service"
                  : kind === "about" || kind === "team" || kind === "cta"
                    ? "section"
                    : kind === "gallery"
                      ? "gallery"
                      : "hero",
        name: `${kind} ${slot.id}`,
        prompt: `${profileId} ${kind} photography`,
        alt: slot.alt,
        url: slot.url,
        storagePath: null,
        status: "generated",
        mimeType: "image/jpeg",
        metadata: {
          purpose: kind === "products" ? "product" : kind === "backgrounds" ? "background" : kind === "testimonials" ? "testimonial" : kind === "features" ? "service" : kind === "gallery" ? "gallery" : kind === "hero" ? "hero" : "section",
          provider: slot.provider || "premium-stock",
          style: profileId,
          prompt: `${profileId} ${kind}`,
          section: kind,
        },
      });
    }
  }
  return items;
}

export function enrichManifestWithProfileSlots(
  manifest: CoreAssetManifest,
  ctx: ImageProfileContext,
  opts?: { projectSeed?: string },
): CoreAssetManifest {
  const hydrated = hydrateSlotsFromManifest(manifest, ctx, opts);
  const profileItems = slotsToManifestItems(hydrated.slots, hydrated.profileId);
  const byId = new Map(manifest.items.map((item) => [item.id, item]));

  for (const item of profileItems) {
    if (!byId.has(item.id)) {
      byId.set(item.id, item);
    }
  }

  return {
    ...manifest,
    items: [...byId.values()],
  };
}

import {
  DEFAULT_IMAGE_PROFILE,
  INDUSTRY_IMAGE_PROFILES,
} from "@/lib/ai-core/image-engine/profiles/data";
import type {
  ImageProfileContext,
  IndustryImageProfile,
  ResolvedImageProfile,
} from "@/lib/ai-core/image-engine/profiles/types";

const PROFILE_BY_ID = new Map(
  INDUSTRY_IMAGE_PROFILES.map((profile) => [profile.id, profile]),
);

function normalizeToken(value: string): string {
  return value.toLowerCase().replace(/[_\s]+/g, "-").trim();
}

function tokenize(value: string): string[] {
  return normalizeToken(value)
    .split(/[^a-z0-9-]+/)
    .filter((t) => t.length > 1);
}

/**
 * Detect the best industry image profile from business context.
 */
export function resolveImageProfile(
  ctx: ImageProfileContext,
): ResolvedImageProfile {
  const candidates = [
    ctx.routingIndustryId,
    ctx.industry,
    ctx.subcategory,
    ctx.businessType,
  ]
    .filter(Boolean)
    .map((v) => normalizeToken(v!));

  for (const candidate of candidates) {
    const exact = PROFILE_BY_ID.get(candidate);
    if (exact) {
      return { profile: exact, matchedBy: "exact", confidence: 1 };
    }
  }

  for (const candidate of candidates) {
    for (const profile of INDUSTRY_IMAGE_PROFILES) {
      if (profile.aliases.some((alias) => alias === candidate)) {
        return { profile, matchedBy: "alias", confidence: 0.95 };
      }
      if (profile.aliases.some((alias) => candidate.includes(alias) && alias.length > 2)) {
        return { profile, matchedBy: "alias", confidence: 0.9 };
      }
      if (
        profile.subcategories?.some(
          (sub) => sub === candidate || candidate.includes(sub),
        )
      ) {
        return { profile, matchedBy: "subcategory", confidence: 0.9 };
      }
    }
  }

  const haystack = candidates.join(" ");
  if (haystack) {
    let best: { profile: IndustryImageProfile; score: number } | null = null;
    for (const profile of INDUSTRY_IMAGE_PROFILES) {
      const tokens = [
        profile.id,
        ...profile.aliases,
        ...(profile.subcategories ?? []),
      ];
      const score = tokens.reduce((sum, token) => {
        if (!token) return sum;
        if (haystack.includes(token)) return sum + token.length;
        return sum;
      }, 0);
      if (score > 0 && (!best || score > best.score)) {
        best = { profile, score };
      }
    }
    if (best) {
      return {
        profile: best.profile,
        matchedBy: "alias",
        confidence: Math.min(0.85, 0.5 + best.score / 40),
      };
    }
  }

  return {
    profile: DEFAULT_IMAGE_PROFILE,
    matchedBy: "fallback",
    confidence: 0.5,
  };
}

export function getImageProfileById(id: string): IndustryImageProfile | null {
  return PROFILE_BY_ID.get(normalizeToken(id)) ?? null;
}

export function listImageProfiles(): IndustryImageProfile[] {
  return [...INDUSTRY_IMAGE_PROFILES];
}

export {
  DEFAULT_IMAGE_PROFILE,
  INDUSTRY_IMAGE_PROFILES,
} from "@/lib/ai-core/image-engine/profiles/data";

export type {
  ImageProfileContext,
  IndustryImageProfile,
  ResolvedImageProfile,
} from "@/lib/ai-core/image-engine/profiles/types";

import type { ImageSlotKind } from "@/lib/ai-core/image-engine/slots";
import type { ImageProfileContext } from "@/lib/ai-core/image-engine/profiles/types";
import { resolveImageProfile } from "@/lib/ai-core/image-engine/profiles";
import type { DetectedImageContext } from "@/lib/ai-core/image-engine/rules/types";

function normalize(value: string): string {
  return value.toLowerCase().replace(/[_\s]+/g, "-").trim();
}

/**
 * Detect business industry, subcategory, and visual style before image selection.
 */
export function detectImageContext(ctx: ImageProfileContext): DetectedImageContext {
  const resolved = resolveImageProfile(ctx);
  const subcategory =
    ctx.subcategory?.trim() ||
    resolved.profile.subcategories?.find((sub) => {
      const hay = [ctx.industry, ctx.businessType, ctx.routingIndustryId]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return hay.includes(sub);
    }) ||
    null;

  const visualStyle =
    ctx.visualStyle?.trim() ||
    ctx.brandStyle?.trim() ||
    resolved.profile.visualStyle;

  return {
    industryId: resolved.profile.id,
    industryLabel: resolved.profile.label,
    subcategory,
    visualStyle,
    colorMood: resolved.profile.colorMood,
    matchedBy: resolved.matchedBy,
    confidence: resolved.confidence,
  };
}

/** Map template package IDs to image profile industries. */
export const PACKAGE_INDUSTRY_MAP: Record<string, string> = {
  "saas-enterprise": "saas",
  "corporate-business": "corporate",
  "restaurant-premium": "restaurant",
  "restaurant-signature": "restaurant",
  "real-estate-premium": "real-estate",
  "real-estate-prestige": "real-estate",
  "medical-premium": "medical",
  "creative-agency-premium": "creative-agency",
  "creative-portfolio": "creative-agency",
  "hotel-resort-premium": "hotel",
  "finance-premium": "finance",
  "education-premium": "education",
  "ecommerce-premium": "ecommerce",
  "ai-startup-signal": "saas",
};

export function contextFromPackage(
  templatePackageId: string,
  extras: ImageProfileContext = {},
): ImageProfileContext {
  const industry =
    extras.industry ||
    PACKAGE_INDUSTRY_MAP[templatePackageId] ||
    extras.routingIndustryId ||
    "corporate";
  return {
    ...extras,
    industry,
    routingIndustryId: extras.routingIndustryId ?? industry,
  };
}

export function slotOrientationForKind(kind: ImageSlotKind): "landscape" | "portrait" | "square" | "any" {
  switch (kind) {
    case "team":
    case "testimonials":
      return "portrait";
    case "hero":
    case "backgrounds":
    case "cta":
      return "landscape";
    case "products":
      return "square";
    default:
      return "any";
  }
}

import type { ImageProfileContext } from "@/lib/ai-core/image-engine/profiles/types";
import { resolveImageProfile } from "@/lib/ai-core/image-engine/profiles";
import {
  IMAGE_SLOT_KINDS,
  SLOT_MIN_COUNTS,
  type ImageSlotAssignment,
  type ImageSlotKind,
  type SiteImageSlotMap,
} from "@/lib/ai-core/image-engine/slots";
import { checkAspectRatioHint } from "@/lib/ai-core/image-engine/slot-validator";
import { detectImageContext } from "@/lib/ai-core/image-engine/rules/detect-context";
import { inferSourceTier, resolveSlotImageSource } from "@/lib/ai-core/image-engine/rules/priority-resolver";
import { getIndustrySlotRules } from "@/lib/ai-core/image-engine/rules/slot-rules";
import { isWrongIndustryUrl, urlAllowedForSlot } from "@/lib/ai-core/image-engine/rules/url-registry";
import type {
  ImageCandidate,
  ImageRejectionRecord,
  ImageSelectionRecord,
  ImageSourceTier,
  IndustryImageRulesReport,
} from "@/lib/ai-core/image-engine/rules/types";

const PLACEHOLDER_RE =
  /placehold\.co|via\.placeholder|picsum\.photos|dummyimage|data:image\/svg/i;

function isLowQuality(url: string): boolean {
  return PLACEHOLDER_RE.test(url) || !url.trim();
}

function haystackForCandidate(candidate: ImageCandidate): string {
  return [candidate.url, candidate.alt ?? "", candidate.provider ?? ""]
    .join(" ")
    .toLowerCase();
}

function hasForbiddenSubject(text: string, forbidden: string[]): string | null {
  for (const subject of forbidden) {
    if (text.includes(subject.toLowerCase())) return subject;
  }
  return null;
}

function pickReplacement(
  kind: ImageSlotKind,
  industryId: string,
  used: Set<string>,
  index: number,
): { url: string; tier: ImageSourceTier } {
  const profile = resolveImageProfile({ industry: industryId }).profile;
  const pool = profile.slots[kind] ?? profile.slots.backgrounds ?? profile.slots.hero;
  for (let i = 0; i < pool.length; i += 1) {
    const candidate = pool[(index + i) % pool.length]!;
    if (!used.has(candidate)) {
      return { url: candidate, tier: "library" };
    }
  }
  const fallback = pool[index % pool.length] ?? profile.slots.hero[0] ?? "";
  return { url: fallback, tier: "library" };
}

export type ValidateImageCandidateInput = {
  candidate: ImageCandidate;
  kind: ImageSlotKind;
  industryId: string;
  subcategory: string | null;
  usedUrls: Set<string>;
  allowReuse?: boolean;
  isUserOverride?: boolean;
};

export type ValidateImageCandidateResult = {
  accepted: boolean;
  rejection?: Omit<ImageRejectionRecord, "slotId" | "kind" | "url">;
};

/**
 * Validate a single image candidate against industry rules.
 * User uploads always pass validation (highest priority).
 */
export function validateImageCandidate(
  input: ValidateImageCandidateInput,
): ValidateImageCandidateResult {
  const { candidate, kind, industryId, subcategory, usedUrls, allowReuse, isUserOverride } =
    input;

  if (isUserOverride || candidate.isUserOverride) {
    return { accepted: true };
  }

  const url = candidate.url;
  if (!url || isLowQuality(url)) {
    return {
      accepted: false,
      rejection: {
        category: "low-quality",
        detail: "Placeholder or empty image rejected.",
      },
    };
  }

  const profile = resolveImageProfile({ industry: industryId }).profile;
  const rules = getIndustrySlotRules(industryId);
  const slotRule = rules.slots[kind];
  const haystack = haystackForCandidate(candidate);

  if (candidate.industryId && candidate.industryId !== industryId && !allowReuse) {
    return {
      accepted: false,
      rejection: {
        category: "wrong-industry",
        detail: `Image tagged for "${candidate.industryId}" but business is "${industryId}".`,
      },
    };
  }

  if (isWrongIndustryUrl(url, industryId)) {
    return {
      accepted: false,
      rejection: {
        category: "wrong-industry",
        detail: `Image belongs to unrelated industry library (not "${industryId}").`,
      },
    };
  }

  if (
    !urlAllowedForSlot(url, kind, industryId, profile.slots) &&
    candidate.sourceTier !== "user"
  ) {
    return {
      accepted: false,
      rejection: {
        category: "wrong-section",
        detail: `Image not allowed for ${kind} slot in ${industryId}.`,
      },
    };
  }

  if (subcategory && rules.subcategories.length > 0) {
    const subMatch = rules.subcategories.some(
      (sub) => subcategory.includes(sub) || sub.includes(subcategory),
    );
    if (!subMatch && candidate.sourceTier === "library") {
      const subForbidden = hasForbiddenSubject(haystack, [subcategory]);
      if (subForbidden) {
        return {
          accepted: false,
          rejection: {
            category: "wrong-subcategory",
            detail: `Image conflicts with subcategory "${subcategory}".`,
          },
        };
      }
    }
  }

  const forbidden = hasForbiddenSubject(haystack, slotRule.forbiddenSubjects);
  if (forbidden) {
    return {
      accepted: false,
      rejection: {
        category: "forbidden-subject",
        detail: `Forbidden subject "${forbidden}" for ${industryId} ${kind}.`,
      },
    };
  }

  if (!allowReuse && usedUrls.has(url)) {
    return {
      accepted: false,
      rejection: {
        category: "duplicate",
        detail: "Duplicate image URL rejected.",
      },
    };
  }

  if (candidate.assignedKind && candidate.assignedKind !== kind) {
    return {
      accepted: false,
      rejection: {
        category: "wrong-section",
        detail: `Image assigned to ${candidate.assignedKind} but used in ${kind}.`,
      },
    };
  }

  if (!checkAspectRatioHint(url, kind) && slotRule.orientation !== "any") {
    return {
      accepted: false,
      rejection: {
        category: "wrong-orientation",
        detail: `Image orientation unsuitable for ${kind} (expected ${slotRule.orientation}).`,
      },
    };
  }

  const wMatch = url.match(/[?&]w=(\d+)/);
  const width = wMatch ? Number(wMatch[1]) : 1600;
  if (width < slotRule.minWidth) {
    return {
      accepted: false,
      rejection: {
        category: "low-quality",
        detail: `Image width ${width}px below minimum ${slotRule.minWidth}px.`,
      },
    };
  }

  return { accepted: true };
}

export type RunIndustryImageRulesInput = {
  slots: SiteImageSlotMap;
  ctx: ImageProfileContext;
  userOverrides?: ImageCandidate[];
};

/**
 * Run the Industry Image Rules Engine: validate all slots, auto-replace rejections,
 * and produce a full validation report.
 */
export function runIndustryImageRulesEngine(
  input: RunIndustryImageRulesInput,
): IndustryImageRulesReport & { slots: SiteImageSlotMap } {
  const detected = detectImageContext(input.ctx);
  const profile = resolveImageProfile(input.ctx).profile;
  const rules = getIndustrySlotRules(detected.industryId);
  const used = new Set<string>();
  const selected: ImageSelectionRecord[] = [];
  const rejected: ImageRejectionRecord[] = [];
  const sourceCounts: Record<ImageSourceTier, number> = {
    user: 0,
    ai: 0,
    library: 0,
    stock: 0,
  };
  let replaced = 0;

  const userBySlotId = new Map(
    (input.userOverrides ?? []).map((u) => [u.url, u]),
  );

  const repaired: SiteImageSlotMap = {
    hero: [],
    gallery: [],
    about: [],
    features: [],
    team: [],
    products: [],
    testimonials: [],
    backgrounds: [],
    cta: [],
  };

  for (const kind of IMAGE_SLOT_KINDS) {
    const minCount = SLOT_MIN_COUNTS[kind];
    const source = input.slots[kind];
    const next: ImageSlotAssignment[] = [];

    for (let i = 0; i < Math.max(minCount, source.length); i += 1) {
      const slot = source[i];
      const slotId = slot?.id ?? `${kind}-${i + 1}`;
      const userOverride = slot?.isUserOverride
        ? slot
        : userBySlotId.get(slot?.url ?? "");

      const resolved = resolveSlotImageSource({
        kind,
        index: i,
        userUrl: userOverride?.url ?? (slot?.isUserOverride ? slot.url : null),
        aiUrl: slot?.sourceTier === "ai" || inferSourceTier(slot ?? {}) === "ai" ? slot?.url : null,
        libraryUrl:
          slot?.sourceTier === "library" || slot?.provider === "premium-stock"
            ? slot?.url
            : profile.slots[kind]?.[i],
        stockUrl: slot?.url,
      });

      let url = resolved?.url ?? slot?.url ?? "";
      let tier = resolved?.sourceTier ?? inferSourceTier(slot ?? {});
      let alt = slot?.alt ?? `${profile.label} ${kind} photography`;

      const validation = validateImageCandidate({
        candidate: {
          url,
          alt,
          provider: slot?.provider,
          sourceTier: tier,
          industryId: slot?.industryId,
          isUserOverride: Boolean(userOverride?.isUserOverride ?? slot?.isUserOverride),
          assignedKind: slot?.kind,
        },
        kind,
        industryId: detected.industryId,
        subcategory: detected.subcategory,
        usedUrls: used,
        allowReuse: profile.allowReuse,
        isUserOverride: Boolean(userOverride?.isUserOverride ?? slot?.isUserOverride),
      });

      if (!validation.accepted && validation.rejection) {
        const replacement = pickReplacement(kind, detected.industryId, used, i);
        rejected.push({
          slotId,
          kind,
          url,
          ...validation.rejection,
          replacedWith: replacement.url,
          replacementTier: replacement.tier,
        });
        url = replacement.url;
        tier = replacement.tier;
        alt = `${profile.label} ${kind} photography`;
        replaced += 1;
      }

      if (url) {
        if (!profile.allowReuse) used.add(url);
        sourceCounts[tier] += 1;
        selected.push({
          slotId,
          kind,
          url,
          sourceTier: tier,
          industryId: detected.industryId,
          accepted: true,
        });
        next.push({
          id: slotId,
          kind,
          url,
          alt,
          industryId: detected.industryId,
          provider: slot?.provider ?? tier,
          sourceTier: tier,
          isUserOverride: Boolean(userOverride?.isUserOverride ?? slot?.isUserOverride),
        });
      }
    }

    while (next.length < minCount) {
      const replacement = pickReplacement(kind, detected.industryId, used, next.length);
      if (!replacement.url) break;
      if (!profile.allowReuse) used.add(replacement.url);
      sourceCounts[replacement.tier] += 1;
      replaced += 1;
      const slotId = `${kind}-${next.length + 1}`;
      selected.push({
        slotId,
        kind,
        url: replacement.url,
        sourceTier: replacement.tier,
        industryId: detected.industryId,
        accepted: true,
      });
      next.push({
        id: slotId,
        kind,
        url: replacement.url,
        alt: `${profile.label} ${kind} photography`,
        industryId: detected.industryId,
        provider: replacement.tier,
        sourceTier: replacement.tier,
      });
      rejected.push({
        slotId,
        kind,
        url: "",
        category: "low-quality",
        detail: `Filled missing ${kind} slot from industry library.`,
        replacedWith: replacement.url,
        replacementTier: replacement.tier,
      });
    }

    repaired[kind] = next;
  }

  const slotCoverage: IndustryImageRulesReport["slotCoverage"] = {};
  let coverageScore = 0;
  for (const kind of IMAGE_SLOT_KINDS) {
    const required = SLOT_MIN_COUNTS[kind];
    const actual = repaired[kind].length;
    const passed = actual >= required;
    slotCoverage[kind] = { required, actual, passed };
    if (passed) coverageScore += 10;
  }

  const rejectionPenalty = Math.min(40, rejected.length * 2);
  const score = Math.max(0, Math.min(100, coverageScore + 20 - rejectionPenalty));
  const passed =
    repaired.hero.length > 0 &&
    rejected.filter((r) => r.category === "wrong-industry").length === 0 &&
    Object.values(slotCoverage).every((c) => c?.passed);

  return {
    passed,
    score,
    detected,
    profileId: profile.id,
    selected,
    rejected,
    replaced,
    sourceCounts,
    slotCoverage,
    summary: passed
      ? `Industry image rules passed for ${profile.label} (${detected.industryId}). ${selected.length} images selected, ${replaced} replaced.`
      : `Industry image rules failed for ${profile.label}: ${rejected.length} rejections.`,
    slots: repaired,
  };
}

