export async function persistAudioArtifact(
  supabase: AnySupabase,
  input: {
    userId: string;
    projectId: string;
    kind: AudioArtifact["kind"];
    bytes: Uint8Array;
    mimeType?: string;
    durationSec: number;
    provider: string;
  },
): Promise<AudioArtifact> {
  const mimeType = assertValidAudioBytes({
    bytes: input.bytes,
    declaredMime: input.mimeType,
    durationSec: input.durationSec,
  });
  const id = randomUUID();
  const ext = mimeType === "audio/mpeg" ? "mp3" : mimeType === "audio/ogg" ? "ogg" : "wav";
  const storagePath = `${input.userId}/${input.projectId}/audio/${id}.${ext}`;
  const { error: uploadError } = await supabase.storage.from(VIDEO_STUDIO_BUCKET).upload(storagePath, input.bytes, {
    contentType: mimeType,
    upsert: false,
  });
  if (uploadError) {
    throw new AudioEngineError(`Audio storage upload failed: ${uploadError.message || "unknown"}`, "provider_failed");
  }
  const signed = await supabase.storage.from(VIDEO_STUDIO_BUCKET).createSignedUrl(storagePath, 60 * 60);
  const url = signed.data?.signedUrl || `storage://${storagePath}`;
  const sha256 = sha256Hex(input.bytes);
  const { data, error } = await supabase
    .from("video_media")
    .insert({
      id,
      user_id: input.userId,
      generation_id: input.projectId,
      kind: input.kind,
      mime_type: mimeType,
      storage_path: storagePath,
      public_url: url,
      size_bytes: input.bytes.byteLength,
      duration_sec: input.durationSec,
      provider: input.provider,
      sha256,
      meta: { audioKind: input.kind },
    })
    .select("*")
    .single();
  throwIfError(error, "video_media.insert");
  const artifact = artifactFromMediaRow(data as AudioMediaRow);
  artifact.bytes = input.bytes;
  if (!isValidAudioArtifact(artifact)) {
    throw new AudioEngineError("Persisted audio artifact failed validation.", "invalid_audio");
  }
  return artifact;
}

export async function loadAudioArtifact(
  supabase: AnySupabase,
  input: { userId: string; artifactId: string },
): Promise<AudioArtifact | null> {
  const { data, error } = await supabase.from("video_media").select("*").eq("id", input.artifactId).maybeSingle();
  throwIfError(error, "video_media.read");
  if (!data) return null;
  const row = data as AudioMediaRow;
  assertAudioOwnership({ ownerId: row.user_id, userId: input.userId });
  const artifact = artifactFromMediaRow(row);
  return isValidAudioArtifact(artifact) ? artifact : null;
}

export async function signAudioArtifactUrl(
  supabase: AnySupabase,
  input: { userId: string; artifactId: string; expiresInSec?: number },
): Promise<string> {
  const { data, error } = await supabase.from("video_media").select("*").eq("id", input.artifactId).maybeSingle();
  throwIfError(error, "video_media.read");
  if (!data) throw new AudioEngineError("Audio artifact not found.", "not_found");
  const row = data as AudioMediaRow;
  assertAudioOwnership({ ownerId: row.user_id, userId: input.userId });
  const signed = await supabase.storage
    .from(VIDEO_STUDIO_BUCKET)
    .createSignedUrl(row.storage_path, input.expiresInSec ?? 3600);
  const url = signed.data?.signedUrl || row.public_url;
  if (!url) throw new AudioEngineError("Signed audio URL could not be created.", "not_found");
  return url;
}

export function mixJobFromRecord(
  job: AudioJobRecord,
  settings: Omit<AudioMixJob, "id" | "projectId" | "audioPlanId" | "status" | "artifactId" | "idempotencyKey" | "attempt" | "estimatedCost" | "actualCost">,
): AudioMixJob {
  return {
    id: job.id,
    projectId: job.projectId,
    audioPlanId: job.audioPlanId || "",
    status: job.status,
    voiceLevel: settings.voiceLevel,
    musicLevel: settings.musicLevel,
    sfxLevel: settings.sfxLevel,
    ducking: settings.ducking,
    normalize: settings.normalize,
    fadeInSec: settings.fadeInSec,
    fadeOutSec: settings.fadeOutSec,
    targetDurationSec: settings.targetDurationSec,
    artifactId: job.artifactId,
    idempotencyKey: job.idempotencyKey,
    attempt: job.attempt,
    estimatedCost: job.estimatedCost,
    actualCost: job.actualCost,
  };
}

export function applyArtifactToVoice(track: VoiceTrack, artifact: AudioArtifact): VoiceTrack {
  return { ...track, artifactId: artifact.id, provider: artifact.provider as VoiceTrack["provider"], status: "succeeded" };
}

export function applyArtifactToMusic(track: MusicTrack, artifact: AudioArtifact): MusicTrack {
  return { ...track, artifactId: artifact.id, provider: artifact.provider, status: "succeeded" };
}

export function applyArtifactToSfx(track: SFXTrack, artifact: AudioArtifact): SFXTrack {
  return { ...track, artifactId: artifact.id, status: "succeeded" };
}

import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import { test } from "node:test";
import { LipSyncError } from "@/lib/ai-core/video-production-platform/lip-sync/errors";
import type { LipSyncJobHandle, LipSyncProvider } from "@/lib/ai-core/video-production-platform/lip-sync/contract";
import { heygenLipSyncProvider } from "@/lib/ai-core/video-production-platform/lip-sync/heygen";
import { clearLipSyncJobCache } from "@/lib/ai-core/video-production-platform/lip-sync/job-cache";
import { resolveLipSyncProvider } from "@/lib/ai-core/video-production-platform/lip-sync/registry";
import { runLipSync } from "@/lib/ai-core/video-production-platform/lip-sync/service";
import { findLipSyncJobByIdempotencyKey, insertLipSyncJob, loadOwnedMedia } from "@/lib/ai-core/video-production-platform/lip-sync/persist";
import { buildLipSyncIdempotencyKey } from "@/lib/ai-core/video-production-platform/lip-sync/job-cache";
import type { MemoryQueryBuilder } from "@/lib/ai-core/video-production-platform/test/memory-query-builder";

const USER = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
const OTHER = "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb";

function contractMp4(): Uint8Array {
  const bytes = new Uint8Array(5000);
  bytes.set([0x00, 0x00, 0x00, 0x18, 0x66, 0x74, 0x79, 0x70, 0x69, 0x73, 0x6f, 0x6d], 0);
  return bytes;
}

function createMemorySupabase() {
  const tables: Record<string, Record<string, unknown>[]> = {
    video_lipsync_jobs: [],
    video_media: [],
  };
  let lastUpload = contractMp4();

  function matches(row: Record<string, unknown>, filters: Array<[string, string, unknown]>) {
    return filters.every(([op, key, value]) => {
      if (op === "eq") return row[key] === value;
      return true;
    });
  }

  function from(table: string) {
    const state: {
      action: string;
      payload: unknown;
      filters: Array<[string, string, unknown]>;
    } = { action: "select", payload: null, filters: [] };

    async function execute(shape: "single" | "maybe" | "many") {
      const rows = tables[table] || (tables[table] = []);
      let data: Record<string, unknown>[] = [];
      let error: { message: string; code?: string } | null = null;
      if (state.action === "insert") {
        const incoming = Array.isArray(state.payload) ? state.payload : [state.payload];
        for (const raw of incoming as Record<string, unknown>[]) {
          if (table === "video_lipsync_jobs" && rows.some((row) => row.idempotency_key === raw.idempotency_key)) {
            error = { code: "23505", message: "duplicate idempotency_key" };
            break;
          }
          const row: Record<string, unknown> = { created_at: new Date().toISOString(), ...raw };
          if (!row.id) row.id = randomUUID();
          rows.push(row);
          data.push(row);
        }
      } else if (state.action === "update") {
        for (const row of rows) {
          if (matches(row, state.filters)) {
            Object.assign(row, state.payload as object);
            data.push(row);
          }
        }
      } else {
        data = rows.filter((row) => matches(row, state.filters));
      }
      if (error) return { data: null, error };
      if (shape === "single") return { data: data[0] || null, error: data[0] ? null : { message: "missing" } };
      if (shape === "maybe") return { data: data[0] || null, error: null };
      return { data, error: null };
    }

    const api: MemoryQueryBuilder = {
      insert(payload: unknown) {
        state.action = "insert";
        state.payload = payload;
        return api;
      },
      update(payload: unknown) {
        state.action = "update";
        state.payload = payload;
        return api;
      },
      select() {
        return api;
      },
      eq(key: string, value: unknown) {
        state.filters.push(["eq", key, value]);
        return api;
      },
      maybeSingle: () => execute("maybe"),
      single: () => execute("single"),
      then(resolve, reject?) {
        return execute("many").then(resolve, reject);
      },
    };
    return api;
  }

  return {
    from,
    storage: {
      from() {
        return {
          async upload(_path: string, bytes: Uint8Array) {
            lastUpload = bytes;
            return { error: null };
          },
          async createSignedUrl() {
            return { data: { signedUrl: "https://signed.example/media" } };
          },
          getPublicUrl() {
            return { data: { publicUrl: "https://signed.example/media" } };
          },
        };
      },
    },
    _tables: tables,
  };
}

async function seedMedia(
  supabase: ReturnType<typeof createMemorySupabase>,
  input: { userId?: string; projectId: string; videoId?: string; audioId?: string },
) {
  const videoId = input.videoId || randomUUID();
  const audioId = input.audioId || randomUUID();
  const userId = input.userId || USER;
  await supabase.from("video_media").insert({
    id: videoId,
    user_id: userId,
    generation_id: input.projectId,
    scene_id: null,
    kind: "clip",
    mime_type: "video/mp4",
    storage_path: `${userId}/${input.projectId}/source.mp4`,
    public_url: "https://signed.example/source.mp4",
    size_bytes: 5000,
    duration_sec: 8,
    provider: "kling",
    sha256: "source-sha",
    width: 1280,
    height: 720,
  });
  await supabase.from("video_media").insert({
    id: audioId,
    user_id: userId,
    generation_id: input.projectId,
    scene_id: null,
    kind: "voice",
    mime_type: "audio/mpeg",
    storage_path: `${userId}/${input.projectId}/voice.mp3`,
    public_url: "https://signed.example/voice.mp3",
    size_bytes: 512,
    duration_sec: 8,
    provider: "openai",
    sha256: "audio-sha",
  });
  return { videoId, audioId };
}

function mockLipSync(behavior: { failFirst?: boolean; invalid?: boolean; processingFirst?: boolean } = {}): LipSyncProvider & { createCalls: number } {
  let createCalls = 0;
  const succeed = (idempotencyKey: string): LipSyncJobHandle => ({
    provider: "heygen",
    status: "succeeded",
    idempotencyKey,
    mimeType: "video/mp4",
    bytes: behavior.invalid ? new Uint8Array([0x3c, 0x73, 0x76, 0x67]) : contractMp4(),
    durationSec: 8,
    width: 1280,
    height: 720,
    message: behavior.invalid ? "invalid" : "ok",
  });
  const provider: LipSyncProvider & { createCalls: number } = {
    id: "heygen",
    label: "Mock HeyGen",
    createCalls: 0,
    status: () => "ready",
    capabilities: () => ({
      languages: ["en"],
      modes: ["precision"],
      requiresHttpsAssets: true,
      maxDurationSec: 60,
    }),
    estimateCost: ({ durationSec }) => ({
      provider: "heygen",
      credits: Math.max(2, Math.ceil(durationSec / 4)),
      currency: "credits",
      durationSec,
    }),
    health: () => ({ ok: true, status: "ready", reason: "mock" }),
    async createJob(request) {
      createCalls += 1;
      provider.createCalls = createCalls;
      if (behavior.failFirst && createCalls === 1) {
        return {
          provider: "heygen",
          status: "failed",
          idempotencyKey: request.idempotencyKey,
          message: "provider down",
          errorCode: "provider_failed",
        };
      }
      if (behavior.processingFirst && createCalls === 1) {
        return {
          provider: "heygen",
          status: "processing",
          idempotencyKey: request.idempotencyKey,
          externalJobId: "ext-1",
          message: "queued",
        };
      }
      return succeed(request.idempotencyKey);
    },
    async pollJob(_id, idempotencyKey) {
      return succeed(idempotencyKey);
    },
  };
  return provider;
}

