function unescapeHtml(text: string): string {
  return text
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

function readConfigFromAttrs(attrs: string): string | undefined {
  const patterns = [
    new RegExp(`${WB_ICON_CONFIG_ATTR}\\s*=\\s*"((?:\\\\.|[^"\\\\])*)"`, "i"),
    new RegExp(`${WB_ICON_CONFIG_ATTR}\\s*=\\s*'((?:\\\\.|[^'\\\\])*)'`, "i"),
  ];
  for (const re of patterns) {
    const match = attrs.match(re);
    if (match?.[1]) return unescapeHtml(match[1]);
  }
  return undefined;
}

function readIdFromAttrs(attrs: string): string | undefined {
  const match = attrs.match(
    new RegExp(`${WB_ICON_ID_ATTR}\\s*=\\s*("([^"]*)"|'([^']*)')`, "i"),
  );
  return match?.[2] ?? match?.[3];
}

function readIconNameFromComment(inner: string): string | undefined {
  const match = inner.match(/\{\/\*\s*wb-icon(?:-(?:left|right))?:([A-Za-z0-9]+)\s*\*\/\}/);
  return match?.[1];
}

function readButtonIconConfig(attrs: string, side: "left" | "right"): string | undefined {
  const attr = `data-wb-icon-${side}-config`;
  const patterns = [
    new RegExp(`${attr}\\s*=\\s*"((?:\\\\.|[^"\\\\])*)"`, "i"),
    new RegExp(`${attr}\\s*=\\s*'((?:\\\\.|[^'\\\\])*)'`, "i"),
  ];
  for (const re of patterns) {
    const match = attrs.match(re);
    if (match?.[1]) return unescapeHtml(match[1]);
  }
  return undefined;
}

function buttonPosition(icon: VisualButton["icon"]): IconPosition {
  if (icon === "left" || icon === "right") return icon;
  return "none";
}

function buttonToIcon(button: VisualButton, exportName: string): VisualIcon | null {
  if (button.icon === "none" && !button.iconName) return null;
  const name = resolveIconName(button.iconName || "ArrowRight");
  const base = createDefaultIcon({
    id: `${button.id}-icon`,
    name,
    label: button.label ? `${button.label} icon` : "Button icon",
    kind: "button",
    sourceKind: "button",
    sourceIndex: button.sourceIndex,
    sectionExportName: exportName,
    position: buttonPosition(button.icon),
    buttonId: button.id,
    decorative: !button.ariaLabel.trim(),
    ariaLabel: button.ariaLabel,
  });
  return base;
}

function parseNavItemBlock(block: string): {
  href: string;
  label: string;
  icon?: string;
  iconConfig?: string;
} {
  const hrefMatch = block.match(/href:\s*("([^"]*)"|'([^']*)')/);
  const labelMatch = block.match(/label:\s*("([^"]*)"|'([^']*)')/);
  const iconMatch = block.match(/icon:\s*("([^"]*)"|'([^']*)')/);
  const configMatch = block.match(
    /iconConfig:\s*("((?:\\.|[^"\\])*)"|'((?:\\.|[^'\\])*)')/,
  );
  return {
    href: hrefMatch?.[2] ?? hrefMatch?.[3] ?? "",
    label: labelMatch?.[2] ?? labelMatch?.[3] ?? "",
    icon: iconMatch?.[2] ?? iconMatch?.[3],
    iconConfig: configMatch?.[2]
      ? configMatch[2].replace(/\\"/g, '"').replace(/\\\\/g, "\\")
      : configMatch?.[3],
  };
}

function parseLinksArrayLiteral(
  source: string,
  varName: string,
): Array<{ href: string; label: string; icon?: string; iconConfig?: string }> {
  const re = new RegExp(
    `(?:const|let)\\s+${varName}\\s*=\\s*(\\[[\\s\\S]*?\\])\\s*;`,
    "i",
  );
  const match = source.match(re);
  if (!match?.[1]) return [];

  const items: Array<{
    href: string;
    label: string;
    icon?: string;
    iconConfig?: string;
  }> = [];
  const body = match[1]!;
  let depth = 0;
  let start = -1;
  for (let i = 0; i < body.length; i += 1) {
    const ch = body[i]!;
    if (ch === "{") {
      if (depth === 0) start = i;
      depth += 1;
    } else if (ch === "}") {
      depth -= 1;
      if (depth === 0 && start >= 0) {
        items.push(parseNavItemBlock(body.slice(start, i + 1)));
        start = -1;
      }
    }
  }
  return items;
}

function inferKindFromSection(exportName: string, kindHint?: string): IconElementKind {
  if (/SiteHeader|Nav/i.test(exportName) || kindHint === "header") return "nav";
  if (/SiteFooter|Footer/i.test(exportName) || kindHint === "footer") return "footer";
  if (/Hero/i.test(exportName) || kindHint === "hero") return "hero";
  if (/Feature/i.test(exportName)) return "feature";
  if (/Service/i.test(exportName)) return "service";
  if (/Contact/i.test(exportName)) return "contact";
  if (/Cta|CTA/i.test(exportName) || kindHint === "cta") return "cta";
  if (/Info/i.test(exportName)) return "info";
  return "inline";
}

function findInlineIconSpans(source: string): Array<{
  index: number;
  attrs: string;
  inner: string;
  kind: IconElementKind;
}> {
  const spans: Array<{
    index: number;
    attrs: string;
    inner: string;
    kind: IconElementKind;
  }> = [];
  const tagRe = /<span\b([^>]*className\s*=\s*["'][^"']*wb-icon[^"']*["'][^>]*)>([\s\S]*?)<\/span>/gi;
  let match: RegExpExecArray | null;
  let index = 0;
  while ((match = tagRe.exec(source))) {
    spans.push({
      index,
      attrs: match[1] ?? "",
      inner: match[2] ?? "",
      kind: "inline",
    });
    index += 1;
  }

  const configRe = new RegExp(
    `<span\\b([^>]*${WB_ICON_CONFIG_ATTR}[^>]*)>([\\s\\S]*?)<\\/span>`,
    "gi",
  );
  while ((match = configRe.exec(source))) {
    if (spans.some((s) => s.attrs === match![1])) continue;
    spans.push({
      index,
      attrs: match[1] ?? "",
      inner: match[2] ?? "",
      kind: "inline",
    });
    index += 1;
  }

  return spans;
}

function findListItemIcons(
  source: string,
  sectionKind: IconElementKind,
): Array<{ index: number; label: string }> {
  const items: Array<{ index: number; label: string }> = [];
  if (/<nav\b/i.test(source) || /<footer\b/i.test(source)) return items;
  const liRe = /<li\b[^>]*>([\s\S]*?)<\/li>/gi;
  let match: RegExpExecArray | null;
  let index = 0;
  while ((match = liRe.exec(source))) {
    const inner = match[1] ?? "";
    if (/wb-icon/.test(inner) || inner.includes(WB_ICON_CONFIG_ATTR)) {
      index += 1;
      continue;
    }
    const label = unescapeHtml(inner.replace(/<[^>]+>/g, "").trim()).slice(0, 80);
    if (label) items.push({ index, label });
    index += 1;
  }
  if (items.length && sectionKind === "inline") {
    return items.map((item) => ({ ...item }));
  }
  return items;
}

function findSocialIcons(source: string, exportName: string): VisualIcon[] {
  const icons: VisualIcon[] = [];
  const socialRe =
    /<a\b([^>]*href\s*=\s*["'][^"']*(?:instagram|twitter|linkedin|facebook|youtube|x\.com)[^"']*["'][^>]*)>([\s\S]*?)<\/a>/gi;
  let match: RegExpExecArray | null;
  let index = 0;
  while ((match = socialRe.exec(source))) {
    const attrs = match[1] ?? "";
    const config = parseIconConfig(readConfigFromAttrs(attrs));
    const base = createDefaultIcon({
      id: `${exportName}-social-${index}`,
      name: "Share2",
      label: "Social link",
      kind: "social",
      sourceKind: "inline",
      sourceIndex: index,
      sectionExportName: exportName,
      position: "left",
    });
    icons.push(mergeIconConfig(base, config));
    index += 1;
  }
  return icons;
}

function findContactIcons(source: string, exportName: string): VisualIcon[] {
  const icons: VisualIcon[] = [];
  const contactRe =
    /<a\b([^>]*href\s*=\s*["'](?:mailto:|tel:)[^"']*["'][^>]*)>([\s\S]*?)<\/a>/gi;
  let match: RegExpExecArray | null;
  let index = 0;
  while ((match = contactRe.exec(source))) {
    const attrs = match[1] ?? "";
    const href = attrs.match(/href\s*=\s*["']([^"']*)["']/i)?.[1] ?? "";
    const defaultName = href.startsWith("mailto:") ? "Mail" : "Phone";
    const config = parseIconConfig(readConfigFromAttrs(attrs));
    const base = createDefaultIcon({
      id: `${exportName}-contact-${index}`,
      name: defaultName,
      label: href.startsWith("mailto:") ? "Email" : "Phone",
      kind: "contact",
      sourceKind: "inline",
      sourceIndex: index,
      sectionExportName: exportName,
      position: "left",
    });
    icons.push(mergeIconConfig(base, config));
    index += 1;
  }
  return icons;
}

function enrichButtonIconsFromSource(
  icons: VisualIcon[],
  componentSource: string | undefined,
): VisualIcon[] {
  if (!componentSource) return icons;
  const tagRe = /<(a|button)\b([^>]*)>([\s\S]*?)<\/\1>/gi;
  let match: RegExpExecArray | null;
  let anchorIndex = 0;
  let buttonIndex = 0;

  while ((match = tagRe.exec(componentSource))) {
    const tag = match[1]!.toLowerCase();
    const attrs = match[2] ?? "";
    const inner = match[3] ?? "";
    const index = tag === "a" ? anchorIndex++ : buttonIndex++;

    for (const side of ["left", "right"] as const) {
      const iconAttr = attrs.match(
        new RegExp(`data-wb-icon-${side}\\s*=\\s*("([^"]*)"|'([^']*)')`, "i"),
      );
      const iconName = iconAttr?.[2] ?? iconAttr?.[3];
      const configRaw =
        readButtonIconConfig(attrs, side) ?? readConfigFromAttrs(attrs);
      const commentName = readIconNameFromComment(inner);
      const resolvedName = resolveIconName(iconName ?? commentName);

      const iconId = readIdFromAttrs(attrs);
      const existing = icons.find(
        (ic) =>
          ic.sourceKind === "button" &&
          ic.sourceIndex === index &&
          ic.position === side,
      );

      if (!existing && !iconName && !commentName) continue;

      const base = createDefaultIcon({
        id: iconId ?? `${existing?.id ?? `btn-${index}-${side}`}`,
        name: resolvedName,
        label: existing?.label ?? `${side} icon`,
        kind: "button",
        sourceKind: "button",
        sourceIndex: index,
        sectionExportName: existing?.sectionExportName ?? "",
        position: side,
        buttonId: existing?.buttonId,
      });
      const merged = mergeIconConfig(base, parseIconConfig(configRaw));
      if (existing) {
        const idx = icons.indexOf(existing);
        icons[idx] = { ...merged, id: existing.id, buttonId: existing.buttonId };
      } else {
        icons.push(merged);
      }
    }
  }
  return icons;
}

export function extractIconsFromSection(params: {
  exportName: string;
  componentSource?: string;
  pageSource?: string;
  kindHint?: string;
}): VisualIcon[] {
  const { exportName, componentSource, pageSource, kindHint } = params;
  const icons: VisualIcon[] = [];
  const sectionKind = inferKindFromSection(exportName, kindHint);

  const buttons = extractButtonsFromSection({
    exportName,
    componentSource,
    pageSource,
  });
  for (const button of buttons) {
    const icon = buttonToIcon(button, exportName);
    if (icon) icons.push(icon);
  }

  if (componentSource) {
    if (/SiteHeader|NavModern/i.test(exportName)) {
      const navItems =
        parseLinksArrayLiteral(componentSource, "links") ||
        parseLinksArrayLiteral(componentSource, "NAV") ||
        parseLinksArrayLiteral(componentSource, "navLinks");
      navItems.forEach((item, index) => {
        const config = parseIconConfig(item.iconConfig);
        const name = resolveIconName(item.icon);
        const base = createDefaultIcon({
          id: `${exportName}-nav-icon-${index}`,
          name,
          label: item.label ? `${item.label} icon` : "Nav icon",
          kind: "nav",
          sourceKind: "array",
          sourceIndex: index,
          sectionExportName: exportName,
          arrayPropName: "links",
          position: "left",
          linkId: `${exportName}-nav-${index}`,
        });
        icons.push(mergeIconConfig(base, config));
      });
    }

    for (const span of findInlineIconSpans(componentSource)) {
      const config = parseIconConfig(readConfigFromAttrs(span.attrs));
      const commentName = readIconNameFromComment(span.inner);
      const id = readIdFromAttrs(span.attrs) ?? `${exportName}-icon-${span.index}`;
      const base = createDefaultIcon({
        id,
        name: resolveIconName(commentName),
        label: "Icon",
        kind: span.kind,
        sourceKind: "inline",
        sourceIndex: span.index,
        sectionExportName: exportName,
      });
      icons.push(mergeIconConfig(base, config));
    }

    const listKind =
      sectionKind === "feature" || sectionKind === "service" || sectionKind === "list"
        ? sectionKind
        : sectionKind === "hero"
          ? "hero"
          : "list";
    findListItemIcons(componentSource, listKind).forEach((item, idx) => {
      icons.push(
        createDefaultIcon({
          id: `${exportName}-list-${item.index}`,
          name: "Check",
          label: item.label,
          kind: listKind,
          sourceKind: "inline",
          sourceIndex: item.index,
          sectionExportName: exportName,
          position: "left",
        }),
      );
    });

    icons.push(...findSocialIcons(componentSource, exportName));
    icons.push(...findContactIcons(componentSource, exportName));
  }

  enrichButtonIconsFromSource(icons, componentSource);

  const deduped = new Map<string, VisualIcon>();
  for (const icon of icons) {
    deduped.set(icon.id, icon);
  }
  return [...deduped.values()];
}

/**
 * Apply icon edits to generated TSX source files.
 */

import {
  applyButtonToPageSource,
  applyButtonToSectionSource,
} from "@/lib/ai-core/visual-editor/button-persist";
import type { VisualButton } from "@/lib/ai-core/visual-editor/button-types";
import {
  serializeIconConfig,
  WB_ICON_CLASS,
  WB_ICON_CONFIG_ATTR,
  WB_ICON_ID_ATTR,
  type PersistedArrayIcon,
} from "@/lib/ai-core/visual-editor/icon-config";
import { iconWrapperStyle } from "@/lib/ai-core/visual-editor/icon-styles";
import type { VisualIcon } from "@/lib/ai-core/visual-editor/icon-types";
import {
  parseComponentInvocation,
  updateComponentJsxStringProp,
} from "@/lib/ai-core/visual-editor/hydrate-node-text";
import type { CSSProperties } from "react";

function escapeJsxAttr(value: string): string {
  return value.replace(/"/g, "&quot;");
}

function styleToJsxObject(style: CSSProperties): string {
  const entries = Object.entries(style).filter(
    ([, value]) => value !== undefined && value !== null && value !== "",
  );
  if (!entries.length) return "";
  const body = entries
    .map(([key, value]) => `${key}: ${JSON.stringify(String(value))}`)
    .join(", ");
  return ` style={{ ${body} }}`;
}

function iconComment(name: string, position?: "left" | "right"): string {
  if (position) return `{/* wb-icon-${position}:${name} */}`;
  return `{/* wb-icon:${name} */}`;
}

function buildIconSpan(icon: VisualIcon, position?: "left" | "right"): string {
  const config = serializeIconConfig(icon);
  const attrs = [
    `className="${WB_ICON_CLASS}"`,
    `${WB_ICON_ID_ATTR}="${escapeJsxAttr(icon.id)}"`,
    `${WB_ICON_CONFIG_ATTR}="${escapeJsxAttr(config)}"`,
    `aria-hidden="${icon.decorative ? "true" : "false"}"`,
  ];
  if (!icon.decorative && icon.ariaLabel.trim()) {
    attrs.push(`aria-label="${escapeJsxAttr(icon.ariaLabel)}"`);
  }
  return `<span ${attrs.join(" ")}${styleToJsxObject(iconWrapperStyle(icon))}>${iconComment(icon.name, position)}</span>`;
}

function buttonIconPosition(icon: VisualIcon): VisualButton["icon"] {
  if (icon.position === "left" || icon.position === "right") return icon.position;
  return icon.name ? "left" : "none";
}

function iconToButtonPatch(icon: VisualIcon): Partial<VisualButton> {
  return {
    icon: buttonIconPosition(icon),
    iconName: icon.name,
    ariaLabel: icon.decorative ? "" : icon.ariaLabel,
  };
}

function patchButtonIconAttrs(
  source: string,
  icon: VisualIcon,
): string | null {
  const tagRe = /<(a|button)\b[^>]*>[\s\S]*?<\/\1>/gi;
  const matches: RegExpExecArray[] = [];
  let match: RegExpExecArray | null;
  while ((match = tagRe.exec(source))) {
    matches.push(match);
  }
  const target = matches[icon.sourceIndex];
  if (!target || target.index === undefined) return null;

  const tag = target[0].match(/<(a|button)\b/i)?.[1]?.toLowerCase() ?? "a";
  const side = icon.position === "right" ? "right" : "left";
  const config = serializeIconConfig(icon);
  let attrs = target[0].match(new RegExp(`<${tag}\\b([^>]*)>`, "i"))?.[1] ?? "";

  attrs = attrs
    .replace(new RegExp(`data-wb-icon-${side}\\s*=\\s*("([^"]*)"|'([^']*)')`, "gi"), "")
    .replace(
      new RegExp(`data-wb-icon-${side}-config\\s*=\\s*("([^"]*)"|'([^']*)')`, "gi"),
      "",
    )
    .trim();

  if (icon.position !== "none" && icon.name) {
    attrs += ` data-wb-icon-${side}="${escapeJsxAttr(icon.name)}"`;
    attrs += ` data-wb-icon-${side}-config="${escapeJsxAttr(config)}"`;
  }

  let inner = target[0].replace(new RegExp(`^<${tag}\\b[^>]*>|</${tag}>$`, "gi"), "");
  inner = inner.replace(
    new RegExp(`\\{\\/\\*\\s*wb-icon-${side}:[A-Za-z0-9]+\\s*\\*\\/\\}`, "g"),
    "",
  );
  inner = inner.replace(
    new RegExp(
      `<span\\b[^>]*${WB_ICON_CLASS}[^>]*>[\\s\\S]*?<\\/span>`,
      "gi",
    ),
    "",
  );

  const parts: string[] = [];
  if (side === "left" && icon.position !== "none" && icon.name) {
    parts.push(buildIconSpan(icon, "left"));
  }
  parts.push(inner.trim());
  if (side === "right" && icon.position !== "none" && icon.name) {
    parts.push(buildIconSpan(icon, "right"));
  }

  const replacement = `<${tag} ${attrs}>${parts.join("")}</${tag}>`;
  return (
    source.slice(0, target.index) +
    replacement +
    source.slice(target.index + target[0].length)
  );
}

function parseNavArrayFromSource(
  sectionSource: string,
): { varName: string; body: string } | null {
  const patterns = ["links", "NAV", "navLinks"];
  for (const varName of patterns) {
    const re = new RegExp(
      `const\\s+${varName}\\s*=\\s*(\\[[\\s\\S]*?\\])\\s*;`,
      "i",
    );
    const match = sectionSource.match(re);
    if (match?.[1]) return { varName, body: match[1] };
  }
  return null;
}

function parseNavItems(body: string): PersistedArrayIcon[] {
  const items: PersistedArrayIcon[] = [];
  let depth = 0;
  let start = -1;
  for (let i = 0; i < body.length; i += 1) {
    const ch = body[i]!;
    if (ch === "{") {
      if (depth === 0) start = i;
      depth += 1;
    } else if (ch === "}") {
      depth -= 1;
      if (depth === 0 && start >= 0) {
        const block = body.slice(start, i + 1);
        const hrefMatch = block.match(/href:\s*("([^"]*)"|'([^']*)')/);
        const labelMatch = block.match(/label:\s*("([^"]*)"|'([^']*)')/);
        const iconMatch = block.match(/icon:\s*("([^"]*)"|'([^']*)')/);
        const configMatch = block.match(
          /iconConfig:\s*("((?:\\.|[^"\\])*)"|'((?:\\.|[^'\\])*)')/,
        );
        items.push({
          href: hrefMatch?.[2] ?? hrefMatch?.[3] ?? "#",
          label: labelMatch?.[2] ?? labelMatch?.[3] ?? "Link",
          icon: iconMatch?.[2] ?? iconMatch?.[3],
          iconConfig: configMatch?.[2]
            ? configMatch[2].replace(/\\"/g, '"').replace(/\\\\/g, "\\")
            : configMatch?.[3],
        });
        start = -1;
      }
    }
  }
  return items;
}

function iconsArrayLiteral(items: PersistedArrayIcon[]): string {
  return `[${items
    .map((item) => {
      const parts = [
        `href: ${JSON.stringify(item.href)}`,
        `label: ${JSON.stringify(item.label)}`,
      ];
      if (item.icon) parts.push(`icon: ${JSON.stringify(item.icon)}`);
      if (item.iconConfig) parts.push(`iconConfig: ${JSON.stringify(item.iconConfig)}`);
      return `{ ${parts.join(", ")} }`;
    })
    .join(", ")}]`;
}

function patchNavArrayIcon(sectionSource: string, icon: VisualIcon): string | null {
  const parsed = parseNavArrayFromSource(sectionSource);
  if (!parsed) return null;

  const items = parseNavItems(parsed.body);
  while (items.length <= icon.sourceIndex) {
    items.push({ href: "#", label: "Link" });
  }
  items[icon.sourceIndex] = {
    ...items[icon.sourceIndex]!,
    icon: icon.name,
    iconConfig: serializeIconConfig(icon),
  };

  const literal = iconsArrayLiteral(items);
  const re = new RegExp(
    `const\\s+${parsed.varName}\\s*=\\s*\\[[\\s\\S]*?\\]\\s*;`,
    "i",
  );
  return sectionSource.replace(re, `const ${parsed.varName} = ${literal};`);
}

function replaceListItemByIndex(
  source: string,
  index: number,
  icon: VisualIcon,
): string | null {
  const liRe = /<li\b([^>]*)>([\s\S]*?)<\/li>/gi;
  let match: RegExpExecArray | null;
  let i = 0;
  while ((match = liRe.exec(source))) {
    if (i !== index) {
      i += 1;
      continue;
    }
    if (match.index === undefined) return null;
    let inner = match[2] ?? "";
    inner = inner.replace(
      new RegExp(`<span\\b[^>]*${WB_ICON_CLASS}[^>]*>[\\s\\S]*?<\\/span>`, "gi"),
      "",
    );
    inner = inner.replace(/\{\/\*\s*wb-icon:[A-Za-z0-9]+\s*\*\/\}/g, "").trim();
    const span = buildIconSpan(icon);
    const replacement = `<li${match[1] ?? ""}>${span}${inner ? ` ${inner}` : ""}</li>`;
    return (
      source.slice(0, match.index) +
      replacement +
      source.slice(match.index + match[0].length)
    );
  }
  return null;
}

function replaceInlineIconByIndex(
  source: string,
  index: number,
  icon: VisualIcon,
): string | null {
  const tagRe = new RegExp(
    `<span\\b[^>]*(?:${WB_ICON_CLASS}|${WB_ICON_CONFIG_ATTR})[^>]*>[\\s\\S]*?<\\/span>`,
    "gi",
  );
  let match: RegExpExecArray | null;
  let i = 0;
  while ((match = tagRe.exec(source))) {
    if (i !== index) {
      i += 1;
      continue;
    }
    if (match.index === undefined) return null;
    return (
      source.slice(0, match.index) +
      buildIconSpan(icon) +
      source.slice(match.index + match[0].length)
    );
  }
  return null;
}

function replaceAnchorByIndex(
  source: string,
  index: number,
  icon: VisualIcon,
): string | null {
  const tagRe = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi;
  let match: RegExpExecArray | null;
  let i = 0;
  while ((match = tagRe.exec(source))) {
    if (i !== index) {
      i += 1;
      continue;
    }
    if (match.index === undefined) return null;
    const attrs = match[1] ?? "";
    let inner = match[2] ?? "";
    inner = inner.replace(
      new RegExp(`<span\\b[^>]*${WB_ICON_CLASS}[^>]*>[\\s\\S]*?<\\/span>`, "gi"),
      "",
    );
    const config = serializeIconConfig(icon);
    let nextAttrs = attrs
      .replace(new RegExp(`${WB_ICON_CONFIG_ATTR}\\s*=\\s*("([^"]*)"|'([^']*)')`, "gi"), "")
      .trim();
    nextAttrs += ` ${WB_ICON_CONFIG_ATTR}="${escapeJsxAttr(config)}"`;
    if (!icon.decorative && icon.ariaLabel.trim()) {
      nextAttrs = nextAttrs.replace(/aria-label\s*=\s*("([^"]*)"|'([^']*)')/gi, "");
      nextAttrs += ` aria-label="${escapeJsxAttr(icon.ariaLabel)}"`;
    }
    const span = buildIconSpan(icon);
    const replacement = `<a ${nextAttrs}>${span}${inner.trim() ? ` ${inner.trim()}` : ""}</a>`;
    return (
      source.slice(0, match.index) +
      replacement +
      source.slice(match.index + match[0].length)
    );
  }
  return null;
}

export function applyIconToSectionSource(
  sectionSource: string,
  icon: VisualIcon,
  button?: VisualButton,
): string | null {
  if (icon.kind === "nav" && icon.sourceKind === "array") {
    return patchNavArrayIcon(sectionSource, icon);
  }

  if (icon.kind === "list" || icon.kind === "feature" || icon.kind === "service") {
    const listPatch = replaceListItemByIndex(sectionSource, icon.sourceIndex, icon);
    if (listPatch) return listPatch;
  }

  if (icon.kind === "contact" || icon.kind === "social") {
    const anchorPatch = replaceAnchorByIndex(sectionSource, icon.sourceIndex, icon);
    if (anchorPatch) return anchorPatch;
  }

  if (icon.sourceKind === "inline") {
    const inlinePatch = replaceInlineIconByIndex(sectionSource, icon.sourceIndex, icon);
    if (inlinePatch) return inlinePatch;
  }

  if (icon.kind === "button" || icon.buttonId || icon.sourceKind === "button") {
    let next = sectionSource;
    if (button) {
      const nextButton = { ...button, ...iconToButtonPatch(icon) };
      const buttonPatch = applyButtonToSectionSource(sectionSource, nextButton);
      if (buttonPatch) next = buttonPatch;
    }
    const iconPatch = patchButtonIconAttrs(next, icon);
    return iconPatch ?? next;
  }

  return replaceInlineIconByIndex(sectionSource, icon.sourceIndex, icon);
}

export function applyIconToPageSource(
  pageSource: string,
  exportName: string,
  icon: VisualIcon,
  button?: VisualButton,
): string | null {
  if (!button || button.sourceKind !== "prop") return null;
  const nextButton = { ...button, ...iconToButtonPatch(icon) };
  return applyButtonToPageSource(pageSource, exportName, nextButton);
}

export function serializeIcon(icon: VisualIcon): string {
  return JSON.stringify(icon);
}

export function iconsEqual(a: VisualIcon, b: VisualIcon): boolean {
  return serializeIcon(a) === serializeIcon(b);
}

