  parseLinkConfig,
  WB_LINK_CONFIG_ATTR,
} from "@/lib/ai-core/visual-editor/link-config";
import {
  inferLinkType,
  parseRelAttribute,
  stripHrefForEditor,
} from "@/lib/ai-core/visual-editor/link-format";
