      if (page.sectionIds.length <= 1) {
        throw new WebsiteEditorError("A page must keep at least one section.", "illegal_delete");
      }
      next.components = next.components.filter((item) => item.sectionId !== section.id);
      next.sections = next.sections.filter((item) => item.id !== section.id);
      const sectionIds = page.sectionIds.filter((id) => id !== section.id);
      next.pages = next.pages.map((item) => (item.id === page.id ? { ...item, sectionIds } : item));
      next.sections = next.sections.map((item) =>
        item.pageId === page.id ? { ...item, order: sectionIds.indexOf(item.id) } : item,
      );
      break;
    }
    case "deleteComponent": {
      const component = findComponent(next, command.componentId);
      const section = findSection(next, component.sectionId);
      const rooted = next.components.filter(
        (item) => item.id === component.id || hasAncestor(next.components, item.id, component.id),
      );
      if (section.componentIds.length - rooted.length < 1) {
        throw new WebsiteEditorError("A section must keep at least one component.", "illegal_delete");
      }
      const removed = new Set(rooted.map((item) => item.id));
      next.components = next.components
        .filter((item) => !removed.has(item.id))
        .map((item) =>
          item.sectionId === section.id &&
          item.parentComponentId === component.parentComponentId &&
          item.order > component.order
            ? { ...item, order: item.order - 1 }
            : item,
        );
      next.sections = next.sections.map((item) =>
        item.id === section.id ? { ...item, componentIds: item.componentIds.filter((id) => !removed.has(id)) } : item,
      );
      break;
    }
    default:
      throw new WebsiteEditorError("Command cannot mutate the plan.", "invalid_input");
  }
  return syncHomepageSeo(touch(next, at));
}

function hasAncestor(components: WebsiteComponent[], id: string, ancestorId: string): boolean {
  let current = components.find((item) => item.id === id);
  const seen = new Set<string>();
  while (current?.parentComponentId) {
    if (current.parentComponentId === ancestorId) return true;
    if (seen.has(current.id)) return false;
    seen.add(current.id);
    current = components.find((item) => item.id === current?.parentComponentId);
  }
  return false;
}

export function openWebsiteEditor(params: {
  structure: WebsiteGeneratedStructure;
  actorUserId: string;
  sessionId?: string;
  now?: () => string;
}): WebsiteEditorSession {
  assertActiveEditablePlan(params.structure, params.actorUserId);
  const at = params.now?.() ?? new Date().toISOString();
  const homepage = params.structure.pages.find((page) => page.isHomepage)!;
  return {
    id: params.sessionId ?? randomUUID(),
    userId: params.actorUserId,
    projectId: params.structure.project.id,
    planId: params.structure.plan.id,
    selection: { pageId: homepage.id, sectionId: homepage.sectionIds[0] ?? null, componentId: null },
    structure: cloneStructure(params.structure),
    history: emptyEditorHistory(),
    autosave: { dirty: false, revision: 0, savedAt: at },
    appliedCommandKeys: [],
    updatedAt: at,
  };
}

export function applyEditorCommand(input: ApplyEditorCommandInput & { createId?: () => string; now?: () => string }): WebsiteEditorSession {
  assertEditorSessionOwnership(input.session, input.actorUserId);
  const at = input.now?.() ?? new Date().toISOString();
  const createId = input.createId ?? randomUUID;

  if (input.idempotencyKey && input.session.appliedCommandKeys.includes(input.idempotencyKey)) {
    return input.session;
  }

  const command = input.command;
  if (command.type === "selectPage" || command.type === "selectSection" || command.type === "selectComponent") {
    assertSelection(input.session.structure, command);
    const selection: EditorSelection =
      command.type === "selectPage"
        ? { pageId: command.pageId, sectionId: null, componentId: null }
        : command.type === "selectSection"
          ? { pageId: command.pageId, sectionId: command.sectionId, componentId: null }
          : { pageId: command.pageId, sectionId: command.sectionId, componentId: command.componentId };
    return {
      ...input.session,
      selection,
      updatedAt: at,
      appliedCommandKeys: input.idempotencyKey
        ? [...input.session.appliedCommandKeys, input.idempotencyKey].slice(-100)
        : input.session.appliedCommandKeys,
    };
  }

  if (command.type === "autosave") {
    return {
      ...input.session,
      autosave: { dirty: false, revision: input.session.autosave.revision, savedAt: at },
      updatedAt: at,
      appliedCommandKeys: input.idempotencyKey
        ? [...input.session.appliedCommandKeys, input.idempotencyKey].slice(-100)
        : input.session.appliedCommandKeys,
    };
  }

  if (command.type === "undo") {
    const undone = undoEditorHistory(input.session.history, input.session.structure);
    assertEditorStructure(undone.structure, input.actorUserId);
    return {
      ...input.session,
      structure: undone.structure,
      history: undone.history,
      selection: remapSelection(input.session.selection, undone.structure),
      autosave: { dirty: true, revision: input.session.autosave.revision + 1, savedAt: input.session.autosave.savedAt },
      updatedAt: at,
    };
  }

  if (command.type === "redo") {
    const redone = redoEditorHistory(input.session.history, input.session.structure);
    assertEditorStructure(redone.structure, input.actorUserId);
    return {
      ...input.session,
      structure: redone.structure,
      history: redone.history,
      selection: remapSelection(input.session.selection, redone.structure),
      autosave: { dirty: true, revision: input.session.autosave.revision + 1, savedAt: input.session.autosave.savedAt },
      updatedAt: at,
    };
  }

  const history = pushEditorHistory(input.session.history, input.session.structure);
  const structure = applyMutation(input.session.structure, command, createId, at);
  assertEditorStructure(structure, input.actorUserId);
  return {
    ...input.session,
    structure,
    history,
    selection: remapSelection(input.session.selection, structure),
    autosave: { dirty: true, revision: input.session.autosave.revision + 1, savedAt: input.session.autosave.savedAt },
    updatedAt: at,
    appliedCommandKeys: input.idempotencyKey
      ? [...input.session.appliedCommandKeys, input.idempotencyKey].slice(-100)
      : input.session.appliedCommandKeys,
  };
}

/**
 * Pre-delivery validation for Website Builder generations.
 * Checks industry, images, language, RTL, pages, and hero alignment.
 */

import type { GeneratedProjectFile } from "@/lib/ai/types";
import type { AssetManifest } from "@/plugins/website/types";
import {
  detectIndustryFromPrompt,
  isArabicPrompt,
  type PromptIndustryMatch,
} from "@/lib/ai-core/website-builder/prompt-industry";
import { resolveContentLanguage } from "@/lib/ai-core/content/content-language";
import {
  countArabicCharacters,
  extractUserFacingCopyFromSource,
} from "@/lib/ai-core/website-builder/llm-language";
import { resolveLocaleFromLanguage } from "@/lib/i18n/website-output-locale";

export type GenerationValidationIssue = {
  id: string;
  severity: "error" | "warning";
  message: string;
  repairTarget?: "content" | "images" | "locale" | "pages";
};

export type GenerationValidationResult = {
  passed: boolean;
  issues: GenerationValidationIssue[];
  expectedIndustry: PromptIndustryMatch | null;
};

const INDUSTRY_IMAGE_HINTS: Record<string, RegExp[]> = {
  furniture: [/furniture|sofa|living|bedroom|interior|showroom|أثاث|كنب/i],
  restaurant: [/food|dining|restaurant|chef|kitchen|plate|مطعم|طعام/i],
  technology: [
    /computer|laptop|server|office|tech|data|software|حاسوب|تكنولوجيا/i,
  ],
  saas: [/computer|laptop|office|tech|software|dashboard|data/i],
  "real-estate": [/home|house|property|interior|architecture|عقار/i],
  clinic: [/medical|health|clinic|doctor|patient|hospital|dental|عيادة|صحة/i],
  law: [/law|legal|attorney|courtroom|lawyer|litigation/i],
  education: [/education|school|university|campus|student|teacher/i],
  blog: [/blog|article|editorial|magazine|writing|publishing/i],
  "landing-page": [/landing|startup|product|marketing|saas|launch/i],
  automotive: [/car|vehicle|automotive|showroom|سيار/i],
  tourism: [/travel|destination|landscape|hotel|tour|سفر/i],
};

function fileBlob(files: GeneratedProjectFile[]): string {
  return files.map((f) => f.content).join("\n");
}

function hasRtlInFiles(files: GeneratedProjectFile[]): boolean {
  return files.some(
    (f) =>
      /dir=["']rtl["']/i.test(f.content) ||
      /direction:\s*rtl/i.test(f.content) ||
      /html\[dir="rtl"\]/i.test(f.content),
  );
}

function heroImageUrl(
  files: GeneratedProjectFile[],
  manifest?: AssetManifest | null,
): string {
  const heroFromManifest = manifest?.items?.find(
    (i) => i.role === "hero" || i.id === "hero",
  )?.url;
  if (heroFromManifest) return heroFromManifest;
  const siteImages = files.find((f) => f.path.includes("site-images"));
  if (siteImages) {
    const m = siteImages.content.match(
      /HERO_IMAGE\s*=\s*["']([^"']+)["']/,
    );
    if (m?.[1]) return m[1];
  }
  const home = files.find((f) => f.path.includes("app/page"));
  const img = home?.content.match(/src=["']([^"']+)["']/);
  return img?.[1] || "";
}

function industryMentionedInContent(
  industryId: string,
  label: string,
  blob: string,
): boolean {
  const id = industryId.toLowerCase();
  const words = [
    label.toLowerCase(),
    id,
    id.replace(/-/g, " "),
  ].filter(Boolean);
  return words.some((w) => w.length > 2 && blob.toLowerCase().includes(w));
}

/**
 * Validate a generated website against prompt expectations.
 */
export function validateWebsiteGeneration(params: {
  prompt: string;
  language: string;
  industry?: string | null;
  industryId?: string | null;
  files: GeneratedProjectFile[];
  assetManifest?: AssetManifest | null;
  expectedPages?: string[];
}): GenerationValidationResult {
  const issues: GenerationValidationIssue[] = [];
  const expected = detectIndustryFromPrompt(params.prompt);
  const blob = fileBlob(params.files);
  const locale = resolveLocaleFromLanguage(params.language);
  const arabicOutput = resolveContentLanguage(params.language) === "ar";
  const arabicPrompt = isArabicPrompt(params.prompt);

  if (expected) {
    const mentioned = industryMentionedInContent(
      expected.industryId,
      expected.label,
      blob,
    );
    const wrongVertical =
      expected.industryId === "furniture" &&
      /\b(travel|tourism|destination|hotel)\b/i.test(blob) &&
      !/\bfurniture\b/i.test(blob);
    if (wrongVertical) {
      issues.push({
        id: "industry-mismatch",
        severity: "error",
        message: `Content reads like travel/tourism but prompt is ${expected.label}.`,
        repairTarget: "content",
      });
    } else if (!mentioned && expected.confidence >= 0.85) {
      issues.push({
        id: "industry-weak",
        severity: "warning",
        message: `Generated copy does not clearly reflect ${expected.label}.`,
        repairTarget: "content",
      });
    }
  }

  if (arabicOutput || arabicPrompt || locale.rtl) {
    const userCopy = extractUserFacingCopyFromSource(blob);
    const arabicChars = countArabicCharacters(userCopy || blob);
    if (arabicChars < 40) {
      issues.push({
        id: "language-arabic",
        severity: "error",
        message: "Arabic prompt but generated copy is mostly English.",
        repairTarget: "content",
      });
    }
    if (!hasRtlInFiles(params.files)) {
      issues.push({
        id: "rtl-missing",
        severity: "error",
        message: "Arabic site missing RTL (dir=rtl) in layout or CSS.",
        repairTarget: "locale",
      });
    }
  }

  const industryKey =
    expected?.industryId ||
    (params.industryId || params.industry || "business").toLowerCase();
  const hero = heroImageUrl(params.files, params.assetManifest ?? undefined);
  if (hero && expected) {
    const hints = INDUSTRY_IMAGE_HINTS[expected.industryId] || [];
    const urlLooksWrong =
      expected.industryId === "furniture" &&
      /travel|tour|beach|mountain|airplane/i.test(hero);
    if (urlLooksWrong) {
      issues.push({
        id: "hero-image-mismatch",
        severity: "error",
        message:
          "Hero image appears unrelated to the business (travel vs furniture).",
        repairTarget: "images",
      });
    } else if (
      hints.length &&
      !hints.some((h) => h.test(hero)) &&
      /unsplash\.com/i.test(hero)
    ) {
      issues.push({
        id: "hero-image-weak",
        severity: "warning",
        message: `Hero image may not match ${expected.label} industry.`,
        repairTarget: "images",
      });
    }
  }

  const pages = params.expectedPages?.filter(Boolean) || [];
  if (pages.length) {
    const missing = pages.filter(
      (p) => !blob.toLowerCase().includes(p.toLowerCase().slice(0, 6)),
    );
    if (missing.length > pages.length / 2) {
      issues.push({
        id: "pages-missing",
        severity: "warning",
        message: `Expected pages may be missing: ${missing.slice(0, 4).join(", ")}`,
        repairTarget: "pages",
      });
    }
  }

  const errors = issues.filter((i) => i.severity === "error");
  return {
    passed: errors.length === 0,
    issues,
    expectedIndustry: expected,
  };
}

export function buildGenerationRepairInstruction(
  result: GenerationValidationResult,
): string {
  const lines = result.issues
    .filter((i) => i.severity === "error")
    .map((i) => `- ${i.message}`);
  if (!lines.length) return "";
  const industry = result.expectedIndustry?.label || "the business";
  return [
    `[validation-repair] Fix the following before delivery:`,
    ...lines,
    `Ensure all user-facing copy, navigation, buttons, and headings match ${industry}.`,
    result.issues.some((i) => i.id === "language-arabic")
      ? "Write ALL visible text in Arabic. Do not mix English unless it is a proper brand name."
      : "",
    result.issues.some((i) => i.id === "rtl-missing")
      ? "Set html lang=ar dir=rtl and mirror navigation for RTL."
      : "",
    result.issues.some((i) => i.repairTarget === "images")
      ? "Use industry-appropriate hero and section images only."
      : "",
  ]
    .filter(Boolean)
    .join("\n");
}

/**
 * RenderDocument → Next.js 16 React project (Phase 5).
 */

import type { HtmlNode, RenderDocument, RenderPageDocument } from "@/lib/ai-core/website-builder/render/contracts";
import { findHtml, walkHtml } from "@/lib/ai-core/website-builder/render/renderer";
import { reactComponentFiles } from "@/lib/ai-core/website-builder/react-renderer/components";
import type {
  ReactSectionComponent,
  ReactSiteContent,
  ReactSitePage,
  ReactSiteSection,
  ReactSiteTheme,
  ReactTreeNode,
  ReactWebsiteProject,
  WebsiteReactRenderContext,
} from "@/lib/ai-core/website-builder/react-renderer/contracts";
import { reactLayoutFiles } from "@/lib/ai-core/website-builder/react-renderer/layout";
import { reactMetadataFiles } from "@/lib/ai-core/website-builder/react-renderer/metadata";
import { WebsiteReactRenderError } from "@/lib/ai-core/website-builder/react-renderer/errors";
import { assertReactWebsiteProject } from "@/lib/ai-core/website-builder/react-renderer/validation";

const SECTION_COMPONENT: Record<string, ReactSectionComponent> = {
  hero: "Hero",
  features: "Features",
  services: "Services",
  about: "About",
  gallery: "Gallery",
  team: "Team",
  testimonials: "Testimonials",
  pricing: "Pricing",
  faq: "FAQ",
  cta: "CTA",
  contact: "Contact",
  footer: "Footer",
};

const DEFAULT_THEME: ReactSiteTheme = {
  name: "Corporate Precision",
  colors: {
    background: "#0B1220",
    foreground: "#F8FAFC",
    accent: "#2563EB",
    muted: "#94A3B8",
  },
  fonts: { sans: "Inter", display: "Sora" },
  radiusPx: 8,
};

function textOf(node: HtmlNode): string {
  const parts = [node.text ?? "", ...node.children.map((child) => textOf(child))];
  return parts.join(" ").replace(/\s+/g, " ").trim();
}

function metaContent(tree: HtmlNode, nameOrProperty: string, key: "name" | "property"): string {
  const match = findHtml(tree, "meta").find((node) => node.attrs[key] === nameOrProperty);
  return match?.attrs.content ?? "";
}

function headingText(node: HtmlNode): string {
  const heading = [...findHtml(node, "h1"), ...findHtml(node, "h2"), ...findHtml(node, "h3")][0];
  return heading ? textOf(heading) : "";
}

function parseSection(node: HtmlNode, page: RenderPageDocument): ReactSiteSection | null {
  const id = node.attrs.id ?? "";
  const prefix = `section-${page.slug}-`;
  if (!id.startsWith(prefix)) return null;
  const rest = id.slice(prefix.length);
  const split = rest.lastIndexOf("-");
  const type = rest.slice(0, split);
  const component = SECTION_COMPONENT[type];
  if (!component || component === "Footer") return null;
  const images = findHtml(node, "img").map((image, index) => ({
    src: image.attrs.src ?? "",
    alt: image.attrs.alt ?? `${page.slug} visual`,
    priority: type === "hero" && index === 0,
  })).filter((image) => image.src && image.alt.length >= 3);
  const form = findHtml(node, "form")[0];
  const video = findHtml(node, "source").find((item) => (item.attrs.type ?? "").includes("video"));
  const articles = findHtml(node, "article");
  const items = articles.length
    ? articles.map((article) => ({
        title: headingText(article) || textOf(article).slice(0, 48),
        body: findHtml(article, "p")[0] ? textOf(findHtml(article, "p")[0]) : textOf(article),
      }))
    : findHtml(node, "li").map((item) => ({ title: textOf(item).slice(0, 48), body: textOf(item) }));
  const paragraphs = findHtml(node, "p").map((item) => textOf(item)).filter(Boolean);
  return {
    id,
    component,
    title: headingText(node) || page.slug,
    body: paragraphs[0] ?? textOf(node),
    cta: findHtml(node, "button")[0] ? textOf(findHtml(node, "button")[0]) : findHtml(node, "a").find((link) => !link.attrs.href?.startsWith("/")) ? textOf(findHtml(node, "a")[0]) : null,
    images,
    items,
    quotes: findHtml(node, "blockquote").map((quote) => textOf(quote)).filter(Boolean),
    form: form
      ? {
          label: form.attrs["aria-label"] ?? "contact",
          fields: findHtml(form, "input").map((input) => input.attrs.name ?? input.attrs.id ?? "field").filter(Boolean),
        }
      : null,
    videoSrc: video?.attrs.src ?? null,
  };
}

function parsePage(page: RenderPageDocument): ReactSitePage {
  const titleNode = findHtml(page.tree, "title")[0];
  const canonical = findHtml(page.tree, "link").find((node) => node.attrs.rel === "canonical")?.attrs.href ?? page.canonicalUrl;
  const mains = findHtml(page.tree, "main");
  if (mains.length !== 1) {
    throw new WebsiteReactRenderError(`Page "${page.slug}" must contain one main element.`, "invalid_document");
  }
  const sections: ReactSiteSection[] = [];
  walkHtml(mains[0], (node, parent) => {
    if (parent?.tag !== "main") return;
    if (node.tag === "section" || node.tag === "aside") {
      const parsed = parseSection(node, page);
      if (parsed) sections.push(parsed);
    }
  });
  if (!sections.some((section) => section.component === "Hero") && !sections.some((section) => section.title)) {
    throw new WebsiteReactRenderError(`Page "${page.slug}" has no renderable sections.`, "invalid_react_tree");
  }
  return {
    slug: page.slug,
    path: page.path,
    title: titleNode?.text?.trim() || page.slug,
    description: metaContent(page.tree, "description", "name"),
    canonicalUrl: canonical,
    ogImage: metaContent(page.tree, "og:image", "property") || `${page.path}og`,
    locale: page.tree.attrs.lang || "en",
    sections,
  };
}

export function parseReactSiteContent(context: WebsiteReactRenderContext): ReactSiteContent {
  const headerLink = findHtml(context.document.pages[0]?.tree ?? { tag: "html", attrs: {}, children: [] }, "a")[0];
  return {
    name: context.siteName || textOf(headerLink ?? { tag: "a", attrs: {}, children: [], text: "Site" }) || "Site",
    baseUrl: context.document.baseUrl,
    locale: context.document.pages[0]?.tree.attrs.lang || "en",
    navigation: context.document.navigation.map((item) => ({ href: item.href, label: item.label })),
    pages: context.document.pages.map(parsePage),
    theme: context.theme ?? DEFAULT_THEME,
  };
}

function contentModule(content: ReactSiteContent): string {
  return `export type ReactSiteImage = {
  src: string;
  alt: string;
  priority: boolean;
};

export type ReactSiteSection = {
  id: string;
  component: ${content.pages[0] ? `"Hero" | "Features" | "Services" | "About" | "Gallery" | "Team" | "Testimonials" | "Pricing" | "FAQ" | "CTA" | "Contact" | "Footer"` : "string"};
  title: string;
  body: string;
  cta: string | null;
  images: ReactSiteImage[];
  items: Array<{ title: string; body: string }>;
  quotes: string[];
  form: { label: string; fields: string[] } | null;
  videoSrc: string | null;
};

export type ReactSitePage = {
  slug: string;
  path: string;
  title: string;
  description: string;
  canonicalUrl: string;
  ogImage: string;
  locale: string;
  sections: ReactSiteSection[];
};

export const siteContent = ${JSON.stringify(
    {
      name: content.name,
      baseUrl: content.baseUrl,
      locale: content.locale,
      navigation: content.navigation,
      pages: content.pages,
      theme: content.theme,
    },
    null,
    2,
  )} as const;

export function getPage(slug: string) {
  return siteContent.pages.find((page) => page.slug === slug);
}
`;
}

function reactTree(content: ReactSiteContent): ReactTreeNode {
  const home = content.pages.find((page) => page.path === "/") ?? content.pages[0];
  return {
    name: "RootLayout",
    server: true,
    filePath: "app/layout.tsx",
    children: [
      { name: "Header", server: true, filePath: "components/header.tsx", children: [
        { name: "Navigation", server: true, filePath: "components/navigation.tsx", children: [] },
        { name: "ThemeToggle", server: false, filePath: "components/theme-toggle.tsx", children: [] },
      ] },
      {
        name: "SitePage",
        server: true,
        filePath: "components/site-page.tsx",
        children: home.sections.map((section) => ({
          name: section.component,
          server: true,
          filePath: `components/${section.component.toLowerCase()}.tsx`,
          children: [],
        })),
      },
      { name: "Footer", server: true, filePath: "components/footer.tsx", children: [] },
    ],
  };
}

export function buildReactWebsiteProject(context: WebsiteReactRenderContext): ReactWebsiteProject {
  if (!context.document.pages.length) {
    throw new WebsiteReactRenderError("Render document has no pages.", "invalid_document");
  }
  const content = parseReactSiteContent(context);
  const files = [
    { path: "lib/site/content.ts", language: "ts" as const, contents: contentModule(content) },
    ...reactComponentFiles(),
    ...reactLayoutFiles(content),
    ...reactMetadataFiles(content),
  ];
  const project: ReactWebsiteProject = {
    files,
    tree: reactTree(content),
    content,
    createdAt: context.now(),
  };
  assertReactWebsiteProject(project);
  return project;
}

/**
 * Compose real App Router pages for industry site structure.
 */

import type { GeneratedProjectFile } from "@/lib/ai/types";
import type {
  ManagedPageDef,
  NavLink,
  SiteStructurePlan,
} from "@/lib/ai-core/website-management/types";
import { wireNavAndFooterToRoutes } from "@/lib/ai-core/website-management/pages/wire-nav";
import { writeStructureToFiles } from "@/lib/ai-core/website-management/pages/site-structure";

function pageShell(params: {
  brand: string;
  title: string;
  description: string;
  bodyImports: string;
  bodyJsx: string;
}): string {
  return `import type { Metadata } from "next";
import { SiteHeader } from "@/components/layout/site-header";
import { SiteFooter } from "@/components/layout/site-footer";
${params.bodyImports}

export const metadata: Metadata = {
  title: ${JSON.stringify(params.title)},
  description: ${JSON.stringify(params.description)},
};

export default function ManagedPage() {
