/**
 * Generate secondary page files (skips home `/` which is composed separately).
 * Keeps existing automotive models/[slug] if already present.
 */
export function composeManagedSecondaryPages(params: {
  structure: SiteStructurePlan;
  brandName: string;
}): GeneratedProjectFile[] {
  const brand = params.brandName || "Brand";
  const files: GeneratedProjectFile[] = [];

  for (const page of params.structure.pages) {
    if (page.route === "/") continue;
    // Prefer richer automotive composers already in polish for models/inventory
    if (
      params.structure.industryId === "automotive" &&
      (page.route === "/models" || page.route === "/inventory")
    ) {
      continue;
    }

    const body = sectionForRoute(
      page.route,
      params.structure.industryId,
      brand,
      page.label,
    );
    files.push({
      path: page.path,
      language: "tsx",
      content: pageShell({
        brand,
        title: `${brand} · ${page.label}`,
        description: page.purpose,
        bodyImports: body.imports,
        bodyJsx: body.jsx,
      }),
    });
  }

  // Dynamic vehicle detail for automotive if not already handled
  if (params.structure.industryId === "automotive") {
    files.push({
      path: "app/models/[slug]/page.tsx",
      language: "tsx",
      content: `import type { Metadata } from "next";
import { SiteHeader } from "@/components/layout/site-header";
import { SiteFooter } from "@/components/layout/site-footer";
import { VehicleDetail } from "@/components/sections/vehicle-detail";
import { AppointmentCalendar } from "@/components/sections/appointment-calendar";

type Props = { params: Promise<{ slug: string }> };

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { slug } = await params;
  return { title: ${JSON.stringify(brand)} + " · " + slug };
}

export default async function VehicleDetailPage({ params }: Props) {
  const { slug } = await params;
  return (
    <main className="min-h-screen bg-[var(--color-background)] text-[var(--color-foreground)] antialiased">
      <SiteHeader brandName=${JSON.stringify(brand)} />
      <VehicleDetail slug={slug} />
      <AppointmentCalendar />
      <SiteFooter brandName=${JSON.stringify(brand)} />
    </main>
  );
}
`,
    });
  }

  // Sitemap route helper
  const urls = params.structure.sitemapPaths
    .map((p) => `  ${JSON.stringify(p)},`)
    .join("\n");
  files.push({
    path: "lib/site-sitemap.ts",
    language: "typescript",
    content: `/** Auto-generated site sitemap paths */
export const SITE_SITEMAP_PATHS = [
${urls}
] as const;

export const SITE_NAV_LINKS = ${JSON.stringify(params.structure.navLinks, null, 2)} as const;

export const SITE_FOOTER_LINKS = ${JSON.stringify(params.structure.footerLinks, null, 2)} as const;
`,
  });

  return files;
}

function slugifyRoute(label: string): string {
  return label
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 48) || "page";
}

export function routeToPagePath(route: string): string {
  if (route === "/") return "app/page.tsx";
  const clean = route.replace(/^\//, "").replace(/\/$/, "");
  return `app/${clean}/page.tsx`;
}

export function addPage(
  structure: SiteStructurePlan,
  params: { label: string; route?: string; purpose?: string },
): SiteStructurePlan {
  const baseRoute = params.route || `/${slugifyRoute(params.label)}`;
  const route = baseRoute.startsWith("/") ? baseRoute : `/${baseRoute}`;
  const path = routeToPagePath(route);
  if (structure.pages.some((p) => p.route === route)) return structure;

  const page: ManagedPageDef = {
    route,
    path,
    label: params.label,
    purpose: params.purpose || `${params.label} page`,
    sections: [],
  };

  return {
    ...structure,
    pages: [...structure.pages, page],
    sitemapPaths: structure.sitemapPaths.includes(route)
      ? structure.sitemapPaths
      : [...structure.sitemapPaths, route],
  };
}

export function removePage(
  structure: SiteStructurePlan,
  route: string,
): SiteStructurePlan {
  if (route === "/") return structure;
  return {
    ...structure,
    pages: structure.pages.filter((p) => p.route !== route),
    sitemapPaths: structure.sitemapPaths.filter((p) => p !== route),
    navLinks: structure.navLinks.filter((l) => l.href !== route),
    footerLinks: structure.footerLinks.filter((l) => l.href !== route),
  };
}

export function duplicatePage(
  structure: SiteStructurePlan,
  route: string,
): SiteStructurePlan {
  const source = structure.pages.find((p) => p.route === route);
  if (!source) return structure;
  const copyLabel = `${source.label} Copy`;
  let candidate = `/${slugifyRoute(copyLabel)}`;
  let i = 2;
  while (structure.pages.some((p) => p.route === candidate)) {
    candidate = `/${slugifyRoute(copyLabel)}-${i}`;
    i += 1;
  }
  return addPage(structure, {
    label: copyLabel,
    route: candidate,
    purpose: source.purpose,
  });
}

export function reorderPages(
  structure: SiteStructurePlan,
  routes: string[],
): SiteStructurePlan {
  const byRoute = new Map(structure.pages.map((p) => [p.route, p]));
  const pages = routes
    .map((r) => byRoute.get(r))
    .filter((p): p is ManagedPageDef => Boolean(p));
  for (const page of structure.pages) {
    if (!pages.some((p) => p.route === page.route)) pages.push(page);
  }
  return {
    ...structure,
    pages,
    sitemapPaths: routes.length ? routes : structure.sitemapPaths,
  };
}

export function setHomepage(
  structure: SiteStructurePlan,
  route: string,
): SiteStructurePlan {
  const target = structure.pages.find((p) => p.route === route);
  const currentHome = structure.pages.find((p) => p.route === "/");
  if (!target || route === "/") return structure;

  const pages = structure.pages.map((p) => {
    if (p.route === "/") {
      return { ...target, route: "/", path: "app/page.tsx" };
    }
    if (p.route === route && currentHome) {
      return {
        ...currentHome,
        route,
        path: routeToPagePath(route),
      };
    }
    return p;
  });

  const sitemapPaths = structure.sitemapPaths.map((p) =>
    p === route ? "/" : p === "/" ? route : p,
  );

  return { ...structure, pages, sitemapPaths };
}

export function updatePageMeta(
  structure: SiteStructurePlan,
  route: string,
  patch: Partial<Pick<ManagedPageDef, "label" | "purpose">>,
): SiteStructurePlan {
  return {
    ...structure,
    pages: structure.pages.map((p) =>
      p.route === route ? { ...p, ...patch } : p,
    ),
  };
}

/**
 * Apply structure changes to blueprint files: pages, sitemap, nav wiring.
 */
export function applyStructureToProjectFiles(params: {
  files: GeneratedProjectFile[];
  structure: SiteStructurePlan;
  brandName: string;
}): GeneratedProjectFile[] {
  const validPaths = new Set(params.structure.pages.map((p) => p.path));
  let files = params.files.filter((f) => {
    if (f.path === "app/page.tsx") return validPaths.has("app/page.tsx");
    if (/^app\/.+\/page\.tsx$/.test(f.path)) return validPaths.has(f.path);
    return true;
  });

  const secondary = composeManagedSecondaryPages({
    structure: params.structure,
    brandName: params.brandName,
  });
  for (const file of secondary) {
    if (
      files.some((f) => f.path === file.path) &&
      (file.path.startsWith("app/models") ||
        file.path.startsWith("app/inventory"))
    ) {
      continue;
    }
    files = [...files.filter((f) => f.path !== file.path), file];
  }

  files = writeStructureToFiles(files, params.structure);
  return wireNavAndFooterToRoutes(files, params.structure);
}

import { Ratelimit } from "@upstash/ratelimit";
import { executeWithUpstashFallback, getUpstashRedis, isUpstashRedisConfigured } from "@/lib/api/upstash-redis";
export { isUpstashRedisConfigured, pingUpstashRedis } from "@/lib/api/upstash-redis";
import type { SupabaseClient } from "@supabase/supabase-js";
import {
  authorizeAiUsageCredits,
  type AiUsageLease,
  type BeginAiUsageResult,
} from "@/lib/billing/ai-usage-settlement";
export type { AiUsageLease, BeginAiUsageResult } from "@/lib/billing/ai-usage-settlement";
import { withTiming } from "@/lib/perf/timing";
import { NextResponse } from "next/server";

export type AiRateLimitResource =
  | "ideas"
  | "market-analysis"
  | "reports"
  | "website-builder"
  | "webapp-builder"
  | "landing-page-builder"
  | "logo-designer"
  | "brand-identity"
  | "image-generator"
  | "video-studio"
  | "content-studio"
  | "business-suite"
  | "ai-agents"
  | "workspace"
  | "seo-analyzer"
  | "ai-core";

const AI_RATE_LIMITS: Record<
  AiRateLimitResource,
  { requests: number; window: "1 m" | "1 h" }
> = {
  ideas: { requests: 10, window: "1 m" },
  "market-analysis": { requests: 10, window: "1 m" },
  reports: { requests: 10, window: "1 m" },
  "website-builder": { requests: 10, window: "1 m" },
  "webapp-builder": { requests: 5, window: "1 m" },
  "landing-page-builder": { requests: 10, window: "1 m" },
  "logo-designer": { requests: 10, window: "1 m" },
  "brand-identity": { requests: 10, window: "1 m" },
  "image-generator": { requests: 10, window: "1 m" },
  "video-studio": { requests: 5, window: "1 m" },
  "content-studio": { requests: 15, window: "1 m" },
  "business-suite": { requests: 10, window: "1 m" },
  "ai-agents": { requests: 10, window: "1 m" },
  workspace: { requests: 10, window: "1 m" },
  "seo-analyzer": { requests: 20, window: "1 m" },
  "ai-core": { requests: 10, window: "1 m" },
};

function isUpstashConfigured(): boolean {
  return isUpstashRedisConfigured();
}

function createLimiter(resource: AiRateLimitResource): Ratelimit | null {
  const redis = getUpstashRedis();
  if (!redis) return null;

  const { requests, window } = AI_RATE_LIMITS[resource];

  return new Ratelimit({
    redis,
    limiter: Ratelimit.slidingWindow(requests, window),
    prefix: `ratelimit:ai:${resource}`,
    analytics: true,
  });
}

const limiterCache = new Map<AiRateLimitResource, Ratelimit>();
const memoryLimitStore = new Map<string, number[]>();

function getLimiter(resource: AiRateLimitResource): Ratelimit | null {
  let limiter = limiterCache.get(resource);
  if (!limiter) {
    limiter = createLimiter(resource) ?? undefined;
    if (limiter) limiterCache.set(resource, limiter);
  }
  return limiter ?? null;
}

function rateLimitHeaders(limit: number, remaining: number, reset: number) {
  return {
    "X-RateLimit-Limit": String(limit),
    "X-RateLimit-Remaining": String(Math.max(0, remaining)),
    "X-RateLimit-Reset": String(reset),
    "Retry-After": String(Math.max(1, Math.ceil((reset - Date.now()) / 1000))),
  };
}

function windowMs(window: "1 m" | "1 h") {
  return window === "1 h" ? 60 * 60 * 1000 : 60 * 1000;
}

function enforceMemoryRateLimit(userId: string, resource: AiRateLimitResource) {
  const { requests, window } = AI_RATE_LIMITS[resource];
  const now = Date.now();
  const duration = windowMs(window);
  const key = `${resource}:${userId}`;
  const recent = (memoryLimitStore.get(key) ?? []).filter(
    (timestamp) => now - timestamp < duration,
  );

  if (recent.length >= requests) {
    const reset = recent[0] + duration;
    return NextResponse.json(
      {
        error: "Too many AI requests. Please try again later.",
        retryAfter: Math.max(1, Math.ceil((reset - now) / 1000)),
      },
      {
        status: 429,
        headers: rateLimitHeaders(requests, 0, reset),
      },
    );
  }

  recent.push(now);
  memoryLimitStore.set(key, recent);

  if (memoryLimitStore.size > 5000) {
    for (const [storeKey, timestamps] of memoryLimitStore) {
      const active = timestamps.filter((timestamp) => now - timestamp < duration);
      if (active.length) {
        memoryLimitStore.set(storeKey, active);
      } else {
        memoryLimitStore.delete(storeKey);
      }
    }
  }

  return null;
}

/**
 * Per-user rate limit for AI generation (POST) routes.
 * Uses Upstash when configured; production falls back to per-instance memory limits.
 */
export async function enforceAiRateLimit(
  userId: string,
  resource: AiRateLimitResource,
): Promise<NextResponse | null> {
  const memoryFallback = () =>
    process.env.NODE_ENV === "production"
      ? enforceMemoryRateLimit(userId, resource)
      : null;

  if (!isUpstashConfigured()) {
    return memoryFallback();
  }

  const limiter = getLimiter(resource);
  if (!limiter) {
    return memoryFallback();
  }

  return executeWithUpstashFallback(
    async () => {
      const { success, limit, remaining, reset } = await limiter.limit(userId);

      if (!success) {
        return NextResponse.json(
          {
            error: "Too many AI requests. Please try again later.",
            retryAfter: Math.max(1, Math.ceil((reset - Date.now()) / 1000)),
          },
          {
            status: 429,
            headers: rateLimitHeaders(limit, remaining, reset),
          },
        );
      }

      return null;
    },
    memoryFallback,
    "ai-rate-limit",
  );
}

/**
 * Rate limit + credit *authorization* for AI generation routes.
 *
 * Does NOT deduct credits. Call `lease.settle()` only after the required
 * generation result succeeds. Call `lease.release()` on failure paths
 * (idempotent no-op when nothing was settled; refunds if already settled).
 */
export async function beginAiUsage(
  supabase: SupabaseClient,
  userId: string,
  resource: AiRateLimitResource,
  operationId?: string,
): Promise<BeginAiUsageResult> {
  return withTiming(`ai.usage.${resource}`, async () => {
    const rateLimited = await enforceAiRateLimit(userId, resource);
    if (rateLimited) return { ok: false, response: rateLimited };

    return authorizeAiUsageCredits(supabase, userId, resource, undefined, operationId);
  });
}

/**
 * @deprecated Prefer `beginAiUsage` + `lease.settle()` / `lease.release()`.
 * Kept as a rate-limit + soft credit check that does not charge.
 * Routes that still call this without settling will not consume credits —
 * migrate to beginAiUsage and settle on success.
 */
export async function enforceAiUsage(
  supabase: SupabaseClient,
  userId: string,
  resource: AiRateLimitResource,
): Promise<NextResponse | null> {
  const gate = await beginAiUsage(supabase, userId, resource);
  return gate.ok ? null : gate.response;
}

const MUTATION_RATE = { requests: 30, window: "1 m" as const };
const mutationMemoryStore = new Map<string, number[]>();
const authMemoryStore = new Map<string, number[]>();
const AUTH_RATE = { requests: 10, window: "1 m" as const };
const WEBHOOK_RATE = { requests: 120, window: "1 m" as const };
const webhookMemoryStore = new Map<string, number[]>();

function enforceKeyedMemoryLimit(
  store: Map<string, number[]>,
  key: string,
  limit: number,
  window: "1 m" | "1 h",
  errorMessage: string,
): NextResponse | null {
  const now = Date.now();
  const duration = windowMs(window);
  const recent = (store.get(key) ?? []).filter((ts) => now - ts < duration);

  if (recent.length >= limit) {
    const reset = recent[0] + duration;
    return NextResponse.json(
      {
        error: errorMessage,
        retryAfter: Math.max(1, Math.ceil((reset - now) / 1000)),
      },
      { status: 429, headers: rateLimitHeaders(limit, 0, reset) },
    );
  }

  recent.push(now);
  store.set(key, recent);

  if (store.size > 5000) {
    for (const [storeKey, timestamps] of store) {
      const active = timestamps.filter((timestamp) => now - timestamp < duration);
      if (active.length) {
        store.set(storeKey, active);
      } else {
        store.delete(storeKey);
      }
    }
  }

  return null;
}

/**
 * Lightweight rate limiter for non-AI mutation endpoints.
 * Uses Upstash when configured; otherwise in-memory (dev / single-instance).
 * Public growth keys fail closed in Vercel production without Upstash.
 */
export function enforceMutationRateLimit(userId: string): NextResponse | null {
  if (
    process.env.VERCEL_ENV === "production" &&
    !isUpstashConfigured() &&
    userId.startsWith("growth-")
  ) {
    return NextResponse.json(
      {
        error: "Service temporarily unavailable. Rate limiting is not configured.",
        code: "RATE_LIMIT_UNAVAILABLE",
      },
      { status: 503 },
    );
  }

  return enforceKeyedMemoryLimit(
    mutationMemoryStore,
    userId,
    MUTATION_RATE.requests,
    MUTATION_RATE.window,
    "Too many requests. Please slow down.",
  );
}

const mutationUpstashCache = new Map<string, Ratelimit>();

/** Async mutation limiter — prefers Upstash when available. */
export async function enforceMutationRateLimitAsync(
  userId: string,
): Promise<NextResponse | null> {
  if (!isUpstashConfigured()) {
    return enforceMutationRateLimit(userId);
  }

  const redis = getUpstashRedis();
  if (!redis) {
    return enforceMutationRateLimit(userId);
  }

  let limiter = mutationUpstashCache.get("mutation");
  if (!limiter) {
    limiter = new Ratelimit({
      redis,
      limiter: Ratelimit.slidingWindow(MUTATION_RATE.requests, MUTATION_RATE.window),
      prefix: "ratelimit:mutation",
      analytics: true,
    });
    mutationUpstashCache.set("mutation", limiter);
  }

  return executeWithUpstashFallback(
    async () => {
      const { success, limit, remaining, reset } = await limiter!.limit(userId);
      if (!success) {
        return NextResponse.json(
          {
            error: "Too many requests. Please slow down.",
            retryAfter: Math.max(1, Math.ceil((reset - Date.now()) / 1000)),
          },
          { status: 429, headers: rateLimitHeaders(limit, remaining, reset) },
        );
      }
      return null;
    },
    () => enforceMutationRateLimit(userId),
    "mutation-rate-limit",
  );
}

/** Auth endpoints: 10 attempts per minute per email (or IP key). */
export function enforceAuthRateLimit(key: string): NextResponse | null {
  return enforceKeyedMemoryLimit(
    authMemoryStore,
    `auth:${key.toLowerCase()}`,
    AUTH_RATE.requests,
    AUTH_RATE.window,
    "Too many authentication attempts. Please try again later.",
  );
}

/** Billing webhook ingress: 120 requests per minute per provider. */
export function enforceWebhookRateLimit(provider: string): NextResponse | null {
  return enforceKeyedMemoryLimit(
    webhookMemoryStore,
    `webhook:${provider}`,
    WEBHOOK_RATE.requests,
    WEBHOOK_RATE.window,
    "Too many webhook requests.",
  );
}

import type { TokenUsage } from "@/lib/ai/types";
import { brandIdentityEngine } from "@/lib/ai-core/brand-studio/engine";
import { modelToBlueprint } from "@/lib/ai-core/brand-studio/model";
import type {
  BrandOutput,
  BrandIdentityPluginInput,
  BrandProgressEvent,
} from "@/plugins/brand-identity";

export type { BrandOutput, BrandIdentityPluginInput, BrandProgressEvent };

type GenerateBrandInput = BrandIdentityPluginInput & {
  onProgress?: (event: string) => void;
  templateId?: string;
};

export type BrandGenerationResult = BrandOutput & {
  progressEvents: BrandProgressEvent[];
  usage: TokenUsage;
  generationTimeMs: number;
  provider: string;
  model?: import("@/lib/ai-core/brand-studio/types").BrandIdentityModel;
};

/**
 * Brand Designer entrypoint — unified BrandIdentityEngine via AI Core LayerRunner.
 * API route remains /api/brand-identity.
 */
export async function generateBrandIdentity(
  input: GenerateBrandInput,
): Promise<BrandGenerationResult> {
  const { onProgress, templateId, ...pluginInput } = input;

  const result = await brandIdentityEngine.generate(pluginInput, {
    onProgress,
    templateId,
  });

  return {
    ...result.output,
    progressEvents: result.progressEvents,
    usage: result.usage,
    generationTimeMs: result.generationTimeMs,
    provider: result.provider,
    model: result.model,
  };
}

