/**
 * Website Builder orchestration implementation.
 *
 * Canonical public API: import `generateWebsite` from `@/lib/website-generator`.
 */
export async function generateWebsite(input: GenerateWebsiteInput): Promise<
  GeneratedWebsiteProject & {
    progressEvents: WebsiteGenerationProgressEvent[];
    usage: TokenUsage;
    generationTimeMs: number;
    provider: string;
    pipelinePerformanceReport?: PerformanceProfilingReport;
    pipelinePerformanceMarkdown?: string;
    productionPipelineReports?: ProductionPipelineReports;
  }
> {
  const {
    onProgress,
    onFilesCheckpoint,
    preferredProvider,
    autoFallback,
    ...pluginInput
  } = input;

  const settings = providerManager.getUserSettings();
  const useFallback = autoFallback ?? settings?.auto_fallback ?? true;
  const preferred = resolvePreferredProvider(input);
  const providers = resolveProviderChain(preferred, useFallback);
  const route = resolveWebsiteTbgeRoute();

  const resolvedWebsiteStructureTemplateId = pluginInput.websiteStructureTemplateId
    ? resolveBuilderTemplatePackageId(pluginInput.websiteStructureTemplateId)
    : undefined;
  const resolvedTemplateId = pluginInput.templateId
    ? resolveBuilderTemplatePackageId(pluginInput.templateId)
    : resolvedWebsiteStructureTemplateId;

  const tbdpWiring = wireWebsiteGenerationStart({
    prompt: pluginInput.prompt,
    language: pluginInput.language,
    industryId: pluginInput.industryId,
    templateId: resolvedTemplateId,
    websiteStructureTemplateId: resolvedWebsiteStructureTemplateId,
    templateIntelligenceId: pluginInput.templateIntelligenceId,
    components: pluginInput.components,
    theme: pluginInput.theme,
  });

  let resolvedPluginInput = pluginInput;
  if (
    resolvedTemplateId !== pluginInput.templateId ||
    resolvedWebsiteStructureTemplateId !== pluginInput.websiteStructureTemplateId
  ) {
    resolvedPluginInput = {
      ...pluginInput,
      templateId: resolvedTemplateId,
      websiteStructureTemplateId: resolvedWebsiteStructureTemplateId,
    };
  }
  const userChoseTemplate = Boolean(
    pluginInput.templateIntelligenceId?.trim() ||
      pluginInput.websiteStructureTemplateId?.trim() ||
      pluginInput.templateId?.trim() ||
      pluginInput.marketplaceTemplateId?.trim(),
  );
  if (
    tbdpWiring.enabled &&
    userChoseTemplate &&
    tbdpWiring.suggestedComponents &&
    !resolvedPluginInput.components?.length
  ) {
    resolvedPluginInput = {
      ...resolvedPluginInput,
      components: tbdpWiring.suggestedComponents,
    };
  }

  let masterPlanContext: MasterPlanIntegrationContext | ProductionPipelineContext | undefined;
  let productionReports: ProductionPipelineReports | undefined;

  if (isProductionPipelineEnabled()) {
    onProgress?.("[production] Running full production pipeline planning...");
    const planned = await runProductionPlanningPhase({
      pluginInput: resolvedPluginInput,
      tbdpWiring,
      onProgress,
    });
    if (!planned.ok) {
      throw new Error(
        `Production pipeline failed at ${planned.stage}: ${planned.errors.join("; ")}`,
      );
    }
    masterPlanContext = planned.context;
    productionReports = {
      trace: planned.context.trace,
      timing: planned.context.planningTiming,
      validation: planned.context.validationReport,
      quality: planned.context.qualityReport,
    };
    resolvedPluginInput = planned.context.enrichedInput;
  } else if (isMasterPlanIntegrationEnabled()) {
    onProgress?.("[master-plan] Resolving Master Plan authority...");
    const wired = await wireMasterPlanIntegration({
      pluginInput: resolvedPluginInput,
      tbdpWiring,
      onProgress,
    });
    if (!wired.ok) {
      throw new Error(
        `Master Plan integration failed: ${wired.errors.join("; ")}`,
      );
    }
    masterPlanContext = wired.context;
    resolvedPluginInput = wired.context.enrichedInput;
  }

  if (route.mode === "tbge-primary") {
    const providerName =
      providers.find((name) => providerManager.isConfigured(name)) ?? null;
    if (!providerName) {
      throw new Error(
        "No AI provider configured. Set DEEPSEEK_API_KEY to enable generation.",
      );
    }
    const connectLabel = isProductionPipelineEnabled()
      ? "Connecting to Content Provider..."
      : `Connecting to ${providerName}...`;
    onProgress?.(connectLabel);
    const tbgeResult = await runTbgeOnlyGeneration({
      pluginInput: resolvedPluginInput,
      providerName,
      onProgress,
      onFilesCheckpoint,
      masterPlanContext,
      productionReports,
    });
    const tbgeWithIndustry = applyResolvedIndustryToProject(tbgeResult, {
      prompt: resolvedPluginInput.prompt,
      industryId: resolvedPluginInput.industryId,
    });
    const tbgeWithAssets = await generateAssetsForWebsiteProject(
      tbgeWithIndustry,
      resolvedPluginInput,
      { onProgress },
    );
    const tbgeWithComposedHome = composeTbgeUnifiedHomeIfNeeded(tbgeWithAssets, {
      spec: tbgeResult.tbgeSpec,
      industryId: resolvedPluginInput.industryId ?? tbgeResult.tbgeSpec?.business.industryId,
      language: resolvedPluginInput.language,
      prompt: resolvedPluginInput.prompt,
    });
    const v2Project = await applyV2StructureToGenerationResult(
      tbgeWithComposedHome,
      resolvedPluginInput,
      onProgress,
    );
    const mergedProject = await finalizeProjectEnhancements(
      {
        ...tbgeWithComposedHome,
        ...v2Project,
        assetManifest:
          v2Project.assetManifest ?? tbgeWithComposedHome.assetManifest,
        settings: mergeIntegrationSettings(
          mergeTbdpSettings(
            (v2Project.settings ?? {}) as Record<string, unknown>,
            tbdpWiring.settingsPatch,
          ),
          masterPlanContext?.settingsPatch ?? {},
        ) as GeneratedWebsiteProject["settings"],
      },
      resolvedPluginInput,
    );
    const imageStrategy = resolveSiteImageStrategy(
      resolvedPluginInput.imageStrategyMode ??
        mergedProject.sitePlan?.imageStrategy,
    );
    const withImages = applyFinalImageInjectionToProject(mergedProject, {
      imageStrategy,
    });
    return {
      ...withImages,
      settings: mergedProject.settings,
      progressEvents: tbgeResult.progressEvents,
      usage: tbgeResult.usage,
      generationTimeMs: tbgeResult.generationTimeMs,
      provider: tbgeResult.provider,
      productionPipelineReports:
        tbgeResult.productionPipelineReports ?? productionReports,
    };
  }

  let lastError: unknown = null;

  for (const providerName of providers) {
    if (!providerManager.isConfigured(providerName)) continue;
    try {
      const connectLabel = isProductionPipelineEnabled()
        ? "Connecting to Content Provider..."
        : `Connecting to ${providerName}...`;
      onProgress?.(connectLabel);

      const adapter = createWebsiteBuilderAdapter();
      const profiler = getActiveWebsiteProfiler() ?? new WebsitePipelineProfiler();
      profiler.snapshotMemory("generation-start");

      const runGeneration = async () =>
        profiler.measure("website-builder", "layerRunner.run", async () =>
          layerRunner.run(
            adapter,
            {
              brief: profiler.attachToBrief(websiteInputToBrief(resolvedPluginInput)),
              mode: resolvedPluginInput.mode,
              continueInstruction: resolvedPluginInput.continueInstruction,
              priorArtifacts: priorArtifactsFromWebsiteInput(resolvedPluginInput),
              userId: resolvedPluginInput.userId,
              parentRunId: resolvedPluginInput.parentGenerationId,
            },
            {
              provider: providerName,
              onProgress,
              onFilesCheckpoint,
            },
          ),
        );

      const result = getActiveWebsiteProfiler()
        ? await runGeneration()
        : await runWithWebsiteProfiler(profiler, runGeneration);

      profiler.snapshotMemory("generation-end");
      const project = result.finalOutput ?? result.generation;

      const wiredProject = tbdpWiring.enabled || masterPlanContext
        ? {
            ...project,
            settings: mergeIntegrationSettings(
              mergeTbdpSettings(
                (project.settings ?? {}) as Record<string, unknown>,
                tbdpWiring.settingsPatch,
              ),
              masterPlanContext?.settingsPatch ?? {},
            ) as GeneratedWebsiteProject["settings"],
          }
        : project;

      const v2Project = await applyV2StructureToGenerationResult(
        wiredProject,
        resolvedPluginInput,
        onProgress,
      );

      const withSitePlan = await finalizeProjectEnhancements(
        v2Project,
        resolvedPluginInput,
      );

      const imageStrategy = resolveSiteImageStrategy(
        resolvedPluginInput.imageStrategyMode ??
          withSitePlan.sitePlan?.imageStrategy,
      );
      const withImages = applyFinalImageInjectionToProject(withSitePlan, {
        imageStrategy,
      });

      return {
        ...withImages,
        progressEvents: result.progressEvents as WebsiteGenerationProgressEvent[],
        usage: result.usage ?? emptyTokenUsage(),
        generationTimeMs: result.generationTimeMs,
        provider: result.provider,
        pipelinePerformanceReport: profiler.toReport(),
        pipelinePerformanceMarkdown: profiler.formatMarkdownReport(),
      };
    } catch (error) {
      lastError = error;
      onProgress?.(
        error instanceof Error
          ? `${providerName} failed: ${error.message}. Trying next provider...`
          : `${providerName} failed. Trying next provider...`,
      );
    }
  }

  if (providers.length > 0 && lastError) {
    throw lastError instanceof Error
      ? lastError
      : new Error("All configured AI providers failed.");
  }

  throw new Error(
    "No AI provider configured. Set DEEPSEEK_API_KEY to enable generation.",
  );
}

/**
 * WebsiteSeoService — apply SEO agent fixes to saved generations.
 * Extracted from POST /api/website-builder/[id]/seo/apply (Phase 0).
 */

import type { SupabaseClient } from "@supabase/supabase-js";
import { extractWebsiteFilesFromBlueprint } from "@/plugins/website/iteration";
import type { GeneratedWebsiteProject } from "@/plugins/website/types";
import type { WebsiteGeneration } from "@/types/database";
import { runSeoAgent } from "@/lib/ai-core/seo-agent";
import {
  applySeoPackageFix,
  getSeoFix,
} from "@/lib/ai-core/seo-optimizer";
import {
  runWebsiteEditor,
  type WebsiteEditAction,
} from "@/lib/ai-core/website-editor";
import { buildWebsiteAnalyticsSummary } from "@/lib/ai-core/analytics";
import { runConversionOptimizer } from "@/lib/ai-core/conversion-optimizer";
import type {
  CoreBusinessProfile,
  CoreProductStrategy,
} from "@/lib/ai-core/layers/types";
import { commitBlueprintRevision } from "@/lib/website/platform/commit";
import { readBlueprintRevisionFromGeneration } from "@/lib/website/platform/revision";
import {
  loadWebsiteGenerationForUser,
  toWebsiteProject,
} from "@/lib/website/platform/load-generation";
import type { WebsiteCommitOptions } from "@/lib/website/platform/types";

export type WebsiteSeoApplyRequest = {
  fixId: string;
  applyEditor?: boolean;
};

export type WebsiteSeoApplySuccess = {
  ok: true;
  fix: NonNullable<ReturnType<typeof getSeoFix>>;
  notes: string[];
  report: ReturnType<typeof runSeoAgent>;
  project: GeneratedWebsiteProject;
  generation: WebsiteGeneration;
  revision?: number;
  aiRunId?: string | null;
};

export type WebsiteSeoApplyFailure = {
  ok: false;
  code: "NOT_FOUND" | "VALIDATION" | "CONFLICT" | "SERVER";
  error: string;
};

export type WebsiteSeoApplyResult = WebsiteSeoApplySuccess | WebsiteSeoApplyFailure;

function buildSeoAgentContext(params: {
  generationId: string;
  generation: WebsiteGeneration;
  project: GeneratedWebsiteProject;
  files: ReturnType<typeof extractWebsiteFilesFromBlueprint>;
  analytics: Awaited<ReturnType<typeof buildWebsiteAnalyticsSummary>>;
  conversionOptimizer: Awaited<ReturnType<typeof runConversionOptimizer>>;
}) {
  const profile = (params.project.businessProfile ||
    null) as CoreBusinessProfile | null;
  const strategy = (params.project.strategy || null) as CoreProductStrategy | null;

  return runSeoAgent({
    generationId: params.generationId,
    files: params.files,
    strategy: strategy || undefined,
    profile: profile || undefined,
    industryId: profile?.industry || null,
    seoPackage: params.project.seoPackage || null,
    performanceReport: params.project.performanceReport || null,
    assetManifest: (params.project.assetManifest as never) || null,
    analytics: params.analytics,
    conversionOptimizer: params.conversionOptimizer,
  });
}

export async function executeWebsiteSeoApply(params: {
  supabase: SupabaseClient;
  userId: string;
  generationId: string;
  request: WebsiteSeoApplyRequest;
  commit?: Pick<WebsiteCommitOptions, "expectedRevision" | "idempotencyKey"> &
    Partial<Pick<WebsiteCommitOptions, "operation" | "mutationMeta">>;
}): Promise<WebsiteSeoApplyResult> {
  const generation = await loadWebsiteGenerationForUser(
    params.supabase,
    params.userId,
    params.generationId,
  );
  if (!generation) {
    return { ok: false, code: "NOT_FOUND", error: "Website not found." };
  }

  const project = toWebsiteProject(generation);
  const files = extractWebsiteFilesFromBlueprint(generation.blueprint);
  if (!files.length) {
    return {
      ok: false,
      code: "VALIDATION",
      error: "Generation has no editable files.",
    };
  }

  const profile = (project.businessProfile || null) as CoreBusinessProfile | null;
  const strategy = (project.strategy || null) as CoreProductStrategy | null;

  const analytics = await buildWebsiteAnalyticsSummary(
    params.generationId,
    14,
    params.supabase,
  );
  const conversionOptimizer = await runConversionOptimizer({
    generationId: params.generationId,
    conversionReport: project.conversionReport ?? null,
    industry: profile?.industry || null,
    projectName: generation.project_name || profile?.projectName || null,
    client: params.supabase,
  });

  const agent = buildSeoAgentContext({
    generationId: params.generationId,
    generation,
    project,
    files,
    analytics,
    conversionOptimizer,
  });

  const fix = getSeoFix(agent.optimizer, params.request.fixId);
  if (!fix) {
    return { ok: false, code: "NOT_FOUND", error: "SEO fix not found." };
  }

  let nextFiles = files;
  let seoPackage = project.seoPackage;
  const notes: string[] = [];

  try {
    if (
      fix.injectSeoPackage ||
      fix.applyMode === "seo-package" ||
      fix.applyMode === "both"
    ) {
      const applied = applySeoPackageFix({
        files: nextFiles,
        optimizer: agent.optimizer,
        fixId: fix.id,
      });
      nextFiles = applied.files;
      seoPackage = applied.seoPackage;
      notes.push(...applied.notes);
    }

    const shouldEditor =
      params.request.applyEditor !== false &&
      (fix.applyMode === "editor" || fix.applyMode === "both") &&
      (fix.command || fix.actions?.length);

    if (shouldEditor) {
      const editResult = runWebsiteEditor({
        files: nextFiles,
        project: { ...project, files: nextFiles },
        command: fix.command || fix.title,
        actions: (fix.actions || []) as WebsiteEditAction[],
      });
      nextFiles = editResult.files;
      notes.push(editResult.summary);
      notes.push(...editResult.appliedNotes.slice(0, 4));
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : "Apply fix failed";
    return { ok: false, code: "VALIDATION", error: message };
  }

  const nextProject: GeneratedWebsiteProject = {
    ...project,
    files: nextFiles,
    seoPackage: seoPackage || agent.optimizer.assets.seoPackage,
    seoPerformanceReport: agent.analysis.performanceReport,
    progressEvents: [
      ...(project.progressEvents ?? []),
      `[seo-agent] Applied fix ${fix.id}: ${fix.title}`,
    ],
  };

  const committed = await commitBlueprintRevision({
    supabase: params.supabase,
    userId: params.userId,
    generationId: params.generationId,
    project: nextProject,
    projectKind: nextProject.projectKind ?? "website",
    input: {
      prompt: generation.business_description || `SEO fix: ${fix.title}`,
      language: generation.language || "English",
      theme: "modern",
      features: [],
      productId: "website-builder",
      projectId: generation.project_id ?? undefined,
      mode: "continue",
      parentGenerationId: params.generationId,
      continueInstruction: fix.command || fix.title,
    },
    commit: {
      operation: params.commit?.operation ?? "website.seo.apply",
      expectedRevision: params.commit?.expectedRevision,
      idempotencyKey: params.commit?.idempotencyKey,
      mutationMeta: params.commit?.mutationMeta ?? {
        fixId: fix.id,
        fixTitle: fix.title,
      },
    },
  });

  if (!committed.ok) {
    return {
      ok: false,
      code: committed.code === "CONFLICT" ? "CONFLICT" : "SERVER",
      error: committed.error,
    };
  }

  const refreshed = buildSeoAgentContext({
    generationId: params.generationId,
    generation: committed.generation,
    project: committed.project,
    files: extractWebsiteFilesFromBlueprint(committed.generation.blueprint),
    analytics,
    conversionOptimizer,
  });

  return {
    ok: true,
    fix,
    notes,
    report: refreshed,
    project: committed.project,
    generation: committed.generation,
    revision: readBlueprintRevisionFromGeneration(committed.generation),
    aiRunId: committed.aiRunId,
  };
}

/**
 * Phase 2 — pick the highest-priority SEO fix and apply it (Copilot SEO improve).
 */
export async function executeWebsiteSeoImprove(params: {
  supabase: SupabaseClient;
  userId: string;
  generationId: string;
  command?: string;
  commit?: Pick<WebsiteCommitOptions, "expectedRevision" | "idempotencyKey"> &
    Partial<Pick<WebsiteCommitOptions, "operation" | "mutationMeta">>;
}): Promise<WebsiteSeoApplyResult> {
  const generation = await loadWebsiteGenerationForUser(
    params.supabase,
    params.userId,
    params.generationId,
  );
  if (!generation) {
    return { ok: false, code: "NOT_FOUND", error: "Website not found." };
  }

  const project = toWebsiteProject(generation);
  const files = extractWebsiteFilesFromBlueprint(generation.blueprint);
  if (!files.length) {
    return {
      ok: false,
      code: "VALIDATION",
      error: "Generation has no editable files.",
    };
  }

  const profile = (project.businessProfile || null) as CoreBusinessProfile | null;
  const analytics = await buildWebsiteAnalyticsSummary(
    params.generationId,
    14,
    params.supabase,
  );
  const conversionOptimizer = await runConversionOptimizer({
    generationId: params.generationId,
    conversionReport: project.conversionReport ?? null,
    industry: profile?.industry || null,
    projectName: generation.project_name || profile?.projectName || null,
    client: params.supabase,
  });

  const agent = buildSeoAgentContext({
    generationId: params.generationId,
    generation,
    project,
    files,
    analytics,
    conversionOptimizer,
  });

  const fixes = agent.optimizer.fixes;
  if (!fixes.length) {
    return {
      ok: false,
      code: "VALIDATION",
      error: "No SEO fixes available for this site.",
    };
  }

  const topFix = fixes[0]!;

  return executeWebsiteSeoApply({
    supabase: params.supabase,
    userId: params.userId,
    generationId: params.generationId,
    request: { fixId: topFix.id, applyEditor: true },
    commit: params.commit,
  });
}

import { getProfessionalScaffoldByPath } from "@/lib/ai-core/components";
import type { GeneratedProjectFile } from "@/lib/ai/types";
import {
  validateGeneratedProject,
  type ProjectCapabilityFlags,
} from "@/lib/ai/validator";
import {
  buildWebsiteScaffold,
  mergeMissingScaffoldFiles,
  resolveProjectNameFromFiles,
  syncPackageJsonDependencies,
} from "@/lib/ai/website-scaffold";
import { buildPlatformProductionScaffolds } from "@/lib/website/platform-scaffolds";
import { remediateSiteImagesInFiles } from "@/lib/website/site-images-parser";
import { validateAndRepairProjectImages } from "@/lib/website/image-management/validate-before-render";

const EXPORT_FLAGS: ProjectCapabilityFlags = {
  requiresAuth: false,
  requiresDatabase: false,
  requiresDashboard: false,
  isEcommerce: false,
  isSaas: false,
  databaseProvider: "none",
};

const NODE_BUILTIN_PACKAGES = new Set([
  "crypto",
  "node:crypto",
  "fs",
  "path",
  "os",
  "util",
  "stream",
  "buffer",
  "events",
]);

export type WebsiteExportPrepResult = {
  files: GeneratedProjectFile[];
  issues: string[];
  warnings: string[];
  blockingIssues: string[];
  ready: boolean;
  fixesApplied: string[];
};

function candidatePathsForImport(importPath: string): string[] {
  const base = importPath.replace(/^@\//, "");
  return [
    base,
    `${base}.tsx`,
    `${base}.ts`,
    `${base}.jsx`,
    `${base}.js`,
    `${base}/index.tsx`,
    `${base}/index.ts`,
  ];
}

function injectMissingScaffolds(
  files: GeneratedProjectFile[],
  fixes: string[],
): GeneratedProjectFile[] {
  const byPath = new Map(files.map((f) => [f.path.replaceAll("\\", "/"), { ...f }]));
  let changed = true;
  let rounds = 0;

  while (changed && rounds < 8) {
    changed = false;
    rounds += 1;
    const projectPaths = new Set(byPath.keys());
    const validation = validateGeneratedProject([...byPath.values()], EXPORT_FLAGS);

    for (const issue of validation.issues) {
      const missingMatch = issue.match(/missing project import "@\/([^"]+)"/);
      if (!missingMatch?.[1]) continue;

      for (const candidate of candidatePathsForImport(missingMatch[1])) {
        const normalized = candidate.replaceAll("\\", "/");
        if (byPath.has(normalized)) continue;

        const scaffold = getProfessionalScaffoldByPath(normalized);
        if (!scaffold) continue;

        byPath.set(normalized, {
          path: normalized,
          content: scaffold,
          language: normalized.endsWith(".ts") ? "typescript" : "tsx",
        });
        fixes.push(`Injected scaffold: ${normalized}`);
        changed = true;
        break;
      }
    }
  }

  return [...byPath.values()];
}

function fixNodeBuiltinImports(
  files: GeneratedProjectFile[],
  fixes: string[],
): GeneratedProjectFile[] {
  return files.map((file) => {
    if (!file.path.endsWith(".ts") && !file.path.endsWith(".tsx")) return file;

    let content = file.content;
    const before = content;

    content = content.replace(
      /from\s+['"]crypto['"]/g,
      'from "node:crypto"',
    );
    content = content.replace(
      /require\s*\(\s*['"]crypto['"]\s*\)/g,
      'require("node:crypto")',
    );

    if (content !== before) {
      fixes.push(`Normalized Node crypto import in ${file.path}`);
    }

    return { ...file, content };
  });
}

function stripUnresolvedImports(
  files: GeneratedProjectFile[],
  fixes: string[],
): GeneratedProjectFile[] {
  const byPath = new Map(files.map((f) => [f.path, { ...f }]));
  const projectPaths = new Set(byPath.keys());
  const validation = validateGeneratedProject([...byPath.values()], EXPORT_FLAGS);

  for (const issue of validation.issues) {
    const fileMatch = issue.match(/^([^:]+): missing project import/);
    if (!fileMatch?.[1]) continue;

    const filePath = fileMatch[1];
    const file = byPath.get(filePath);
    if (!file) continue;

    const importMatch = issue.match(/missing project import "(@\/[^"]+)"/);
    if (!importMatch?.[1]) continue;

    const importPath = importMatch[1];
    const escaped = importPath.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const importLine = new RegExp(
      `^\\s*import\\s+[^;]*from\\s+['"]${escaped}['"];?\\s*\\n?`,
      "m",
    );

    if (importLine.test(file.content)) {
      file.content = file.content.replace(importLine, "");
      fixes.push(`Removed unresolved import ${importPath} from ${filePath}`);
      byPath.set(filePath, file);
      continue;
    }

    // Drop broken page files that only exist as dangling routes.
    if (filePath.startsWith("app/") && filePath.endsWith("/page.tsx")) {
      byPath.delete(filePath);
      fixes.push(`Removed unroutable page missing dependencies: ${filePath}`);
    }
  }

  return [...byPath.values()];
}

function injectProductionScaffolds(
  files: GeneratedProjectFile[],
  fixes: string[],
): GeneratedProjectFile[] {
  const projectName = resolveProjectNameFromFiles(files);
  const scaffolds = [
    ...buildWebsiteScaffold(projectName),
    ...buildPlatformProductionScaffolds(projectName),
  ];
  const { files: merged, injected } = mergeMissingScaffoldFiles(files, scaffolds);
  for (const path of injected) {
    fixes.push(`Injected production scaffold: ${path}`);
  }
  return merged;
}

/**
 * Compose always passes eyebrow/title/subtitle/items/etc. Zero-arg scaffolds
 * must accept those props or exported `next build` fails typecheck.
 */
function acceptComposableSectionProps(source: string): string {
  return source.replace(
    /export function ([A-Za-z0-9_]+)\(\) \{/g,
    `export function $1(_props?: {
  eyebrow?: string;
  title?: string;
  subtitle?: string;
  items?: unknown;
  features?: unknown;
  plans?: unknown;
  quotes?: unknown;
  faqs?: unknown;
  primaryCta?: string;
  secondaryCta?: string;
  ctaLabel?: string;
  bullets?: unknown;
  imageUrl?: string | null;
  [key: string]: unknown;
}) {`,
  );
}

/**
 * Overwrite known professional component scaffolds with the current platform
 * source so export builds stay in sync with compose-generated props (e.g. eyebrow).
 */
function refreshProfessionalScaffolds(
  files: GeneratedProjectFile[],
  fixes: string[],
): GeneratedProjectFile[] {
  return files.map((file) => {
    const path = file.path.replaceAll("\\", "/");
    const fresh = getProfessionalScaffoldByPath(path);
    if (fresh) {
      const next = acceptComposableSectionProps(fresh);
      if (next !== file.content) {
        fixes.push(`Refreshed production scaffold: ${path}`);
        return { ...file, content: next, language: file.language || "tsx" };
      }
      return file;
    }
    if (!/\.(tsx|jsx)$/.test(path)) return file;
    const loosened = acceptComposableSectionProps(file.content);
    if (loosened === file.content) return file;
    fixes.push(`Accepted composable props on: ${path}`);
    return { ...file, content: loosened };
  });
}

const EXPORT_BUILD_CONFIG_PATHS = new Set([
  "next.config.ts",
  ".eslintrc.json",
]);

/** Force-refresh build config so exported projects inherit current lint/build policy. */
function refreshExportBuildConfigs(
  files: GeneratedProjectFile[],
  fixes: string[],
): GeneratedProjectFile[] {
  const projectName = resolveProjectNameFromFiles(files);
  const scaffolds = buildWebsiteScaffold(projectName);
  const byPath = new Map(
    files.map((file) => [file.path.replaceAll("\\", "/"), { ...file }]),
  );
  for (const scaffold of scaffolds) {
    const path = scaffold.path.replaceAll("\\", "/");
    if (!EXPORT_BUILD_CONFIG_PATHS.has(path)) continue;
    const existing = byPath.get(path);
    if (!existing || existing.content !== scaffold.content) {
      byPath.set(path, { ...scaffold, path });
      fixes.push(`Refreshed export build config: ${path}`);
    }
  }
  return [...byPath.values()];
}

function classifyExportIssues(issues: string[]): {
  blocking: string[];
  warnings: string[];
} {
  const blocking: string[] = [];
  const warnings: string[] = [];

  for (const issue of issues) {
    if (/imports "([^"]+)" but package\.json is missing/.test(issue)) {
      const pkg = issue.match(/missing "([^"]+)"/)?.[1];
      if (pkg && NODE_BUILTIN_PACKAGES.has(pkg)) {
        warnings.push(issue);
        continue;
      }
    }
    if (issue.startsWith("Missing required production file:")) {
      warnings.push(issue);
      continue;
    }
    blocking.push(issue);
  }

  return { blocking, warnings };
}

/**
 * Prepare generated website files for ZIP export — inject scaffolds, fix imports,
 * sync package.json, and validate without mutating the generation pipeline.
 */
export function prepareWebsiteProjectForExport(
  files: GeneratedProjectFile[],
): WebsiteExportPrepResult {
  const fixesApplied: string[] = [];
  let current = [...files];

  current = fixNodeBuiltinImports(current, fixesApplied);
  const beforeRemediation = current;
  current = remediateSiteImagesInFiles(current);
  if (
    beforeRemediation.some((f) =>
      f.path.replaceAll("\\", "/").includes("lib/site-images"),
    )
  ) {
    fixesApplied.push("Remediated premium stock URLs in lib/site-images.ts");
  }
  const validated = validateAndRepairProjectImages(current, {});
  if (validated.repairs > 0) {
    current = validated.files;
    fixesApplied.push(
      `Validated and repaired ${validated.repairs} image slot(s) before export`,
    );
  }
  current = injectProductionScaffolds(current, fixesApplied);
  current = refreshProfessionalScaffolds(current, fixesApplied);
  current = refreshExportBuildConfigs(current, fixesApplied);
  current = injectMissingScaffolds(current, fixesApplied);
  current = stripUnresolvedImports(current, fixesApplied);
  current = syncPackageJsonDependencies(current);
  current = injectMissingScaffolds(current, fixesApplied);
  current = injectProductionScaffolds(current, fixesApplied);
  current = refreshProfessionalScaffolds(current, fixesApplied);
  current = refreshExportBuildConfigs(current, fixesApplied);
  current = syncPackageJsonDependencies(current);

  const validation = validateGeneratedProject(current, EXPORT_FLAGS);
  const { blocking, warnings } = classifyExportIssues(validation.issues);

  const essentialPaths = ["app/page.tsx", "app/layout.tsx", "package.json"];
  const paths = new Set(current.map((f) => f.path));
  for (const essential of essentialPaths) {
    if (!paths.has(essential)) {
      blocking.push(`Export blocked: missing essential file ${essential}`);
    }
  }

  return {
    files: current,
    issues: validation.issues,
    warnings,
    blockingIssues: blocking,
    ready: blocking.length === 0,
    fixesApplied,
  };
}

