          <ul className="flex flex-col gap-3">
            {${linksVar}.map((link) => (
              <li key={link.href}>
                <a href={link.href} onClick={() => setOpen(false)} className="${p}-font-body block py-1 text-sm font-medium text-[var(--color-foreground)]">
                  {link.label}
                </a>
              </li>
            ))}
            <li className="pt-2">
