  const child = spawn("npm", ["run", "start", "--", "-p", String(port)], {
    cwd: root,
    shell: true,
    stdio: "ignore",
    env: { ...process.env, PORT: String(port) },
  });

  try {
    await waitForServer(baseUrl);
    await verifyLiveServer(baseUrl);
  } catch (err) {
    fail("live server", err.message);
  } finally {
    child.kill("SIGTERM");
  }
}

const WEBSITE_SMOKE_SCRIPTS = [
  "smoke:website-ai",
  "smoke:website-publish",
  "smoke:website-design-engine",
];

function runNpmScript(script) {
  return new Promise((resolve, reject) => {
    const child = spawn("npm", ["run", script], {
      cwd: root,
      shell: true,
      stdio: "inherit",
      env: process.env,
    });
    child.on("error", reject);
    child.on("close", (code) => {
      if (code === 0) resolve();
      else reject(new Error(`${script} exited with code ${code}`));
    });
  });
}

async function runWebsiteSmokeScripts() {
  console.log("\n[13] Website Builder smoke scripts");
  for (const script of WEBSITE_SMOKE_SCRIPTS) {
    try {
      await runNpmScript(script);
      pass(script);
    } catch (err) {
      fail(script, err.message);
    }
  }
}

async function main() {
  console.log("Trend Business AI — verification\n");
  const supabase = await verifySupabase();
  if (supabase) {
    await verifyRequiredColumns(supabase);
  }
  verifyMigrationFiles();
  verifyRouteFiles();

  const skipLive = process.argv.includes("--skip-live");
  if (!skipLive && existsSync(join(root, ".next", "BUILD_ID"))) {
    console.log("\n[Live checks] Starting production server on :3099 …");
    await runLiveChecks();
  } else if (skipLive) {
    console.log("\n[Live checks] skipped (--skip-live)");
  } else {
    console.log("\n[Live checks] skipped (run npm run build first)");
  }

  await runWebsiteSmokeScripts();

  console.log("\n--- Summary ---");
  const ok = results.filter((r) => r.ok).length;
  const bad = results.filter((r) => !r.ok).length;
  console.log(`${ok} passed, ${bad} failed`);
  process.exit(failed ? 1 : 0);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

