/** Wire CRM, ERP, BI, Cyber workspace tab labels to i18n */
import fs from "node:fs";
import path from "node:path";

const workspaces = [
  {
    file: "components/dashboard/crm/crm-workspace.tsx",
    scope: "crm",
    tabs: [
      "overview",
      "accounts",
      "contacts",
